    def record_coaching_fight_outcome(self, company, winner, loser, method, fight):
        """Connect significant results to existing coaching and mentor arcs."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return None
        for fighter, won, opponent in ((winner, True, loser), (loser, False, winner)):
            gym_name = str(getattr(fighter, "camp", "") or "")
            key = self.coaching_loyalty_story_key(fighter, gym_name)
            thread = self.story_thread(key) if key else None
            meaningful = bool(fight.get("title") or fight.get("divisional_title") or fight.get("main"))
            if thread and thread.get("status") not in {"resolved", "abandoned"}:
                if won and (fight.get("title") or fight.get("divisional_title")):
                    phase, importance = "championship_breakthrough", 4
                    summary = f"{fighter.name} and {gym_name} reached championship level with a {method} win over {opponent.name}."
                elif won and (meaningful or getattr(fighter, "career_win_streak", 0) >= 3):
                    phase, importance = "breakthrough", 3
                    summary = f"{fighter.name}'s work with {gym_name} produced a defining {method} win over {opponent.name}."
                elif not won and meaningful and getattr(fighter, "momentum", 0) <= -2:
                    phase, importance = "loyalty_test", 3
                    summary = f"A loss to {opponent.name} put {fighter.name}'s partnership with {gym_name} under pressure."
                else:
                    phase = ""
                if phase:
                    self.record_coaching_loyalty_story(
                        fighter, gym_name, phase=phase, summary=summary, importance=importance,
                        event_ref=f"{key}:{phase}:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
                    )

            prospect_id = str(getattr(fighter, "academy_prospect_id", "") or "")
            mentor_key = f"academy-mentorship:{prospect_id}" if prospect_id else ""
            mentor = self.story_thread(mentor_key) if mentor_key else None
            if not mentor or mentor.get("status") in {"resolved", "abandoned"}:
                continue
            if won and (fight.get("title") or fight.get("divisional_title")):
                summary = f"The academy coaching plan culminated in {fighter.name}'s championship victory over {opponent.name}."
                self.upsert_story_thread(
                    mentor_key, "Academy Mentorship", status="resolved", phase="mentorship_fulfilled",
                    importance=5, fighters=[fighter], companies=[company, "Fighting Academy"],
                    beat_kind="senior_payoff",
                    beat_ref=f"{mentor_key}:title:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
                    summary=summary, resolution=summary,
                )
            elif not won and meaningful:
                self.upsert_story_thread(
                    mentor_key, "Academy Mentorship", status="active", phase="senior_test",
                    importance=3, fighters=[fighter], companies=[company, "Fighting Academy"],
                    beat_kind="senior_test",
                    beat_ref=f"{mentor_key}:test:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
                    summary=f"{fighter.name}'s loss to {opponent.name} became the first major test of the academy coaching plan.",
                )

    def record_combat_sport_story(self, sport, company, fighter, opponent, *, phase, summary, status="active", importance=3, resolution=""):
        key = self.combat_sport_story_key(sport, fighter)
        if not key:
            return None
        return self.upsert_story_thread(
            key, f"{sport} Career", status=status, phase=phase, importance=importance,
            fighters=[fighter, opponent] if opponent else [fighter], companies=[company],
            origin_ref=f"{key}:{phase}:{self.month}:{self.week}",
            beat_kind=phase, beat_ref=f"{key}:{phase}:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
            summary=summary, stakes=f"The result shapes {fighter.name}'s standing and legacy in {sport}.",
            resolution=resolution,
        )

    def record_crossover_story(self, fighter, opponent, *, phase, summary, status="active", resolution=""):
        key = self.crossover_story_key(fighter)
        if not key:
            return None
        return self.upsert_story_thread(
            key, "Crossover Career", status=status, phase=phase, importance=4,
            fighters=[fighter, opponent] if opponent else [fighter],
            companies=[self.fighter_company_name(fighter), self.fighter_company_name(opponent) if opponent else ""],
            origin_ref=f"{key}:{phase}:{self.month}:{self.week}",
            beat_kind=phase, beat_ref=f"{key}:{phase}:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
            summary=summary, stakes="Success can create a multi-sport attraction; failure can force a difficult return to the original career path.",
            resolution=resolution,
        )

    def record_hometown_story(self, fighter, region, popularity, note=""):
        key = self.hometown_story_key(fighter, region)
        if not key:
            return None
        popularity = max(0, min(100, int(popularity or 0)))
        phase = "market_icon" if popularity >= 90 else "hometown_star" if popularity >= 75 else "local_hero"
        existing = self.story_thread(key)
        prior_resolved = bool(existing and existing.get("status") == "resolved")
        if prior_resolved and popularity < 90:
            phase = str(existing.get("phase", phase) or phase)
        status = "resolved" if popularity >= 90 or prior_resolved else "active"
        summary = f"{fighter.name} became a {phase.replace('_', ' ')} in {region} ({popularity}/100)."
        if note:
            summary += f" {note}"
        return self.upsert_story_thread(
            key, "Hometown Hero", status=status, phase=phase,
            importance=5 if popularity >= 90 else 4 if popularity >= 75 else 3,
            fighters=[fighter], companies=[self.fighter_company_name(fighter), region],
            origin_ref=f"{key}:local_hero", beat_kind=phase,
            beat_ref=f"{key}:{phase}", summary=summary,
            stakes=f"Future appearances in {region} can turn local support into a defining home-market legacy.",
            resolution=(
                summary if popularity >= 90
                else str(existing.get("resolution", "") or "") if prior_resolved
                else ""
            ),
        )

    def record_homecoming_booking(self, event, company=""):
        """Frame already-booked home-market headline fights; never discover cards."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return []
        event = event or {}
        region = str(event.get("region", "") or "")
        city = str(event.get("city", "") or "")
        company = str(company or self.player_company_name)
        written = []
        for fight in event.get("fights", []) or []:
            if not (fight.get("main") or fight.get("title") or fight.get("divisional_title")):
                continue
            for fighter in self.event_fight_fighters(fight):
                connection = self.fighter_event_connection(fighter, region, city)
                if connection.get("strength", 0) < 0.80:
                    continue
                key = self.hometown_story_key(fighter, region)
                existing = self.story_thread(key)
                market_popularity = int(connection.get("market_popularity", 0) or 0)
                if market_popularity < 60 and not existing:
                    continue
                location = city or region
                summary = (
                    f"{fighter.name} was booked for a {connection['level'].lower()} homecoming at "
                    f"{event.get('name', 'an upcoming event')} in {location}."
                )
                thread = self.upsert_story_thread(
                    key, "Hometown Hero", status="active", phase="homecoming_booked",
                    importance=4 if fight.get("title") or fight.get("divisional_title") else 3,
                    fighters=[fighter], companies=[company, region],
                    origin_ref=f"{key}:homecoming:{event.get('month', self.month)}:{event.get('week', self.week)}",
                    stakes="The home crowd will judge whether local support becomes a defining performance or a painful setback.",
                    beat_kind="homecoming_booked",
                    beat_ref=(
                        f"{key}:booked:{event.get('month', self.month)}:{event.get('week', self.week)}:"
                        f"{self.story_company_key(event.get('name', 'event'))}"
                    ),
                    summary=summary,
                )
                if thread:
                    written.append(thread)
        return written

    def record_hometown_fight_story(
        self, fighter, opponent, fight, method, won, *, event_name="", company="",
    ):
        """Resolve the homecoming meaning of one completed fight by direct identity."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        fight = fight or {}
        region = str(fight.get("region", "") or "")
        city = str(fight.get("city", "") or "")
        connection = self.fighter_event_connection(fighter, region, city)
        if connection.get("strength", 0) < 0.80:
            return None
        key = self.hometown_story_key(fighter, region)
        existing = self.story_thread(key)
        popularity = int((getattr(fighter, "regional_popularity", {}) or {}).get(region, 0) or 0)
        if popularity < 60 and not existing:
            return None
        title = bool(fight.get("title") or fight.get("divisional_title") or fight.get("special_belt"))
        main = bool(fight.get("main"))
        official = method not in ("Draw", "No Contest")
        if not official:
            phase, importance = "homecoming_unresolved", 3
            outcome = f"ended without a decisive result against {getattr(opponent, 'name', 'the opponent')}"
        elif won and title:
            phase, importance = "home_title_triumph", 5
            outcome = f"won a championship homecoming against {getattr(opponent, 'name', 'the opponent')} by {method}"
        elif won:
            phase, importance = ("homecoming_triumph", 4) if main else ("homecoming_win", 3)
            outcome = f"won the homecoming against {getattr(opponent, 'name', 'the opponent')} by {method}"
        elif title or main:
            phase, importance = "homecoming_heartbreak", 4
            outcome = f"lost the homecoming spotlight to {getattr(opponent, 'name', 'the opponent')} by {method}"
        else:
            phase, importance = "homecoming_setback", 3
            outcome = f"suffered a home-market setback against {getattr(opponent, 'name', 'the opponent')}"
        location = city or region
        summary = f"{fighter.name} {outcome} at {event_name or 'an event'} in {location}."
        prior_resolved = bool(existing and existing.get("status") == "resolved")
        resolved = bool(won and title) or popularity >= 90 or prior_resolved
        stored_phase = str(existing.get("phase", phase) or phase) if prior_resolved else phase
        resolution = (
            str(existing.get("resolution", "") or "")
            if prior_resolved else summary if resolved else ""
        )
        company = str(company or self.fighter_company_name(fighter) or self.player_company_name)
        return self.upsert_story_thread(
            key, "Hometown Hero", status="resolved" if resolved else "active",
            phase=stored_phase, importance=importance, fighters=[fighter], companies=[company, region],
            origin_ref=f"{key}:homecoming", beat_kind=phase,
            beat_ref=(
                f"{key}:result:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}:"
                f"{self.story_company_key(event_name or 'event')}"
            ),
            summary=summary,
            stakes="Home-market expectations now shape the fighter's local legacy.",
            resolution=resolution,
        )

    def record_academy_mentorship_story(self, prospect, *, phase, summary, fighter=None, status="active", resolution=""):
        key = self.academy_mentorship_story_key(prospect)
        if not key:
            return None
        return self.upsert_story_thread(
            key, "Academy Mentorship", status=status, phase=phase, importance=3,
            fighters=[fighter] if fighter else [], companies=[self.player_company_name, "Fighting Academy"],
            origin_ref=f"{key}:mentor", beat_kind=phase,
            beat_ref=f"{key}:{phase}:{self.month}:{self.week}", summary=summary,
            stakes="The aligned coaching plan will be judged by the prospect's development and senior transition.",
            resolution=resolution,
        )

    def record_contract_promise_story(self, fighter, promises, company=""):
        promises = [str(value) for value in (promises or []) if value]
        key = self.contract_promise_story_key(fighter)
        if not key or not promises:
            return None
        company = company or self.player_company_name
        promise_text = " and ".join(promises)
        return self.upsert_story_thread(
            key, "Contract Promise", status="active", phase="commitment_made", importance=3,
            fighters=[fighter], companies=[company],
            origin_ref=f"{key}:made:{self.month}:{self.week}:{'-'.join(promises)}",
            beat_kind="promise_made", beat_ref=f"{key}:made:{self.month}:{self.week}:{'-'.join(promises)}",
            summary=f"{company} promised {fighter.name} a {promise_text} opportunity.",
            stakes=f"The commitment is due by {self.format_game_date(getattr(fighter, 'promise_deadline_month', self.month), 1, include_week=False)} and will affect trust.",
        )

    def resolve_contract_promise_story(self, fighter, promises, kept, company=""):
        promises = [str(value) for value in (promises or []) if value]
        key = self.contract_promise_story_key(fighter)
        if not key or not promises:
            return None
        company = company or self.player_company_name
        remaining = bool(getattr(fighter, "main_event_promise", False) or getattr(fighter, "top_opponent_promise", False))
        status = "active" if kept and remaining else "resolved"
        phase = "partially_fulfilled" if kept and remaining else "fulfilled" if kept else "broken"
        promise_text = " and ".join(promises)
        summary = (
            f"{company} kept its {promise_text} commitment to {fighter.name}."
            if kept else f"{company} broke its {promise_text} commitment to {fighter.name}."
        )
        return self.upsert_story_thread(
            key, "Contract Promise", status=status, phase=phase, importance=4 if not kept else 3,
            fighters=[fighter], companies=[company], beat_kind="promise_kept" if kept else "promise_broken",
            beat_ref=f"{key}:{phase}:{self.month}:{self.week}", summary=summary,
            stakes=("Other promised opportunities still remain." if remaining else "The contract commitment has reached its outcome."),
            resolution=summary if status == "resolved" else "",
        )

    def active_contract_saga(self, fighter):
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return None
        key = str(getattr(fighter, "contract_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        return thread if thread and thread.get("status") not in {"resolved", "abandoned"} else None

    def record_contract_saga(
        self, fighter, company, *, phase, summary, status="active", importance=3,
        resolution="", beat_ref="", former_company="", current_company="",
    ):
        """Create or advance one fighter contract chapter by direct key."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        company = str(company or "").strip()
        key = str(getattr(fighter, "contract_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        if not key or not thread or (
            thread.get("status") in {"resolved", "abandoned"}
            and status not in {"resolved", "abandoned"}
        ):
            key = self.new_contract_saga_story_key(fighter, company)
            fighter.contract_story_key = key
            thread = None
        if not key:
            return None
        companies = list(thread.get("companies", []) or []) if thread else []
        companies.extend(value for value in (former_company, current_company, company) if value)
        beat_ref = beat_ref or f"{key}:{phase}:{self.month}:{self.week}"
        thread = self.upsert_story_thread(
            key, "Contract Saga", status=status, phase=phase, importance=importance,
            fighters=[fighter], companies=companies, origin_ref=beat_ref,
            stakes="Trust, leverage, sporting opportunity, and rival interest will determine where the fighter's next chapter unfolds.",
            beat_kind=phase, beat_ref=beat_ref, summary=summary, resolution=resolution,
        )
        if thread:
            if former_company:
                thread["former_company"] = str(former_company)
            elif not thread.get("former_company") and company:
                thread["former_company"] = company
            if current_company:
                thread["current_company"] = str(current_company)
        return thread

    def record_contract_pressure(self, fighter, company, months, note=""):
        months = max(0, int(months or 0))
        phase = "final_month" if months <= 1 else "renewal_window"
        summary = note or (
            f"{fighter.name} entered the final month of negotiations with {company}."
            if months <= 1 else f"{fighter.name} and {company} opened renewal discussions with {months} months remaining."
        )
        return self.record_contract_saga(
            fighter, company, phase=phase, summary=summary,
            importance=4 if months <= 1 and (fighter.champion or fighter.popularity >= 65) else 3,
            beat_ref=f"contract-pressure:{fighter.fighter_id}:{company}:{months}:{self.month}",
            former_company=company,
        )

    def record_contract_renewal(self, fighter, company, months, source="Negotiated renewal"):
        thread = self.active_contract_saga(fighter)
        if not thread:
            return None
        summary = f"{fighter.name} renewed with {company} for {int(months)} months. {source}."
        result = self.record_contract_saga(
            fighter, company, phase="renewed", status="resolved", importance=3,
            summary=summary, resolution=summary,
            beat_ref=f"contract-renewal:{fighter.fighter_id}:{company}:{self.month}:{self.week}",
            former_company=thread.get("former_company", company), current_company=company,
        )
        fighter.contract_story_key = ""
        return result

    def record_contract_exit(self, fighter, company, reason="Contract expiry"):
        membership = getattr(self, "record_membership_event", None)
        if callable(membership):
            membership(
                fighter, "leave", company_name=company,
                effective_month=getattr(self, "month", 0), effective_week=getattr(self, "week", 0),
                reason=reason,
                source_transaction=f"contract-exit:{getattr(fighter, 'fighter_id', '')}:{company}:{getattr(self, 'month', 0)}:{getattr(self, 'week', 0)}",
            )
        feeder_result = self.resolve_feeder_pathway_departure(fighter, company, reason)
        crossroads_result = self.resolve_crossroads_departure(fighter, company, "released", reason)
        significant = bool(
            fighter in getattr(self, "roster", [])
            or self.active_contract_saga(fighter)
            or getattr(fighter, "champion", False)
            or getattr(fighter, "interim_champion", False)
            or getattr(fighter, "popularity", 0) >= 55
            or getattr(fighter, "overall", 0) >= 80
        )
        if not significant:
            return feeder_result or crossroads_result
        phase = "released" if "release" in reason.lower() or "cut" in reason.lower() else "expired_exit"
        summary = f"{fighter.name} left {company}. {reason}. The open market will determine the next chapter."
        contract_result = self.record_contract_saga(
            fighter, company, phase=phase, summary=summary, importance=4 if fighter.champion else 3,
            beat_ref=f"contract-exit:{fighter.fighter_id}:{company}:{self.month}:{self.week}:{phase}",
            former_company=company,
        )
        return contract_result or feeder_result or crossroads_result

    def record_contract_signing(self, fighter, new_company, source="Contract signing", *, record_membership=True):
        """Record the narrative side of a signing and, by default, its membership fact.

        A few domain owners must append the membership fact *before* moving a
        fighter between roster collections.  They can do that at their own
        mutation boundary and pass ``record_membership=False`` here so the
        post-move narrative hook does not create a second historical row.
        """
        membership = getattr(self, "record_membership_event", None)
        if record_membership and callable(membership):
            membership(
                fighter, "join", company_name=new_company,
                effective_month=getattr(self, "month", 0), effective_week=getattr(self, "week", 0),
                reason=source,
                source_transaction=f"contract-signing:{getattr(fighter, 'fighter_id', '')}:{new_company}:{getattr(self, 'month', 0)}:{getattr(self, 'week', 0)}",
            )
        thread = self.active_contract_saga(fighter)
        if not thread:
            return None
        former = str(thread.get("former_company", "") or "")
        if not former:
            former = next((name for name in thread.get("companies", []) if name != new_company), "")
        returned = bool(former and former == new_company)
        phase = "return_signing" if returned else "defection"
        status = "resolved" if returned else "active"
        summary = (
            f"{fighter.name} returned to {new_company}, closing the contract dispute."
            if returned else f"{fighter.name} joined {new_company} after leaving {former or 'their former promotion'}. {source}."
        )
        result = self.record_contract_saga(
            fighter, new_company, phase=phase, status=status, importance=4,
            summary=summary, resolution=summary if returned else "",
            beat_ref=f"contract-signing:{fighter.fighter_id}:{new_company}:{self.month}:{self.week}",
            former_company=former, current_company=new_company,
        )
        if returned:
            fighter.contract_story_key = ""
        return result

    def record_contract_revenge_fight(self, winner, loser, winner_company, loser_company, method, event_name):
        """Pay off a defection only when a real cross-company fight supplies it."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return []
        resolved = []
        for fighter, won, opponent, current_company, opposing_company in (
            (winner, True, loser, winner_company, loser_company),
            (loser, False, winner, loser_company, winner_company),
        ):
            thread = self.active_contract_saga(fighter)
            if not thread or thread.get("phase") != "defection":
                continue
            former = str(thread.get("former_company", "") or "")
            current = str(thread.get("current_company", "") or current_company)
            if not former or former != opposing_company or current != current_company:
                continue
            phase = "revenge_won" if won else "revenge_denied"
            summary = (
                f"{fighter.name} beat {opponent.name} by {method} at {event_name}, winning the grudge match against {former}."
                if won else f"{fighter.name}'s first revenge fight against {former} ended in defeat to {opponent.name} by {method}."
            )
            result = self.record_contract_saga(
                fighter, current_company, phase=phase, status="resolved", importance=5,
                summary=summary, resolution=summary,
                beat_ref=f"contract-revenge:{fighter.fighter_id}:{opponent.fighter_id}:{self.month}:{self.week}:{self.story_company_key(event_name)}",
                former_company=former, current_company=current,
            )
            fighter.contract_story_key = ""
            if result:
                resolved.append(result)
        return resolved

    def new_staff_tenure_story_key(self, member, company=None):
        """Return a direct, collision-safe key without searching staff history."""
        if not isinstance(member, dict):
            return ""
        staff_id = str(member.get("staff_id", "") or "").strip()
        company = str(company or getattr(self, "player_company_name", "") or "").strip()
        if not staff_id or not company:
            return ""
        base = (
            f"staff-tenure:{staff_id}:{self.story_company_key(company)}:"
            f"{int(self.month)}:{int(self.week)}"
        )
        if not self.story_thread(base):
            return base
        sequence = 2
        while self.story_thread(f"{base}:{sequence}"):
            sequence += 1
        return f"{base}:{sequence}"

    def active_staff_tenure(self, member):
        """Resolve one staff chapter through its saved key only."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not isinstance(member, dict):
            return None
        key = str(member.get("staff_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        return thread if thread and thread.get("status") not in {"resolved", "abandoned"} else None

    def record_staff_tenure_story(
        self, member, *, phase, summary, status="active", importance=2,
        resolution="", event_ref="", company=None,
    ):
        """Advance one staff career from an existing staff-domain event."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not isinstance(member, dict):
            return None
        staff_id = str(member.get("staff_id", "") or "").strip()
        if not staff_id:
            return None
        company = str(company or getattr(self, "player_company_name", "") or "").strip()
        key = str(member.get("staff_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        if not key or not thread or (
            thread.get("status") in {"resolved", "abandoned"}
            and status not in {"resolved", "abandoned"}
        ):
            key = self.new_staff_tenure_story_key(member, company)
            member["staff_story_key"] = key
        if not key:
            return None
        event_ref = str(event_ref or f"{key}:{phase}:{self.month}:{self.week}")
        thread = self.upsert_story_thread(
            key, "Staff Tenure", status=status, phase=phase, importance=importance,
            companies=[company], origin_ref=event_ref,
            stakes=(
                f"{member.get('name', 'This staff member')}'s {member.get('role', 'operations')} work, "
                "contract trust, and future with the promotion remain at stake."
            ),
            beat_kind=phase, beat_ref=event_ref, summary=summary, resolution=resolution,
        )
        if thread:
            thread["staff_ids"] = [staff_id]
            thread["staff_names"] = [str(member.get("name", "Staff") or "Staff")]
            thread["staff_role"] = str(member.get("role", "Operations") or "Operations")
        return thread

    def staff_member_for_role(self, role):
        """Return the known player staff lead from the already-bounded staff list."""
        # The Staff management layer owns the effective lead rule.  Use it for
        # contribution attribution too, so the roster card, passive effect and
        # narrative evidence cannot disagree about a morale-adjusted lead.
        if hasattr(self, "staff_effective_lead"):
            lead = self.staff_effective_lead(role)
            if lead is not None:
                return lead
        candidates = [
            member for member in getattr(self, "staff", [])
            if isinstance(member, dict) and member.get("role") == role
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda member: (
            int(member.get("skill", 0) or 0), int(member.get("morale", 0) or 0),
            str(member.get("staff_id", "") or ""),
        ))

    def record_staff_contribution(
        self, role, kind, summary, *, event_ref, member=None, importance=3, setback=False,
    ):
        """Record one first-of-kind staff achievement from an owning domain event."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return None
        member = member if isinstance(member, dict) else self.staff_member_for_role(role)
        if not member or member.get("role") != role or not member.get("staff_id"):
            return None
        kind = str(kind or "").strip()
        if not kind:
            return None
        existing = self.active_staff_tenure(member)
        recorded = list(dict.fromkeys(
            str(value) for value in (
                (existing or {}).get("contribution_kinds", [])
                or member.get("staff_milestone_kinds", [])
                or []
            ) if value
        ))[:12]
        if kind in recorded:
            return existing
        phase = "role_setback" if setback else (
            "department_legacy" if len(recorded) >= 2 else "role_breakthrough"
        )
        thread = self.record_staff_tenure_story(
            member, phase=phase, summary=summary, importance=importance,
            event_ref=str(event_ref or f"staff-contribution:{member['staff_id']}:{kind}:{self.month}:{self.week}"),
        )
        if not thread:
            return None
        recorded.append(kind)
        recorded = list(dict.fromkeys(recorded))[-12:]
        legacy_delta = -1 if setback else max(1, min(5, int(importance or 1)))
        legacy_score = max(0, min(100, int(thread.get("staff_legacy_score", 0) or 0) + legacy_delta))
        thread["contribution_kinds"] = recorded
        thread["staff_legacy_score"] = legacy_score
        member["staff_milestone_kinds"] = recorded
        member["staff_legacy_score"] = legacy_score
        return thread

    def record_event_staff_milestones(self, package):
        """Interpret a settled player card without searching event or staff history."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not isinstance(package, dict):
            return []
        finance = package.get("finance", {}) if isinstance(package.get("finance"), dict) else {}
        event_name = str(package.get("event_name", "Event") or "Event")
        event_ref = f"staff-event:{self.story_company_key(event_name)}:{self.month}:{self.week}"
        fight_count = max(0, int(package.get("fight_count", 0) or 0))
        excitement = float(package.get("average_excitement", 0) or 0)
        attendance = max(0, int(finance.get("attendance", 0) or 0))
        capacity = max(1, int(finance.get("venue_capacity", 1) or 1))
        sell_through = attendance / capacity
        written = []

        if fight_count >= 4 and excitement >= 78:
            written.append(self.record_staff_contribution(
                "Matchmaker", "standout_card",
                f"The matchmaking team delivered a standout {event_name} card averaging {round(excitement)} excitement.",
                event_ref=f"{event_ref}:matchmaker-standout", importance=4,
            ))
        elif fight_count >= 4 and excitement < 40:
            written.append(self.record_staff_contribution(
                "Matchmaker", "card_backlash",
                f"The matchmaking team faced questions after {event_name} averaged only {round(excitement)} excitement.",
                event_ref=f"{event_ref}:matchmaker-setback", importance=3, setback=True,
            ))

        marketing_spend = max(0, int(finance.get("marketing", 0) or 0))
        if sell_through >= 0.95:
            written.append(self.record_staff_contribution(
                "Marketing", "sellout_campaign",
                f"The marketing team helped {event_name} sell {round(sell_through * 100)}% of the venue.",
                event_ref=f"{event_ref}:marketing-sellout", importance=4,
            ))
        elif marketing_spend > 0 and sell_through < 0.45:
            written.append(self.record_staff_contribution(
                "Marketing", "campaign_miss",
                f"The campaign for {event_name} reached only {round(sell_through * 100)}% venue sell-through despite paid promotion.",
                event_ref=f"{event_ref}:marketing-setback", importance=3, setback=True,
            ))

        broadcast_income = max(0, int(finance.get("broadcast_income", 0) or 0))
        ticket_revenue = max(0, int(finance.get("ticket_revenue", 0) or 0))
        media_outcome = package.get("media_outcome", {}) if isinstance(package.get("media_outcome"), dict) else {}
        if media_outcome.get("delivered") and broadcast_income >= max(100_000, ticket_revenue):
            written.append(self.record_staff_contribution(
                "Broadcast Producer", "broadcast_breakthrough",
                f"{event_name} delivered ${broadcast_income:,} in broadcast income, matching or exceeding its live gate.",
                event_ref=f"{event_ref}:broadcast-breakthrough", importance=4,
            ))
        return [thread for thread in written if thread]

    def active_feeder_pathway(self, fighter):
        """Resolve one child-to-parent chapter through the fighter's saved key."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        key = str(getattr(fighter, "feeder_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        return thread if thread and thread.get("status") not in {"resolved", "abandoned"} else None

    def record_feeder_pathway_transition(
        self, fighter, child_company, parent_company, *, phase, summary,
        pathway_kind="", status="active", importance=3, resolution="", event_ref="",
    ):
        """Advance one known fighter pathway without discovering child alumni."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        child_company = str(child_company or "").strip()
        parent_company = str(parent_company or "").strip()
        if not child_company or not parent_company:
            return None
        key = str(getattr(fighter, "feeder_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        if not key or not thread or (
            thread.get("status") in {"resolved", "abandoned"}
            and status not in {"resolved", "abandoned"}
        ):
            key = self.new_feeder_pathway_story_key(fighter, child_company)
            fighter.feeder_story_key = key
            thread = None
        if not key:
            return None
        event_ref = str(event_ref or f"{key}:{phase}:{self.month}:{self.week}")
        thread = self.upsert_story_thread(
            key, "Feeder Pathway", status=status, phase=phase, importance=importance,
            fighters=[fighter], companies=[child_company, parent_company], origin_ref=event_ref,
            stakes=(
                f"Development at {child_company} must translate into a meaningful senior career "
                f"with {parent_company}."
            ),
            beat_kind=phase, beat_ref=event_ref, summary=summary, resolution=resolution,
        )
        if thread:
            thread["child_company"] = child_company
            thread["parent_company"] = parent_company
            if pathway_kind:
                thread["pathway_kind"] = str(pathway_kind)
            thread.setdefault("parent_fights", 0)
            thread.setdefault("child_highlight_recorded", False)
            thread.setdefault("parent_breakthrough_recorded", False)
            thread.setdefault("recent_result_refs", [])
        return thread

    def record_feeder_fight_result(self, company, first, second, method, fight):
        """Interpret one settled fight for directly linked feeder-pathway fighters."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return []
        # This helper is called from both player and game-AI settlement. Almost
        # every fight has no feeder participant, so exit before resolving a story
        # index or normalising fight data. This keeps the normal calendar path O(1).
        if not (
            str(getattr(first, "feeder_story_key", "") or "")
            or str(getattr(second, "feeder_story_key", "") or "")
        ):
            return []
        company = str(company or "").strip()
        fight = fight or {}
        is_draw = method == "Draw"
        is_title = bool(fight.get("divisional_title", fight.get("title") and not fight.get("special_belt")))
        is_main = bool(fight.get("main"))
        written = []
        for fighter, opponent, won in (
            (first, second, None if is_draw else True),
            (second, first, None if is_draw else False),
        ):
            thread = self.active_feeder_pathway(fighter)
            if not thread:
                continue
            child_company = str(thread.get("child_company", "") or "")
            parent_company = str(thread.get("parent_company", "") or "")
            if company not in {child_company, parent_company}:
                continue
            if company == child_company and not (is_title or is_main):
                continue
            key = str(getattr(fighter, "feeder_story_key", "") or "")
            result_ref = (
                f"{key}:fight:{self.story_company_key(company)}:{self.month}:{self.week}:"
                f"{getattr(opponent, 'fighter_id', '')}:{fighter.record_w}:{fighter.record_l}:{fighter.record_d}:{method}"
            )
            recent_refs = list(thread.get("recent_result_refs", []) or [])
            if result_ref in recent_refs:
                continue
            recent_refs.append(result_ref)
            thread["recent_result_refs"] = recent_refs[-8:]

            if company == child_company:
                if is_title and won is True:
                    phase = "child_champion"
                    summary = f"{fighter.name} became a champion at {child_company} by defeating {opponent.name} by {method}."
                    importance = 4
                elif won is True:
                    phase = "child_breakthrough"
                    summary = f"{fighter.name} won a featured {child_company} bout against {opponent.name} by {method}."
                    importance = 3
                elif won is None:
                    phase = "child_unresolved"
                    summary = f"{fighter.name}'s featured {child_company} bout with {opponent.name} ended in a draw."
                    importance = 3
                else:
                    phase = "child_setback"
                    summary = f"{fighter.name}'s development path hit a setback against {opponent.name} at {child_company}."
                    importance = 3
                result = self.record_feeder_pathway_transition(
                    fighter, child_company, parent_company, phase=phase, summary=summary,
                    pathway_kind=thread.get("pathway_kind", ""), importance=importance,
                    event_ref=result_ref,
                )
                if result:
                    result["child_highlight_recorded"] = True
                    written.append(result)
                continue

            parent_fights = max(0, int(thread.get("parent_fights", 0) or 0)) + 1
            thread["parent_fights"] = parent_fights
            if is_title and won is True:
                phase, status, importance = "parent_champion", "resolved", 5
                summary = (
                    f"{fighter.name} completed the pathway from {child_company} to {parent_company} champion "
                    f"by defeating {opponent.name} by {method}."
                )
            elif parent_fights == 1:
                phase, status, importance = (
                    "parent_debut_win" if won is True else "parent_debut_draw" if won is None else "parent_debut_setback",
                    "active", 4 if won is True else 3,
                )
                outcome = "won" if won is True else "drew" if won is None else "lost"
                summary = f"{fighter.name} {outcome} their {parent_company} debut against {opponent.name}."
            elif won is True and (is_main or is_title) and not thread.get("parent_breakthrough_recorded", False):
                phase, status, importance = "parent_breakthrough", "active", 4
                summary = f"{fighter.name} turned the feeder pathway into a featured {parent_company} win over {opponent.name}."
            else:
                continue
            result = self.record_feeder_pathway_transition(
                fighter, child_company, parent_company, phase=phase, status=status,
                summary=summary, resolution=summary if status == "resolved" else "",
                pathway_kind=thread.get("pathway_kind", ""), importance=importance,
                event_ref=result_ref,
            )
            if result:
                result["parent_fights"] = parent_fights
                if phase == "parent_breakthrough":
                    result["parent_breakthrough_recorded"] = True
                if status == "resolved":
                    fighter.feeder_story_key = ""
                written.append(result)
        return written

    def resolve_feeder_pathway_departure(self, fighter, company, reason):
        thread = self.active_feeder_pathway(fighter)
        if not thread or str(thread.get("parent_company", "") or "") != str(company or ""):
            return None
        child_company = str(thread.get("child_company", "") or "")
        summary = f"{fighter.name}'s pathway from {child_company} ended with departure from {company}. {reason}."
        result = self.record_feeder_pathway_transition(
            fighter, child_company, company, phase="parent_departure", status="resolved",
            importance=3, summary=summary, resolution=summary,
            pathway_kind=thread.get("pathway_kind", ""),
            event_ref=f"{fighter.feeder_story_key}:departure:{self.month}:{self.week}",
        )
        fighter.feeder_story_key = ""
        return result

    def active_breakout_run(self, fighter):
        """Resolve one live upset follow-up through its fighter-local key."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        key = str(getattr(fighter, "breakout_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        return thread if thread and thread.get("status") not in {"resolved", "abandoned"} else None

    def record_breakout_fight_story(self, company, winner, loser, method, fight, major_upset=None):
        """Connect a major upset to its bounded follow-up results without discovery scans."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not winner or not loser:
            return []
        is_draw = method == "Draw"
        winner_key = str(getattr(winner, "breakout_story_key", "") or "")
        loser_key = str(getattr(loser, "breakout_story_key", "") or "")
        upset = bool(
            major_upset if major_upset is not None
            else not is_draw and int(winner.overall) + 8 <= int(loser.overall)
        )
        if not winner_key and not loser_key and not upset:
            return []

        company = str(company or self.fighter_company_name(winner) or self.player_company_name)
        fight = fight or {}
        is_title = bool(fight.get("title") or fight.get("divisional_title") or fight.get("special_belt"))
        is_main = bool(fight.get("main"))
        participants = (
            ((winner, loser, None), (loser, winner, None))
            if is_draw else ((winner, loser, True), (loser, winner, False))
        )
        written = []
        for fighter, opponent, won in participants:
            thread = self.active_breakout_run(fighter)
            if thread is None:
                if won is not True or not upset:
                    continue
                key = self.new_breakout_run_story_key(fighter, opponent)
                if not key or self.story_thread(key):
                    continue
                origin_result_ref = (
                    f"{key}:result:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}:"
                    f"{fighter.record_w}:{fighter.record_l}:{fighter.record_d}:{method}"
                )
                gap = max(8, int(opponent.overall) - int(fighter.overall))
                status = "resolved" if is_title else "active"
                phase = "championship_shock" if is_title else "giant_slayer"
                summary = (
                    f"{fighter.name} shocked {opponent.name} by {method}, overcame a {gap}-point rating gap, "
                    + ("and captured a championship." if is_title else "and now has to prove the upset was a true arrival.")
                )
                fighter.breakout_story_key = key
                thread = self.upsert_story_thread(
                    key, "Breakout Run", status=status, phase=phase,
                    importance=5 if is_title else 4, fighters=[fighter, opponent], companies=[company],
                    origin_ref=key, beat_kind=phase, beat_ref=key, summary=summary,
                    stakes=(
                        "The championship shock is now part of the permanent record."
                        if is_title else "The next results will decide whether this was one great night or the start of a new level."
                    ),
                    resolution=summary if status == "resolved" else "",
                )
                if thread:
                    thread["origin_opponent_id"] = str(getattr(opponent, "fighter_id", "") or "")
                    thread["origin_opponent_name"] = opponent.name
                    thread["upset_gap"] = gap
                    thread["follow_up_fights"] = 0
                    thread["follow_up_wins"] = 0
                    thread["setbacks"] = 0
                    thread["recent_result_refs"] = [origin_result_ref]
                    if status == "resolved":
                        fighter.breakout_story_key = ""
                    written.append(thread)
                    self.record_world_story(
                        "Breakout", f"{fighter.name} delivers a major upset over {opponent.name}.",
                        summary, [company], [fighter.name, opponent.name],
                        importance=5 if is_title else 4,
                        fighter_ids=[fighter.fighter_id, opponent.fighter_id],
                        story_id=thread.get("story_id", ""),
                    )
                continue

            key = str(getattr(fighter, "breakout_story_key", "") or "")
            result_ref = (
                f"{key}:result:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}:"
                f"{fighter.record_w}:{fighter.record_l}:{fighter.record_d}:{method}"
            )
            recent_refs = list(thread.get("recent_result_refs", []) or [])
            if result_ref in recent_refs:
                continue
            follow_up_fights = max(0, int(thread.get("follow_up_fights", 0) or 0)) + 1
            follow_up_wins = max(0, int(thread.get("follow_up_wins", 0) or 0))
            setbacks = max(0, int(thread.get("setbacks", 0) or 0))
            status = "active"
            importance = 3
            resolution = ""
            if won is None:
                phase = "expectations_unresolved"
                summary = f"{fighter.name}'s first tests after the upset remained unresolved in a draw with {opponent.name}."
            elif won:
                follow_up_wins += 1
                if is_title:
                    phase, status, importance = "championship_arrival", "resolved", 5
                    summary = f"{fighter.name} converted the upset into a championship by defeating {opponent.name} by {method}."
                elif is_main:
                    phase, status, importance = "spotlight_confirmed", "resolved", 4
                    summary = f"{fighter.name} confirmed the breakout under main-event pressure against {opponent.name}."
                elif follow_up_wins >= 2:
                    phase, status, importance = "breakout_confirmed", "resolved", 4
                    summary = f"{fighter.name} followed the upset with {follow_up_wins} straight wins, confirming a new competitive level."
                else:
                    phase = "momentum_building"
                    summary = f"{fighter.name} followed the upset with a win over {opponent.name}; one more strong result can confirm the breakout."
            else:
                setbacks += 1
                if is_title:
                    phase, status, importance = "title_test_fell_short", "resolved", 4
                    summary = f"{fighter.name}'s post-upset rise reached a title test but ended in defeat to {opponent.name}."
                elif setbacks >= 2:
                    phase, status, importance = "run_stalled", "resolved", 3
                    summary = f"{fighter.name}'s breakout run stalled after a second follow-up defeat, this time against {opponent.name}."
                else:
                    phase = "pressure_setback"
                    summary = f"{fighter.name} lost to {opponent.name} under new post-upset expectations; the next result will define the run."
            if status == "resolved":
                resolution = summary
            result = self.upsert_story_thread(
                key, "Breakout Run", status=status, phase=phase, importance=importance,
                fighters=[fighter], companies=[company], beat_kind=phase,
                beat_ref=result_ref, summary=summary,
                stakes=(
                    "The breakout chapter has reached its competitive answer."
                    if status == "resolved" else "The fighter is still trying to turn one major upset into a sustainable rise."
                ),
                resolution=resolution,
            )
            if result:
                recent_refs.append(result_ref)
                result["recent_result_refs"] = recent_refs[-8:]
                result["follow_up_fights"] = follow_up_fights
                result["follow_up_wins"] = follow_up_wins
                result["setbacks"] = setbacks
                if status == "resolved":
                    fighter.breakout_story_key = ""
                    self.record_world_story(
                        "Breakout", f"{fighter.name}'s breakout run reaches its verdict.",
                        summary, [company], [fighter.name], importance=importance,
                        fighter_ids=[fighter.fighter_id], story_id=result.get("story_id", ""),
                    )
                written.append(result)
        return written

    def resolve_breakout_retirement(self, fighter, company):
        thread = self.active_breakout_run(fighter)
        if not thread:
            return None
        key = str(getattr(fighter, "breakout_story_key", "") or "")
        summary = f"{fighter.name}'s breakout chapter ended with retirement at a final record of {fighter.record}."
        result = self.upsert_story_thread(
            key, "Breakout Run", status="resolved", phase="retired", importance=3,
            fighters=[fighter], companies=[company] if company else [], beat_kind="retirement",
            beat_ref=f"{key}:retirement:{self.month}:{self.week}", summary=summary,
            stakes="The breakout chapter is complete.", resolution=summary,
        )
        fighter.breakout_story_key = ""
        return result

    def new_crossroads_story_key(self, fighter, opponent):
        fighter_id = str(getattr(fighter, "fighter_id", "") or "")
        opponent_id = str(getattr(opponent, "fighter_id", "") or "")
        if not fighter_id:
            return ""
        return (
            f"crossroads:{fighter_id}:{self.month}:{self.week}:{opponent_id}:"
            f"{fighter.record_w}:{fighter.record_l}:{fighter.record_d}"
        )

    def active_crossroads_story(self, fighter):
        """Resolve one live decline chapter through its fighter-local key."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not fighter:
            return None
        key = str(getattr(fighter, "crossroads_story_key", "") or "")
        thread = self.story_thread(key) if key else None
        return thread if thread and thread.get("status") not in {"resolved", "abandoned"} else None

    def record_crossroads_fight_story(self, company, winner, loser, method, fight):
        """Turn an established fighter's third straight loss into one bounded chapter."""
        if getattr(self, "narrative_tracking_enabled", True) is False or not winner or not loser:
            return []
        is_draw = method == "Draw"
        winner_key = str(getattr(winner, "crossroads_story_key", "") or "")
        loser_key = str(getattr(loser, "crossroads_story_key", "") or "")
        if is_draw and not winner_key and not loser_key:
            return []
        if not is_draw and not winner_key and not loser_key:
            loser_established = (
                int(getattr(loser, "age", 0) or 0) >= 30
                or int(getattr(loser, "record_w", 0) or 0)
                + int(getattr(loser, "record_l", 0) or 0)
                + int(getattr(loser, "record_d", 0) or 0) >= 18
                or int(getattr(loser, "popularity", 0) or 0) >= 45
            )
            if not loser_established:
                return []

        company = str(company or self.fighter_company_name(winner) or self.player_company_name)
        fight = fight or {}
        is_title = bool(fight.get("title") or fight.get("divisional_title") or fight.get("special_belt"))
        participants = (
            ((winner, loser, None), (loser, winner, None))
            if is_draw else ((winner, loser, True), (loser, winner, False))
        )
        written = []
        for fighter, opponent, won in participants:
            thread = self.active_crossroads_story(fighter)
            if thread is None:
                if won is not False:
                    continue
                established = (
                    int(getattr(fighter, "age", 0) or 0) >= 30
                    or int(getattr(fighter, "record_w", 0) or 0)
                    + int(getattr(fighter, "record_l", 0) or 0)
                    + int(getattr(fighter, "record_d", 0) or 0) >= 18
                    or int(getattr(fighter, "popularity", 0) or 0) >= 45
                )
                if not established:
                    continue
                loss_streak = self.in_universe_loss_streak(fighter, limit=4)
                if loss_streak < 3:
                    continue
                key = self.new_crossroads_story_key(fighter, opponent)
                if not key or self.story_thread(key):
                    continue
                result_ref = (
                    f"{key}:result:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}:"
                    f"{fighter.record_w}:{fighter.record_l}:{fighter.record_d}:{method}"
                )
                summary = (
                    f"{fighter.name}'s third consecutive loss, against {opponent.name}, has turned poor form "
                    "into a career crossroads."
                )
                fighter.crossroads_story_key = key
                thread = self.upsert_story_thread(
                    key, "Career Crossroads", status="active", phase="decline_pressure", importance=4,
                    fighters=[fighter, opponent], companies=[company], origin_ref=key,
                    beat_kind="third_straight_loss", beat_ref=key, summary=summary,
                    stakes="A recovery win, reinvention, release, or retirement will define the next chapter.",
                )
                if thread:
                    thread["origin_opponent_id"] = str(getattr(opponent, "fighter_id", "") or "")
                    thread["origin_opponent_name"] = opponent.name
                    thread["losses_at_origin"] = loss_streak
                    thread["crossroads_fights"] = 0
                    thread["follow_up_losses"] = 0
                    thread["reinventions"] = 0
                    thread["recent_result_refs"] = [result_ref]
                    written.append(thread)
                    self.record_world_story(
                        "Career Crossroads", f"{fighter.name} reaches a career crossroads.", summary,
                        [company], [fighter.name, opponent.name], importance=4,
                        fighter_ids=[fighter.fighter_id, opponent.fighter_id],
                        story_id=thread.get("story_id", ""),
                    )
                continue

            key = str(getattr(fighter, "crossroads_story_key", "") or "")
            result_ref = (
                f"{key}:result:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}:"
                f"{fighter.record_w}:{fighter.record_l}:{fighter.record_d}:{method}"
            )
            recent_refs = list(thread.get("recent_result_refs", []) or [])
            if result_ref in recent_refs:
                continue
            crossroads_fights = max(0, int(thread.get("crossroads_fights", 0) or 0)) + 1
            follow_up_losses = max(0, int(thread.get("follow_up_losses", 0) or 0))
            status, importance, resolution = "active", 3, ""
            if won is None:
                phase = "uncertain_draw"
                summary = f"{fighter.name}'s crossroads remained unresolved after a draw with {opponent.name}."
            elif won:
                phase = "championship_return" if is_title else "recovery_win"
                status, importance = "resolved", 5 if is_title else 4
                summary = (
                    f"{fighter.name} answered the losing run by defeating {opponent.name}"
                    + (" and winning a championship." if is_title else f" by {method}.")
                )
                resolution = summary
            else:
                follow_up_losses += 1
                chapter_losses = int(thread.get("losses_at_origin", 3) or 3) + follow_up_losses
                phase = "last_chance" if chapter_losses >= 5 else "decline_deepens"
                summary = (
                    f"{fighter.name}'s decline deepened after defeat to {opponent.name}; "
                    f"{chapter_losses} losses now define the crossroads chapter."
                )
            result = self.upsert_story_thread(
                key, "Career Crossroads", status=status, phase=phase, importance=importance,
                fighters=[fighter, opponent], companies=[company], beat_kind=phase,
                beat_ref=result_ref, summary=summary,
                stakes=("The crossroads has reached its competitive answer." if status == "resolved"
                        else "The next result or career decision may determine whether the fighter can continue."),
                resolution=resolution,
            )
            if result:
                recent_refs.append(result_ref)
                result["recent_result_refs"] = recent_refs[-8:]
                result["crossroads_fights"] = crossroads_fights
                result["follow_up_losses"] = follow_up_losses
                if status == "resolved":
                    fighter.crossroads_story_key = ""
                    self.record_world_story(
                        "Career Crossroads", f"{fighter.name}'s crossroads reaches a verdict.", summary,
                        [company], [fighter.name, opponent.name], importance=importance,
                        fighter_ids=[fighter.fighter_id, opponent.fighter_id],
                        story_id=result.get("story_id", ""),
                    )
                written.append(result)
        return written

    def record_crossroads_reinvention(self, fighter, company, old_weight, new_weight):
        thread = self.active_crossroads_story(fighter)
        if not thread:
            return None
        key = str(getattr(fighter, "crossroads_story_key", "") or "")
        event_ref = f"{key}:weight:{self.month}:{old_weight}:{new_weight}"
        if any(str(beat.get("ref", "") or "") == event_ref for beat in thread.get("beats", [])):
            return thread
        summary = f"{fighter.name} responded to the losing run by moving from {old_weight} to {new_weight}."
        result = self.upsert_story_thread(
            key, "Career Crossroads", status="active", phase="division_reinvention", importance=4,
            fighters=[fighter], companies=[company] if company else [], beat_kind="division_reinvention",
            beat_ref=event_ref, summary=summary,
            stakes="The first result in the new division will decide whether the reinvention worked.",
        )
        if result:
            result["reinventions"] = max(0, int(thread.get("reinventions", 0) or 0)) + 1
        return result

    def resolve_crossroads_departure(self, fighter, company, outcome="released", reason=""):
        thread = self.active_crossroads_story(fighter)
        if not thread:
            return None
        key = str(getattr(fighter, "crossroads_story_key", "") or "")
        phase = "retired" if outcome == "retired" else "released"
        verb = "retired" if phase == "retired" else f"left {company or 'their promotion'}"
        summary = f"{fighter.name}'s career crossroads ended when they {verb}."
        if reason:
            summary += f" {reason}"
        result = self.upsert_story_thread(
            key, "Career Crossroads", status="resolved", phase=phase, importance=3,
            fighters=[fighter], companies=[company] if company else [], beat_kind=phase,
            beat_ref=f"{key}:{phase}:{self.month}:{self.week}", summary=summary,
            stakes="The crossroads chapter is complete.", resolution=summary,
        )
        fighter.crossroads_story_key = ""
        if result:
            self.record_world_story(
                "Career Crossroads", f"{fighter.name}'s crossroads reaches a verdict.", summary,
                [company] if company else [], [fighter.name], importance=3,
                fighter_ids=[fighter.fighter_id], story_id=result.get("story_id", ""),
            )
        return result

    def record_injury_return_result(self, company, fighter, opponent, won, method):
        key = self.injury_story_key(fighter)
        thread = self.story_thread(key)
        if not thread or thread.get("status") in {"resolved", "abandoned"} or thread.get("phase") != "return_pending":
            return None
        outcome = (
            f"{fighter.name} won their first fight back against {opponent.name} by {method}."
            if won else f"{fighter.name}'s first fight back ended in defeat against {opponent.name}."
        )
        resolved = self.upsert_story_thread(
            key, "Injury Comeback", status="resolved", phase="return_complete", importance=4 if won else 3,
            fighters=[fighter, opponent], companies=[company], beat_kind="return_result",
            beat_ref=f"{key}:return:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
            summary=outcome, stakes="The medical comeback has reached its competitive payoff.",
            resolution=outcome,
        )
        self.record_world_story(
            "Injury Comeback", outcome, f"Return from {thread.get('injury', 'a serious injury')}.",
            companies=[company], fighters=[fighter.name, opponent.name], importance=4 if won else 3,
            fighter_ids=[fighter.fighter_id, opponent.fighter_id],
            story_id=resolved.get("story_id", "") if resolved else "",
        )
        return resolved

    def record_comeback_contract_story(self, fighter, *, farewell=False, fights=1, company=""):
        key = self.comeback_story_key(fighter)
        if not key:
            return None
        company = company or self.player_company_name
        summary = (
            f"{fighter.name} signed for one final farewell fight."
            if farewell else f"{fighter.name} returned on a {max(1, int(fights or 1))}-fight comeback commitment."
        )
        return self.upsert_story_thread(
            key, "Comeback", status="active", phase="farewell_booked" if farewell else "contracted",
            importance=4, fighters=[fighter], companies=[company],
            origin_ref=f"{key}:contract:{self.month}:{self.week}",
            beat_kind="comeback_contract", beat_ref=f"{key}:contract:{self.month}:{self.week}",
            summary=summary,
            stakes=("One final result will close the fighter's career." if farewell else "The guaranteed fights will determine whether the return becomes a real second chapter."),
        )

    def record_comeback_fight_result(self, company, fighter, opponent, won, method):
        key = self.comeback_story_key(fighter)
        thread = self.story_thread(key)
        if not thread or thread.get("status") in {"resolved", "abandoned"}:
            return None
        completed = max(0, int(getattr(fighter, "contract_fights_completed", 0) or 0))
        guaranteed = max(0, int(getattr(fighter, "guaranteed_fights", 0) or 0))
        result = "won" if won else "lost"
        commitment_complete = guaranteed > 0 and completed >= guaranteed and not getattr(fighter, "comeback_contract", False)
        phase = "commitment_complete" if commitment_complete else "comeback_active"
        stakes = (
            "The agreed comeback is complete; another deal or a farewell decision is now required."
            if commitment_complete else f"Comeback commitment progress: {completed}/{guaranteed or '?'} fights."
        )
        return self.upsert_story_thread(
            key, "Comeback", status="active", phase=phase, importance=4,
            fighters=[fighter, opponent], companies=[company], beat_kind="comeback_fight",
            beat_ref=f"{key}:fight:{self.month}:{self.week}:{getattr(opponent, 'fighter_id', '')}",
            summary=f"{fighter.name} {result} a comeback fight against {opponent.name} by {method}.",
            stakes=stakes,
        )

    def record_title_chase_story(self, company, contender, champion=None, source="Contender surge"):
        if getattr(self, "_seeding_universe", False):
            return None
        summary = f"{contender.name} emerged as a championship contender"
        if champion:
            summary += f" and called for {champion.name}"
        summary += "."
        ref = f"{self.title_chase_story_key(company, contender)}:emerged:{self.month}:{self.week}"
        return self.upsert_story_thread(
            self.title_chase_story_key(company, contender), "Title Chase",
            status="active", phase="contender", importance=3,
            fighters=[contender] + ([champion] if champion else []), companies=[company],
            origin_ref=ref, stakes="The contender is trying to turn current form into a legitimate title opportunity.",
            beat_kind="contender_surge", beat_ref=ref, summary=summary,
        )

    def record_title_story_result(
        self, company, winner, loser, method, *, defense=False, loser_was_champion=False,
        title_label="divisional championship",
    ):
        """Advance title chase/reign threads from an already-settled title fight."""
        company = str(company or "World")
        result_ref = (
            f"title-result:{self.story_company_key(company)}:{self.month}:{self.week}:"
            f"{getattr(winner, 'fighter_id', '')}:{getattr(loser, 'fighter_id', '')}:{method}"
        )
        if loser_was_champion and loser is not winner:
            old_key = self.title_reign_story_key(company, loser)
            old_thread = self.upsert_story_thread(
                old_key, "Championship Reign", status="resolved", phase="reign_ended", importance=4,
                fighters=[loser, winner], companies=[company], beat_kind="title_loss",
                beat_ref=f"{result_ref}:old-reign", summary=f"{loser.name}'s reign ended against {winner.name} by {method}.",
                stakes="The previous championship era has ended.",
                resolution=f"{winner.name} ended {loser.name}'s reign by {method}.",
            )
            if old_thread:
                old_thread["resolution"] = f"{winner.name} ended {loser.name}'s reign by {method}."

        if defense:
            phase = "established_reign" if getattr(winner, "title_defenses", 0) >= 3 else "reign"
            summary = f"{winner.name} defended the {title_label} against {loser.name} by {method}."
            stakes = f"The reign continues with {getattr(winner, 'title_defenses', 0)} recorded defense(s)."
            story_type = "Title Defense"
        else:
            phase = "new_champion"
            summary = f"{winner.name} won the {title_label} from {loser.name} by {method}."
            stakes = "A new championship reign has begun."
            story_type = "Title Change"
        reign = self.upsert_story_thread(
            self.title_reign_story_key(company, winner), "Championship Reign",
            status="active", phase=phase, importance=4, fighters=[winner, loser], companies=[company],
            origin_ref=result_ref, stakes=stakes, beat_kind="title_defense" if defense else "title_win",
            beat_ref=f"{result_ref}:winner-reign", summary=summary,
        )

        academy_key = self.academy_lineage_story_key(winner)
        if getattr(winner, "academy_graduate", False) and self.story_thread(academy_key):
            self.upsert_story_thread(
                academy_key, "Academy Lineage", status="resolved", phase="homegrown_champion", importance=5,
                fighters=[winner, loser], companies=[company], beat_kind="academy_title_win",
                beat_ref=f"{result_ref}:academy-champion",
                summary=f"Academy graduate {winner.name} completed the path from youth development to champion.",
                stakes="The academy pathway has produced its defining senior payoff.",
                resolution=f"{winner.name} became a homegrown champion for {company}.",
            )

        chase_key = self.title_chase_story_key(company, winner)
        if self.story_thread(chase_key):
            self.upsert_story_thread(
                chase_key, "Title Chase", status="resolved", phase="champion", importance=4,
                fighters=[winner, loser], companies=[company], beat_kind="title_win",
                beat_ref=f"{result_ref}:chase-won", summary=summary,
                stakes="The title chase reached its payoff.", resolution=f"{winner.name} became champion.",
            )
        losing_chase_key = self.title_chase_story_key(company, loser)
        if self.story_thread(losing_chase_key):
            self.upsert_story_thread(
                losing_chase_key, "Title Chase", status="cooling", phase="setback", importance=3,
                fighters=[loser, winner], companies=[company], beat_kind="title_loss",
                beat_ref=f"{result_ref}:chase-lost",
                summary=f"{loser.name}'s title challenge ended in defeat against {winner.name}.",
                stakes="The failed challenger must rebuild before another credible opportunity.",
            )
        self.record_world_story(
            story_type, summary, stakes, companies=[company], fighters=[winner.name, loser.name],
            importance=4 if not defense else 3,
            fighter_ids=[winner.fighter_id, loser.fighter_id],
            story_id=reign.get("story_id", "") if reign else "",
        )
        return reign

    def record_redemption_story_result(self, company, winner, loser, method, fight, *, loser_was_champion=False):
        """Open or pay off one direct-key redemption thread after a real result."""
        self.record_injury_return_result(company, winner, loser, True, method)
        self.record_injury_return_result(company, loser, winner, False, method)
        self.record_comeback_fight_result(company, winner, loser, True, method)
        self.record_comeback_fight_result(company, loser, winner, False, method)
        winner_key = self.redemption_story_key(winner)
        winner_thread = self.story_thread(winner_key)
        result_ref = (
            f"redemption-result:{self.month}:{self.week}:{getattr(winner, 'fighter_id', '')}:"
            f"{getattr(loser, 'fighter_id', '')}:{method}"
        )
        if winner_thread and winner_thread.get("status") not in {"resolved", "abandoned"}:
            resolved = self.upsert_story_thread(
                winner_key, "Redemption", status="resolved", phase="redeemed", importance=3,
                fighters=[winner, loser], companies=[company], beat_kind="comeback_win",
                beat_ref=f"{result_ref}:redeemed",
                summary=f"{winner.name} answered their setback by defeating {loser.name} by {method}.",
                stakes="The comeback produced a meaningful competitive answer.",
                resolution=f"{winner.name} returned to winning form against {loser.name}.",
            )
            self.record_world_story(
                "Redemption", f"{winner.name} completes a comeback win.",
                resolved.get("resolution", "") if resolved else "",
                companies=[company], fighters=[winner.name, loser.name], importance=3,
                fighter_ids=[winner.fighter_id, loser.fighter_id],
                story_id=resolved.get("story_id", "") if resolved else "",
            )

        loser_key = self.redemption_story_key(loser)
        existing = self.story_thread(loser_key)
        upset = winner.overall + 5 < loser.overall or winner.popularity + 15 < loser.popularity
        if existing and existing.get("status") not in {"resolved", "abandoned"}:
            self.upsert_story_thread(
                loser_key, "Redemption", status="active", phase="deeper_setback", importance=3,
                fighters=[loser, winner], companies=[company], beat_kind="setback",
                beat_ref=f"{result_ref}:setback",
                summary=f"{loser.name}'s rebuild suffered another setback against {winner.name}.",
                stakes="Another defeat has made the route back more difficult.",
            )
        elif loser_was_champion or upset:
            cause = "lost the championship" if loser_was_champion else "suffered a major upset"
            self.upsert_story_thread(
                loser_key, "Redemption", status="active", phase="setback", importance=3,
                fighters=[loser, winner], companies=[company], origin_ref=f"{result_ref}:opened",
                beat_kind="setback", beat_ref=f"{result_ref}:opened",
                summary=f"{loser.name} {cause} against {winner.name} by {method}.",
                stakes="The next meaningful appearance will show whether the fighter can rebuild.",
            )

    def record_world_story(self, story_type, headline, detail="", companies=None, fighters=None, importance=1, fighter_ids=None, story_id=""):
        entry = {
            "month": self.month, "week": self.week, "year": GAME_START_YEAR + (self.month - 1) // 12,
            "type": story_type, "headline": headline, "detail": detail,
            "companies": companies or [], "fighters": fighters or [], "importance": importance,
        }
        if fighter_ids:
            entry["fighter_ids"] = list(fighter_ids)
        if story_id:
            entry["story_id"] = str(story_id)
            self.ensure_story_thread_index()
            thread = self._story_thread_id_index.get(str(story_id))
            if thread:
                from narrative_presentation import chapter_context
                entry["narrative_context"] = chapter_context(thread)
        self.world_chronicle = [entry] + list(getattr(self, "world_chronicle", []))
        self.world_chronicle = self.world_chronicle[:800]
        return entry

    def staff_skill(self, role):
        weighted = []
        for member in getattr(self, "staff", []) or []:
            if not isinstance(member, dict) or member.get("role") != role:
                continue
            try:
                skill = int(member.get("skill", 45) or 45) if not isinstance(member.get("skill", 45), bool) else 45
            except (TypeError, ValueError, OverflowError):
                skill = 45
            try:
                morale = int(member.get("morale", 65) or 65) if not isinstance(member.get("morale", 65), bool) else 65
            except (TypeError, ValueError, OverflowError):
                morale = 65
            weighted.append(skill * (0.72 + morale / 230))
        if not weighted:
            return 45
        return max(weighted)

    def staff_effect(self, role, scale=1.0):
        """Small but persistent player-staff impact; quality never becomes an auto-win."""
        return max(-2.0, min(12.0, (self.staff_skill(role) - 50) * 0.16 * scale))

    def staff_negotiation_discount(self, role="Talent Relations", base=2600):
        """Translate the existing staff leverage into a bounded target discount."""
        base = max(0, int(base or 0))
        quality = max(0.0, self.staff_effect(role))
        return round(base * min(1.0, quality / 12.0))

    def staff_negotiation_administration_saving(self, base=2600):
        """Return the Contract Administrator's post-modifier saving only.

        Keeping this separate from staff leverage means the approved 2% is
        applied after the existing negotiation modifier rather than being
        swallowed by its cap.  It is a target-basis saving, never fighter pay.
        """
        base = max(0, int(base or 0))
        reduction_fn = getattr(self, "staff_specialty_cost_reduction", None)
        return reduction_fn(
            "Talent Relations", base, cost_type="negotiation_administration",
        ) if callable(reduction_fn) else 0

    def staff_role_info(self, role):
        role_key = role if isinstance(role, str) else "Operations"
        return STAFF_ROLE_EFFECTS.get(role_key, {
            "label": role_key or "Operations",
            "summary": "Supports the promotion's daily operations.",
            "metric": "General operations",
        })

    def staff_contract_remaining(self, member):
        """Return a bounded remaining-term projection without rewriting evidence.

        Legacy staff rows can carry a malformed term (for example ``"unknown"``)
        while the calendar worker is waiting for an explicit review.  Contract
        readers and Academy Coach assignment checks must remain usable in that
        state; treating the term as unavailable/expired for display is safer
        than raising during a page refresh or accidentally granting active
        access.  The raw value is left untouched for the audit and repair
        boundary.
        """
        if not isinstance(member, dict):
            return 0
        raw = member.get("contract_months", STAFF_CONTRACT_DEFAULT_MONTHS)
        if isinstance(raw, bool):
            return 0
        if raw is None or raw == "":
            return 0
        try:
            return max(0, int(raw))
        except (TypeError, ValueError, OverflowError):
            return 0

    def staff_contract_status(self, member):
        months = self.staff_contract_remaining(member)
        if months <= 0:
            return "EXPIRED"
        if months == 1:
            return "Final month"
        if months <= 3:
            return "Expiring soon"
        return "Active"

    def staff_contract_expiry_label(self, member):
        months = self.staff_contract_remaining(member)
        if months <= 0:
            return "Expired"
        return self.format_game_date(self.month + months, 1)

    def staff_contract_target(self, member, existing=False):
        """Return the monthly salary a staff member considers a fair deal."""
        if not isinstance(member, dict):
            return 3500

        def safe_int(value, default):
            if isinstance(value, bool) or value is None or value == "":
                return default
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return default

        salary = max(3500, safe_int(member.get("salary", 3500), 3500))
        reputation = max(0, safe_int(member.get("reputation", 50), 50))
        role = member.get("role")
        staff_rows = getattr(self, "staff", []) or []
        scarcity_count = sum(
            1 for item in staff_rows
            if isinstance(item, dict) and item.get("role") == role
        )
        scarcity = 1.08 if scarcity_count <= 1 else 1.0
        loyalty = 0.97 if existing else 1.0
        return max(3500, round(salary * (1.02 + reputation / 1800) * scarcity * loyalty / 100) * 100)

    def staff_contract_offer_score(self, member, salary, months, existing=False):
        target = self.staff_contract_target(member, existing=existing)
        def safe_int(value, default=0):
            if isinstance(value, bool) or value is None or value == "":
                return default
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return default

        salary_score = max(0.0, min(72.0, (safe_int(salary) / max(1, target)) * 58))
        term_score = min(18.0, max(0, safe_int(months)) / 3.2)
        relationship = 8.0 if existing else 0.0
        reputation_value = safe_int(member.get("reputation", 50), 50) if isinstance(member, dict) else 50
        heat_value = safe_int(member.get("negotiation_heat", 0)) if isinstance(member, dict) else 0
        reputation = max(0, min(8.0, reputation_value / 12))
        heat = max(0.0, heat_value / 12)
        return max(0.0, min(100.0, salary_score + term_score + relationship + reputation - heat))

    def apply_staff_contract(self, member, salary, months, existing=False):
        if not isinstance(member, dict):
            return None
        salary = max(3500, int(salary))
        months = max(STAFF_CONTRACT_MIN_MONTHS, min(STAFF_CONTRACT_MAX_MONTHS, int(months)))
        member["salary"] = salary
        member["contract_months"] = months
        member["contract_start_month"] = self.month
        member["contract_expiry_month"] = self.month + months
        member["contract_type"] = "Exclusive"
        raw_heat = member.get("negotiation_heat", 0)
        try:
            heat = int(raw_heat or 0) if not isinstance(raw_heat, bool) else 0
        except (TypeError, ValueError):
            heat = 0
        raw_morale = member.get("morale", 65)
        try:
            morale = int(raw_morale or 65) if not isinstance(raw_morale, bool) else 65
        except (TypeError, ValueError):
            morale = 65
        member["negotiation_heat"] = max(0, heat - 12)
        member["morale"] = min(100, morale + 4)
        return member

    def staff_member_busy(self, member):
        if not isinstance(member, dict):
            return False
        if member.get("role") != "Scout" or not hasattr(self, "scout_workload"):
            return False
        return self.scout_workload(member) > 0

    def check_staff_contract_warnings(self):
        """Create actionable inbox warnings before staff deals lapse."""
        for member in getattr(self, "staff", []):
            if not isinstance(member, dict):
                continue
            months = self.staff_contract_remaining(member)
            if months not in (3, 1):
                continue
            when = "one month" if months == 1 else "three months"
            raw_salary = member.get("salary", 0)
            try:
                salary = 0 if isinstance(raw_salary, bool) else int(raw_salary or 0)
            except (TypeError, ValueError, OverflowError):
                salary = 0
            self.inbox.append({
                "subject": f"Staff Contract Expiring - {member.get('name', 'Staff')}",
                "body": (f"{member.get('name', 'Staff')} ({member.get('role', 'Operations')}) has {when} left on a "
                         f"${salary:,}/month deal. Open Staff and negotiate before they leave."),
                "type": "Staff", "resolved": False,
            })
            self.news.insert(0, f"Staff contract notice: {member.get('name', 'Staff')} expires in {when}.")
            self.record_staff_tenure_story(
                member, phase="final_month" if months == 1 else "renewal_window",
                summary=(
                    f"{member.get('name', 'Staff')} entered the final month of their "
                    f"{member.get('role', 'operations')} contract."
                    if months == 1 else
                    f"{member.get('name', 'Staff')}'s {member.get('role', 'operations')} renewal window opened."
                ),
                importance=3 if months == 1 else 2,
                event_ref=f"staff-contract-warning:{member.get('staff_id', '')}:{months}:{self.month}",
            )

    def update_staff_contracts(self):
        """Tick staff terms and release expired staff after active assignments finish."""
        departing = []
        for member in list(getattr(self, "staff", [])):
            if not isinstance(member, dict):
                # Keep malformed legacy rows available for the employment
                # audit; a calendar tick must never reinterpret a row or
                # route its departure through another employee's identity.
                continue
            has_term = "contract_months" in member
            raw_term = member.get("contract_months", STAFF_CONTRACT_DEFAULT_MONTHS)
            if has_term and (isinstance(raw_term, bool) or raw_term is None or raw_term == ""):
                raw_term_invalid = True
            else:
                try:
                    int(raw_term)
                    raw_term_invalid = False
                except (TypeError, ValueError):
                    raw_term_invalid = True
            if raw_term_invalid:
                review_key = f"staff-contract-malformed:{member.get('staff_id', '')}:{self.month}:{self.week}"
                existing_notice = any(
                    isinstance(row, dict) and row.get("reference") == review_key
                    for row in getattr(self, "inbox", [])
                )
                member["contract_review_required"] = True
                if not existing_notice:
                    self.inbox.append({
                        "subject": "Staff Contract Needs Review",
                        "body": (f"{member.get('name', 'Staff')}'s contract term is malformed and was not ticked. "
                                 "Review the retained deal before renewing or releasing this employee."),
                        "type": "Staff", "resolved": False, "reference": review_key,
                    })
                continue
            months = self.staff_contract_remaining(member) - 1
            member["contract_months"] = months
            if months > 0:
                continue
            finite_scout_work = (
                member.get("role") == "Scout" and hasattr(self, "scout_workload")
                and self.scout_workload(member, include_active_academy=False) > 0
            )
            staff_busy = getattr(self, "staff_member_busy", lambda _member: False)
            if finite_scout_work or (member.get("role") != "Scout" and staff_busy(member)):
                member["contract_months"] = 1
                self.inbox.append({
                    "subject": f"Staff Deal Extended - {member.get('name', 'Scout')}",
                    "body": f"{member.get('name', 'Scout')}'s contract reached expiry while an active scouting assignment was running. The deal is held for one month so the report can finish.",
                    "type": "Staff", "resolved": False,
                })
                continue
            departing.append(member)
        for member in departing:
            if member.get("role") == "Scout" and self.academy_network_uses_scout(member):
                cancelled, detail = self.cancel_academy_network()
                if cancelled:
                    self.inbox.append({
                        "subject": f"Academy Network Closed - {member.get('name', 'Scout')}",
                        "body": f"The assigned scout's contract ended. {detail}",
                        "type": "Scouting", "resolved": False,
                    })
            if member.get("role") == "Academy Coach":
                academy = self.repair_academy(getattr(self, "academy", {}))
                assignment = self.academy_coach_assignment(academy)
                if str(assignment.get("staff_id", "")) == str(member.get("staff_id", "")):
                    prospect_name = next((item.get("name", "the assigned prospect") for item in academy.get("prospects", [])
                                          if str(item.get("prospect_id", "")) == str(assignment.get("prospect_id", ""))), "the assigned prospect")
                    academy["coach_assignment"] = {}
                    academy["coach_assignment_review"] = (
                        f"{member.get('name', 'The Academy Coach')} left after contract expiry while supervising {prospect_name}. "
                        "Review the active block before assigning a replacement."
                    )
                    self.inbox.append({
                        "subject": "Academy Coach Assignment Needs Review",
                        "body": academy["coach_assignment_review"], "type": "Academy", "resolved": False,
                    })
            self.staff.remove(member)
            self.inbox.append({
                "subject": f"Staff Contract Ended - {member.get('name', 'Staff')}",
                "body": f"{member.get('name', 'Staff')} ({member.get('role', 'Operations')}) left after their staff contract expired.",
                "type": "Staff", "resolved": False,
            })
            self.news.insert(0, f"{member.get('name', 'Staff')} left after their staff contract expired.")
            departure = (
                f"{member.get('name', 'Staff')} left {self.player_company_name} after their "
                f"{member.get('role', 'operations')} contract expired."
            )
            self.record_staff_tenure_story(
                member, phase="contract_expired", status="resolved", importance=3,
                summary=departure, resolution=departure,
                event_ref=f"staff-contract-expired:{member.get('staff_id', '')}:{self.month}:{self.week}",
            )
        payroll = 0
        for item in getattr(self, "staff", []) or []:
            if not isinstance(item, dict):
                continue
            raw_salary = item.get("salary", 0)
            try:
                salary = 0 if isinstance(raw_salary, bool) else int(raw_salary or 0)
            except (TypeError, ValueError):
                salary = 0
            payroll += max(0, salary)
        self.finance["staff_payroll"] = payroll

    @staticmethod
    def _legacy_staff_identity(scope, member):
        """Return a stable ID seed for an ID-less retained staff row.

        Compatibility repair runs at load/startup boundaries, but it must not
        make the employee identity depend on the row's current list position.
        Keep the seed to retained employment facts that are stable across
        contract ticking; the caller adds a deterministic suffix only when the
        source contains an exact duplicate.
        """
        if not isinstance(member, dict):
            return f"{scope}|opaque|{type(member).__name__}"
        identity = {
            "scope": str(scope or "staff"),
            "name": str(member.get("name", "") or ""),
            "role": str(member.get("role", "") or ""),
            "contract_type": str(member.get("contract_type", "") or ""),
            "contract_start_month": member.get("contract_start_month", ""),
        }
        return json.dumps(identity, sort_keys=True, separators=(",", ":"), default=str)

    def ensure_staff_profiles(self):
        specialty_by_role = {
            "Scout": "Prospect eye", "Doctor": "Injury prevention", "Marketing": "Regional campaigns",
            "Matchmaker": "Contender logic", "Drug Testing Officer": "Compliance",
            "Broadcast Producer": "Live production", "Talent Relations": "Contract trust",
            "Academy Coach": "Development blocks",
        }
        current_month = max(1, int(getattr(self, "month", 1) or 1))
        staff_groups = (
            ("staff", list(getattr(self, "staff", []) or [])),
            ("candidate", list(getattr(self, "staff_candidates", []) or [])),
        )
        seen_ids = set()
        for scope, members in staff_groups:
            for member in members:
                if not isinstance(member, dict):
                    continue
                raw_role = member.get("role")
                role_key = raw_role if isinstance(raw_role, str) else ""
                raw_skill = member.get("skill", 50)
                if isinstance(raw_skill, bool):
                    skill_value = 50
                else:
                    try:
                        skill_value = int(raw_skill)
                    except (TypeError, ValueError):
                        skill_value = 50
                staff_id = str(member.get("staff_id", "") or "")
                if not staff_id or staff_id in seen_ids:
                    identity = self._legacy_staff_identity(scope, member)
                    digest = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:16]
                    staff_id = f"STF-{digest}"
                    suffix = 1
                    while staff_id in seen_ids:
                        digest = hashlib.sha256(f"{identity}|{suffix}".encode("utf-8")).hexdigest()[:16]
                        staff_id = f"STF-{digest}"
                        suffix += 1
                    member["staff_id"] = staff_id
                seen_ids.add(staff_id)
                # Compatibility repair must be stable and must not advance the
                # simulation RNG merely because an older save lacks staff detail.
                profile_seed = int(hashlib.sha256(staff_id.encode("utf-8")).hexdigest()[:16], 16)
                profile_rng = random.Random(profile_seed)
                member.setdefault("specialty", specialty_by_role.get(role_key, "Operations"))
                member.setdefault("reputation", max(35, min(95, skill_value + profile_rng.randint(-8, 6))))
                member.setdefault("contract_months", STAFF_CONTRACT_DEFAULT_MONTHS)
                member.setdefault("contract_type", "Exclusive")
                member.setdefault("contract_start_month", max(1, current_month - 1))
                member.setdefault("contract_expiry_month", current_month + self.staff_contract_remaining(member))
                member.setdefault("staff_story_key", "")
                raw_milestones = member.get("staff_milestone_kinds", [])
                member["staff_milestone_kinds"] = list(dict.fromkeys(
                    str(value) for value in raw_milestones if value
                ))[:12] if isinstance(raw_milestones, list) else []
                try:
                    staff_legacy_score = int(member.get("staff_legacy_score", 0) or 0)
                except (TypeError, ValueError):
                    staff_legacy_score = 0
                member["staff_legacy_score"] = max(0, min(100, staff_legacy_score))
                member.setdefault("negotiation_heat", 0)
                if role_key == "Scout":
                    skill = skill_value
                    for key, offset in (("fighter_judging", 0), ("potential_judging", -2), ("efficiency", 1), ("regional_knowledge", -3), ("networking", -1), ("reliability", 2), ("negotiation", -4), ("professionalism", 1)):
                        member.setdefault(key, max(25, min(95, skill + offset + profile_rng.randint(-7, 7))))

    def promotion_strategy(self, promo):
        if not getattr(promo, "strategy", None):
            promo.strategy = self.seed_promotion_strategy(promo.name, getattr(promo, "show_personality", "Balanced"))
        promo.strategy.setdefault("growth_ceiling", self.seed_promotion_strategy(promo.name, getattr(promo, "show_personality", "Balanced")).get("growth_ceiling", 76))
        return promo.strategy

    def promotion_strategy_read_model(self, promo):
        """Return saved promotion strategy facts without migration writes.

        Profile, standings and child-manager readers must not seed a missing
        strategy or add compatibility defaults just because a row was opened.
        Gameplay/calendar owners continue to use ``promotion_strategy`` when a
        strategy is explicitly needed for simulation or an action.
        """
        raw = getattr(promo, "strategy", {}) if promo is not None else {}
        return deepcopy(raw) if isinstance(raw, dict) else {}

    def rival_academy_program(self, promo, *, repair=True):
        """Return rival youth-program state, optionally without save repair.

        Calendar progression and explicit academy actions use the repairing
        default. The Academy rival-program table is a reader, so it requests
        ``repair=False`` and receives a defensive projection when an older
        promotion has no youth-program block yet.
        """
        strategy = self.promotion_strategy(promo) if repair else self.promotion_strategy_read_model(promo)
        program = strategy.get("youth_academy")
        if isinstance(program, dict) and not repair:
            program = deepcopy(program)
        if not isinstance(program, dict):
            stable = int(hashlib.sha256(f"academy|{promo.name}".encode("utf-8")).hexdigest()[:12], 16)
            philosophies = ("Balanced MMA", "Striking Academy", "Wrestling Pipeline", "Submission School", "Athletic Development")
            level = max(1, min(5, 1 + int(getattr(promo, "size", 35) or 35) // 25))
            program = {
                "name": f"{promo.name} Youth Programme", "level": level,
                "philosophy": philosophies[stable % len(philosophies)],
                "reputation": max(10, min(90, round((getattr(promo, "reputation_score", 40) + getattr(promo, "size", 35)) / 2))),
                "region": getattr(promo, "region", "USA"), "prospects": [],
                "graduates": 0, "intakes": 0, "last_intake_month": 0,
                "last_graduate": "", "poached_leads": 0,
            }
            if repair:
                strategy["youth_academy"] = program
        for key, default in {
            "name": f"{promo.name} Youth Programme", "level": 1, "philosophy": "Balanced MMA",
            "reputation": 20, "region": getattr(promo, "region", "USA"), "prospects": [],
            "graduates": 0, "intakes": 0, "last_intake_month": 0, "last_graduate": "", "poached_leads": 0,
        }.items():
            if key not in program:
                program[key] = [] if isinstance(default, list) else default
        if not isinstance(program.get("prospects"), list):
            program["prospects"] = []
        program["prospects"] = [row for row in program["prospects"] if isinstance(row, dict)][:8]
        return program

    def rival_academy_promotions(self):
        return [
            promo for promo in getattr(self, "promotions", [])
            if not getattr(promo, "is_regional_feeder", False)
            and not getattr(promo, "is_child_promotion", False)
            and int(getattr(promo, "size", 0) or 0) >= 42
        ]

    def add_rival_academy_prospect(self, promo, source=None):
        program = self.rival_academy_program(promo)
        if len(program["prospects"]) >= 8:
            return None
        if source is None:
            fighter = self.create_generated_fighter(
                2, 12, 34, min(64, 48 + program.get("level", 1) * 3),
                region=program.get("region", getattr(promo, "region", self.player_region)), age_override=random.randint(14, 16),
            )
            source = {
                "prospect_id": f"rival-{promo.name}-{fighter.fighter_id}", "name": fighter.name,
                "age": fighter.age, "region": fighter.region, "gender": fighter.gender, "weight": fighter.weight,
                "rating": fighter.overall, "potential": max(fighter.overall + 8, fighter.potential),
                "style": fighter.style, "stance": fighter.stance, "trait": fighter.trait,
                "striking": fighter.striking, "wrestling": fighter.wrestling, "grappling": fighter.grappling,
                "cardio": fighter.cardio, "chin": fighter.chin, "power": fighter.power,
                "toughness": fighter.toughness, "fight_iq": fighter.fight_iq,
                "dedication": fighter.motivation, "coachability": fighter.professionalism, "confidence": fighter.morale,
            }
        row = deepcopy(source)
        row["academy_name"] = program["name"]
        row["joined_month"] = self.month
        row["graduation_month"] = self.month + max(12, (18 - int(row.get("age", 15) or 15)) * 12)
        program["prospects"].append(row)
        program["intakes"] = int(program.get("intakes", 0) or 0) + 1
        program["last_intake_month"] = self.month
        return row

    def graduate_rival_academy_prospect(self, promo, prospect):
        fighter = self.academy_prospect_to_fighter(prospect)
        fighter.age = max(18, int(prospect.get("age", 18) or 18) + max(0, (self.month - int(prospect.get("joined_month", self.month) or self.month)) // 12))
        fighter.feeder_origin = f"{promo.name} Youth Programme"
        fighter.camp = promo.name
        fighter.contract_type = "Developmental"
        fighter.contract_months = random.randint(18, 30)
        fighter.career_achievements = [f"Graduated from {promo.name}'s youth programme."]
        if not self.promotion_division_open(promo, fighter.gender, fighter.weight):
            return None
        membership_recorded = False
        membership = getattr(self, "record_membership_event", None)
        if callable(membership):
            membership(
                fighter, "join", promotion=promo,
                reason="Rival academy graduation",
                source_transaction=f"rival-academy-graduation:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}",
            )
            membership_recorded = True
        promo.roster.append(fighter)
        self.record_contract_signing(
            fighter, promo.name, source="Rival academy graduation",
            record_membership=not membership_recorded,
        )
        program = self.rival_academy_program(promo)
        if prospect in program["prospects"]:
            program["prospects"].remove(prospect)
        program["graduates"] = int(program.get("graduates", 0) or 0) + 1
        program["last_graduate"] = fighter.name
        if fighter.potential >= 88 or fighter.overall >= 65:
            self.news.insert(0, f"Rival academy graduate: {fighter.name} joins {promo.name} from its youth programme.")
        return fighter

    def process_rival_academies(self):
        """Advance rival youth cohorts once per month without duplicating the feeder system."""
        if self.week != 1:
            return
        for promo in self.rival_academy_promotions():
            program = self.rival_academy_program(promo)
            for prospect in list(program.get("prospects", [])):
                # Rival cohorts develop monthly in compact form; they become
                # ordinary Fighter objects only when they graduate.
                if random.random() < min(0.42, 0.12 + program.get("level", 1) * 0.055):
                    fields = self.academy_philosophy_fields({"philosophy": program.get("philosophy", "Balanced MMA")})
                    field = random.choice(fields)
                    prospect[field] = min(int(prospect.get("potential", 75) or 75), int(prospect.get(field, prospect.get("rating", 40)) or 40) + 1)
                    # A compact rival row can carry a readiness rating above its
                    # six broad-skill mean. Development must never make that
                    # persistent rating move backwards merely by recalculating it.
                    prospect["rating"] = max(
                        int(prospect.get("rating", 40) or 40),
                        min(
                            int(prospect.get("potential", 75) or 75),
                            round(sum(int(prospect.get(key, 40) or 40) for key in ("striking", "wrestling", "grappling", "cardio", "chin", "fight_iq")) / 6),
                        ),
                    )
                if self.month >= int(prospect.get("graduation_month", self.month + 1) or self.month + 1) and len(promo.roster) < 100:
                    self.graduate_rival_academy_prospect(promo, prospect)
            stable_offset = int(hashlib.sha256(promo.name.encode("utf-8")).hexdigest()[:8], 16) % 12
            if ((self.month - 1) % 12 == stable_offset
                    and self.month - int(program.get("last_intake_month", 0) or 0) >= 10
                    and len(program.get("prospects", [])) < max(2, program.get("level", 1) + 1)
                    and len(promo.roster) < 100):
                self.add_rival_academy_prospect(promo)

    def rival_academy_for_region(self, region):
        candidates = [promo for promo in self.rival_academy_promotions() if self.rival_academy_program(promo).get("region") == region]
        if not candidates:
            return None
        return max(candidates, key=lambda promo: (self.rival_academy_program(promo).get("reputation", 0), promo.size))

    def place_academy_lead_with_rival(self, prospect):
        offer = prospect.get("rival_offer") if isinstance(prospect.get("rival_offer"), dict) else {}
        promo = next((item for item in self.rival_academy_promotions() if item.name == offer.get("promotion")), None)
        if not promo:
            return False
        placed = self.add_rival_academy_prospect(promo, prospect)
        if not placed:
            return False
        program = self.rival_academy_program(promo)
        program["poached_leads"] = int(program.get("poached_leads", 0) or 0) + 1
        self.record_academy_recruitment_win(prospect, promo.name)
        return True

    def record_academy_recruitment_win(self, prospect, winner_company):
        """Link an already-decided contested youth signing to a promotion rivalry."""
        if getattr(self, "narrative_tracking_enabled", True) is False:
            return None
        offer = prospect.get("rival_offer") if isinstance(prospect.get("rival_offer"), dict) else {}
        rival_company = str(offer.get("promotion", "") or "")
        winner_company = str(winner_company or "")
        if not rival_company:
            return None
        loser_company = self.player_company_name if winner_company == rival_company else rival_company
        return self.record_promotion_war_event(
            winner_company, loser_company, "academy_recruitment",
            f"{winner_company} won the contested academy recruitment of {prospect.get('name', 'a youth prospect')}.",
            points=1, importance=3,
            event_ref=(
                f"academy-recruitment:{prospect.get('prospect_id', '')}:"
                f"{self.month}:{self.week}:{self.story_company_key(winner_company)}"
            ),
        )

    def process_academy_recruitment_competition(self, academy):
        if not academy.get("network_active"):
            return
        for prospect in academy.get("talent_pool", []):
            if prospect.get("rival_offer"):
                continue
            rival = self.rival_academy_for_region(prospect.get("region", academy.get("network_region")))
            if not rival:
                continue
            program = self.rival_academy_program(rival)
            interest = 0.05 + program.get("reputation", 20) / 600 + max(0, prospect.get("potential", 70) - 82) / 120
            if random.random() < min(0.35, interest):
                prospect["rival_offer"] = {"promotion": rival.name, "academy": program["name"], "made_week": self.calendar_week_index()}
                prospect["signing_cost"] = round(self.academy_signing_cost(prospect) * 1.15)
                academy["last_scout_report"] = f"{rival.name} has entered the recruitment race for {prospect['name']}; their signing demand rose."

    def is_child_promotion(self, promo):
        return bool(getattr(promo, "is_child_promotion", False))

    def child_promotion_strategy_profile(self, strategy):
        return {
            "Youth Prospects": {"mode": "Prospect Rebuild", "personality": "Prospect Builder", "star": 24, "prospect": 94, "merit": 52},
            "Big Names": {"mode": "Star Chasing", "personality": "Star Builder", "star": 94, "prospect": 35, "merit": 48},
            "Merit & Contenders": {"mode": "Contender Cycle", "personality": "Seasonal", "star": 54, "prospect": 46, "merit": 94},
            "Balanced": {"mode": "Balanced", "personality": "Balanced", "star": 58, "prospect": 58, "merit": 60},
        }.get(strategy, {"mode": "Balanced", "personality": "Balanced", "star": 58, "prospect": 58, "merit": 60})

    def child_promotion_loaned(self, promo, fighter):
        loaned_ids = set(getattr(promo, "loaned_fighter_ids", None) or [])
        return str(getattr(fighter, "fighter_id", "")) in loaned_ids or getattr(fighter, "loaned_to_promotion", "") == promo.name

    def child_loan_return_boundary(self, fighter):
        """Return a valid agreed loan boundary, or ``None`` for legacy loans."""
        try:
            month = int(getattr(fighter, "loan_return_month", 0) or 0)
            week = int(getattr(fighter, "loan_return_week", 0) or 0)
        except (TypeError, ValueError):
            return None
        if month <= 0 or week not in range(1, WEEKS_PER_MONTH + 1):
            return None
        return month, week

    def child_loan_return_label(self, fighter):
        boundary = self.child_loan_return_boundary(fighter)
        if not boundary:
            return "Open-ended; parent recall required"
        return self.format_game_date(*boundary)

    def child_loan_commitments_after(self, promo, fighter, boundary):
        """Find the latest still-recorded child-card commitment for a loan.

        Child AI cards normally resolve in their monthly review, but imported
        saves and player-created feeder cards can retain a scheduled event. We
        inspect both ID and legacy-name references and never mutate the event.
        """
        fighter_id = str(getattr(fighter, "fighter_id", "") or "")
        fighter_name = str(getattr(fighter, "name", "") or "")
        latest = None
        # A stale/imported parent card can still reference the fighter after a
        # roster move. Include it alongside the child schedule so a return
        # never invalidates an already-committed bout owned by either side.
        owners = (promo, self) if promo is not self else (self,)
        for owner in owners:
            for event in getattr(owner, "scheduled_events", []) or []:
                if not isinstance(event, dict):
                    continue
                refs = set()
                for fight in event.get("fights", []) or []:
                    if hasattr(self, "event_fight_participant_references"):
                        refs.update(self.event_fight_participant_references(fight))
                    else:
                        refs.update(self.event_fight_participants(fight))
                if fighter_id not in refs and fighter_name not in refs:
                    continue
                try:
                    event_boundary = (int(event.get("month", 0) or 0), int(event.get("week", 1) or 1))
                    event_index = self.calendar_week_index(*event_boundary)
                except (TypeError, ValueError):
                    continue
                if event_index >= self.calendar_week_index(*boundary):
                    latest = event_boundary if latest is None else max(latest, event_boundary, key=lambda item: self.calendar_week_index(*item))
        return latest

    def child_loan_return_status(self, promo, fighter):
        """Expose the agreed date and any safe-boundary delay for read models/UI."""
        boundary = self.child_loan_return_boundary(fighter)
        if not boundary:
            return {"agreed": None, "due": False, "delayed": False, "safe_boundary": None, "label": self.child_loan_return_label(fighter)}
        current_index = self.calendar_week_index()
        agreed_index = self.calendar_week_index(*boundary)
        latest = self.child_loan_commitments_after(promo, fighter, boundary)
        safe_boundary = latest if latest else boundary
        safe_index = self.calendar_week_index(*safe_boundary)
        due = current_index >= agreed_index
        delayed = due and safe_index > agreed_index
        return {
            "agreed": {"month": boundary[0], "week": boundary[1]},
            "due": due,
            "delayed": delayed,
            "safe_boundary": {"month": safe_boundary[0], "week": safe_boundary[1]},
            "label": self.format_game_date(*boundary),
            "safe_label": self.format_game_date(*safe_boundary),
        }

    def process_child_promotion_loan_returns(self):
        """Return time-bounded loans at the first safe weekly boundary.

        This runs after due player cards have settled and before new world
        bookings. A scheduled child bout at or after the agreed date holds the
        fighter until the next boundary after that commitment; no title or
        ownership mechanic is introduced and the operation consumes no RNG.
        """
        returned = []
        delayed = []
        current_index = self.calendar_week_index()
        for promo in [item for item in getattr(self, "promotions", []) if self.is_child_promotion(item)]:
            for fighter in list(getattr(promo, "roster", []) or []):
                if not self.child_promotion_loaned(promo, fighter):
                    continue
                boundary = self.child_loan_return_boundary(fighter)
                if not boundary or current_index < self.calendar_week_index(*boundary):
                    continue
                latest = self.child_loan_commitments_after(promo, fighter, boundary)
                safe_index = self.calendar_week_index(*(latest or boundary))
                # Without a later committed child card the agreed boundary
                # itself is the safe return point. A retained card, however,
                # must be allowed to settle before the roster move.
                if latest and current_index <= safe_index:
                    delayed.append((fighter, promo, latest or boundary))
                    continue
                ok, note = self.recall_fighter_from_child_promotion(
                    promo.name, fighter.fighter_id,
                    return_reason="Development loan term completed.",
                    return_phase="loan_completed",
                )
                if ok:
                    returned.append((fighter, promo, note))
        for fighter, promo, safe_boundary in delayed:
            note = (
                f"{fighter.name}'s development loan to {promo.name} reached its agreed "
                f"return date, but a committed child bout holds the return until "
                f"after {self.format_game_date(*safe_boundary)}."
            )
            if not any(str(item.get("body", "")) == note for item in getattr(self, "inbox", []) if isinstance(item, dict)):
                self.news.insert(0, note)
                self.inbox.insert(0, {"subject": "Development loan return delayed", "body": note, "type": "Child Promotion", "resolved": False})
        return returned

    def repair_child_promotion_state(self):
        """Normalize child metadata and rebuild the protected-loan index after loading."""
        children = [promo for promo in getattr(self, "promotions", []) if self.is_child_promotion(promo)]
        child_by_name = {str(promo.name): promo for promo in children}
        all_fighters = []
        seen_ids = set()
        for roster in [getattr(self, "roster", []), getattr(self, "free_agents", []), getattr(self, "retired_fighters", [])]:
            all_fighters.extend(roster or [])
        for promo in getattr(self, "promotions", []):
            all_fighters.extend(getattr(promo, "roster", []) or [])
        for fighter in all_fighters:
            fighter_id = str(getattr(fighter, "fighter_id", ""))
            if fighter_id in seen_ids:
                continue
            seen_ids.add(fighter_id)
            target_name = str(getattr(fighter, "loaned_to_promotion", "") or "")
            target = child_by_name.get(target_name)
            target_contains = target and any(str(getattr(item, "fighter_id", "")) == fighter_id for item in getattr(target, "roster", []))
            if target_name and (not target_contains or getattr(fighter, "retired", False) or getattr(fighter, "retirement_pending", False)):
                fighter.loaned_from_company = ""
                fighter.loaned_to_promotion = ""
                fighter.loan_return_month = 0
                fighter.loan_return_week = 0
        for promo in getattr(self, "promotions", []):
            if not self.is_child_promotion(promo):
                continue
            promo.parent_company = str(getattr(promo, "parent_company", "") or self.player_company_name)
            promo.child_strategy = getattr(promo, "child_strategy", "Balanced") or "Balanced"
            if promo.child_strategy not in AI_CHILD_PROMOTION_STRATEGIES:
                promo.child_strategy = "Balanced"
            try:
                promo.parent_profit_share = max(0, min(100, int(getattr(promo, "parent_profit_share", 0) or 0)))
            except (TypeError, ValueError):
                promo.parent_profit_share = 0
            raw_scheduled = getattr(promo, "scheduled_events", None)
            if not isinstance(raw_scheduled, list):
                raw_scheduled = []
            clean_scheduled = []
            seen_event_ids = set()
            for index, raw_event in enumerate(raw_scheduled):
                if not isinstance(raw_event, dict):
                    continue
                event = dict(raw_event)
                try:
                    event["month"] = max(1, int(event.get("month", 1) or 1))
                    event["week"] = max(1, min(WEEKS_PER_MONTH, int(event.get("week", 1) or 1)))
                except (TypeError, ValueError):
                    continue
                event.setdefault("status", "Scheduled")
                event.setdefault("event_name", event.get("name", f"{promo.name} Child Card {index + 1}"))
                event.setdefault("name", event.get("event_name", f"{promo.name} Child Card {index + 1}"))
                event_id = str(event.get("event_id", "") or "")
                if event_id:
                    base_id = event_id
                else:
                    base_id = f"legacy-child-event:{getattr(promo, 'promotion_id', '') or promo.name}:{event['month']}:{event['week']}"
                candidate_id, suffix = base_id, 2
                while candidate_id in seen_event_ids:
                    candidate_id = f"{base_id}#{suffix}"
                    suffix += 1
                seen_event_ids.add(candidate_id)
                event["event_id"] = candidate_id
                event.setdefault("promotion_id", str(getattr(promo, "promotion_id", "") or ""))
                event.setdefault("owner_ref", str(getattr(promo, "promotion_id", "") or promo.name))
                event.setdefault("fights", [])
                event.setdefault("bouts", [])
                clean_scheduled.append(event)
            promo.scheduled_events = sorted(
                clean_scheduled,
                key=lambda row: (row.get("month", 1), row.get("week", 1), str(row.get("event_id", ""))),
            )
            try:
                saved_counter = int(getattr(promo, "scheduled_event_counter", 0) or 0)
            except (TypeError, ValueError):
                saved_counter = 0
            promo.scheduled_event_counter = max(saved_counter, len(promo.scheduled_events))
            promo.loaned_fighter_ids = list(dict.fromkeys(str(item) for item in (getattr(promo, "loaned_fighter_ids", None) or []) if item))
            actual = []
            for fighter in getattr(promo, "roster", []):
                if (getattr(fighter, "retired", False) or getattr(fighter, "retirement_pending", False)):
                    fighter.loaned_from_company = ""
                    fighter.loaned_to_promotion = ""
                    fighter.loan_return_month = 0
                    fighter.loan_return_week = 0
                    continue
                if self.child_promotion_loaned(promo, fighter):
                    fighter.loaned_from_company = promo.parent_company
                    fighter.loaned_to_promotion = promo.name
                    try:
                        raw_month = int(getattr(fighter, "loan_return_month", 0) or 0)
                        raw_week = int(getattr(fighter, "loan_return_week", 0) or 0)
                    except (TypeError, ValueError):
                        raw_month, raw_week = 0, 0
                    if raw_month < 1 or raw_week not in range(1, WEEKS_PER_MONTH + 1):
                        fighter.loan_return_month = 0
                        fighter.loan_return_week = 0
                    else:
                        fighter.loan_return_month = raw_month
                        fighter.loan_return_week = raw_week
                    actual.append(fighter.fighter_id)
            promo.loaned_fighter_ids = list(dict.fromkeys(actual))
            self.set_child_promotion_settings(promo, promo.child_strategy, promo.parent_profit_share, announce=False)

    def set_child_promotion_settings(self, promo, strategy="Balanced", profit_share=0, announce=True):
        if not self.is_child_promotion(promo):
            return False, "That promotion is not a player-owned MMA child promotion."
        if strategy not in AI_CHILD_PROMOTION_STRATEGIES:
            return False, "Choose a valid child-promotion strategy."
        try:
            share = max(0, min(100, int(profit_share)))
        except (TypeError, ValueError):
            return False, "Profit share must be a number from 0 to 100."
        profile = self.child_promotion_strategy_profile(strategy)
        promo.child_strategy = strategy
        promo.parent_profit_share = share
        promo.show_personality = profile["personality"]
        ai_strategy = self.promotion_strategy(promo)
        ai_strategy.update({
            "current_mode": profile["mode"], "star_focus": profile["star"],
            "prospect_focus": profile["prospect"], "merit_focus": profile["merit"],
            "child_strategy": strategy, "parent_profit_share": share,
        })
        if announce:
            note = f"{promo.name} strategy set to {strategy}; parent profit share is {share}%."
            self.news.insert(0, note)
            promo.show_history = list(promo.show_history or [])
            promo.show_history.insert(0, note)
            promo.show_history = promo.show_history[:12]
        return True, note if announce else strategy

    def launch_ai_child_promotion(self, capital, strategy="Balanced", profit_share=0, name=""):
        """Launch a player-funded MMA promotion that the normal AI manages."""
        if getattr(self, "spectator_mode", False):
            return False, "Spectator Mode cannot launch a child promotion."
        try:
            capital = int(capital)
        except (TypeError, ValueError):
            return False, "Startup capital must be a whole-dollar amount."
        if capital < AI_CHILD_PROMOTION_MIN_CAPITAL:
            return False, f"Child promotions require at least ${AI_CHILD_PROMOTION_MIN_CAPITAL:,}."
        if capital > AI_CHILD_PROMOTION_MAX_CAPITAL:
            return False, f"Startup capital cannot exceed ${AI_CHILD_PROMOTION_MAX_CAPITAL:,}."
        if self.cash < capital:
            return False, f"Your company needs ${capital:,}, but has only ${self.cash:,}."
        if strategy not in AI_CHILD_PROMOTION_STRATEGIES:
            return False, "Choose a valid child-promotion strategy."
        try:
            share = max(0, min(100, int(profit_share)))
        except (TypeError, ValueError):
            return False, "Profit share must be a number from 0 to 100."
        requested_name = str(name or "").strip()
        if not requested_name:
            requested_name = f"{self.player_company_name} Development"
        used_names = {self.player_company_name, *(promo.name for promo in self.promotions)}
        promotion_name = requested_name
        suffix = 2
        while promotion_name in used_names:
            promotion_name = f"{requested_name} {suffix}"
            suffix += 1
        profile = self.child_promotion_strategy_profile(strategy)
        size = max(28, min(78, 30 + capital // 1_000_000 * 2))
        company_pop = max(25, min(68, int(getattr(self, "company_pop", 38))))
        promotion = Promotion(
            promotion_name, self.player_region, size, capital, [],
            reputation="Regional", reputation_score=company_pop, stability=62,
            show_history=[], belts={}, interim_belts={}, belt_history={},
            rules={"rounds": 3, "title_rounds": 5, "round_length": 5, "drug_testing": "Standard", "judging_randomness": 3, "active_fighter_target": 120},
            broadcasters=self.promotion_broadcasters(promotion_name, size), weight_classes=list(WEIGHTS),
            show_personality=profile["personality"], is_child_promotion=True,
            parent_company=self.player_company_name, child_strategy=strategy,
            parent_profit_share=share,
            startup_capital=capital, initial_roster_budget=capital, loaned_fighter_ids=[],
            strategy=self.seed_promotion_strategy(promotion_name, profile["personality"]),
            executive=self.seed_promotion_executive(promotion_name), era_history=[],
        )
        self.promotions.append(promotion)
        self.set_child_promotion_settings(promotion, strategy, profit_share, announce=False)
        self.cash -= capital
        signed = self.seed_child_promotion_roster(promotion, capital)
        if not signed:
            self.promotions.remove(promotion)
            self.cash += capital
            return False, "The launch was cancelled because no eligible MMA free agents were available for an opening roster."
        self.record_finance_transaction(
            f"Launch MMA child promotion: {promotion.name}", costs=capital,
            category="Child promotion", source="Startup capital", counterparty=promotion.name,
            reference=f"child-launch:{promotion.name}:{self.month}:{self.week}",
        )
        promotion.initial_roster_budget = capital
        headline = f"{promotion.name} launched with ${capital:,} startup capital, {len(signed)} initial fighters, and a {strategy.lower()} strategy."
        self.news.insert(0, headline)
        self.record_world_story("MMA Child Promotion", headline, f"Parent company: {promotion.parent_company}. Profit share: {promotion.parent_profit_share}%.", [promotion.name, self.player_company_name], [fighter.name for fighter in signed[:10]], importance=4)
        return True, promotion

    def seed_child_promotion_roster(self, promo, capital):
        """Spend launch capital on a broad, strategy-shaped opening roster."""
        strategy = getattr(promo, "child_strategy", "Balanced")
        target = max(12, min(64, capital // 125_000))
        available = [fighter for fighter in self.free_agents if not fighter.retired and not fighter.retirement_pending and not fighter.injured and not fighter.ai_offer_company and fighter.primary_discipline == "MMA"]
        counts = {}
        def value(fighter):
            key = (fighter.gender, fighter.weight)
            need = max(0, 4 - counts.get(key, 0)) * 90
            if strategy == "Youth Prospects":
                return need + max(0, fighter.potential - fighter.overall) * 5 + max(0, 29 - fighter.age) * 4 + fighter.overall * 0.35
            if strategy == "Big Names":
                return need + fighter.popularity * 4 + fighter.star_quality * 1.5 + fighter.overall * 1.2
            if strategy == "Merit & Contenders":
                return need + fighter.overall * 2 + fighter.elo_rating * 0.04 + fighter.record_w * 0.7
            return need + fighter.overall + fighter.popularity * 0.8 + max(0, fighter.potential - fighter.overall) * 1.5
        signed = []
        while available and len(signed) < target:
            fighter = max(available, key=value)
            available.remove(fighter)
            purse = max(2_500, self.ai_market_purse(promo, fighter))
            signing = max(5_000, round(purse * (0.42 if fighter.age <= 28 else 0.65) / 500) * 500)
            if promo.cash < signing + purse:
                continue
            membership_recorded = False
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                membership(
                    fighter, "join", promotion=promo,
                    reason="Opening roster signing",
                    source_transaction=f"opening-signing:{getattr(fighter, 'fighter_id', fighter.name)}:{promo.name}:{self.month}:{self.week}",
                )
                membership_recorded = True
            self.free_agents.remove(fighter)
            promo.cash -= signing
            self.record_promotion_finance_transaction(
                promo, f"Opening roster signing: {fighter.name}", costs=signing,
                category="Roster", source="Opening roster", counterparty=fighter.name,
                reference=f"opening-signing:{getattr(fighter, 'fighter_id', fighter.name)}",
            )
            fighter.purse = purse
            fighter.contract_months = random.randint(12, 28) if fighter.age <= 30 else random.randint(8, 18)
            fighter.exclusive = True
            fighter.contract_type = "Exclusive"
            fighter.free_agent_months = 0
            fighter.champion = False
            fighter.interim_champion = False
            fighter.camp = promo.name
            self.clear_ai_contract_offer(fighter)
            promo.roster.append(fighter)
            self.record_contract_signing(
                fighter, promo.name, source="Opening roster signing",
                record_membership=not membership_recorded,
            )
            counts[(fighter.gender, fighter.weight)] = counts.get((fighter.gender, fighter.weight), 0) + 1
            signed.append(fighter)
        return signed

    def child_promotion_by_reference(self, reference):
        """Resolve a player-owned child by stable ID, then a unique legacy name.

        A duplicate display name is intentionally ambiguous and fails closed;
        callers must retain the promotion ID from the table/proposal instead of
        routing an ownership action to whichever row happens to come first.
        """
        token = str(reference or "").strip()
        if not token:
            return None
        children = [
            promo for promo in getattr(self, "promotions", []) or []
            if self.is_child_promotion(promo)
            and getattr(promo, "parent_company", "") == self.player_company_name
        ]
        direct = [promo for promo in children if str(getattr(promo, "promotion_id", "") or "") == token]
        if direct:
            return direct[0]
        named = [promo for promo in children if str(getattr(promo, "name", "") or "") == token]
        return named[0] if len(named) == 1 else None

    def child_promotion_by_name(self, name):
        """Legacy name lookup retained, but duplicate names fail closed."""
        return self.child_promotion_by_reference(name)

    def child_promotion_transfer_fee(self, fighter):
        return max(25_000, round((fighter.purse * 3 + fighter.popularity * 1_000) / 500) * 500)

    def prepare_child_company_proposal(self, action, promo, fighter, *, cost=0, return_month=None, return_week=None):
        """Create a durable review card for an explicit parent/child move."""
        create = getattr(self, "create_company_proposal", None)
        if not callable(create) or not promo or not fighter:
            return None
        player_name, player_id = self._foundation_company_reference(company_name=self.player_company_name)
        child_name, child_id = self._foundation_company_reference(promotion=promo)
        source_name, source_id = (player_name, player_id) if action == "development_loan" else (child_name, child_id)
        target_name, target_id = (child_name, child_id) if action == "development_loan" else (player_name, player_id)
        if action == "parent_recall":
            source_name, source_id, target_name, target_id = child_name, child_id, player_name, player_id
        rank = getattr(self, "rank_label_for_fighter", None)
        company_rank = rank(fighter, source_name, world=False) if callable(rank) else "Unknown"
        world_rank = rank(fighter, source_name, world=True) if callable(rank) else "Unknown"
        action_label = {
            "development_loan": "Development loan to child promotion",
            "parent_recall": "Recall from child promotion",
            "child_transfer": "Parent transfer from child promotion",
        }.get(str(action), str(action).replace("_", " ").title())
        return_boundary = None
        if action == "development_loan" and return_month is not None and return_week is not None:
            try:
                candidate = (int(return_month), int(return_week))
            except (TypeError, ValueError):
                candidate = None
            if candidate and candidate[0] > 0 and candidate[1] in range(1, WEEKS_PER_MONTH + 1):
                return_boundary = candidate
        expiry = (
            {"month": return_boundary[0], "week": return_boundary[1],
             "label": f"Term ends {self.format_game_date(*return_boundary)}; parent may recall earlier"}
            if return_boundary else
            {"label": "Open until the parent recalls the loan"}
            if action == "development_loan" else
            {"month": int(getattr(self, "month", 0) or 0) + 1, "week": 1,
             "label": "Review at the next monthly boundary"}
        )
        terms = {"action_label": action_label, "child_promotion": child_name,
                 "fighter_id": str(getattr(fighter, "fighter_id", "") or ""),
                 "cash": max(0, int(cost or 0))}
        if return_boundary:
            terms["return_month"], terms["return_week"] = return_boundary
        return create(
            str(action), source_company=source_name, source_company_id=source_id,
            target_company=target_name, target_company_id=target_id,
            fighters=[{
                "fighter_id": str(getattr(fighter, "fighter_id", "") or ""),
                "fighter_name": str(getattr(fighter, "name", "") or ""),
                "role": "moving_fighter", "company": source_name, "company_id": source_id,
                "gender": str(getattr(fighter, "gender", "") or ""),
                "weight": str(getattr(fighter, "weight", "") or ""),
                "company_rank": company_rank, "world_rank": world_rank,
            }],
            costs={"cash": max(0, int(cost or 0)), "currency": "USD"},
            expiry=expiry,
            warnings=[
                "The fighter must remain in the recorded source roster until commit.",
                "Existing title, medical, retirement and booking protections still apply.",
                "No same-name substitute or automatic cross-company transfer is made.",
            ],
            terms=terms,
            reason=f"{action_label} prepared from the child-promotion manager.",
        )

    def commit_child_promotion_action(self, action):
        """Run one explicit child-roster move as an atomic domain action."""
        snapshot = self.capture_event_transaction_state()
        rng_state = random.getstate()
        try:
            return action()
        except Exception:
            self.restore_event_transaction_state(snapshot)
            random.setstate(rng_state)
            raise

    def loan_fighter_to_child_promotion(self, child_name, fighter_id, proposal_id="", return_month=None, return_week=None):
        promo = self.child_promotion_by_name(child_name)
        fighter = next((item for item in self.roster if str(getattr(item, "fighter_id", "")) == str(fighter_id)), None)
        if not promo or not fighter:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Loan could not be started.", error="Select a player-roster fighter and a child promotion.")
            return False, "Select a player-roster fighter and a child promotion."
        if fighter.retired or fighter.injured or fighter.retirement_pending:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Loan rejected by availability rules.", error=f"{fighter.name} is not available to loan.")
            return False, f"{fighter.name} is not available to loan."
        if getattr(fighter, "loaned_to_promotion", ""):
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Loan rejected by existing loan state.", error=f"{fighter.name} is already on loan.")
            return False, f"{fighter.name} is already on loan."
        if fighter.name in self.scheduled_fighter_names(include_booked=True):
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Loan rejected by a booking conflict.", error=f"{fighter.name} is already committed to a fight.")
            return False, f"{fighter.name} is already committed to a fight."
        if return_month is None and return_week is None:
            loan_boundary = None
        else:
            try:
                loan_boundary = (int(return_month), int(return_week))
            except (TypeError, ValueError):
                loan_boundary = None
            if not loan_boundary or loan_boundary[0] < 1 or loan_boundary[1] not in range(1, WEEKS_PER_MONTH + 1):
                return False, "Choose a valid agreed return month and week."
            if self.calendar_week_index(*loan_boundary) <= self.calendar_week_index():
                return False, "The agreed return date must be after the current game date."
        def commit():
            self.belts, self.interim_belts, self.belt_history = self.vacate_fighter_belts(
                fighter, self.roster, self.belts or {}, self.interim_belts or {}, self.belt_history or {},
                "Loaned to a child promotion.",
            )
            self.vacate_special_belts_held_by(fighter, "Loaned to a child promotion.")
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                transition_key = f"feeder-loan:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}"
                membership(fighter, "loan", company_name=self.player_company_name,
                           reason="Loaned to child promotion.", source_transaction=transition_key)
                membership(fighter, "join", promotion=promo,
                           reason="Received on development loan.", source_transaction=transition_key)
            self.roster.remove(fighter)
            promo.roster.append(fighter)
            fighter.loaned_from_company = self.player_company_name
            fighter.loaned_to_promotion = promo.name
            fighter.loan_return_month = loan_boundary[0] if loan_boundary else 0
            fighter.loan_return_week = loan_boundary[1] if loan_boundary else 0
            promo.loaned_fighter_ids = list(dict.fromkeys([*(promo.loaned_fighter_ids or []), fighter.fighter_id]))
            fighter.fight_history = list(fighter.fight_history or [])
            fighter.fight_history.insert(0, f"Month {self.month}: Loaned by {self.player_company_name} to {promo.name}.")
            term_note = f" Return agreed for {self.format_game_date(*loan_boundary)}." if loan_boundary else " Parent recall remains available at any time."
            note = f"{fighter.name} loaned to {promo.name}; the child AI cannot release them.{term_note}"
            self.news.insert(0, note)
            self.record_feeder_pathway_transition(
                fighter, promo.name, self.player_company_name, phase="development_loan",
                pathway_kind="loan", importance=3, summary=note,
                event_ref=f"feeder-loan:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}",
            )
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "committed", outcome="Loan completed; parent and child membership facts were recorded.")
            return True, note
        return self.commit_child_promotion_action(commit)

    def recall_fighter_from_child_promotion(self, child_name, fighter_id, proposal_id="", *, return_reason="Recalled by parent company.", return_phase="parent_recalled"):
        promo = self.child_promotion_by_name(child_name)
        fighter = next((item for item in (promo.roster if promo else []) if str(getattr(item, "fighter_id", "")) == str(fighter_id)), None)
        if not promo or not fighter or not self.child_promotion_loaned(promo, fighter):
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Recall could not be started.", error="That fighter is not a loaned member of this child promotion.")
            return False, "That fighter is not a loaned member of this child promotion."
        if fighter.retired or fighter.retirement_pending:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Recall rejected by retirement state.", error=f"{fighter.name} is retired or pending retirement.")
            return False, f"{fighter.name} is retired or pending retirement and cannot be recalled through the loan manager."
        def commit():
            promo.belts, promo.interim_belts, promo.belt_history = self.vacate_fighter_belts(
                fighter, promo.roster, promo.belts or {}, promo.interim_belts or {}, promo.belt_history or {},
                "Recalled by parent company.",
            )
            self.vacate_special_belts_held_by(fighter, "Recalled by parent company.", owner=promo)
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                transition_key = f"feeder-recall:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}"
                membership(fighter, "leave", promotion=promo,
                           reason=return_reason, source_transaction=transition_key)
                membership(fighter, "return", company_name=self.player_company_name,
                           reason=return_reason, source_transaction=transition_key)
            promo.roster.remove(fighter)
            promo.loaned_fighter_ids = [item for item in (promo.loaned_fighter_ids or []) if str(item) != str(fighter.fighter_id)]
            fighter.loaned_from_company = ""
            fighter.loaned_to_promotion = ""
            fighter.loan_return_month = 0
            fighter.loan_return_week = 0
            if fighter not in self.roster:
                self.roster.append(fighter)
            note = f"{fighter.name} returned from {promo.name} to {self.player_company_name}."
            self.news.insert(0, note)
            self.record_feeder_pathway_transition(
                fighter, promo.name, self.player_company_name, phase=return_phase,
                pathway_kind="loan", importance=4,
                summary=f"{fighter.name} returned from {promo.name} under the development-loan return boundary.",
                event_ref=f"feeder-recall:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}",
            )
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "committed", outcome="Recall completed; child and parent membership facts were recorded.")
            return True, note
        return self.commit_child_promotion_action(commit)

    def take_fighter_from_child_promotion(self, child_name, fighter_id, proposal_id=""):
        """Move any child-roster fighter to the parent, with a simple buyout for AI signings."""
        promo = self.child_promotion_by_name(child_name)
        fighter = next((item for item in (promo.roster if promo else []) if str(getattr(item, "fighter_id", "")) == str(fighter_id)), None)
        if not promo or not fighter:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Transfer could not be started.", error="That fighter is not on the selected child-promotion roster.")
            return False, "That fighter is not on the selected child-promotion roster."
        if fighter.retired or fighter.retirement_pending:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Transfer rejected by retirement state.", error=f"{fighter.name} is retired or pending retirement.")
            return False, f"{fighter.name} is retired or pending retirement and cannot be transferred."
        if self.child_promotion_loaned(promo, fighter):
            return self.recall_fighter_from_child_promotion(child_name, fighter_id, proposal_id=proposal_id)
        buyout = self.child_promotion_transfer_fee(fighter)
        division_key = self.belt_key(fighter.gender, fighter.weight)
        if division_key in set(getattr(self, "closed_divisions", set()) or set()):
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Transfer rejected by the closed parent division.", error=f"{fighter.gender} {fighter.weight} is a closed parent division.")
            return False, f"{fighter.gender} {fighter.weight} is a closed parent division. Reopen it before taking {fighter.name}."
        if self.cash < buyout:
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "needs_review", outcome="Transfer rejected by the cash reserve.", error=f"Taking {fighter.name} requires a ${buyout:,} transfer fee.")
            return False, f"Taking {fighter.name} requires a ${buyout:,} transfer fee."
        def commit():
            promo.belts, promo.interim_belts, promo.belt_history = self.vacate_fighter_belts(
                fighter, promo.roster, promo.belts or {}, promo.interim_belts or {}, promo.belt_history or {},
                "Transferred to the parent company.",
            )
            self.vacate_special_belts_held_by(fighter, "Transferred to the parent company.", owner=promo)
            self.cash -= buyout
            promo.cash += buyout
            self.record_finance_transaction(
                f"Child promotion transfer fee: {promo.name} — {fighter.name}", costs=buyout,
                category="Transfer", source="Parent transfer fee", counterparty=promo.name,
                reference=f"child-transfer:{getattr(fighter, 'fighter_id', fighter.name)}:{self.month}:{self.week}",
            )
            self.record_promotion_finance_transaction(
                promo, f"Transfer fee received: {fighter.name}", revenue=buyout,
                category="Transfer", source="Parent transfer fee", counterparty=self.player_company_name,
                reference=f"child-transfer:{getattr(fighter, 'fighter_id', fighter.name)}:{self.month}:{self.week}",
            )
            promo.finance = promo.finance or {}
            promo.finance["transfer_fees_received"] = int(promo.finance.get("transfer_fees_received", 0) or 0) + buyout
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                transition_key = f"feeder-transfer:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}"
                membership(fighter, "leave", promotion=promo,
                           reason="Transferred to the parent company.", source_transaction=transition_key)
                membership(fighter, "join", company_name=self.player_company_name,
                           reason=f"Transferred from {promo.name}.", source_transaction=transition_key)
            promo.roster.remove(fighter)
            fighter.loaned_from_company = ""
            fighter.loaned_to_promotion = ""
            fighter.loan_return_month = 0
            fighter.loan_return_week = 0
            fighter.contract_type = "Exclusive"
            fighter.exclusive = True
            fighter.camp = self.player_company_name
            if fighter.contract_months <= 0:
                fighter.contract_months = random.randint(12, 24) if fighter.age <= 32 else random.randint(8, 18)
            if fighter not in self.roster:
                self.roster.append(fighter)
            note = f"{fighter.name} transferred from {promo.name} to {self.player_company_name} for ${buyout:,}."
            self.news.insert(0, note)
            self.record_world_story("Child Promotion Transfer", note, "The parent company exercised its right to bring a child-promotion fighter into the main roster.", [promo.name, self.player_company_name], [fighter.name], importance=3)
            self.record_feeder_pathway_transition(
                fighter, promo.name, self.player_company_name, phase="parent_transfer",
                pathway_kind="transfer", importance=4, summary=note,
                event_ref=f"feeder-transfer:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}",
            )
            if proposal_id and callable(getattr(self, "update_company_proposal", None)):
                self.update_company_proposal(proposal_id, "committed", outcome="Parent transfer completed and the buyout was paid once.", terms={"commit_cash": buyout})
            return True, note
        return self.commit_child_promotion_action(commit)

    def distribute_child_promotion_profit(self, promo, profit):
        if not self.is_child_promotion(promo) or profit <= 0:
            return 0
        share = max(0, min(100, int(getattr(promo, "parent_profit_share", 0) or 0)))
        distribution = min(max(0, int(profit * share / 100)), max(0, promo.cash))
        if not distribution:
            return 0
        promo.cash -= distribution
        self.cash += distribution
        self.record_finance_transaction(
            f"Child promotion profit share: {promo.name}", revenue=distribution,
            category="Child promotion", source="Parent profit share", counterparty=promo.name,
            reference=f"child-distribution:{promo.name}:{self.month}:{self.week}",
        )
        self.record_promotion_finance_transaction(
            promo, "Parent profit-share distribution", costs=distribution,
            category="Child promotion", source="Parent profit share", counterparty=self.player_company_name,
            reference=f"child-distribution:{promo.name}:{self.month}:{self.week}",
        )
        strategy = self.promotion_strategy(promo)
        strategy["parent_distributions"] = int(strategy.get("parent_distributions", 0) or 0) + distribution
        strategy["last_parent_distribution"] = {"month": self.month, "amount": distribution, "share": share}
        promo.finance = promo.finance or {}
        promo.finance["parent_distributions"] = int(promo.finance.get("parent_distributions", 0) or 0) + distribution
        return distribution

    def update_ai_promotion_strategy(self, promo):
        strategy = self.promotion_strategy(promo)
        executive = getattr(promo, "executive", None) or self.seed_promotion_executive(promo.name)
        promo.executive = executive
        if self.is_child_promotion(promo):
            child_strategy = getattr(promo, "child_strategy", "Balanced") or "Balanced"
            profile = self.child_promotion_strategy_profile(child_strategy)
            strategy.update({
                "child_strategy": child_strategy, "star_focus": profile["star"],
                "prospect_focus": profile["prospect"], "merit_focus": profile["merit"],
            })
        reserve = max(120_000, promo.size * 8_500)
        prior = strategy.get("current_mode", "Balanced")
        if promo.cash < reserve or promo.stability < 35:
            mode = "Financial Recovery"
        elif self.is_child_promotion(promo):
            mode = self.child_promotion_strategy_profile(getattr(promo, "child_strategy", "Balanced"))["mode"]
        elif promo.reputation_score < 38 and strategy.get("prospect_focus", 50) >= 65:
            mode = "Prospect Rebuild"
        elif promo.momentum >= 5 and strategy.get("star_focus", 50) >= 65:
            mode = "Star Chasing"
        elif strategy.get("merit_focus", 50) >= 65:
            mode = "Contender Cycle"
        else:
            mode = "Title Push" if promo.reputation_score >= 65 else "Balanced"
        strategy["current_mode"] = mode
        strategy["last_review_month"] = self.month
        roster = [fighter for fighter in promo.roster if not fighter.retired]
        ready = [fighter for fighter in roster if self.fighter_available_for_date(fighter) and fighter.fatigue < 55]
        strategy["financial_pressure"] = max(0, round((reserve - promo.cash) / max(1, reserve) * 100 + max(0, 40 - promo.stability) * 1.4))
        strategy["roster_health"] = round(len(ready) / max(1, len(roster)) * 100)
        strategy["prospect_ratio"] = round(sum(1 for fighter in roster if fighter.age <= 27 and fighter.potential >= fighter.overall + 8) / max(1, len(roster)) * 100)
        strategy["star_ratio"] = round(sum(1 for fighter in roster if fighter.popularity + fighter.star_quality >= 145) / max(1, len(roster)) * 100)
        if mode != prior and random.random() < 0.55:
            headline = f"Strategy shift: {promo.name} moves into {mode.lower()} mode."
            self.news.insert(0, headline)
            self.record_world_story("Company Strategy", headline, f"Identity: {strategy.get('identity', 'company')}. Media voice: {strategy.get('media_voice', 'reliable fights')}.", [promo.name], importance=2)
            self.record_promotion_era_story(
                promo, phase=f"strategy_{mode.lower().replace(' ', '_')}",
                summary=f"{promo.name} shifted from {prior} to {mode} under its current leadership.",
                importance=2,
            )
        return strategy

    def update_ai_financial_market(self, promo):
        """Advance a persistent commercial cycle for one AI promotion.

        Sporting success is not a guarantee of commercial success: weaker brands
        experience larger swings in sponsorship, ticket demand, and distribution.
        The values live in ``strategy`` so existing saves receive safe defaults
        and the same company carries its financial story from month to month.
        """
        strategy = self.promotion_strategy(promo)
        executive = getattr(promo, "executive", {}) or {}
        strength = strategy.setdefault("commercial_strength", max(38, min(92, promo.reputation_score + (8 if promo.size >= 75 else -4))))
        volatility = strategy.setdefault("market_volatility", max(8, min(30, round((100 - strength) * 0.45))))
        strategy.setdefault("market_momentum", 0.0)
        if strategy.get("market_review_month") != self.month:
            discipline = executive.get("discipline", 60)
            shock = random.uniform(-volatility, volatility)
            # Disciplined companies smooth bad quarters; aggressive companies
            # feel both the upside and downside more sharply.
            smoothing = 0.48 + discipline / 260
            strategy["market_momentum"] = max(-38.0, min(38.0, strategy["market_momentum"] * smoothing + shock))
            strategy["market_review_month"] = self.month
        return strength, volatility, strategy["market_momentum"]

    def review_ai_executives(self):
        """Quarterly board pressure can force leadership changes and new company eras."""
        if self.month % 3:
            return
        for promo in [item for item in self.promotions if not getattr(item, "is_regional_feeder", False)]:
            executive = getattr(promo, "executive", None) or self.seed_promotion_executive(promo.name)
            promo.executive = executive
            self.review_executive_mandate(promo)
            pressure = max(0, 42 - promo.stability) * 1.1 + max(0, promo.size - promo.reputation_score) * 0.45
            executive["job_security"] = max(1, min(100, executive.get("job_security", 70) + random.randint(-5, 4) - round(pressure / 11)))
            if executive["job_security"] > 18 or random.random() > 0.18:
                continue
            former = executive["name"]
            successor = self.seed_promotion_executive(promo.name)
            if successor["name"] == former:
                # Named franchises seed a fixed executive; a genuine change needs a
                # distinct successor, not the same person "replacing" themselves.
                successor["name"] = f"{random.choice(FIRST_NAMES)} {random.choice(LAST_NAMES)}"
            promo.executive = successor
            promo.executive["job_security"] = random.randint(58, 82)
            promo.era_history = list(getattr(promo, "era_history", []))
            note = f"{promo.executive['name']} replaces {former} as executive, launching a {promo.executive['archetype'].lower()} era."
            promo.era_history.insert(0, {"year": self.current_year(), "note": note})
            promo.era_history = promo.era_history[:40]
            self.news.insert(0, f"Boardroom change: {promo.name} appoints {promo.executive['name']}.")
            self.record_world_story("Executive Change", f"{promo.name} appoints {promo.executive['name']}.", note, [promo.name], importance=4)
            self.record_promotion_era_story(
                promo, phase="new_leadership", summary=note, importance=4,
            )

    def review_executive_mandate(self, promo):
        """Boards issue time-bound mandates that influence strategy and job security."""
        executive = promo.executive or self.seed_promotion_executive(promo.name)
        promo.executive = executive
        mandate = executive.setdefault("board_mandate", "Financial Stability")
        if not executive.get("mandate_target"):
            executive["mandate_target"] = {
                "Reputation Growth": min(100, promo.reputation_score + 4),
                "Financial Stability": max(250_000, promo.size * 10_000),
                "Event Cadence": max(4, promo.event_counter + 5),
                "Roster Pipeline": max(4, len([fighter for fighter in promo.roster if fighter.age <= 26 and fighter.potential - fighter.overall >= 7]) + 2),
                "Title Success": max(2, sum(getattr(fighter, "title_defenses", 0) for fighter in promo.roster) + 2),
            }.get(mandate, promo.reputation_score + 4)
        executive.setdefault("mandate_deadline", self.month + 12)
        executive.setdefault("mandate_history", [])
        target = executive["mandate_target"]
        current = {
            "Reputation Growth": promo.reputation_score,
            "Financial Stability": promo.cash,
            "Event Cadence": promo.event_counter,
            "Roster Pipeline": len([fighter for fighter in promo.roster if fighter.age <= 26 and fighter.potential - fighter.overall >= 7]),
            "Title Success": sum(getattr(fighter, "title_defenses", 0) for fighter in promo.roster),
        }.get(mandate, 0)
        progress = max(0, min(100, round(current / max(1, target) * 100)))
        executive["mandate_progress"] = progress
        if current >= target:
            executive["job_security"] = min(100, executive.get("job_security", 70) + 9)
            note = f"Board mandate achieved: {mandate} ({current:,}/{target:,})."
            executive["mandate_history"] = (executive["mandate_history"] + [{"year": self.current_year(), "note": note}])[-20:]
            executive["mandate_target"] = 0
            executive["mandate_deadline"] = self.month + 12
            self.record_world_story("Board Mandate", f"{promo.name} completes its board mandate.", note, [promo.name], importance=3)
            self.record_promotion_era_story(
                promo, phase="mandate_achieved", summary=f"{promo.name}: {note}", importance=3,
            )
        elif self.month >= executive["mandate_deadline"]:
            executive["job_security"] = max(1, executive.get("job_security", 70) - 14)
            promo.stability = max(1, promo.stability - 2)
            note = f"Board mandate missed: {mandate} ({current:,}/{target:,})."
            executive["mandate_history"] = (executive["mandate_history"] + [{"year": self.current_year(), "note": note}])[-20:]
            executive["mandate_deadline"] = self.month + 6
            if mandate == "Financial Stability":
                self.promotion_strategy(promo)["current_mode"] = "Financial Recovery"
            elif mandate == "Roster Pipeline":
                self.promotion_strategy(promo)["current_mode"] = "Prospect Rebuild"
            self.record_world_story("Board Pressure", f"{promo.name} misses a board mandate.", note, [promo.name], importance=4)
            self.record_promotion_era_story(
                promo, phase="mandate_missed", summary=f"{promo.name}: {note}", importance=4,
            )

    def apply_ai_operating_costs(self):
        """Give AI companies the same ongoing commercial pressure as the player."""
        for promo in [item for item in self.promotions if not getattr(item, "is_regional_feeder", False)]:
            roster_size = len([fighter for fighter in promo.roster if not fighter.retired])
            executive = getattr(promo, "executive", {}) or {}
            discipline = executive.get("discipline", 60)
            strategy = self.promotion_strategy(promo)
            # Cost control matters, but cannot fully erase a large roster and
            # production footprint. This makes reckless expansion expensive.
            operating_multiplier = 0.88 + max(0, 85 - discipline) / 170
            # Fighter purses are paid per card. Office costs therefore scale with
            # roster administration, not as a second hidden salary for every
            # contracted athlete. The old rate made a profitable global company
            # lose several million between shows and hollow out its divisions.
            staff_payroll = 0
            for member in (getattr(promo, "staff", []) or []):
                if not isinstance(member, dict):
                    continue
                raw_salary = member.get("salary", 0)
                if isinstance(raw_salary, bool):
                    continue
                try:
                    staff_payroll += max(0, int(raw_salary or 0))
                except (TypeError, ValueError):
                    # Keep malformed AI employment evidence visible to the
                    # audit while excluding it from this month's bill.
                    continue
            monthly_cost = round((18_000 + promo.size * 650 + roster_size * 325) * operating_multiplier) + staff_payroll
            promo.cash -= monthly_cost
            self.record_promotion_finance_transaction(
                promo, "Monthly operating costs", costs=monthly_cost,
                category="Overhead", source="Office and roster operations",
                reference=f"monthly-overhead:{promo.name}:{self.month}",
            )
            # Companies retain a genuine runway for cards and contract bidding.
            # Surplus above the operating ceiling is returned to ownership and
            # long-term infrastructure monthly. This is deliberately gentler
            # than a hard cap, while preventing an AI with a hot quarter from
            # compounding into nine-figure cash that no roster can use.
            target_reserve = self.ai_financial_runway(promo)
            strategy["target_reserve"] = target_reserve
            cash_ceiling = self.ai_cash_ceiling(promo)
            strategy["cash_ceiling"] = cash_ceiling
            if promo.cash > cash_ceiling:
                surplus = promo.cash - cash_ceiling
                distribution = round(surplus * (0.16 if promo.cash <= cash_ceiling * 1.4 else 0.24))
                promo.cash -= distribution
                self.record_promotion_finance_transaction(
                    promo, "Capital distribution", costs=distribution,
                    category="Ownership", source="Excess cash distribution", counterparty=promo.name,
                    reference=f"capital-distribution:{promo.name}:{self.month}",
                )
                strategy["capital_distributions"] = int(strategy.get("capital_distributions", 0) or 0) + distribution
            commercial_strength = strategy.get("commercial_strength", promo.reputation_score)
            stability_target = max(58, min(86, round(50 + commercial_strength * 0.38)))
            strategy["stability_target"] = stability_target
            # Healthy companies retain distinct identities rather than all
            # accumulating at the old universal 91-92 stability ceiling.
            if self.month % 3 == 0 and promo.stability > stability_target:
                promo.stability = max(stability_target, promo.stability - 1)
            reserve = max(150_000, promo.size * 8_000)
            # Stability reflects whether today's business is viable, not whether
            # it already has enough cash to instantly expand to its eventual
            # 300-fighter ambition. Otherwise solvent companies get trapped in
            # Financial Recovery and never rebuild their thin divisions.
            operating_reserve = max(450_000, promo.size * 8_000 + roster_size * 8_000)
            if promo.cash < 0:
                promo.stability = max(1, promo.stability - 4)
            elif promo.cash < reserve:
                promo.stability = max(1, promo.stability - 2)
            elif promo.cash < reserve * 2:
                promo.stability = max(1, promo.stability - 1)
            elif promo.cash >= operating_reserve and promo.stability < stability_target:
                promo.stability = min(stability_target, promo.stability + 1)

    def _ai_staff_recurring_cost(self, promo):
        """Pure six-month runway basis used before an AI staff signing."""
        # Small test/dummy promotions do not carry the full Promotion schema;
        # treating their missing operating basis as zero keeps the lifecycle
        # adapter injectable without weakening real promotion affordability.
        if not hasattr(promo, "size"):
            return 0
        roster_size = len([fighter for fighter in (getattr(promo, "roster", []) or [])
                           if not getattr(fighter, "retired", False)])
        executive = getattr(promo, "executive", {}) or {}
        try:
            discipline = float(executive.get("discipline", 60) or 60)
        except (TypeError, ValueError):
            discipline = 60.0
        operating_multiplier = 0.88 + max(0.0, 85.0 - discipline) / 170.0
        overhead = round((18_000 + int(getattr(promo, "size", 0) or 0) * 650 + roster_size * 325) * operating_multiplier)
        payroll = 0
        for member in (getattr(promo, "staff", []) or []):
            if not isinstance(member, dict):
                continue
            try:
                salary = int(member.get("salary", 0) or 0)
            except (TypeError, ValueError):
                # Keep the affordability projection readable for legacy rows;
                # the raw staff record remains untouched for explicit review.
                salary = 0
            payroll += max(0, salary)
        return overhead + payroll

    def ai_staff_affordability_snapshot(self, promo, candidate=None):
        """Return a pure, identity-linked affordability/readiness projection.

        S4's hiring rule needs evidence that an AI promotion can carry the
        proposed employee beyond the one-time signing debit.  This helper is a
        read model for the six-month runway rule used by
        :meth:`simulate_ai_staff_market`; it never removes a candidate,
        changes cash, repairs strategy data, creates IDs or consumes RNG.
        ``candidate`` is optional so the same projection can be used for a
        promotion summary or for a selected market row.
        """
        if promo is None:
            return {
                "promotion_id": "", "promotion_name": "Unknown promotion",
                "cash": 0, "existing_staff_payroll": 0,
                "monthly_recurring_cost": 0, "six_month_runway": 0,
                "current_runway_months": None, "post_signing_runway_months": None,
                "runway_basis": "No-revenue recurring-cost stress test",
                "candidate_salary": 0, "signing_cost": 0,
                "required_cash_after_signing": 0, "post_signing_cash": 0,
                "affordable": False, "status": "Unavailable",
                "reason": "Promotion is not available.",
            }

        def integer(value, fallback=0):
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return fallback

        cash = integer(getattr(promo, "cash", 0), 0)
        staff = getattr(promo, "staff", []) or []
        payroll = sum(max(0, integer(member.get("salary", 0), 0))
                       for member in staff if isinstance(member, dict))
        recurring = max(0, integer(self._ai_staff_recurring_cost(promo), 0))
        salary = max(0, integer(candidate.get("salary", 0), 0)) if isinstance(candidate, dict) else 0
        signing = salary * 2
        runway = recurring * 6
        required = runway + salary
        post_signing = cash - signing
        current_runway_months = round(max(0, cash) / recurring, 1) if recurring else None
        post_signing_runway_months = round(max(0, post_signing) / recurring, 1) if recurring else None

        role = str(candidate.get("role", "") or "").strip() if isinstance(candidate, dict) else ""
        strategy = getattr(promo, "strategy", {})
        history = strategy.get("ai_staff_hire_history", []) if isinstance(strategy, dict) else []
        if not isinstance(history, list):
            history = []
        current_month = integer(getattr(self, "month", 0), 0)
        role_hired = bool(role and any(
            isinstance(row, dict) and str(row.get("role", "") or "") == role
            and integer(row.get("month", 0), 0) == current_month
            for row in history
        ))
        role_occupied = bool(role and any(
            isinstance(member, dict) and str(member.get("role", "") or "") == role
            for member in staff
        ))
        reasons = []
        if post_signing < required:
            reasons.append(f"${required:,} required after signing; ${post_signing:,} available")
        if role_hired:
            reasons.append(f"{role} already hired this month")
        if role_occupied:
            reasons.append(f"{role} role already occupied")
        if not isinstance(candidate, dict):
            reasons.append("No candidate selected")
        affordable = not reasons
        return {
            "promotion_id": str(getattr(promo, "promotion_id", "") or ""),
            "promotion_name": str(getattr(promo, "name", "") or "Unknown promotion"),
            "cash": cash,
            "existing_staff_payroll": payroll,
            "monthly_recurring_cost": recurring,
            "six_month_runway": runway,
            "current_runway_months": current_runway_months,
            "post_signing_runway_months": post_signing_runway_months,
            "runway_basis": "No-revenue recurring-cost stress test",
            "candidate_salary": salary,
            "signing_cost": signing,
            "required_cash_after_signing": required,
            "post_signing_cash": post_signing,
            "role": role,
            "role_hired_this_month": role_hired,
            "role_already_occupied": role_occupied,
            "affordable": affordable,
            "status": "Ready" if affordable else "Needs attention",
            "reason": "Ready within the six-month runway rule." if affordable else "; ".join(reasons),
        }

    def ai_staff_employment_rows(self, include_market=True, limit=200):
        """Return a read-only ledger of AI staff employment and market supply.

        The lifecycle helpers own hiring, payroll and expiry.  This adapter is
        deliberately observational: it never repairs missing IDs, creates
        defaults or re-runs affordability logic.  A promotion's stable ID and
        a staff member's stable ID form the durable row identity; legacy rows
        retain a clearly marked name/role/content fallback so duplicate names
        cannot silently steal selection in a future reader.
        """
        try:
            max_rows = max(1, min(500, int(limit)))
        except (TypeError, ValueError, OverflowError):
            max_rows = 200
        rows = []
        used = set()

        def text(value, fallback=""):
            return str(value if value is not None else fallback).strip()

        def integer(value, fallback=0):
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return fallback

        def records(value):
            return value if isinstance(value, (list, tuple)) else []

        def add_row(source, promo, member, index):
            if not isinstance(member, dict):
                return
            promotion_id = text(getattr(promo, "promotion_id", "")) if promo is not None else ""
            promotion_name = text(getattr(promo, "name", ""), "Shared staff market") if promo is not None else "Shared staff market"
            staff_id = text(member.get("staff_id"))
            if staff_id:
                identity = staff_id
            else:
                # Older employment rows may have no staff ID. Bind the
                # read-only projection to retained facts, never to the
                # visible position, so sorting/filtering cannot retarget a
                # legacy employee.
                legacy_fields = (
                    "name", "role", "specialty", "salary", "contract_months",
                    "contract_start_month", "contract_start_week",
                    "contract_end_month", "contract_end_week", "expiry_month",
                    "expiry_week",
                )
                payload = {
                    "source": source,
                    "promotion_id": promotion_id,
                    "promotion_name": promotion_name,
                    "raw_type": type(member).__name__,
                    "fields": {field: member.get(field) for field in legacy_fields},
                }
                digest = hashlib.sha1(
                    json.dumps(payload, sort_keys=True, default=str, separators=(",", ":")).encode("utf-8", "replace")
                ).hexdigest()[:16]
                identity = f"legacy:{digest}"
            base_id = f"ai-staff:{source.lower().replace(' ', '-')}:" \
                f"{promotion_id or promotion_name}|{identity}"
            row_id = base_id
            suffix = 2
            while row_id in used:
                row_id = f"{base_id}#{suffix}"
                suffix += 1
            used.add(row_id)
            months = integer(member.get("contract_months"), 0)
            salary = max(0, integer(member.get("salary"), 0))
            active = source == "AI roster"
            payroll = sum(
                max(0, integer(item.get("salary"), 0))
                for item in records(getattr(promo, "staff", []))
                if isinstance(item, dict)
            ) if active else 0
            rows.append({
                "row_id": row_id,
                "source": source,
                "promotion_id": promotion_id,
                "promotion_name": promotion_name,
                "staff_id": staff_id,
                "identity_quality": "Stable ID" if staff_id else "Legacy fallback",
                "name": text(member.get("name"), "Unnamed staff"),
                "role": text(member.get("role"), "Operations"),
                "specialty": text(member.get("specialty"), "Operations"),
                "skill": integer(member.get("skill"), 0),
                "morale": integer(member.get("morale"), 0),
                "salary": salary,
                "contract_months": months,
                "contract_start_month": integer(member.get("contract_start_month"), 0),
                "contract_expiry_month": integer(member.get("contract_expiry_month"), 0),
                "monthly_payroll": payroll,
                "status": "Active" if active and months > 0 else "Expired" if active else "Available",
            })

        promotions = [promo for promo in records(getattr(self, "promotions", []))
                      if not getattr(promo, "is_regional_feeder", False)]
        for promo in promotions:
            for index, member in enumerate(records(getattr(promo, "staff", []))):
                add_row("AI roster", promo, member, index)
        if include_market:
            for index, member in enumerate(records(getattr(self, "staff_candidates", []))):
                add_row("Shared market", None, member, index)
        rows.sort(key=lambda row: (
            0 if row["source"] == "AI roster" else 1,
            row["promotion_name"].casefold(), row["role"].casefold(),
            row["name"].casefold(), row["row_id"],
        ))
        return rows[:max_rows]

    def update_ai_staff_contracts(self):
        """Tick non-player staff terms and return expired identities to market."""
        market = getattr(self, "staff_candidates", None)
        if not isinstance(market, list):
            market = self.staff_candidates = []
        current_month = 1
        try:
            current_month = max(1, int(getattr(self, "month", 1) or 1))
        except (TypeError, ValueError):
            current_month = 1

        def safe_int(value, fallback=0):
            if isinstance(value, bool):
                return fallback
            try:
                return int(value)
            except (TypeError, ValueError):
                return fallback

        for promo in [item for item in (getattr(self, "promotions", []) or [])
                      if not getattr(item, "is_regional_feeder", False)]:
            members = list(getattr(promo, "staff", []) or [])
            kept = []
            for member in members:
                if not isinstance(member, dict):
                    # Preserve malformed legacy rows for the employment audit;
                    # dropping them here would destroy evidence during a
                    # routine calendar tick.
                    kept.append(member)
                    continue
                raw_months = member.get("contract_months", STAFF_CONTRACT_DEFAULT_MONTHS)
                if "contract_months" in member and (isinstance(raw_months, bool) or not isinstance(raw_months, (int, str))):
                    remaining = None
                else:
                    try:
                        remaining = int(raw_months) - 1
                    except (TypeError, ValueError):
                        remaining = None
                if remaining is None:
                    # An unknown contract boundary cannot safely be treated as
                    # either active or expired. Hold the row for explicit
                    # review, retain the original value and emit one notice per
                    # calendar month rather than silently cutting employment.
                    member.setdefault("contract_review_required", True)
                    member.setdefault("contract_review_reason", "Contract months are malformed; expiry is held for review.")
                    if member.get("contract_review_notice_month") != current_month:
                        self.news.insert(0, f"Staff contract review: {member.get('name', 'Staff')} at {promo.name} has malformed term evidence; expiry was held.")
                        member["contract_review_notice_month"] = current_month
                    kept.append(member)
                    continue
                member["contract_months"] = remaining
                if remaining > 0:
                    kept.append(member)
                    continue
                staff_id = str(member.get("staff_id", "") or "")
                # Preserve legacy AI employees that predate durable staff IDs.
                # They remain explicitly legacy/identity-limited in the market
                # reader; dropping them at expiry would silently lose a saved
                # employment record.  Stable-ID rows still deduplicate retries,
                # while ID-less rows are retained as separate source records
                # rather than being merged by mutable name/role text.
                already_in_market = bool(staff_id) and any(
                    str(candidate.get("staff_id", "")) == staff_id
                    for candidate in market if isinstance(candidate, dict)
                )
                if not already_in_market:
                    market.append(dict(member, contract_months=STAFF_CONTRACT_DEFAULT_MONTHS,
                                       contract_start_month=current_month,
                                       contract_expiry_month=current_month + STAFF_CONTRACT_DEFAULT_MONTHS))
                self.news.insert(0, f"{member.get('name', 'Staff')} returned to the staff market after leaving {promo.name}.")
            promo.staff = kept
            if isinstance(getattr(promo, "finance", None), dict):
                promo.finance["staff_payroll"] = sum(
                    max(0, safe_int(item.get("salary", 0), 0))
                    for item in kept if isinstance(item, dict)
                )
        self.staff_candidates = market[-24:]
        return self.staff_candidates

    def process_promotion_failures(self):
        """Restructure genuinely failed companies instead of silently deleting the world."""
        for promo in list(self.promotions):
            if getattr(promo, "is_regional_feeder", False):
                continue
            # A single bad quarter should force a rebuild, not erase a company.
            # Closure requires a sustained failure after a meaningful attempt to
            # trade, and closed names are persisted to prevent silent reseeding.
            # A company that cannot afford a single recovery card can still
            # fail. Three years is long enough to avoid opening-month churn.
            has_runway_history = self.month >= 37
            insolvent = has_runway_history and promo.cash < -500_000
            terminal = has_runway_history and promo.stability <= 2 and promo.cash < 100_000
            if not (insolvent or terminal):
                continue
            strategy = self.promotion_strategy(promo)
            last_buyout = int(strategy.get("last_buyout_month", 0) or 0)
            # New ownership gets six years to execute its rebuild. Without a
            # protected period, one weak season could trigger another buyout,
            # repeatedly dumping most of the same roster into free agency.
            if last_buyout and self.month - last_buyout < 72:
                last_workout = int(strategy.get("last_post_buyout_workout_month", 0) or 0)
                if promo.cash < 0 and self.month - last_workout >= 12:
                    card_runway = max(750_000, promo.size * 12_000)
                    workout = max(1_000_000, promo.size * 30_000, -promo.cash + card_runway)
                    promo.cash += workout
                    self.record_promotion_finance_transaction(
                        promo, "Post-buyout lender workout", revenue=workout,
                        category="Rescue", source="Lender workout", counterparty=promo.name,
                        reference=f"post-buyout-workout:{promo.name}:{self.month}",
                    )
                    promo.stability = max(22, promo.stability)
                    strategy["last_post_buyout_workout_month"] = self.month
                    strategy["post_buyout_workouts"] = strategy.get("post_buyout_workouts", 0) + 1
                    strategy["current_mode"] = "Post-Buyout Rebuild"
                    promo.show_history = list(promo.show_history or [])
                    promo.show_history.insert(0, f"Post-buyout lender workout: ${workout:,} bridge funding, no roster purge.")
                    promo.show_history = promo.show_history[:12]
                continue
            executive = promo.executive or self.seed_promotion_executive(promo.name)
            promo.executive = executive
            if not executive.get("rescue_capital_used", False):
                rescue = max(4_000_000, promo.size * 75_000)
                executive["rescue_capital_used"] = True
                promo.cash += rescue
                self.record_promotion_finance_transaction(
                    promo, "Investor rescue package", revenue=rescue,
                    category="Rescue", source="Investor rescue", counterparty=promo.name,
                    reference=f"investor-rescue:{promo.name}:{self.month}",
                )
                promo.stability = max(36, promo.stability)
                headline = f"{promo.name} secures a final ${rescue:,} investor rescue package."
                self.news.insert(0, headline)
                self.record_world_story("Investor Rescue", headline, "The board has one chance to rebuild under a financial-recovery strategy.", [promo.name], importance=4)
                self.record_promotion_era_story(
                    promo, phase="investor_rescue", summary=headline, importance=5,
                )
                continue
            self.distressed_promotion_buyout(promo)

    def distressed_promotion_buyout(self, promo):
        """A failing AI company survives via new ownership, but loses most of its roster."""
        executive = promo.executive or self.seed_promotion_executive(promo.name)
        promo.executive = executive
        roster = [fighter for fighter in list(promo.roster) if not getattr(fighter, "retired", False)]
        roster.sort(key=lambda fighter: (fighter.champion, fighter.interim_champion, fighter.popularity + fighter.overall, fighter.potential), reverse=True)
        retain_count = min(len(roster), max(4, round(len(roster) * random.uniform(0.16, 0.28))))
        # Display names are not identities.  A duplicate-name career must not
        # be retained merely because its namesake won the buyout ranking.
        # Stable fighter IDs are the durable key; the object identity fallback
        # keeps an id-less legacy row distinct for this in-memory boundary.
        def retention_key(fighter):
            fighter_id = str(getattr(fighter, "fighter_id", "") or "").strip()
            return ("id", fighter_id) if fighter_id else ("legacy-object", id(fighter))

        retained = {retention_key(fighter) for fighter in roster[:retain_count]}
        retained.update(retention_key(fighter) for fighter in roster if self.child_promotion_loaned(promo, fighter))
        released = []
        for fighter in list(promo.roster):
            if getattr(fighter, "retired", False) or retention_key(fighter) in retained:
                continue
            promo.belts, promo.interim_belts, promo.belt_history = self.vacate_fighter_belts(
                fighter, promo.roster, promo.belts or {}, promo.interim_belts or {}, promo.belt_history or {},
                f"Released after {promo.name}'s distressed buyout.",
            )
            self.vacate_special_belts_held_by(fighter, f"Released after {promo.name}'s distressed buyout.", owner=promo)
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                membership(
                    fighter, "leave", promotion=promo,
                    reason=f"Released after {promo.name}'s distressed buyout.",
                    source_transaction=f"distressed-buyout:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}",
                )
            fighter.champion = False
            fighter.interim_champion = False
            fighter.contract_months = 0
            fighter.exclusive = False
            fighter.contract_type = "Free Agent"
            fighter.ai_offer_company = ""
            fighter.ai_offer_months = 0
            fighter.ai_offer_purse = 0
            fighter.ai_offer_signing_bonus = 0
            fighter.free_agent_months = 0
            fighter.morale = max(20, fighter.morale - random.randint(5, 14))
            fighter.fight_history = fighter.fight_history or []
            fighter.fight_history.insert(0, f"Month {self.month}: Released after {promo.name}'s distressed buyout.")
            promo.roster.remove(fighter)
            self.free_agents.append(fighter)
            released.append(fighter)
        injection = max(4_000_000, promo.size * random.randint(75_000, 105_000))
        previous_cash = promo.cash
        promo.cash = injection
        self.record_promotion_finance_transaction(
            promo, "Distressed ownership recapitalisation",
            revenue=max(0, injection - previous_cash), costs=max(0, previous_cash - injection),
            category="Ownership", source="Distressed buyout", counterparty=promo.name,
            reference=f"distressed-buyout:{promo.name}:{self.month}",
        )
        promo.stability = random.randint(32, 48)
        promo.momentum = max(-4, min(3, promo.momentum + random.randint(-1, 2)))
        promo.size = max(35, promo.size - random.randint(2, 5))
        promo.reputation_score = max(30, promo.reputation_score - random.randint(1, 4))
        promo.reputation = "Global" if promo.reputation_score >= 68 else ("National" if promo.reputation_score >= 45 else "Regional")
        strategy = self.promotion_strategy(promo)
        strategy["current_mode"] = "Post-Buyout Rebuild"
        strategy["market_momentum"] = max(-8, strategy.get("market_momentum", 0) + 6)
        strategy["distressed_buyouts"] = strategy.get("distressed_buyouts", 0) + 1
        strategy["last_buyout_month"] = self.month
        former = executive.get("name", "the old board")
        successor = self.seed_promotion_executive(promo.name)
        if successor.get("name") == former:
            successor["name"] = f"{random.choice(FIRST_NAMES)} {random.choice(LAST_NAMES)}"
        successor["job_security"] = random.randint(62, 86)
        # The first investor rescue is a one-time route. Future failures lead
        # to another ownership change instead of an endless rescue/buyout loop.
        successor["rescue_capital_used"] = strategy["distressed_buyouts"] >= 1
        promo.executive = successor
        promo.era_history = list(getattr(promo, "era_history", []))
        note = f"Distressed buyout injected ${injection:,}, retained {len(promo.roster)} fighters, and released {len(released)} fighters into free agency."
        promo.era_history.insert(0, {"year": self.current_year(), "note": note})
        promo.era_history = promo.era_history[:40]
        promo.show_history = list(promo.show_history or [])
        promo.show_history.insert(0, f"Distressed buyout: new ownership, {len(released)} fighters released, rebuild begins.")
        promo.show_history = promo.show_history[:12]
        headline = f"{promo.name} bought out after financial distress; most of the roster hits free agency."
        self.news.insert(0, headline)
        self.record_world_story("Promotion Buyout", headline, note, [promo.name], [fighter.name for fighter in released[:8]], importance=5)
        self.record_promotion_era_story(
            promo, phase="post_buyout_rebuild", summary=f"{headline} {note}", importance=5,
        )

    def calendar_week_index(self, month=None, week=None):
        return (max(1, month if month is not None else self.month) - 1) * 4 + max(1, week if week is not None else self.week)

    def fighter_available_for_date(self, fighter, month=None, week=None, day=None):
        """Is a fighter clear to compete on this date?

        available_week is the authority. Suspensions, injuries, medical holds
        and every "clear this fighter now" path write it and know nothing about
        days, so treating the finer value as the gate let a suspended fighter
        through on a stale clearance. available_day only refines the boundary
        week, deciding whether a card lands before or after their return inside
        the week they become free.
        """
        if fighter.injured:
            return False
        week_gate = int(getattr(fighter, "available_week", 0) or 0)
        target_week = self.calendar_week_index(month, week)
        if target_week != week_gate:
            return target_week > week_gate
        if day is None:
            return True
        day_gate = int(getattr(fighter, "available_day", 0) or 0)
        week_start = (week_gate - 1) * DAYS_PER_WEEK + 1
        if not week_start <= day_gate < week_start + DAYS_PER_WEEK:
            # No day-level value that belongs to this week: the coarse gate has
            # already cleared them, so do not invent a finer restriction.
            return True
        return self.calendar_day_index(month, week, day) >= day_gate

    def day_index_parts(self, day_index):
        """Turn a running day number back into (month, week, day)."""
        zero_based = max(0, int(day_index) - 1)
        week_index = zero_based // DAYS_PER_WEEK + 1
        day = zero_based % DAYS_PER_WEEK + 1
        month = (week_index - 1) // WEEKS_PER_MONTH + 1
        week = (week_index - 1) % WEEKS_PER_MONTH + 1
        return month, week, day

    def fighter_available_day_index(self, fighter):
        """The first day a fighter may compete, reconciling both gates.

        Mirrors fighter_available_for_date: the week gate decides the week, and
        the day gate only refines the position inside it when it belongs there.
        """
        week_gate = int(getattr(fighter, "available_week", 0) or 0)
        week_start = (max(1, week_gate) - 1) * DAYS_PER_WEEK + 1
        day_gate = int(getattr(fighter, "available_day", 0) or 0)
        if week_start <= day_gate < week_start + DAYS_PER_WEEK:
            return day_gate
        return week_start

    def stamp_last_fight_date(self, *fighters):
        """Record when a fighter last competed, to the day of the card."""
        day_index = self.calendar_day_index(
            self.month, self.week, getattr(self, "_active_card_day", None) or LEGACY_EVENT_DAY
        )
        for fighter in fighters:
            if fighter is None:
                continue
            fighter.last_fight_month = self.month
            fighter.last_fight_day_index = day_index

    def fighter_rest_days(self, fighter, month=None, week=None, day=None):
        """Days between a fighter's last dated bout and the card being considered.

        Returns None until they have fought on a dated card, so callers can
        keep their existing week-based behaviour for older saves.
        """
        last = int(getattr(fighter, "last_fight_day_index", 0) or 0)
        if not last:
            return None
        return max(0, self.calendar_day_index(month, week, day) - last)

    def fighter_return_label(self, fighter):
        available = getattr(fighter, "available_week", 0)
        if not available or self.calendar_week_index() >= available:
            return "Available"
        return_month = (available - 1) // 4 + 1
        return_week = (available - 1) % 4 + 1
        return f"Available {self.format_game_date(return_month, return_week)}"

    def fighter_recovery_date_label(self, fighter):
        """Compact medical-return label for matchmaking tables."""
        if fighter.injured:
            return "Injured"
        available = int(getattr(fighter, "available_week", 0) or 0)
        if not available or self.calendar_week_index() >= available:
            return "Now"
        return_month = (available - 1) // 4 + 1
        return_week = (available - 1) % 4 + 1
        return self.format_game_date(return_month, return_week)

    def fighter_fatigue_label(self, fighter):
        fatigue = max(0, min(100, int(getattr(fighter, "fatigue", 0) or 0)))
        if fatigue >= 65:
            condition = "Unfit"
        elif fatigue >= 55:
            condition = "Tired"
        elif fatigue >= 40:
            condition = "Elevated"
        elif fatigue >= 20:
            condition = "Manageable"
        else:
            condition = "Fresh"
        return f"{fatigue} {condition}"

    def fighter_booking_status(self, fighter, month=None, week=None):
        """Availability label for a specific proposed event, not merely today."""
        if fighter.injured:
            return "Injured"
        if not self.fighter_available_for_date(fighter, month, week):
            return self.fighter_return_label(fighter)
        if fighter.fatigue >= 65:
            return f"Fatigued {fighter.fatigue}"
        return "Ready"

    def serious_injury_status(self, fighter):
        injury = getattr(fighter, "serious_injury", "")
        if not injury:
            return "None"
        decision = "Decision required" if getattr(fighter, "serious_injury_pending", False) else "Recovery underway"
        return f"{injury} — {decision}"

    def establish_rivalry(self, a, b, origin, heat=35, rematch_due=False):
        """Create a mutual, persistent feud and retain the story on both profiles."""
        if not a or not b or a is b or a.gender != b.gender or a.weight != b.weight:
            return False
        a.rival, b.rival = b.name, a.name
        a.rival_fighter_id = getattr(b, "fighter_id", "")
        b.rival_fighter_id = getattr(a, "fighter_id", "")
        shared_heat = max(10, min(100, heat))
        a.rivalry_heat = max(getattr(a, "rivalry_heat", 0), shared_heat)
        b.rivalry_heat = max(getattr(b, "rivalry_heat", 0), shared_heat)
        a.rivalry_origin = b.rivalry_origin = origin
        a.rivalry_rematch_due = b.rivalry_rematch_due = rematch_due
        a.rivalry_last_month = b.rivalry_last_month = self.month
        a.rivalry_history = (a.rivalry_history or [])[-39:] + [f"Month {self.month}: Rivalry with {b.name} began — {origin}."]
        b.rivalry_history = (b.rivalry_history or [])[-39:] + [f"Month {self.month}: Rivalry with {a.name} began — {origin}."]
        story_key = self.rivalry_story_key(a, b)
        origin_ref = f"{story_key}:origin:{self.month}:{self.week}:{hashlib.sha1(str(origin).encode('utf-8')).hexdigest()[:10]}"
        self.record_rivalry_story(
            a, b, phase="rematch_due" if rematch_due else "emerging",
            importance=3 if rematch_due else 2, beat_kind="origin", beat_ref=origin_ref,
            summary=f"The rivalry between {a.name} and {b.name} began: {origin}.",
            stakes=("A rematch is already demanded." if rematch_due else "The feud is building toward a credible divisional fight."),
        )
        return True

    def build_rivalry_heat(self, a, b, amount, note=""):
        """Add heat to a live feud so promotion can build a fight over weeks.

        ``establish_rivalry`` only ever raised heat to a floor, so repeated
        promotion could not make a grudge bigger. This is the accumulation the
        Media Desk needs for a booked grudge match to be worth building toward.
        """
        if not a or not b or not self.rivalry_heat_between(a, b):
            return 0
        amount = int(amount or 0)
        if amount <= 0:
            return int(max(getattr(a, "rivalry_heat", 0), getattr(b, "rivalry_heat", 0)))
        heat = min(100, max(getattr(a, "rivalry_heat", 0), getattr(b, "rivalry_heat", 0)) + amount)
        a.rivalry_heat = b.rivalry_heat = heat
        a.rivalry_last_month = b.rivalry_last_month = self.month
        if note:
            for fighter in (a, b):
                fighter.rivalry_history = (fighter.rivalry_history or [])[-39:]
                fighter.rivalry_history.append(f"Month {self.month}: {note} Heat now {heat}/100.")
            story_key = self.rivalry_story_key(a, b)
            beat_ref = f"{story_key}:heat:{self.month}:{self.week}:{hashlib.sha1(str(note).encode('utf-8')).hexdigest()[:10]}"
            self.record_rivalry_story(
                a, b, phase="hot" if heat >= 70 else "building", importance=3 if heat >= 70 else 2,
                beat_kind="escalation", beat_ref=beat_ref,
                summary=f"{note} Rivalry heat reached {heat}/100.",
                stakes="A promoted grudge match now carries sporting and commercial value.",
            )
        return heat

    def _rivalry_fighter_pool(self, fighter):
        """Return the ownership pool used to resolve a legacy rival name.

        Old saves retain display-name references.  They remain supported when
        the name identifies exactly one fighter in that roster; ambiguity must
        never silently attach a feud to an arbitrary same-name fighter.
        """
        pools = [getattr(self, "roster", []), getattr(self, "free_agents", [])]
        pools.extend(getattr(promotion, "roster", []) for promotion in getattr(self, "promotions", []))
        pools.extend(
            world.get("roster", [])
            for world in getattr(self, "combat_sport_worlds", {}).values()
            if isinstance(world, dict)
        )
        pools.append(getattr(self, "retired_fighters", []))
        for pool in pools:
            if any(candidate is fighter for candidate in pool):
                return pool
        return [candidate for pool in pools for candidate in pool]

    def resolve_rivalry_target(self, fighter):
        """Resolve one fighter's rival without guessing between duplicate names."""
        if not fighter or not getattr(fighter, "rival", ""):
            return None
        pool = self._rivalry_fighter_pool(fighter)
        rival_id = str(getattr(fighter, "rival_fighter_id", "") or "")
        if rival_id:
            return next((candidate for candidate in pool if getattr(candidate, "fighter_id", "") == rival_id), None)
        matches = [candidate for candidate in pool if candidate is not fighter and candidate.name == fighter.rival]
        return matches[0] if len(matches) == 1 else None

    def resolve_friend_target(self, fighter):
        """Resolve a legacy friend name only when it identifies one roster mate."""
        if not fighter or not getattr(fighter, "friend", ""):
            return None
        pool = self._rivalry_fighter_pool(fighter)
        matches = [
            candidate for candidate in pool
            if candidate is not fighter and candidate.name == fighter.friend
        ]
        return matches[0] if len(matches) == 1 else None

    def fighter_points_to_rival(self, fighter, opponent):
        """Test a proposed rival in O(1) for current ID-backed records.

        AI matchmaking calls this for many candidate pairs, so resolving every
        comparison through a roster scan would turn card construction cubic.
        Only legacy name-only records pay the uniqueness scan.
        """
        if not fighter or not opponent or fighter is opponent:
            return False
        rival_id = str(getattr(fighter, "rival_fighter_id", "") or "")
        if rival_id:
            return rival_id == str(getattr(opponent, "fighter_id", "") or "")
        if not getattr(fighter, "rival", "") or fighter.rival != opponent.name:
            return False
        matches = [
            candidate for candidate in self._rivalry_fighter_pool(fighter)
            if candidate is not fighter and candidate.name == fighter.rival
        ]
        return len(matches) == 1 and matches[0] is opponent

    def rivalry_is_between(self, a, b):
        if not a or not b or a is b:
            return False
        return self.fighter_points_to_rival(a, b) or self.fighter_points_to_rival(b, a)

    def mutual_rivalry_between(self, a, b):
        if not a or not b or a is b:
            return False
        return self.fighter_points_to_rival(a, b) and self.fighter_points_to_rival(b, a)

    def rivalry_heat_between(self, a, b):
        if self.rivalry_is_between(a, b):
            return max(getattr(a, "rivalry_heat", 0), getattr(b, "rivalry_heat", 0), 20)
        return 0

    def grudge_match_state(self, a, b):
        """Describe the feud between two fighters for booking and presentation.

        A rivalry already fed hype quietly. Surfacing it lets the player book a
        grudge match deliberately and see what the feud is worth.
        """
        if not a or not b:
            return {"grudge": False, "heat": 0, "origin": "", "rematch_due": False}
        heat = self.rivalry_heat_between(a, b)
        if not heat:
            return {"grudge": False, "heat": 0, "origin": "", "rematch_due": False}
        return {
            "grudge": True,
            "heat": int(heat),
            "origin": getattr(a, "rivalry_origin", "") or getattr(b, "rivalry_origin", ""),
            "rematch_due": bool(getattr(a, "rivalry_rematch_due", False) or getattr(b, "rivalry_rematch_due", False)),
        }

    def fight_grudge_state(self, fight):
        """Resolve the feud behind a booked fight from its current participants."""
        fighters = [item for item in self.event_fight_fighters(fight) if item]
        if len(fighters) != 2:
            return {"grudge": False, "heat": 0, "origin": "", "rematch_due": False}
        return self.grudge_match_state(fighters[0], fighters[1])

    def event_grudge_gate_bonus(self, event, results=None):
        """Gate lift from the feuds actually being settled on this card."""
        total = 0.0
        seen = set()
        rows = [row[2] for row in (results or [])] or list((event or {}).get("fights", []))
        for fight in rows:
            key = id(fight)
            if key in seen:
                continue
            seen.add(key)
            state = self.fight_grudge_state(fight)
            if not state["grudge"]:
                continue
            weight = 1.0 if (fight.get("main") or fight.get("title")) else 0.55
            total += (state["heat"] / 100.0) * weight
        return round(min(GRUDGE_MATCH_MAX_GATE_BONUS, total * GRUDGE_MATCH_MAX_GATE_BONUS), 4)

    def assign_career_goal(self, fighter, previous=""):
        """Give a fighter a concrete ambition that matches their public persona."""
        persona = getattr(fighter, "negotiation_persona", "Professional")
        options = {
            "Competitive": [("Win a World Title", 1), ("Build a Win Streak", 4), ("Settle a Rivalry", 1)],
            "Star Chaser": [("Become a Star", 70), ("Win a World Title", 1), ("Build a Win Streak", 4)],
            "Hard Bargainer": [("Secure a Payday", max(fighter.purse + 3_000, round(fighter.purse * 1.35))), ("Become a Star", 65)],
            "Security First": [("Earn Contract Security", 18), ("Secure a Payday", max(fighter.purse + 2_000, round(fighter.purse * 1.2)))],
            "Loyalist": [("Build a Win Streak", 3), ("Win a World Title", 1), ("Earn Contract Security", 16)],
            "Professional": [("Build a Win Streak", 3), ("Become a Star", 60), ("Win a World Title", 1)],
        }
        candidates = [item for item in options.get(persona, options["Professional"]) if item[0] != previous]
        if fighter.rival:
            candidates.append(("Settle a Rivalry", 1))
        goal, target = random.choice(candidates)
        fighter.career_goal, fighter.career_goal_target = goal, target
        fighter.career_goal_progress = 0
        fighter.career_goal_last_review = self.month
        return goal

    def career_goal_state(self, fighter):
        goal, target = getattr(fighter, "career_goal", ""), max(1, getattr(fighter, "career_goal_target", 1))
        if goal == "Win a World Title":
            return int(bool(fighter.champion)), 100 if fighter.champion else min(85, max(0, fighter.rank_score // 12))
        if goal == "Build a Win Streak":
            return fighter.career_win_streak >= target, min(100, round(fighter.career_win_streak / target * 100))
        if goal == "Become a Star":
            return fighter.popularity >= target, min(100, round(fighter.popularity / target * 100))
        if goal == "Secure a Payday":
            return fighter.purse >= target, min(100, round(fighter.purse / target * 100))
        if goal == "Earn Contract Security":
            return fighter.contract_months >= target, min(100, round(fighter.contract_months / target * 100))
        if goal == "Settle a Rivalry":
            resolved = not fighter.rival and any("claims the rivalry result" in str(note) for note in (fighter.rivalry_history or []))
            return resolved, 100 if resolved else (65 if fighter.rival else 0)
        return False, 0

    def process_career_goals(self):
        """Review active goals monthly; fulfillment improves morale, neglect erodes trust."""
        for roster, player_owned in [(self.roster, True)] + [(promo.roster, False) for promo in self.promotions]:
            for fighter in roster:
                if fighter.retired:
                    continue
                if not getattr(fighter, "career_goal", ""):
                    self.assign_career_goal(fighter)
                complete, progress = self.career_goal_state(fighter)
                fighter.career_goal_progress = progress
                if complete:
                    goal = fighter.career_goal
                    fighter.career_goal_history = (fighter.career_goal_history or [])[-19:] + [f"Month {self.month}: Completed career goal — {goal}."]
                    fighter.morale = min(100, fighter.morale + 7)
                    fighter.motivation = min(99, fighter.motivation + 6)
                    fighter.relationship_trust = min(100, fighter.relationship_trust + 4)
                    if player_owned:
                        self.inbox.append({"subject": f"Career Goal Completed — {fighter.name}", "body": f"{fighter.name} completed their goal: {goal}. Morale and motivation improved.", "type": "Talent Relations", "fighter": fighter.name, "resolved": False})
                    self.assign_career_goal(fighter, previous=goal)
                elif player_owned and progress < 20 and self.month - getattr(fighter, "career_goal_last_review", 0) >= 6:
                    fighter.relationship_trust = max(1, fighter.relationship_trust - 2)
                    fighter.morale = max(15, fighter.morale - 1)
                    fighter.career_goal_last_review = self.month
                    self.inbox.append({"subject": f"Career Goal Stalling — {fighter.name}", "body": f"{fighter.name}'s goal ({fighter.career_goal}) is only {progress}% complete. Their camp wants a clearer path.", "type": "Talent Relations", "fighter": fighter.name, "resolved": False})

    def is_player_academy_graduate(self, fighter):
        return bool(
            getattr(fighter, "academy_graduate", False)
            or "Fighting Academy" in str(getattr(fighter, "feeder_origin", ""))
        )

    def career_arc_note(self, fighter, note):
        fighter.career_arc_history = (getattr(fighter, "career_arc_history", None) or [])[-29:] + [
            f"Month {self.month}: {note}"
        ]

    def career_arc_definition(self, arc_type):
        definitions = {
            "Homegrown Champion": {
                "title": "Homegrown Champion",
                "objective": "Build an academy graduate into the promotion's first homegrown champion.",
                "deadline": 60,
            },
            "Veteran Final Run": {
                "title": "One Last Title Run",
                "objective": "Give a proven veteran a credible route to one final championship opportunity.",
                "deadline": 9,
            },
            "Professional Reset": {
                "title": "Professional Reset",
                "objective": "Turn raw talent into reliable habits before poor discipline limits the prospect.",
                "deadline": 8,
            },
            "Weight Management": {
                "title": "Weight-Cut Turnaround",
                "objective": "Stabilise a difficult cut and make weight for two consecutive appearances.",
                "deadline": 12,
            },
            "Camp Fit": {
                "title": "Find The Right Room",
                "objective": "Move a stalled fighter into a camp that suits their development.",
                "deadline": 9,
            },
            "Champion Ambition": {
                "title": "Keep The Champion",
                "objective": "Give the champion opponents, visibility, and a contract future worth defending.",
                "deadline": 6,
            },
        }
        return definitions.get(arc_type, {"title": arc_type, "objective": "Guide this fighter through the next stage of their career.", "deadline": 8})

    def active_career_arc(self, fighter):
        arc = getattr(fighter, "career_arc", None)
        return arc if isinstance(arc, dict) and arc.get("status", "active") == "active" else None

    def start_career_arc(self, fighter, arc_type, source="Career review"):
        if not fighter or self.active_career_arc(fighter):
            return False
        definition = self.career_arc_definition(arc_type)
        arc = {
            "type": arc_type,
            "title": definition["title"],
            "objective": definition["objective"],
            "status": "active",
            "started_month": self.month,
            "deadline_month": self.month + definition["deadline"],
            "plan": "",
            "last_review_month": self.month,
            "source": source,
            "baseline_title_shots": getattr(fighter, "title_shots", 0),
            "baseline_defenses": getattr(fighter, "title_defenses", 0),
            "baseline_fit": round(self.gym_fit_score(fighter, self.gym_by_name(fighter.camp), fighter.region)) if self.gym_by_name(fighter.camp) else 0,
            "weight_successes": 0,
        }
        fighter.career_arc = arc
        fighter.career_arc_last_offer_month = self.month
        self.career_arc_note(fighter, f"{definition['title']} began. {definition['objective']}")
        gym = self.gym_by_name(getattr(fighter, "camp", ""))
        if gym:
            self.record_gym_story(gym, f"Career story: {definition['title']}", definition["objective"], fighter=fighter)
        if arc_type == "Weight Management":
            self.record_weight_journey_story(
                fighter, phase="turnaround_started",
                summary=f"{fighter.name} began a structured weight-cut turnaround after reliability concerns.",
            )
        elif arc_type == "Camp Fit":
            self.record_gym_journey_story(
                fighter, phase="fit_review",
                summary=f"{fighter.name}'s camp fit came under review after development stalled.",
            )
        if fighter in getattr(self, "roster", []) and not getattr(self, "spectator_mode", False):
            self.inbox.append({
                "subject": f"Career Story - {fighter.name}",
                "body": f"{definition['title']}: {definition['objective']} Open Fighter Career Goals to choose how to support the plan.",
                "type": "Talent Relations", "fighter": fighter.name, "resolved": False,
            })
        return True

    def career_arc_state(self, fighter):
        arc = self.active_career_arc(fighter)
        if not arc:
            return False, 0, "No active career story."
        arc_type = arc.get("type", "")
        elapsed = max(0, self.month - arc.get("started_month", self.month))
        plan = arc.get("plan", "")
        if arc_type == "Homegrown Champion":
            if fighter.champion:
                return True, 100, "The academy graduate reached the summit."
            rank = getattr(fighter, "ranking_position", 0)
            ranking_progress = 70 if rank and rank <= 3 else 52 if rank and rank <= 6 else 35 if rank and rank <= 10 else 12
            progress = min(92, ranking_progress + min(20, getattr(fighter, "career_win_streak", 0) * 5) + min(10, fighter.record_w * 2))
            return False, progress, "Build ranking momentum, then earn a legitimate title fight."
        if arc_type == "Veteran Final Run":
            if fighter.champion or getattr(fighter, "title_shots", 0) > arc.get("baseline_title_shots", 0):
                return True, 100, "The veteran received the promised championship opportunity."
            rank = getattr(fighter, "ranking_position", 0)
            progress = 18 + (42 if getattr(fighter, "top_opponent_promise", False) else 0) + (20 if getattr(fighter, "main_event_promise", False) else 0)
            if rank and rank <= 5:
                progress += 20
            return False, min(90, progress), "Book a ranked opponent or title fight; the result remains up to the fight engine."
        if arc_type == "Professional Reset":
            professionalism = getattr(fighter, "professionalism", 50)
            progress = min(100, max(0, (professionalism - 35) * 2) + min(24, elapsed * 4))
            return professionalism >= 65 and elapsed >= 4, progress, "Structured training needs time, reliable habits, and active competition."
        if arc_type == "Weight Management":
            successes = int(arc.get("weight_successes", 0) or 0)
            return successes >= 2, min(100, successes * 50), f"Made weight appearances: {successes}/2."
        if arc_type == "Camp Fit":
            gym = self.gym_by_name(getattr(fighter, "camp", ""))
            current_fit = round(self.gym_fit_score(fighter, gym, fighter.region)) if gym else 0
            improved = current_fit - arc.get("baseline_fit", current_fit)
            complete = bool(plan) and improved >= 8 and elapsed >= 2
            progress = min(100, max(8, 35 + improved * 5 + elapsed * 4 if plan else 8))
            return complete, progress, f"Current camp fit {current_fit:+d}; a meaningful improvement needs time in the new room."
        if arc_type == "Champion Ambition":
            defense_gain = max(0, getattr(fighter, "title_defenses", 0) - arc.get("baseline_defenses", 0))
            if not fighter.champion:
                return False, 0, "The title changed hands before the retention plan was completed."
            secure_deal = fighter.contract_months >= 8
            spotlight = plan in ("Showcase campaign", "Renew the deal")
            complete = defense_gain >= 1 and secure_deal and bool(plan)
            progress = min(95, defense_gain * 45 + (25 if secure_deal else 0) + (20 if spotlight else 0) + (10 if getattr(fighter, "top_opponent_promise", False) else 0))
            return complete, progress, "Keep a real opponent path and a credible future on the champion's contract."
        return False, 0, arc.get("objective", "")

    def career_arc_options(self, fighter):
        arc = self.active_career_arc(fighter)
        if not arc:
            return []
        options = {
            "Homegrown Champion": [
                ("title_path", "Build contender path", "Promise a ranked opponent within six months; this does not guarantee a title shot."),
                ("development", "Fund structured development", "Invest $6,000 in coaching, habits, and a focused development block."),
                ("camp", "Review camp fit", "Choose a gym and camp plan suited to the fighter's long-term development."),
            ],
            "Veteran Final Run": [
                ("title_path", "Back the final run", "Commit to a ranked opponent and featured opportunity within six months."),
                ("showcase", "Build a farewell showcase", "Spend $25,000 on a media push and feature the fighter when a suitable bout is booked."),
                ("decline", "Set honest expectations", "Decline the title-run request; trust and morale will fall, but no promise is made."),
            ],
            "Professional Reset": [
                ("development", "Fund structured development", "Invest $6,000 in coaching, habits, and a focused development block."),
                ("camp", "Review camp fit", "Put the fighter in a more accountable room and set a clear workload."),
            ],
            "Weight Management": [
                ("nutrition", "Fund nutrition support", "Spend $8,000 on a targeted weight-management programme and set the next camp focus."),
                ("camp", "Review division and camp", "Choose a camp plan now; a division move remains available from the fighter profile."),
            ],
            "Camp Fit": [
                ("camp", "Find the right room", "Choose a new gym, focus, and workload; the fit must improve over time."),
                ("development", "Fund structured development", "Invest $6,000 in coaching while you decide whether a move is needed."),
            ],
            "Champion Ambition": [
                ("showcase", "Build a showcase campaign", "Spend $25,000 on visibility and commit to a meaningful featured defence."),
                ("title_path", "Promise elite opposition", "Commit to a ranked challenger within six months."),
                ("contract", "Renew the deal", "Open contract negotiations to secure the champion's long-term future."),
            ],
        }
        return options.get(arc.get("type"), [])

    def apply_career_arc_plan(self, fighter, action):
        arc = self.active_career_arc(fighter)
        if not arc:
            return False, "This fighter has no active career story.", ""
        costs = {"development": 6000, "nutrition": 8000, "showcase": 25000}
        cost = costs.get(action, 0)
        if cost and self.cash < cost:
            return False, f"${cost:,} is required for this plan, but the company cannot fund it today.", ""
        if action == "contract":
            arc["plan"] = "Renew the deal"
            self.career_arc_note(fighter, "The promotion opened contract talks to secure the next chapter.")
            return True, "Open the contract offer and agree terms that match the champion's ambition.", "contract"
        if action == "camp":
            arc["plan"] = "Camp review"
            self.career_arc_note(fighter, "The promotion ordered a camp and workload review.")
            return True, "Choose the gym, focus, and workload for the next camp.", "camp"
        if action == "decline":
            arc["plan"] = "Expectations managed"
            fighter.relationship_trust = max(1, fighter.relationship_trust - 8)
            fighter.morale = max(15, fighter.morale - 6)
            self.career_arc_note(fighter, "The promotion declined the requested title run and set honest expectations.")
            if fighter in self.roster:
                self.inbox.append({
                    "subject": f"Career Story Closed - {fighter.name}",
                    "body": "The veteran's requested final title run was declined. The decision is final, so it will not be penalized again at the old review deadline.",
                    "type": "Talent Relations", "fighter": fighter.name, "resolved": True,
                })
            fighter.career_arc = None
            return True, "The request was declined. The veteran remains under contract, but trust and morale fell.", ""
        if cost:
            self.cash -= cost
            self.finance["other"] = self.finance.get("other", 0) - cost
            self.record_finance_transaction(
                f"Career plan: {action} ({fighter.name})", costs=cost,
                category="Fighter development", source="Career journey", counterparty=fighter.name,
                reference=f"career-plan:{getattr(fighter, 'fighter_id', fighter.name)}:{action}:{self.month}:{self.week}",
            )
        if action == "development":
            arc["plan"] = "Structured development"
            fighter.professionalism = min(99, fighter.professionalism + 4)
            fighter.motivation = min(99, fighter.motivation + 5)
            self.ensure_detailed_skills(fighter)
            fighter.detailed_skills["dedication"] = min(99, fighter.detailed_skills.get("dedication", fighter.professionalism) + 3)
            fighter.camp_focus = "Game Plan" if fighter.camp_focus == "Balanced" else fighter.camp_focus
            note = f"Invested ${cost:,} in a structured development programme."
        elif action == "nutrition":
            arc["plan"] = "Nutrition programme"
            fighter.camp_focus = "Weight Management"
            fighter.camp_intensity = "Standard"
            fighter.walk_weight = max(WEIGHT_LIMITS.get(fighter.weight, fighter.walk_weight) + 3, (fighter.walk_weight or self.default_walk_weight(fighter)) - 2)
            fighter.weight_cut_penalty = max(0, fighter.weight_cut_penalty - 3)
            self.ensure_detailed_skills(fighter)
            fighter.detailed_skills["weight_cutting"] = min(99, fighter.detailed_skills.get("weight_cutting", fighter.cardio) + 3)
            note = f"Invested ${cost:,} in nutrition and weight-cut support."
        elif action == "showcase":
            arc["plan"] = "Showcase campaign"
            fighter.popularity = min(100, fighter.popularity + 3)
            fighter.media_heat = min(100, fighter.media_heat + 8)
            fighter.main_event_promise = True
            fighter.top_opponent_promise = True
            fighter.promise_deadline_month = max(fighter.promise_deadline_month, self.month + 6)
            note = f"Invested ${cost:,} in a showcase campaign and meaningful opponent path."
        elif action == "title_path":
            arc["plan"] = "Contender path"
            fighter.top_opponent_promise = True
            if arc.get("type") in ("Veteran Final Run", "Champion Ambition"):
                fighter.main_event_promise = True
            fighter.promise_deadline_month = max(fighter.promise_deadline_month, self.month + 6)
            fighter.motivation = min(99, fighter.motivation + 4)
            note = "Committed to a ranked-opponent path within six months."
        else:
            return False, "That career-plan action is not available.", ""
        self.career_arc_note(fighter, note)
        gym = self.gym_by_name(getattr(fighter, "camp", ""))
        if gym:
            self.record_gym_story(gym, f"Career plan: {arc.get('title', arc.get('type'))}", note, fighter=fighter)
        if arc.get("type") == "Weight Management":
            self.record_weight_journey_story(
                fighter, phase="support_plan", summary=f"{fighter.name}: {note}",
            )
        elif arc.get("type") == "Camp Fit":
            self.record_gym_journey_story(
                fighter, phase="support_plan", summary=f"{fighter.name}: {note}",
            )
        return True, note, ""

    def ensure_relationship_cases(self):
        """Repair the Talent Relations case shelf without deriving new concerns."""
        normalized = self.relationship_cases_read_model()
        self.relationship_cases = normalized
        return normalized

    @staticmethod
    def _legacy_relationship_case_id(case):
        """Return a deterministic identity for an ID-less retained case row."""
        case = case if isinstance(case, dict) else {}
        payload = {
            "fighter_id": str(case.get("fighter_id", "") or ""),
            "fighter_name": str(case.get("fighter_name", "") or ""),
            "company_at_open": str(case.get("company_at_open", "") or ""),
            "source_kind": str(case.get("source_kind", "") or ""),
            "source_ref": str(case.get("source_ref", "") or ""),
            "review_month": case.get("review_month", 0),
            "created_week": case.get("created_week", 0),
            "original_obligations": list(case.get("original_obligations", []) or [])
            if isinstance(case.get("original_obligations", []), (list, tuple)) else [],
        }
        digest = hashlib.sha1(json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")).hexdigest()[:20]
        return f"CASE-legacy-{digest}"

    def relationship_cases_read_model(self):
        """Return a defensive case projection without repairing saved rows.

        Talent Relations pages and Staff contract review are readers.  They
        must be able to explain a malformed legacy case without rewriting the
        source shelf; explicit case opening/acknowledgement/action mutations
        continue to use ``ensure_relationship_cases``.
        """
        rows = getattr(self, "relationship_cases", None)
        if not isinstance(rows, list):
            return []
        normalized, seen = [], set()
        for raw in rows[:200]:
            if not isinstance(raw, dict):
                continue
            case = dict(raw)
            case_id = str(case.get("case_id", "") or "").strip()[:60]
            if not case_id:
                base_case_id = self._legacy_relationship_case_id(case)
                case_id = base_case_id
                suffix = 2
                while case_id in seen:
                    case_id = f"{base_case_id}#{suffix}"
                    suffix += 1
            if not case_id or case_id in seen:
                continue
            seen.add(case_id)
            status = str(case.get("status", "Open") or "Open")
            if status not in {"Open", "Partially delivered", "Ready to review", "Resolved", "Closed - departed", "Transferred"}:
                status = "Open"
            history = case.get("history", [])
            if not isinstance(history, list):
                history = []
            evidence_refs = case.get("evidence_refs", [])
            if not isinstance(evidence_refs, (list, tuple)):
                evidence_refs = []
            original_obligations = case.get("original_obligations", [])
            if not isinstance(original_obligations, (list, tuple)):
                original_obligations = []

            def safe_nonnegative_int(value):
                try:
                    return max(0, int(value or 0))
                except (TypeError, ValueError, OverflowError):
                    return 0

            case.update({
                "case_id": case_id, "fighter_id": str(case.get("fighter_id", "") or ""),
                "fighter_name": str(case.get("fighter_name", "") or "")[:120],
                "company_at_open": str(case.get("company_at_open", "") or "")[:120],
                "source_kind": str(case.get("source_kind", "") or "")[:40],
                "source_ref": str(case.get("source_ref", "") or "")[:160],
                "reason": str(case.get("reason", "") or "")[:800],
                "evidence_refs": [str(value)[:160] for value in evidence_refs if value][:12],
                "what_owed": str(case.get("what_owed", "") or "")[:800],
                "original_obligations": [str(value)[:100] for value in original_obligations if value][:8],
                "review_month": safe_nonnegative_int(case.get("review_month", 0)),
                "acknowledged": bool(case.get("acknowledged", False)),
                "selected_action": str(case.get("selected_action", "") or "")[:80],
                "resolution": str(case.get("resolution", "") or "")[:800], "status": status,
                "created_week": safe_nonnegative_int(case.get("created_week", 0)),
                "updated_week": safe_nonnegative_int(case.get("updated_week", case.get("created_week", 0))),
                "last_review_week": safe_nonnegative_int(case.get("last_review_week", 0)),
                "history": [dict(item) for item in history[-12:] if isinstance(item, dict)],
            })
            normalized.append(case)
        return normalized

    def _relationship_case_fighter(self, fighter_id):
        key = str(fighter_id or "")
        if not key:
            return None
        return next((fighter for fighter in self.all_scoutable_fighters()
                     if str(getattr(fighter, "fighter_id", "") or "") == key), None)

    def _relationship_case_source(self, fighter):
        promises = []
        if getattr(fighter, "main_event_promise", False):
            promises.append("main-event")
        if getattr(fighter, "top_opponent_promise", False):
            promises.append("top-opponent")
        if promises:
            return {
                "kind": "Contract Promise", "ref": self.contract_promise_story_key(fighter),
                "obligations": promises,
                "reason": f"{fighter.name} has an active {' and '.join(promises)} commitment.",
                "owed": f"Deliver a {' and '.join(promises)} opportunity before the recorded deadline.",
                "review_month": int(getattr(fighter, "promise_deadline_month", 0) or self.month),
            }
        arc = self.active_career_arc(fighter)
        if arc:
            _complete, progress, summary = self.career_arc_state(fighter)
            ref = f"career-arc:{getattr(fighter, 'fighter_id', '')}:{arc.get('started_month', self.month)}"
            return {
                "kind": "Career Journey", "ref": ref,
                "obligations": [str(arc.get("type", "Career Journey"))],
                "reason": f"{fighter.name}'s {arc.get('title', 'career story')} needs a documented decision.",
                "owed": f"{summary} Current progress is {progress}%.",
                "review_month": int(arc.get("deadline_month", self.month) or self.month),
            }
        return None

    def open_relationship_case(self, fighter):
        """Open one case from an existing promise or career story, once."""
        source = self._relationship_case_source(fighter) if fighter else None
        if not source:
            return False, "No active promise or Career Journey concern is recorded for this fighter."
        self.ensure_relationship_cases()
        fighter_id = str(getattr(fighter, "fighter_id", "") or "")
        existing = next((case for case in self.relationship_cases
                         if case.get("fighter_id") == fighter_id and case.get("source_ref") == source["ref"]
                         and case.get("status") not in {"Resolved", "Closed - departed"}), None)
        if existing:
            return True, existing
        case_id = f"CASE-{len(self.relationship_cases) + 1:05d}"
        used = {str(case.get("case_id", "")) for case in self.relationship_cases}
        number = len(self.relationship_cases) + 1
        while case_id in used:
            number += 1
            case_id = f"CASE-{number:05d}"
        case = {
            "case_id": case_id, "fighter_id": fighter_id, "fighter_name": str(fighter.name),
            "company_at_open": str(self.fighter_company_name(fighter) if hasattr(self, "fighter_company_name") else self.player_company_name),
            "source_kind": source["kind"], "source_ref": source["ref"], "reason": source["reason"],
            "evidence_refs": [source["ref"]], "what_owed": source["owed"],
            "original_obligations": list(source["obligations"]), "review_month": source["review_month"],
            "acknowledged": False, "selected_action": "", "resolution": "", "status": "Open",
            "created_week": self.calendar_week_index(), "updated_week": self.calendar_week_index(), "last_review_week": 0,
            "history": [{"week": self.calendar_week_index(), "kind": "opened", "summary": source["reason"]}],
        }
        self.relationship_cases.insert(0, case)
        self.relationship_cases = self.relationship_cases[:200]
        return True, case

    def relationship_case_available_actions(self, fighter, source_kind):
        if source_kind == "Career Journey" and fighter:
            actions = [(key, label) for key, label, _description in self.career_arc_options(fighter)]
            return actions + [("no_new_promise", "Set honest expectations")]
        if source_kind == "Contract Promise":
            return [("review_contract", "Review contract"), ("no_new_promise", "Set honest expectations")]
        return [("no_new_promise", "No new commitment")]

    def relationship_case_read_model(self, case):
        """Derive current obligations from source truth; case fields are not a second promise store."""
        case = case if isinstance(case, dict) else {}
        fighter = self._relationship_case_fighter(case.get("fighter_id"))
        source_kind = str(case.get("source_kind", "") or "")
        raw_original = case.get("original_obligations", [])
        original = list(raw_original) if isinstance(raw_original, (list, tuple)) else []
        try:
            review_month = max(0, int(case.get("review_month", 0) or 0))
        except (TypeError, ValueError, OverflowError):
            review_month = 0
        current = []
        if fighter and source_kind == "Contract Promise":
            if getattr(fighter, "main_event_promise", False):
                current.append("main-event")
            if getattr(fighter, "top_opponent_promise", False):
                current.append("top-opponent")
        elif fighter and source_kind == "Career Journey":
            arc = self.active_career_arc(fighter)
            if arc:
                current = [str(arc.get("type", "Career Journey"))]
        company_now = str(self.fighter_company_name(fighter) if fighter and hasattr(self, "fighter_company_name") else "")
        company_at_open = str(case.get("company_at_open", "") or "")
        if not fighter or getattr(fighter, "retired", False):
            status = "Closed - departed"
            resolution = "The fighter is no longer available; responsibility is closed without deleting the recorded story."
        elif company_at_open and company_now and company_now != company_at_open:
            status = "Transferred"
            resolution = f"Responsibility moved from {company_at_open} to {company_now}; the case remains readable without changing the new employer's commitments."
        elif source_kind == "Contract Promise" and not current:
            story = self.story_thread(case.get("source_ref", ""))
            status = "Resolved" if case.get("resolution") or story and story.get("status") == "resolved" else "Ready to review"
            resolution = case.get("resolution", "") or "The source promise flags are no longer active; review the recorded delivery before closing the case."
        elif source_kind == "Career Journey" and fighter:
            complete, _progress, summary = self.career_arc_state(fighter)
            status = "Ready to review" if complete else "Open"
            resolution = summary if complete else ""
        else:
            status = str(case.get("status", "Open") or "Open")
            resolution = str(case.get("resolution", "") or "")
        delivered = [value for value in original if value not in current]
        if current and delivered:
            status = "Partially delivered"
        return {
            "case_id": str(case.get("case_id", "") or ""), "fighter_id": str(case.get("fighter_id", "") or ""),
            "fighter_name": str(getattr(fighter, "name", "") or case.get("fighter_name", "Unknown fighter")),
            "fighter": fighter, "source_kind": source_kind,
            "reason": str(case.get("reason", "") or "Reason unavailable"),
            "what_owed": str(case.get("what_owed", "") or "No obligation recorded"),
            "current_obligations": current, "delivered_obligations": delivered,
            "review_month": review_month, "status": status,
            "acknowledged": bool(case.get("acknowledged", False)),
            "selected_action": str(case.get("selected_action", "") or ""), "resolution": resolution,
            "available_actions": self.relationship_case_available_actions(fighter, source_kind),
            "company_at_open": company_at_open, "company_now": company_now,
        }

    def relationship_case_rows(self, include_closed=True):
        rows = [self.relationship_case_read_model(case) for case in self.relationship_cases_read_model()]
        if not include_closed:
            rows = [row for row in rows if row.get("status") not in {"Resolved", "Closed - departed", "Transferred"}]
        return rows

    def acknowledge_relationship_case(self, case_id):
        self.ensure_relationship_cases()
        case = next((row for row in self.relationship_cases if row.get("case_id") == str(case_id or "")), None)
        if not case:
            return False, "Relationship case not found."
        if not case.get("acknowledged"):
            case["acknowledged"] = True
            case.setdefault("history", []).append({"week": self.calendar_week_index(), "kind": "acknowledged", "summary": "Player reviewed the case evidence."})
            case["history"] = case["history"][-12:]
            case["updated_week"] = self.calendar_week_index()
        return True, case

    def select_relationship_case_action(self, case_id, action):
        self.ensure_relationship_cases()
        case = next((row for row in self.relationship_cases if row.get("case_id") == str(case_id or "")), None)
        if not case:
            return False, "Relationship case not found."
        model = self.relationship_case_read_model(case)
        action = str(action or "")
        if action not in {key for key, _label in model.get("available_actions", [])}:
            return False, "That action is not available for this case."
        case["selected_action"] = action
        case.setdefault("history", []).append({"week": self.calendar_week_index(), "kind": "action_selected", "summary": action})
        case["history"] = case["history"][-12:]
        case["updated_week"] = self.calendar_week_index()
        return True, case

    def review_relationship_case(self, case_id):
        self.ensure_relationship_cases()
        case = next((row for row in self.relationship_cases if row.get("case_id") == str(case_id or "")), None)
        if not case:
            return False, "Relationship case not found."
        model = self.relationship_case_read_model(case)
        case["last_review_week"] = self.calendar_week_index()
        case["updated_week"] = self.calendar_week_index()
        case["status"] = model["status"]
        if model.get("resolution") and model["status"] in {"Resolved", "Closed - departed", "Transferred"}:
            case["resolution"] = model["resolution"]
        case.setdefault("history", []).append({"week": self.calendar_week_index(), "kind": "reviewed", "summary": f"Review: {model['status']}"})
        case["history"] = case["history"][-12:]
        return True, self.relationship_case_read_model(case)

    def complete_career_arc(self, fighter, conclusion):
        arc = self.active_career_arc(fighter)
        if not arc:
            return
        title = arc.get("title", arc.get("type", "Career Story"))
        fighter.career_achievements = (fighter.career_achievements or [])[-39:] + [f"{title}: {conclusion}"]
        self.career_arc_note(fighter, f"Completed {title}. {conclusion}")
        fighter.morale = min(100, fighter.morale + 8)
        fighter.motivation = min(99, fighter.motivation + 6)
        fighter.relationship_trust = min(100, fighter.relationship_trust + 6)
        if arc.get("type") == "Homegrown Champion":
            academy = self.repair_academy(getattr(self, "academy", {}))
            academy["reputation"] = min(100, academy.get("reputation", 10) + 8)
            academy["alumni"] = [
                {**row, "title_wins": max(1, row.get("title_wins", 0))} if row.get("name") == fighter.name else row
                for row in academy.get("alumni", [])
            ]
        gym = self.gym_by_name(getattr(fighter, "camp", ""))
        if gym:
            self.record_gym_story(gym, f"Career story completed: {title}", conclusion, fighter=fighter)
        if arc.get("type") == "Weight Management":
            summary = f"{fighter.name} completed the weight-cut turnaround. {conclusion}"
            self.record_weight_journey_story(
                fighter, phase="turnaround_complete", status="resolved", importance=4,
                summary=summary, resolution=summary,
            )
        elif arc.get("type") == "Camp Fit":
            summary = f"{fighter.name} established a productive fit at {fighter.camp}. {conclusion}"
            self.record_gym_journey_story(
                fighter, phase="fit_confirmed", status="resolved", importance=3,
                summary=summary, resolution=summary,
            )
        if fighter in self.roster:
            self.inbox.append({"subject": f"Career Story Completed - {fighter.name}", "body": f"{title}: {conclusion}", "type": "Talent Relations", "fighter": fighter.name, "resolved": False})
        fighter.career_arc = None

    def fail_career_arc(self, fighter, conclusion):
        arc = self.active_career_arc(fighter)
        if not arc:
            return
        title = arc.get("title", arc.get("type", "Career Story"))
        if arc.get("type") == "Champion Ambition":
            fighter.negotiation_heat = min(100, getattr(fighter, "negotiation_heat", 0) + 12)
            conclusion += " Their camp is now actively testing the market."
        self.career_arc_note(fighter, f"{title} stalled. {conclusion}")
        if arc.get("type") == "Weight Management":
            summary = f"{fighter.name}'s weight-cut turnaround stalled. {conclusion}"
            self.record_weight_journey_story(
                fighter, phase="turnaround_failed", status="resolved", importance=4,
                summary=summary, resolution=summary,
            )
        elif arc.get("type") == "Camp Fit":
            summary = f"{fighter.name}'s search for the right room stalled. {conclusion}"
            self.record_gym_journey_story(
                fighter, phase="fit_unresolved", status="resolved", importance=3,
                summary=summary, resolution=summary,
            )
        fighter.relationship_trust = max(1, fighter.relationship_trust - 7)
        fighter.morale = max(15, fighter.morale - 5)
        if fighter in self.roster:
            self.inbox.append({"subject": f"Career Story Stalled - {fighter.name}", "body": f"{title}: {conclusion}", "type": "Talent Relations", "fighter": fighter.name, "resolved": False})
        fighter.career_arc = None

    def record_career_arc_result(self, fighters, fight):
        for fighter in fighters:
            arc = self.active_career_arc(fighter)
            if not arc:
                continue
            if arc.get("type") == "Weight Management":
                if not getattr(fighter, "missed_weight", False):
                    arc["weight_successes"] = min(2, int(arc.get("weight_successes", 0) or 0) + 1)
                    self.career_arc_note(fighter, f"Made weight successfully ({arc['weight_successes']}/2).")
                    self.record_weight_journey_story(
                        fighter, phase="made_weight",
                        summary=f"{fighter.name} made weight successfully ({arc['weight_successes']}/2 in the turnaround).",
                    )
                else:
                    arc["weight_successes"] = 0
                    self.career_arc_note(fighter, "Missed weight; the turnaround count resets.")
                    self.record_weight_journey_story(
                        fighter, phase="setback", importance=4,
                        summary=f"{fighter.name} missed weight again; the turnaround count reset.",
                    )
            complete, _progress, conclusion = self.career_arc_state(fighter)
            if complete:
                self.complete_career_arc(fighter, conclusion)

    def offer_player_career_arc(self):
        if getattr(self, "spectator_mode", False) or self.rules.get("career_arc_last_generation_month") == self.month:
            return False
        candidates = []
        for fighter in self.roster:
            if fighter.retired or self.active_career_arc(fighter):
                continue
            seen = " ".join(getattr(fighter, "career_arc_history", None) or [])
            if self.is_player_academy_graduate(fighter) and "Homegrown Champion began" not in seen:
                candidates.append((0, fighter.potential * 2 + max(0, 28 - fighter.age), fighter, "Homegrown Champion", "Academy promotion"))
            if fighter.champion and fighter.contract_months <= 10 and "Keep The Champion began" not in seen:
                candidates.append((1, fighter.popularity + fighter.title_defenses * 8, fighter, "Champion Ambition", "Champion contract review"))
            if fighter.age >= 34 and fighter.record_w + fighter.record_l >= 16 and fighter.popularity >= 28 and "One Last Title Run began" not in seen:
                candidates.append((2, fighter.popularity + fighter.record_w + max(0, 39 - fighter.age), fighter, "Veteran Final Run", "Veteran career review"))
            if fighter.age <= 27 and fighter.potential - fighter.overall >= 8 and fighter.professionalism <= 48 and "Professional Reset began" not in seen:
                candidates.append((3, fighter.potential - fighter.professionalism, fighter, "Professional Reset", "Prospect development review"))
            if (fighter.missed_weight or fighter.weight_cut_penalty >= 8) and "Weight-Cut Turnaround began" not in seen:
                candidates.append((4, fighter.weight_cut_penalty + (12 if fighter.missed_weight else 0), fighter, "Weight Management", "Medical and performance review"))
            gym = self.gym_by_name(getattr(fighter, "camp", ""))
            fit = self.gym_fit_score(fighter, gym, fighter.region) if gym else 0
            if fighter.age <= fighter.prime_end and fighter.potential - fighter.overall >= 6 and fit < 48 and "Find The Right Room began" not in seen:
                candidates.append((5, 55 - fit + fighter.potential - fighter.overall, fighter, "Camp Fit", "Camp development review"))
        if not candidates:
            return False
        _priority, _score, fighter, arc_type, source = sorted(candidates, key=lambda row: (row[0], -row[1], row[2].name, row[3]))[0]
        if self.start_career_arc(fighter, arc_type, source):
            self.rules["career_arc_last_generation_month"] = self.month
            return True
        return False

    def process_career_arcs(self):
        """Advance player-controlled long-form stories alongside ordinary career goals."""
        self.offer_player_career_arc()
        for fighter in list(self.roster):
            arc = self.active_career_arc(fighter)
            if not arc:
                continue
            if arc.get("type") == "Champion Ambition" and not fighter.champion:
                self.fail_career_arc(fighter, "The title changed hands before the promised opponent and contract path was secured.")
                continue
            complete, _progress, conclusion = self.career_arc_state(fighter)
            if complete:
                self.complete_career_arc(fighter, conclusion)
                continue
            if self.month > arc.get("deadline_month", self.month):
                if arc.get("type") == "Homegrown Champion":
                    extensions = max(0, int(arc.get("extension_count", 0) or 0))
                    if extensions < 1 and arc.get("plan"):
                        arc["extension_count"] = extensions + 1
                        arc["deadline_month"] = self.month + 24
                        self.career_arc_note(fighter, "The backed homegrown project received one final development extension.")
                    else:
                        self.fail_career_arc(fighter, "The homegrown title path did not become credible within the supported development window.")
                elif arc.get("type") == "Champion Ambition" and fighter.champion and fighter.contract_months > 1:
                    arc["deadline_month"] = self.month + 4
                    self.career_arc_note(fighter, "Champion review extended briefly; a concrete contract or opponent decision is still needed.")
                else:
                    self.fail_career_arc(fighter, "The promised path did not materialise before the review deadline.")

    def refresh_promotion_rankings(self, track=True, company=None, roster=None):
        """Maintain a transparent current/previous rank for the player and every AI promotion."""
        if roster is not None:
            groups = [(company or self.player_company_name, roster)]
        else:
            groups = [(self.player_company_name, self.roster)] + [(promo.name, promo.roster) for promo in self.promotions if not getattr(promo, "is_regional_feeder", False)]
        for _company, roster in groups:
            buckets = {}
            for fighter in roster:
                if not fighter.retired:
                    buckets.setdefault((fighter.gender, fighter.weight), []).append(fighter)
            for fighters in buckets.values():
                champions = [fighter for fighter in fighters if fighter.champion]
                contenders = sorted((fighter for fighter in fighters if not fighter.champion), key=self.rank_value, reverse=True)
                for fighter in champions:
                    old = getattr(fighter, "ranking_position", 0)
                    if track and old:
                        fighter.previous_ranking_position = old
                    fighter.ranking_position = 0
                    fighter.ranking_reason = "Champion"
                for position, fighter in enumerate(contenders, 1):
                    old = getattr(fighter, "ranking_position", 0)
                    if track and old and old != position:
                        fighter.previous_ranking_position = old
                    elif not old:
                        fighter.previous_ranking_position = position
                    fighter.ranking_position = position
                    if getattr(fighter, "owed_title_shot", False):
                        reason = "Guaranteed title shot"
                    elif getattr(fighter, "career_win_streak", 0) >= 3:
                        reason = f"{fighter.career_win_streak}-fight win streak"
                    elif fighter.momentum >= 3:
                        reason = "Strong recent form"
                    elif fighter.fatigue >= 55 or fighter.injured:
                        reason = "Inactive / recovering"
                    else:
                        reason = "Merit ranking"
                    fighter.ranking_reason = reason

    def result_record_fingerprint(self, record):
        """Derive a stable legacy card identity from its event and bout contents.

        Old saves predate ``record_id`` and can contain more than one card with
        the same company, date, and event label.  A content fingerprint keeps
        those genuinely different cards separate while allowing an already
        indexed replay to be recognized on every subsequent load.
        """
        bouts = record.get("fight_logs", []) or record.get("bout_results", []) or []
        compact_bouts = [
            {
                "label": str(row.get("label", "") or ""),
                "a": str(row.get("a", "") or ""),
                "b": str(row.get("b", "") or ""),
                "a_id": str(row.get("a_id", "") or ""),
                "b_id": str(row.get("b_id", "") or ""),
                "result": str(row.get("result", "") or ""),
            }
            for row in bouts if isinstance(row, dict)
        ]
        identity = {
            "date": str(record.get("date", "") or "").strip(),
            "company": str(record.get("company", "") or "").strip(),
            "event": str(record.get("event", record.get("event_name", "")) or "").strip(),
            "summary": str(record.get("summary", "") or "").strip(),
            "bouts": compact_bouts,
        }
        payload = json.dumps(identity, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20]

    def result_archive_key(self, record):
        """Stable identifier shared by detailed replays and the permanent card index."""
        record_id = str(record.get("record_id", "") or "").strip()
        return record_id or f"legacy-{self.result_record_fingerprint(record)}"

    def refresh_result_replay_availability(self):
        """Reconcile replay badges with the retained shelves, not old promises."""
        packages = list(getattr(self, "ai_event_archive", []) or []) + list(getattr(self, "player_event_archive", []) or [])
        available = {self.result_archive_key(row) for row in packages
                     if row.get("log") or row.get("fight_logs")}
        for row in getattr(self, "result_records", []) or []:
            ref = row.get("_archive_ref") or {}
            if row.get("log") or row.get("fight_logs") or ref.get("record_id") in available:
                available.add(self.result_archive_key(row))
        for row in getattr(self, "result_index", []) or []:
            row["has_replay"] = self.result_archive_key(row) in available
            for bout in row.get("bout_results", []) or []:
                # This is the exact authored combat-sport title label. It is
                # metadata evidence only, never evidence of a belt transfer.
                sport = str(bout.get("sport", "") or "")
                label = str(bout.get("label", "") or "")
                if sport and label.startswith(sport + " ") and label.endswith(" Title Bout"):
                    bout["title"] = True
                    bout["divisional_title"] = not bool(bout.get("special_belt"))

    def result_index_row(self, record, has_replay=False):
        """Store only the information needed to browse an old card quickly."""
        from replay_storage import ReplayLines
        fight_logs = record.get("fight_logs", []) or [] if isinstance(record, dict) else []
        if not isinstance(fight_logs, list):
            fight_logs = []
        fight_logs = [row for row in fight_logs if isinstance(row, dict)]
        compact_bouts = []
        for row in fight_logs:
            if not isinstance(row, dict) or not (row.get("a") or row.get("b") or row.get("result")):
                continue
            scorecards = row.get("scorecards", "")
            if not scorecards:
                if isinstance(row.get("lines"), ReplayLines):
                    scorecards = ""
                else:
                    try:
                        scorecards = self.scorecard_summary_from_lines(row.get("lines", []))
                    except Exception:
                        scorecards = ""
            compact_bouts.append({
                "label": row.get("label", "BOUT"), "a": row.get("a", ""), "b": row.get("b", ""),
                "a_id": row.get("a_id", ""), "b_id": row.get("b_id", ""), "weight": row.get("weight", ""),
                "sport": row.get("sport", ""), "result": row.get("result", ""), "scorecards": scorecards,
                "title": bool(row.get("title", False)),
                "divisional_title": bool(row.get("divisional_title", row.get("title") and not row.get("special_belt"))),
                "interim": bool(row.get("interim", False)),
                "special_belt": str(row.get("special_belt", "") or ""),
                "booking_reason": str(row.get("booking_reason", "") or ""),
            })
        if not compact_bouts:
            legacy_bouts = record.get("bout_results", []) if isinstance(record, dict) else []
            compact_bouts = [deepcopy(row) for row in legacy_bouts] if isinstance(legacy_bouts, list) else []
        main = next((row for row in fight_logs if "MAIN" in str(row.get("label", "")).upper()), None)
        if not main and fight_logs:
            main = fight_logs[-1]
        headline = ""
        if main:
            headline = f"{main.get('a', '')} vs {main.get('b', '')}".strip(" vs")
        # Tournament brackets are part of the permanent result index rather
        # than the ageing replay shelf.  Keep their identity-safe draw, seed
        # metadata and stage result evidence so a historic edition remains
        # browseable after its full commentary has been compacted away.  The
        # defensive copy also means a caller cannot mutate the saved index by
        # retaining a reference to an event package.
        raw_tournaments = record.get("tournament_brackets", []) if isinstance(record, dict) else []
        compact_tournaments = []
        tournament_legacy_raw = None
        if not isinstance(raw_tournaments, list):
            tournament_legacy_raw = deepcopy(raw_tournaments)
            raw_tournaments = []
        for bracket in raw_tournaments:
            if not isinstance(bracket, dict):
                continue
            try:
                compact = deepcopy(bracket)
            except Exception:
                compact = dict(bracket)
            stages = []
            raw_stages = compact.get("stages", []) or []
            if not isinstance(raw_stages, list):
                compact["stages_legacy_raw"] = deepcopy(raw_stages)
                raw_stages = []
            for stage in raw_stages:
                if not isinstance(stage, dict):
                    continue
                stage_copy = dict(stage)
                raw_matches = stage.get("matches", []) or []
                if not isinstance(raw_matches, list):
                    stage_copy["matches_legacy_raw"] = deepcopy(raw_matches)
                    raw_matches = []
                stage_copy["matches"] = [dict(match) for match in raw_matches if isinstance(match, dict)]
                stages.append(stage_copy)
            compact["stages"] = stages
            for field in ("entrants", "entrant_ids", "seeds", "substitutions", "result_refs"):
                if not isinstance(compact.get(field, []), list):
                    compact[f"{field}_legacy_raw"] = deepcopy(compact.get(field))
                    compact[field] = []
                else:
                    compact.setdefault(field, [])
            compact_tournaments.append(compact)
        result = {
            "record_id": self.result_archive_key(record),
            "key": self.result_archive_key(record),
            "detail_key": self.result_archive_key(record),
            "date": record.get("date", ""),
            "company": record.get("company", ""),
            "event": record.get("event", record.get("event_name", "")),
            "summary": record.get("summary", ""),
            "headline": headline,
            "fights": record.get("fights", record.get("fight_count", "")),
            "gate": record.get("gate", ""),
            "profit": record.get("profit", ""),
            "bout_results": compact_bouts,
            "tournament_brackets": compact_tournaments,
            "has_replay": bool(has_replay),
        }
        if tournament_legacy_raw is not None:
            result["tournament_brackets_legacy_raw"] = tournament_legacy_raw
        return result

    def archive_result_record(self, record, retain_detail=True):
        """Add a completed card to both the short replay shelf and permanent index."""
        record.setdefault("record_id", f"event-{uuid4().hex}")
        fingerprint = self.result_record_fingerprint(record)
        for package in list(getattr(self, "player_event_archive", [])) + list(getattr(self, "ai_event_archive", [])):
            if not package.get("record_id") and self.result_record_fingerprint(package) == fingerprint:
                package["record_id"] = record["record_id"]
                break
        self.result_records.insert(0, record)
        limit = max(0, int(self.rules.get("global_result_replay_limit", GLOBAL_RESULT_REPLAY_LIMIT)))
        self.result_records = self.result_records[:limit]
        key = self.result_archive_key(record)
        index = getattr(self, "result_index", []) or []
        index = [row for row in index if row.get("key") != key]
        index.insert(0, self.result_index_row(record, has_replay=retain_detail))
        self.result_index = index[:RESULT_INDEX_LIMIT]
        self.refresh_result_replay_availability()

    def ensure_result_index(self):
        """Migrate older saves and expose their retained company history too."""
        # Normalize legacy rows first.  Previous migration code treated an
        # already-indexed detailed replay as a same-name second card, so every
        # load appended another ``|2``, ``|3`` duplicate.  Content-derived
        # legacy IDs make the migration idempotent without collapsing truly
        # different same-week cards.
        index = []
        known = set()
        for saved_row in list(getattr(self, "result_index", []) or []):
            if not isinstance(saved_row, dict):
                continue
            row = dict(saved_row)
            key = self.result_archive_key(row)
            if key in known:
                continue
            row["record_id"] = key
            row["key"] = key
            row["detail_key"] = key
            index.append(row)
            known.add(key)
        for record in reversed(getattr(self, "result_records", []) or []):
            if not isinstance(record, dict):
                continue
            record.setdefault("record_id", self.result_archive_key(record))
            row = self.result_index_row(record, has_replay=True)
            if row["key"] in known:
                existing = next(item for item in index if item.get("key") == row["key"])
                existing["has_replay"] = True
                existing["detail_key"] = row["detail_key"]
                continue
            index.insert(0, row)
            known.add(row["key"])
        # Older saves only retained each promotion's small show-history shelf.
        # Make those cards searchable even though their full replay is gone.
        for promo in getattr(self, "promotions", []):
            for entry in reversed(getattr(promo, "show_history", []) or []):
                event = str(entry).split(":", 1)[0].strip()
                row = {
                    "key": f"legacy|{promo.name}|{event}", "date": "Archive date unavailable",
                    "company": promo.name, "event": event, "summary": str(entry),
                    "headline": "", "fights": "", "gate": "", "profit": "", "has_replay": False,
                }
                if row["key"] not in known:
                    index.append(row)
                    known.add(row["key"])
        self.result_index = index[:RESULT_INDEX_LIMIT]
        self.refresh_result_replay_availability()

    def all_mma_fighters_for_lineage_repair(self):
        fighters = []
        fighters.extend(getattr(self, "roster", []) or [])
        fighters.extend(getattr(self, "free_agents", []) or [])
        fighters.extend(getattr(self, "retired_fighters", []) or [])
        for promo in getattr(self, "promotions", []) or []:
            fighters.extend(getattr(promo, "roster", []) or [])
        return fighters

    def result_lineage_winner_loser(self, result, a_name, b_name):
        text = str(result or "")
        if a_name and text.startswith(f"{a_name} def."):
            return a_name, b_name
        if b_name and text.startswith(f"{b_name} def."):
            return b_name, a_name
        return "", ""

    def result_lineage_method(self, result):
        match = re.search(r"\bby\s+(.+?)(?:\s+\(R\d+\))?$", str(result or ""))
        return match.group(1).strip() if match else "Decision"

    def result_lineage_date_key(self, date_value):
        match = re.search(r"Month\s+(\d+)(?:\s+Week\s+(\d+))?", str(date_value or ""), re.IGNORECASE)
        return (int(match.group(1)), int(match.group(2) or 1)) if match else (0, 0)

    def title_history_has_non_lineal_changes(self, entries):
        current = ""
        for entry in reversed(list(entries or [])):
            if not isinstance(entry, dict):
                # Keep malformed legacy rows as retained evidence and force
                # the migration path to preserve them beside any rebuilt
                # lineal rows. A bad row must not abort save loading.
                return True
            action = str(entry.get("action", ""))
            fighter = str(entry.get("fighter", "") or "")
            note = str(entry.get("note", "") or "")
            opponent_match = re.search(r"Defeated\s+(.+?)\s+by\s+", note)
            opponent = opponent_match.group(1).strip() if opponent_match else ""
            if action in ("Inaugural Champion", "Inaugural Champion Appointed"):
                current = fighter
            elif action == "Champion Crowned":
                if current and current not in {fighter, opponent}:
                    return True
                current = fighter
            elif action == "Title Defense":
                if current and fighter != current:
                    return True
            elif action in ("Vacated", "Division Closed"):
                current = ""
        return False

    def rebuild_lineal_belt_histories_from_results(self):
        """Recover long belt histories without inventing parallel champions.

        Old result indexes label title bouts, but a label alone does not prove
        the winner took the lineal belt. After the first known champion, only a
        bout involving the current holder may produce a defense or crown.
        """
        fighters_by_id = {}
        fighters_by_name = {}
        for fighter in self.all_mma_fighters_for_lineage_repair():
            fid = str(getattr(fighter, "fighter_id", "") or "")
            if fid:
                fighters_by_id[fid] = fighter
            fighters_by_name.setdefault(str(getattr(fighter, "name", "") or ""), []).append(fighter)

        def gender_for_bout(bout):
            for key in ("a_id", "b_id"):
                fighter = fighters_by_id.get(str(bout.get(key, "") or ""))
                if fighter and getattr(fighter, "gender", "") in ("Male", "Female"):
                    return fighter.gender
            for key in ("a", "b"):
                genders = {
                    getattr(fighter, "gender", "")
                    for fighter in fighters_by_name.get(str(bout.get(key, "") or ""), [])
                    if getattr(fighter, "gender", "") in ("Male", "Female")
                }
                if len(genders) == 1:
                    return next(iter(genders))
            return ""

        source_events = []
        seen_source = set()
        for event_index, event in enumerate(getattr(self, "result_index", []) or []):
            company = str(event.get("company", "") or "")
            if not company:
                continue
            for bout_index, bout in enumerate(event.get("bout_results", []) or []):
                label = str(bout.get("label", "") or "").upper()
                divisional_title = bool(bout.get("divisional_title", bout.get("title") and not bout.get("special_belt")))
                legacy_title_label = label in ("TITLE FIGHT", "MAIN EVENT - TITLE FIGHT")
                if str(bout.get("sport", "") or "") or not (divisional_title or legacy_title_label):
                    continue
                weight = str(bout.get("weight", "") or "")
                if weight not in WEIGHTS:
                    continue
                gender = gender_for_bout(bout)
                if gender not in ("Male", "Female"):
                    continue
                a_name, b_name = str(bout.get("a", "") or ""), str(bout.get("b", "") or "")
                a_id, b_id = str(bout.get("a_id", "") or ""), str(bout.get("b_id", "") or "")
                winner_id = str(bout.get("winner_id", "") or "")
                # Newer result rows carry winner identity.  Prefer it over
                # display-name parsing so two same-name fighters cannot make
                # the rebuilt lineage crown the wrong career.  Legacy rows
                # still use the existing name parser, with IDs recovered only
                # when the name is unambiguous.
                winner_fighter = fighters_by_id.get(winner_id) if winner_id else None
                if winner_fighter is not None:
                    winner = str(getattr(winner_fighter, "name", "") or "")
                    if winner_id == a_id:
                        loser, loser_id = b_name, b_id
                    elif winner_id == b_id:
                        loser, loser_id = a_name, a_id
                    else:
                        loser, loser_id = "", ""
                else:
                    winner, loser = self.result_lineage_winner_loser(bout.get("result", ""), a_name, b_name)
                    winner_id = ""
                    loser_id = ""
                    if winner:
                        winner_matches = fighters_by_name.get(winner, [])
                        loser_matches = fighters_by_name.get(loser, [])
                        # A legacy name-only title result is not safe to
                        # rebuild when that winner label belongs to more than
                        # one career. Preserve the source row for review
                        # rather than assigning a crown to an arbitrary
                        # namesake.
                        if len(winner_matches) != 1:
                            winner = ""
                        else:
                            winner_id = str(getattr(winner_matches[0], "fighter_id", "") or "")
                        if len(loser_matches) == 1:
                            loser_id = str(getattr(loser_matches[0], "fighter_id", "") or "")
                if not winner:
                    continue
                key = (
                    str(event.get("date", "") or ""), company, gender, weight,
                    winner_id, loser_id, winner, loser,
                    self.result_lineage_method(bout.get("result", "")),
                )
                if key in seen_source:
                    continue
                seen_source.add(key)
                source_events.append((
                    self.result_lineage_date_key(event.get("date")),
                    event_index, bout_index, str(event.get("date", "") or ""),
                    company, self.belt_key(gender, weight), winner, loser,
                    self.result_lineage_method(bout.get("result", "")), a_name, b_name,
                    winner_id, loser_id, a_id, b_id,
                ))
        source_events.sort(key=lambda row: (row[0], row[1], row[2]))

        rebuilt_by_company = {}
        current_by_company = {}
        for _month, _event_index, _bout_index, date, company, division, winner, loser, method, a_name, b_name, winner_id, loser_id, a_id, b_id in source_events:
            histories = rebuilt_by_company.setdefault(company, self.blank_belt_history())
            current = current_by_company.setdefault(company, {}).get(division, {})
            current_name = str(current.get("name", "") or "") if isinstance(current, dict) else str(current or "")
            current_id = str(current.get("id", "") or "") if isinstance(current, dict) else ""
            participants = {a_name, b_name}
            if not current_name and not current_id:
                action = "Inaugural Champion"
            elif winner_id and current_id and winner_id == current_id:
                action = "Title Defense"
            elif (not winner_id and not current_id and winner == current_name):
                action = "Title Defense"
            elif (current_id and current_id in {a_id, b_id}) or (not current_id and current_name in participants):
                action = "Champion Crowned"
            else:
                continue
            current_by_company[company][division] = {"id": winner_id, "name": winner}
            histories[division].insert(0, {
                "date": date, "action": action, "division": division,
                "fighter": winner, "fighter_id": winner_id,
                "opponent": loser, "opponent_id": loser_id,
                "note": f"Defeated {loser} by {method}.",
            })

        return rebuilt_by_company

    def migrate_lineal_belt_histories(self):
        version = int((getattr(self, "rules", {}) or {}).get("lineal_belt_history_version", 0) or 0)
        if version >= 1:
            return {"updated": 0, "rebuilt_entries": 0}
        rebuilt_by_company = self.rebuild_lineal_belt_histories_from_results()
        if not rebuilt_by_company:
            self.rules["lineal_belt_history_version"] = 1
            return {"updated": 0, "rebuilt_entries": 0}

        def primary_count(history):
            return sum(
                1 for entries in (history or {}).values() for entry in (entries or [])
                if isinstance(entry, dict) and entry.get("action") in ("Champion Crowned", "Inaugural Champion", "Inaugural Champion Appointed", "Title Defense")
            )

        def merge_history(company, existing):
            existing = self.normalize_belt_history(existing)
            rebuilt = self.normalize_belt_history(rebuilt_by_company.get(company, {}))
            if not any(rebuilt.values()):
                return existing, False
            existing_count = primary_count(existing)
            rebuilt_count = primary_count(rebuilt)
            capped = any(len(entries or []) == 80 for entries in existing.values())
            non_lineal = any(self.title_history_has_non_lineal_changes(entries) for entries in existing.values())
            if not (capped or non_lineal or rebuilt_count >= existing_count):
                return existing, False
            def history_identity_key(row):
                """Keep retained title facts distinct even when labels match.

                Older saves often have the same date/action/note for separate
                title transitions.  The visible fighter name is not a safe
                identity (two careers can share it), so deduplication must
                include every retained identity field before falling back to
                the display text.  This remains a migration-local key; it is
                never written back as a synthetic history ID.
                """
                if not isinstance(row, dict):
                    return (type(row).__name__, repr(row))
                return (
                    row.get("date"), row.get("action"), row.get("division"),
                    row.get("fighter_id"), row.get("opponent_id"),
                    row.get("title_event_id"), row.get("event_id"),
                    row.get("fighter"), row.get("opponent"), row.get("note"),
                )

            seen = {
                history_identity_key(row)
                for entries in rebuilt.values() for row in entries if isinstance(row, dict)
            }
            for division, entries in existing.items():
                for entry in entries or []:
                    if not isinstance(entry, dict):
                        # Preserve malformed/forward-compatible source rows
                        # without attempting to interpret or rewrite them.
                        rebuilt[division].append(deepcopy(entry))
                        continue
                    if entry.get("action") in ("Champion Crowned", "Inaugural Champion", "Inaugural Champion Appointed", "Title Defense"):
                        continue
                    row = dict(entry)
                    row.setdefault("division", division)
                    key = history_identity_key(row)
                    if key not in seen:
                        rebuilt[division].append(row)
                        seen.add(key)
                rebuilt[division].sort(
                    key=lambda row: self.result_lineage_date_key(row.get("date")) if isinstance(row, dict) else (0, 0),
                    reverse=True,
                )
            return rebuilt, True

        updated = 0
        self.belt_history, changed = merge_history(getattr(self, "player_company_name", PLAYER_PROMOTION_NAME), getattr(self, "belt_history", {}))
        updated += int(changed)
        for promo in getattr(self, "promotions", []) or []:
            promo.belt_history, changed = merge_history(promo.name, promo.belt_history or {})
            updated += int(changed)
        self.rules["lineal_belt_history_version"] = 1
        return {"updated": updated, "rebuilt_entries": sum(primary_count(history) for history in rebuilt_by_company.values())}

    def repair_future_belt_history_dates(self):
        """Clamp impossible future title-history stamps created by older calendars."""
        current_month = max(1, int(getattr(self, "month", 1) or 1))
        current_week = max(1, min(4, int(getattr(self, "week", 1) or 1)))
        fixed_entries = 0

        def repair_history(history):
            nonlocal fixed_entries
            normalized = self.normalize_belt_history(history)
            for division, entries in normalized.items():
                for entry in entries or []:
                    month, week = self.result_lineage_date_key(entry.get("date"))
                    if month <= 0:
                        entry["date"] = f"Month {current_month} Week {current_week}"
                        entry.setdefault("division", division)
                        fixed_entries += 1
                    elif month > current_month or (month == current_month and week > current_week):
                        entry["date"] = f"Month {current_month} Week {current_week}"
                        entry.setdefault("division", division)
                        fixed_entries += 1
            return normalized

        self.belt_history = repair_history(getattr(self, "belt_history", {}))
        companies_fixed = 1 if fixed_entries else 0
        for promo in getattr(self, "promotions", []) or []:
            before = fixed_entries
            promo.belt_history = repair_history(promo.belt_history or {})
            companies_fixed += 1 if fixed_entries > before else 0
        return {"entries": fixed_entries, "companies": companies_fixed}

    def resolve_rivalry_result(self, winner, loser, fight, method):
        """A rivalry can demand a rematch or be conclusively settled by a result."""
        heat = self.rivalry_heat_between(winner, loser)
        if not heat:
            return
        marquee = bool(fight.get("main") or fight.get("title"))
        series = self.matchup_series_record(winner, loser)
        tied_series = series["meetings"] >= 2 and series["a_wins"] == series["b_wins"]
        rematch = (
            tied_series
            or method == "Decision" and (marquee or heat >= 55) and random.random() < 0.62
        )
        if rematch:
            next_heat = min(100, heat + random.randint(18, 32) if tied_series else heat + random.randint(12, 24))
            if tied_series:
                outcome = (
                    f"The rivalry series is level at {series['a_wins']}-{series['b_wins']}"
                    f"{f'-{series['draws']}' if series['draws'] else ''}; both camps want a decider after "
                    f"{winner.name} beat {loser.name} by {method}."
                )
            else:
                outcome = f"The close result fuels a demanded rematch after {winner.name} beat {loser.name} by {method}."
            winner.rivalry_rematch_due = loser.rivalry_rematch_due = True
        else:
            next_heat = max(0, heat - (random.randint(28, 48) if method not in ("Decision", "Technical Decision") else random.randint(12, 25)))
            outcome = f"{winner.name} claims the rivalry result over {loser.name} by {method}."
            winner.rivalry_rematch_due = loser.rivalry_rematch_due = False
            if next_heat < 20:
                winner.rival = loser.rival = ""
                winner.rival_fighter_id = loser.rival_fighter_id = ""
        winner.rivalry_heat = loser.rivalry_heat = next_heat
        for fighter in (winner, loser):
            fighter.rivalry_last_month = self.month
            fighter.rivalry_history = (fighter.rivalry_history or [])[-39:]
            fighter.rivalry_history.append(f"Month {self.month}: {outcome} Heat now {next_heat}/100.")
        winner.legacy_score = max(0, winner.legacy_score + (8 if marquee else 4))
        winner.popularity = min(100, winner.popularity + (2 if marquee else 1))
        story_key = self.rivalry_story_key(winner, loser)
        result_ref = (
            f"{story_key}:result:{self.month}:{self.week}:{series['meetings']}:"
            f"{getattr(winner, 'fighter_id', '')}:{method}"
        )
        if rematch:
            status, phase = "active", "decider_due" if tied_series else "rematch_due"
            stakes = "The series is level and needs a decider." if tied_series else "The disputed result created demand for another fight."
            resolution = ""
        elif next_heat < 20:
            status, phase = "resolved", "settled"
            stakes, resolution = "The rivalry has been settled in competition.", outcome
        else:
            status, phase = "cooling", "aftermath"
            stakes, resolution = "The result reduced the feud, but public interest has not disappeared.", ""
        thread = self.record_rivalry_story(
            winner, loser, phase=phase, status=status, importance=4 if marquee else 3,
            beat_kind="fight_result", beat_ref=result_ref, summary=outcome,
            stakes=stakes, resolution=resolution,
        )
        self.record_world_story(
            "Rivalry", outcome, stakes, fighters=[winner.name, loser.name],
            importance=4 if marquee else 3,
            fighter_ids=[winner.fighter_id, loser.fighter_id],
            story_id=thread.get("story_id", "") if thread else "",
        )

    def process_rivalry_activity(self):
        """Let active feuds breathe between events without constantly creating them."""
        for roster in [self.roster] + [promo.roster for promo in self.promotions]:
            processed = set()
            for fighter in roster:
                rival = self.resolve_rivalry_target(fighter)
                if not rival or not self.mutual_rivalry_between(fighter, rival):
                    continue
                pair_key = frozenset((getattr(fighter, "fighter_id", id(fighter)), getattr(rival, "fighter_id", id(rival))))
                if pair_key in processed:
                    continue
                processed.add(pair_key)
                if random.random() < 0.12:
                    rise = random.randint(4, 11)
                    fighter.rivalry_heat = rival.rivalry_heat = min(100, max(fighter.rivalry_heat, rival.rivalry_heat) + rise)
                    fighter.media_heat = min(100, fighter.media_heat + rise // 2)
                    rival.media_heat = min(100, rival.media_heat + rise // 2)
                    fighter.rivalry_last_month = rival.rivalry_last_month = self.month
                    headline = f"{fighter.name} and {rival.name} trade fresh shots; their feud reaches {fighter.rivalry_heat}/100 heat."
                    self.news.insert(0, headline)
                    if fighter in self.roster or rival in self.roster:
                        self.inbox.append({"subject": "Rivalry Escalation", "body": headline, "type": "Roster", "fighter": fighter.name, "resolved": False})
                    story_key = self.rivalry_story_key(fighter, rival)
                    self.record_rivalry_story(
                        fighter, rival, phase="hot" if fighter.rivalry_heat >= 70 else "building",
                        importance=3 if fighter.rivalry_heat >= 70 else 2,
                        beat_kind="escalation",
                        beat_ref=f"{story_key}:ambient-rise:{self.month}:{self.week}",
                        summary=headline,
                        stakes="The feud is gaining enough attention to justify a meaningful matchup.",
                    )
                elif self.month - max(fighter.rivalry_last_month, rival.rivalry_last_month) >= 6:
                    cooled = max(0, max(fighter.rivalry_heat, rival.rivalry_heat) - 4)
                    fighter.rivalry_heat = rival.rivalry_heat = cooled
                    if cooled < 12 and not (fighter.rivalry_rematch_due or rival.rivalry_rematch_due):
                        fighter.rival = rival.rival = ""
                        fighter.rival_fighter_id = rival.rival_fighter_id = ""
                        story_key = self.rivalry_story_key(fighter, rival)
                        self.record_rivalry_story(
                            fighter, rival, phase="faded", status="abandoned", importance=1,
                            beat_kind="cooling", beat_ref=f"{story_key}:faded:{self.month}:{self.week}",
                            summary=f"The rivalry between {fighter.name} and {rival.name} faded without another fight.",
                            stakes="The matchup no longer carries active narrative pressure.",
                            resolution="The feud cooled before another credible bout was made.",
                        )

    def apply_serious_injury(self, fighter, source="competition"):
        """Create a rare, career-relevant injury without making it a scripted result."""
        if getattr(fighter, "serious_injury", "") or fighter.retired:
            return False
        injury, months, affected = random.choice([
            ("ACL tear", random.randint(7, 11), ("cardio", "takedown_defence")),
            ("Shoulder reconstruction", random.randint(6, 10), ("wrestling", "grappling")),
            ("Broken hand", random.randint(4, 7), ("striking", "power")),
            ("Concussion symptoms", random.randint(5, 9), ("chin", "fight_iq")),
            ("Neck injury", random.randint(8, 12), ("toughness", "grappling")),
        ])
        fighter.serious_injury = injury
        fighter.serious_injury_pending = (
            fighter in getattr(self, "roster", [])
            or getattr(fighter, "sport_employer", "") == getattr(self, "player_company_name", "")
        )
        fighter.injured = max(fighter.injured, months)
        fighter.available_week = max(getattr(fighter, "available_week", 0), self.calendar_week_index() + months * 4)
        fighter.injury_proneness = min(100, fighter.injury_proneness + random.randint(2, 5))
        # There is a small lasting effect even with proper treatment; the player
        # chooses how much additional risk to take below.
        for stat in affected:
            setattr(fighter, stat, max(1, getattr(fighter, stat, 50) - 1))
        if fighter.detailed_skills:
            for key in random.sample(list(fighter.detailed_skills), k=min(2, len(fighter.detailed_skills))):
                fighter.detailed_skills[key] = max(1, fighter.detailed_skills[key] - 1)
        note = f"Month {self.month}: {injury} ({source}); expected absence {months} months."
        fighter.serious_injury_history = fighter.serious_injury_history or []
        fighter.serious_injury_history.append(note)
        fighter.serious_injury_history = fighter.serious_injury_history[-12:]
        headline = f"Medical alert: {fighter.name} suffers a {injury.lower()}."
        self.news.insert(0, headline)
        company = self.fighter_company_name(fighter) or getattr(fighter, "sport_employer", "") or "Independent Circuit"
        story = self.upsert_story_thread(
            self.injury_story_key(fighter), "Injury Comeback", status="active",
            phase="decision_required" if fighter.serious_injury_pending else "treatment",
            importance=4, fighters=[fighter], companies=[company],
            origin_ref=f"{self.injury_story_key(fighter)}:injury:{self.month}:{self.week}",
            beat_kind="serious_injury", beat_ref=f"{self.injury_story_key(fighter)}:injury:{self.month}:{self.week}",
            summary=f"{fighter.name} suffered a {injury.lower()} and faces an estimated {months}-month absence.",
            stakes="Treatment, recovery time, recurrence risk, and the fighter's career direction are now at stake.",
        )
        if story:
            story["injury"] = injury
        self.record_world_story(
            "Serious Injury", headline, note, companies=[company], fighters=[fighter.name], importance=4,
            fighter_ids=[fighter.fighter_id], story_id=story.get("story_id", "") if story else "",
        )
        if fighter.serious_injury_pending:
            self.inbox.append({"subject": f"Medical Decision — {fighter.name}", "body": f"{fighter.name} has a {injury}. Expected absence: {months} months. Choose surgical repair, accelerated rehabilitation, or retirement.", "type": "Medical", "fighter": fighter.name, "action": "serious_injury", "resolved": False})
        else:
            self.resolve_serious_injury(fighter, "surgery", ai_decision=True)
        return True

    def resolve_serious_injury(self, fighter, choice="surgery", ai_decision=False):
        """Apply the medical trade-off for a serious injury and record it."""
        if not getattr(fighter, "serious_injury", ""):
            return False
        injury = fighter.serious_injury
        if choice == "retire":
            self.mark_retirement_fight_required(fighter, f"Medical retirement after {injury.lower()}")
            fighter.injured = 0
            fighter.serious_injury_pending = False
            outcome = "chose retirement after one final fight"
        elif choice == "rehab":
            fighter.injured = max(2, fighter.injured - random.randint(1, 3))
            fighter.serious_injury_recurrence += random.randint(5, 10)
            fighter.morale = max(15, fighter.morale - random.randint(3, 8))
            fighter.serious_injury_pending = False
            outcome = "chose accelerated rehabilitation (higher recurrence risk)"
        else:
            fighter.injured += random.randint(1, 3)
            fighter.injury_proneness = max(1, fighter.injury_proneness - random.randint(1, 3))
            fighter.morale = max(15, fighter.morale - random.randint(1, 5))
            fighter.serious_injury_pending = False
            outcome = "underwent surgical repair"
        fighter.serious_injury_history = fighter.serious_injury_history or []
        fighter.serious_injury_history.append(f"Month {self.month}: {injury} — {outcome}.")
        fighter.serious_injury_history = fighter.serious_injury_history[-12:]
        company = self.fighter_company_name(fighter) or getattr(fighter, "sport_employer", "") or "Independent Circuit"
        phase = "medical_retirement" if choice == "retire" else "accelerated_rehab" if choice == "rehab" else "surgical_recovery"
        story = self.upsert_story_thread(
            self.injury_story_key(fighter), "Injury Comeback", status="active", phase=phase,
            importance=4, fighters=[fighter], companies=[company], beat_kind="treatment_decision",
            beat_ref=f"{self.injury_story_key(fighter)}:decision:{self.month}:{self.week}:{choice}",
            summary=f"{fighter.name} {outcome} for a {injury.lower()}.",
            stakes=("A final fight now stands between the fighter and medical retirement." if choice == "retire" else "The recovery period and first fight back will determine the next chapter."),
        )
        if story:
            story["injury"] = injury
        if not ai_decision:
            self.news.insert(0, f"Medical update: {fighter.name} {outcome} for a {injury.lower()}.")
        return True

    def retirement_review_month(self, fighter):
        """Stable pseudo-birthday month for old saves that do not store a birth date."""
        return sum(ord(char) for char in fighter.name) % 12 + 1

    def mark_retirement_fight_required(self, fighter, reason="Career review"):
        if getattr(fighter, "retired", False):
            return
        guaranteed = max(0, int(getattr(fighter, "guaranteed_fights", 0) or 0))
        completed = max(0, int(getattr(fighter, "contract_fights_completed", 0) or 0))
        if fighter in self.roster and completed < guaranteed:
            remaining = guaranteed - completed
            fighter.retirement_pending = False
            fighter.retirement_reason = f"Retirement deferred: {remaining} guaranteed comeback fight{'s' if remaining != 1 else ''} remaining."
            return
        fighter.retirement_pending = True
        fighter.retirement_fight_completed = False
        fighter.retirement_fight_due_after_month = 0
        fighter.retirement_requested_month = getattr(fighter, "retirement_requested_month", 0) or self.month
        fighter.retirement_reason = f"{reason}; final fight required."
        self.open_farewell_story(fighter, reason)
        # A retirement fight should be bookable soon; avoid permanent limbo from
        # high accumulated fatigue while still respecting serious injuries.
        if fighter.fatigue > 58:
            fighter.fatigue = 58
        if fighter.injured and fighter.age >= 48:
            fighter.injured = max(0, fighter.injured - 1)

    def scheduled_fighter_references(self, include_booked=False):
        """Return durable IDs for current cards, with names for legacy bouts."""
        references = set()
        fights = list(getattr(self, "booked", [])) if include_booked else []
        for event in getattr(self, "scheduled_events", []):
            if self.is_event_due(event) or (event.get("month", 1), event.get("week", 1)) >= (self.month, self.week):
                fights.extend(event.get("fights", []))
        for fight in fights:
            participant_refs = (
                self.event_fight_participant_references(fight)
                if hasattr(self, "event_fight_participant_references")
                else self.event_fight_participants(fight)
            )
            references.update(reference for reference in participant_refs if reference != "TBA")
        return references

    def fighter_has_scheduled_fight(self, fighter, include_booked=False):
        references = self.scheduled_fighter_references(include_booked=include_booked)
        fighter_id = str(getattr(fighter, "fighter_id", "") or "")
        if fighter_id and fighter_id in references:
            return True
        # Name fallback is only for legacy cards without aligned fighter IDs.
        return fighter.name in references

    def retire_after_final_fight_if_due(self, fighter, company_name=""):
        if not getattr(fighter, "retirement_pending", False) or getattr(fighter, "retired", False):
            return False
        if getattr(fighter, "loaned_to_promotion", ""):
            return False
        # Completing a multi-fight comeback opens a new decision: renew or take
        # one farewell bout.  Do not consume that farewell bout in the same
        # result resolution that completed the comeback commitment.
        if getattr(fighter, "retirement_fight_due_after_month", 0) == self.month:
            return False
        if fighter in getattr(self, "roster", []) and self.fighter_has_scheduled_fight(fighter, include_booked=False):
            fighter.retirement_reason = "Retirement deferred until all already-scheduled fights are completed."
            return False
        was_player_fighter = fighter in getattr(self, "roster", [])
        # Capture the departure before any retirement flags or roster mutation.
        # The surrounding result transaction restores this fact if a later
        # retirement/story hook fails.
        membership = getattr(self, "record_membership_event", None)
        owning_promotion = None
        if fighter in getattr(self, "roster", []):
            company_name = company_name or self.player_company_name
        else:
            owning_promotion = next((promo for promo in getattr(self, "promotions", []) if fighter in getattr(promo, "roster", [])), None)
            if owning_promotion is not None:
                company_name = company_name or owning_promotion.name
        if callable(membership) and company_name and fighter not in getattr(self, "free_agents", []):
            membership(
                fighter, "leave", promotion=owning_promotion,
                company_name=None if owning_promotion is not None else company_name,
                reason="Retired after final fight.",
                source_transaction=f"retirement:{getattr(fighter, 'fighter_id', '')}:{company_name}:{self.month}:{self.week}",
            )
        self.update_fighter_peak_overall(fighter)
        fighter.retirement_fight_completed = True
        fighter.retirement_pending = False
        fighter.retirement_reason = f"Retired after final fight at age {fighter.age}."
        if fighter in self.roster:
            self.belts, self.interim_belts, self.belt_history = self.vacate_fighter_belts(
                fighter, self.roster, self.belts, self.interim_belts, self.belt_history, "Retired after final fight."
            )
            self.vacate_special_belts_held_by(fighter, "Retired after final fight.")
            self.roster.remove(fighter)
        if fighter in self.free_agents:
            self.free_agents.remove(fighter)
            company_name = company_name or "Independent Circuit"
        for promo in getattr(self, "promotions", []):
            if fighter in promo.roster:
                promo.belts, promo.interim_belts, promo.belt_history = self.vacate_fighter_belts(
                    fighter, promo.roster, promo.belts or {}, promo.interim_belts or {}, promo.belt_history or {}, "Retired after final fight."
                )
                self.vacate_special_belts_held_by(fighter, "Retired after final fight.", owner=promo)
                promo.roster.remove(fighter)
                break
        # Mark the final career state only after every owning roster has
        # passed through belt-vacancy and membership boundaries.
        fighter.retired = True
        fighter.champion = False
        fighter.interim_champion = False
        if fighter not in self.retired_fighters:
            self.retired_fighters.insert(0, fighter)
        headline = f"{fighter.name} retired after a final fight" + (f" with {company_name}" if company_name else "") + f" ({fighter.record})."
        self.news.insert(0, headline)
        if was_player_fighter:
            self.inbox.append({"subject": f"Retirement Confirmed - {fighter.name}", "body": f"{fighter.name} has completed their final scheduled fight and retired with a record of {fighter.record}. Any championships they held have been vacated.", "type": "Roster", "resolved": False, "fighter_id": getattr(fighter, "fighter_id", "")})
        self.record_world_story("Retirement", f"{fighter.name} completes final fight.", f"Final record: {fighter.record}. {fighter.retirement_reason}", [company_name] if company_name else [], [fighter.name], 3)
        self.resolve_feeder_pathway_departure(fighter, company_name, fighter.retirement_reason)
        self.resolve_breakout_retirement(fighter, company_name)
        self.resolve_crossroads_departure(fighter, company_name, "retired", fighter.retirement_reason)
        for story_key, story_type in (
            (self.injury_story_key(fighter), "Injury Comeback"),
            (self.comeback_story_key(fighter), "Comeback"),
        ):
            thread = self.story_thread(story_key)
            if thread and thread.get("status") not in {"resolved", "abandoned"}:
                self.upsert_story_thread(
                    story_key, story_type, status="resolved", phase="retired", importance=4,
                    fighters=[fighter], companies=[company_name] if company_name else [],
                    beat_kind="retirement", beat_ref=f"{story_key}:retired:{self.month}:{self.week}",
                    summary=f"{fighter.name} completed a final fight and retired with a record of {fighter.record}.",
                    stakes="The career chapter is complete.",
                    resolution=f"Retired after a final fight at age {fighter.age}.",
                )
        self.consider_hall_of_fame(fighter)
        return True

    def set_post_fight_recovery(self, fighter, method, lost=False):
        # Realistic layoffs: fighters compete a few times a year, not monthly, so
        # careers and title reigns stay believable instead of racking up 130+ fights.
        # Layoffs centre on about a month, with variance and a longer medical
        # suspension after a knockout loss.
        base = 4 if not lost else 5
        if method in KO_METHODS:
            base += 2 if lost else 1
        elif method in SUBMISSION_METHODS:
            base += 1 if lost else 0
        stats = getattr(fighter, "last_fight_stats", None) or {}
        head_damage = max(0, int(stats.get("head_damage", 0) or 0))
        body_damage = max(0, int(stats.get("body_damage", 0) or 0))
        leg_damage = max(0, int(stats.get("leg_damage", 0) or 0))
        cut_details = stats.get("cut_details", []) if isinstance(stats.get("cut_details", []), list) else []
        max_cut_severity = max((int(cut.get("severity", 0) or 0) for cut in cut_details if isinstance(cut, dict)), default=0)
        trauma_weeks = min(4, int(head_damage >= 20) + int(head_damage >= 35)
                           + int(body_damage >= 22) + int(leg_damage >= 22)
                           + int(max_cut_severity >= 4))
        base += trauma_weeks
        stats["medical_layoff_weeks"] = trauma_weeks
        stats["medical_basis"] = {
            "head_damage": head_damage, "body_damage": body_damage,
            "leg_damage": leg_damage, "max_cut_severity": max_cut_severity,
        }
        if lost and (head_damage >= 38 or body_damage >= 30 or leg_damage >= 30 or max_cut_severity >= 5):
            fighter.injured = max(int(getattr(fighter, "injured", 0) or 0), 1)
        base += random.randint(-1, 3)
        resilience = self.ds(fighter, "resilience", fighter.toughness)
        professionalism = getattr(fighter, "professionalism", 50)
        adjustment = 2 if resilience >= 78 and professionalism >= 70 else 0
        if fighter.trait == "Fast Healer":
            adjustment += 2
        elif fighter.trait == "Slow Healer":
            adjustment -= 2
        if any(member is fighter for member in getattr(self, "roster", [])):
            doctor_effect = max(0.0, self.staff_effect("Doctor"))
            adjustment += min(2, int(doctor_effect / 3.0))
        if fighter.injured:
            base += fighter.injured * 4
        layoff_weeks = max(2, base - adjustment)
        fighter.available_week = max(getattr(fighter, "available_week", 0), self.calendar_week_index() + layoff_weeks)
        # Count the layoff from the day they actually fought, so a Saturday
        # card returns them a day later than a Friday one rather than both
        # rounding to the same week.
        fought_on = int(getattr(fighter, "last_fight_day_index", 0) or 0) or self.current_day_index()
        fighter.available_day = max(
            int(getattr(fighter, "available_day", 0) or 0),
            fought_on + layoff_weeks * DAYS_PER_WEEK,
        )

    def apply_visible_trauma_consequences(self, fighter, lost=False):
        """Carry displayed fight damage into confidence and recurrence risk."""
        stats = getattr(fighter, "last_fight_stats", None) or {}
        cuts = stats.get("cut_details", []) if isinstance(stats.get("cut_details", []), list) else []
        max_cut = max((int(row.get("severity", 0) or 0) for row in cuts if isinstance(row, dict)), default=0)
        head = max(0, int(stats.get("head_damage", 0) or 0))
        body = max(0, int(stats.get("body_damage", 0) or 0))
        leg = max(0, int(stats.get("leg_damage", 0) or 0))
        trauma_markers = int(head >= 35) + int(body >= 30) + int(leg >= 30) + int(max_cut >= 5)
        if trauma_markers >= 2:
            confidence_loss = trauma_markers if lost else 1
            fighter.morale = max(15, fighter.morale - confidence_loss)
            fighter.motivation = max(1, fighter.motivation - max(1, confidence_loss - 1))
        recurrence_gain = max(0, trauma_markers - 2)
        if recurrence_gain:
            fighter.serious_injury_recurrence = min(
                100, int(getattr(fighter, "serious_injury_recurrence", 0) or 0) + recurrence_gain,
            )
        stats["trauma_consequences"] = {
            "markers": trauma_markers,
            "confidence_loss": confidence_loss if trauma_markers >= 2 else 0,
            "recurrence_gain": recurrence_gain,
        }

    @staticmethod
    def _simulation_event_key(package):
        """Return a deterministic archive key for pause-policy cursors."""
        if not isinstance(package, dict):
            return ""
        explicit = str(package.get("record_id", "") or package.get("event_id", "") or "").strip()
        if explicit:
            return explicit
        return "|".join(
            str(package.get(field, "") or "")
            for field in ("company", "date", "event_name", "summary", "fight_count")
        )

    def _simulation_event_keys(self):
        return [
            key for key in (self._simulation_event_key(package) for package in getattr(self, "ai_event_archive", []) or [])
            if key
        ][:120]

    @staticmethod
    def _simulation_pause_source_revision():
        """Return the build revision captured by newly armed stop policies."""
        return str(GAME_VERSION)

    def _simulation_pause_policy_source_compatible(self, policy):
        """Allow legacy policies, but fail closed on an explicit mismatch.

        Older saves predate the source-revision field and remain resumable for
        compatibility.  Once a policy carries a revision, a different build
        must not automatically continue a staged spectator job; the player can
        still load the save normally, clear the policy, or arm a new one.
        """
        if not isinstance(policy, dict):
            return True
        saved_revision = str(policy.get("source_revision", "") or "").strip()
        return not saved_revision or saved_revision == self._simulation_pause_source_revision()

    def _simulation_package_matches_policy(self, package, policy):
        if not isinstance(package, dict) or not isinstance(policy, dict):
            return False
        companies = {str(value).casefold() for value in policy.get("watched_company_names", []) if value}
        if companies and str(package.get("company", "") or "").casefold() not in companies:
            return False
        watched_ids = {str(value) for value in policy.get("watched_fighter_ids", []) if value}
        if not watched_ids:
            return True
        for row in package.get("fight_logs", []) or []:
            if not isinstance(row, dict):
                continue
            if watched_ids.intersection({str(row.get("a_id", "") or ""), str(row.get("b_id", "") or "")}):
                return True
        return False

    def evaluate_simulation_pause_policy(self, job=None):
        """Evaluate persisted stop rules at a completed week boundary only.

        This is deliberately read-only: it inspects committed date/archive data
        and never calls a resolver or consumes simulation RNG.
        """
        job = job or getattr(self, "_advance_job", None) or {}
        policy = job.get("pause_policy") if isinstance(job, dict) else None
        if not isinstance(policy, dict):
            policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
        if not isinstance(policy, dict) or not policy.get("enabled"):
            return ""
        if not self._simulation_pause_policy_source_compatible(policy):
            return ""
        target = policy.get("target")
        if isinstance(target, (list, tuple)) and len(target) == 2:
            try:
                target_boundary = (max(1, int(target[0])), max(1, min(4, int(target[1]))))
                if (int(getattr(self, "month", 1)), int(getattr(self, "week", 1))) >= target_boundary:
                    return f"Reached target {self.format_game_date(*target_boundary)}"
            except (TypeError, ValueError):
                pass
        if policy.get("stop_on_event"):
            baseline = {str(value) for value in policy.get("event_cursor", []) if value}
            for package in getattr(self, "ai_event_archive", []) or []:
                key = self._simulation_event_key(package)
                if key and key not in baseline and self._simulation_package_matches_policy(package, policy):
                    company = str(package.get("company", "World") or "World")
                    return f"New hosted event recorded ({company})"
        return ""

    def set_spectator_pause_policy(self, target=None, stop_on_event=False, watched_fighter_ids=None, watched_company_names=None):
        """Persist a safe spectator stop policy in the current save state."""
        if not isinstance(getattr(self, "rules", None), dict):
            self.rules = {}
        raw_target = None
        if isinstance(target, (list, tuple)) and len(target) == 2:
            try:
                raw_target = [max(1, int(target[0])), max(1, min(4, int(target[1])))]
            except (TypeError, ValueError):
                raw_target = None
        policy = {
            "version": 1, "enabled": bool(raw_target or stop_on_event), "target": raw_target,
            "stop_on_event": bool(stop_on_event),
            "source_revision": self._simulation_pause_source_revision(),
            "watched_fighter_ids": [str(value) for value in (watched_fighter_ids or []) if value][:40],
            "watched_company_names": [str(value) for value in (watched_company_names or []) if value][:20],
            "event_cursor": self._simulation_event_keys(),
            "last_completed_boundary": None, "stop_reason": "",
        }
        self.rules["simulation_pause_policy"] = policy
        self.refresh_spectator_pause_policy_ui()
        return deepcopy(policy)

    def apply_spectator_pause_policy(self):
        """Read the observer policy controls and stage them for the next run."""
        target = None
        try:
            target_year = max(GAME_START_YEAR, int(self.spectator_target_year.get()))
            target_month = self.calendar_month_index(target_year, CALENDAR_MONTHS.index(self.spectator_target_calendar_month.get()) + 1)
            target_week = max(1, min(4, int(self.spectator_target_week.get())))
            if (target_month, target_week) > (int(self.month), int(self.week)):
                target = (target_month, target_week)
        except (AttributeError, TypeError, ValueError):
            target = None
        pause_var = getattr(self, "spectator_pause_on_event_var", None)
        policy = self.set_spectator_pause_policy(
            target=target,
            stop_on_event=bool(pause_var.get()) if pause_var is not None else False,
        )
        if not policy.get("enabled"):
            self.refresh_spectator_pause_policy_ui("Choose a future date or enable event monitoring.")
        return policy

    def refresh_spectator_pause_policy_ui(self, message=None):
        label = getattr(self, "spectator_policy_status", None)
        if label is None:
            return
        policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
        if not isinstance(policy, dict) or not policy.get("enabled"):
            reason = (policy.get("stop_reason") if isinstance(policy, dict) else "") or message or "No saved stop policy."
            label.config(text=str(reason))
            return
        if not self._simulation_pause_policy_source_compatible(policy):
            label.config(text="Saved stop policy is from a different game revision. Clear it or arm a new policy.")
            return
        target = policy.get("target")
        target_label = "No date target"
        if isinstance(target, (list, tuple)) and len(target) == 2:
            try:
                safe_month = max(1, int(target[0]))
                safe_week = max(1, min(4, int(target[1])))
                target_label = self.format_game_date(safe_month, safe_week)
            except (TypeError, ValueError, IndexError):
                target_label = "Date target unavailable"
        event_label = "next hosted event" if policy.get("stop_on_event") else "date target"
        label.config(text=f"Armed for {event_label} | target {target_label}. Quick Save preserves this policy.")

    def clear_spectator_pause_policy(self):
        policy = getattr(self, "rules", {}).get("simulation_pause_policy")
        if not isinstance(policy, dict):
            return False
        policy.update({"enabled": False, "target": None, "stop_on_event": False, "watched_fighter_ids": [], "watched_company_names": [], "event_cursor": self._simulation_event_keys(), "stop_reason": ""})
        self.refresh_spectator_pause_policy_ui()
        return True

    def spectator_inline_notice(self, message):
        """Show a non-mutating observer notice on the persistent simulation desk."""
        text = str(message or "")
        status = getattr(self, "spectator_sim_status", None)
        if status is not None and hasattr(status, "config"):
            try:
                status.config(text=text)
            except Exception:
                pass
        policy_status = getattr(self, "spectator_policy_status", None)
        if policy_status is not None and hasattr(policy_status, "config"):
            try:
                policy_status.config(text=text)
            except Exception:
                pass
        return False

    def resume_spectator_simulation(self):
        """Resume from the last committed boundary using the saved policy."""
        if not getattr(self, "spectator_mode", False):
            return self.spectator_inline_notice("Start a new game in Spectator Mode to use world fast-forward controls.")
        policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
        if not self._simulation_pause_policy_source_compatible(policy):
            return self.spectator_inline_notice(
                "The saved stop policy was created by a different game revision. "
                "Load normally, clear it, or arm a new policy before resuming."
            )
        target = policy.get("target") if isinstance(policy, dict) else None
        if not isinstance(target, (list, tuple)) or len(target) != 2:
            return self.spectator_inline_notice("Set a future target date before resuming the observer.")
        target_boundary = (int(target[0]), max(1, min(4, int(target[1]))))
        current = (int(self.month), int(self.week))
        if target_boundary <= current:
            return self.spectator_inline_notice("The saved simulation target has already been reached.")
        policy["enabled"] = True
        policy["stop_reason"] = ""
        policy["event_cursor"] = self._simulation_event_keys()
        self.refresh_spectator_pause_policy_ui()
        weeks = (target_boundary[0] - current[0]) * 4 + (target_boundary[1] - current[1])
        return self.spectator_advance_weeks(weeks, f"Resuming to {self.format_game_date(*target_boundary)}")

    def spectator_advance_weeks(self, weeks=1, status_prefix="Simulating", on_complete=None, stop_condition=None):
        if not getattr(self, "spectator_mode", False):
            return self.spectator_inline_notice("Start a new game in Spectator Mode to use world fast-forward controls.")
        policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
        if isinstance(policy, dict) and policy.get("enabled") and not self._simulation_pause_policy_source_compatible(policy):
            return self.spectator_inline_notice(
                "The saved stop policy was created by a different game revision. "
                "Clear it or arm a new policy before fast-forwarding."
            )
        return self.begin_advance_sequence(
            max(1, int(weeks)),
            status_prefix=status_prefix,
            on_complete=on_complete,
            stop_condition=stop_condition,
        )

    def request_spectator_sim_stop(self):
        """Stop an observer fast-forward safely after its current world week."""
        job = getattr(self, "_advance_job", None)
        if not getattr(self, "spectator_mode", False) or not getattr(self, "_advance_in_progress", False) or not job:
            return False
        if job.get("stop_requested"):
            return True
        job["stop_requested"] = True
        job["stop_reason"] = "User requested stop after the current simulated week"
        self.set_advance_ui_progress(
            "Stopping after the current simulated week",
            (job.get("completed", 0) / max(1, job.get("total", 1))) * 100,
        )
        return True

    def spectator_sim_month(self):
        self.spectator_advance_weeks(4, "Simulating month")

    def spectator_sim_year(self):
        self.spectator_advance_weeks(48, "Simulating year")

    def spectator_sim_to_date(self):
        target_year = max(GAME_START_YEAR, int(self.spectator_target_year.get()))
        target_calendar_month = CALENDAR_MONTHS.index(self.spectator_target_calendar_month.get()) + 1
        target_month = self.calendar_month_index(target_year, target_calendar_month)
        target_week = max(1, min(4, int(self.spectator_target_week.get())))
        target = (target_month, target_week)
        current = (self.month, self.week)
        if target <= current:
            self.spectator_inline_notice("Choose a future calendar date.")
            return False
        weeks = (target_month - self.month) * 4 + (target_week - self.week)
        pause_var = getattr(self, "spectator_pause_on_event_var", None)
        self.set_spectator_pause_policy(
            target=(target_month, target_week),
            stop_on_event=bool(pause_var.get()) if pause_var is not None else False,
        )
        self.spectator_advance_weeks(weeks, f"Simulating to {self.format_game_date(target_month, target_week)}")

    def watch_latest_world_event(self):
        if not self.ai_event_archive:
            return self.spectator_inline_notice("No AI promotion has completed an archived event yet. Sim forward to create one.")
        package = self.ai_event_archive[0]
        self.open_live_fight_window({"name": package.get("event_name", "World Event")}, package, apply_results=False)

    def spectator_watch_next_event(self):
        if not getattr(self, "spectator_mode", False):
            return self.spectator_inline_notice("Start a new game in Spectator Mode to watch the next hosted event.")
        before = len(self.ai_event_archive)
        # A promotion's show cadence is deliberately variable. Two dozen weeks is
        # enough to find a card without turning this command into an endless loop.
        def completed():
            if len(self.ai_event_archive) > before:
                self.watch_latest_world_event()
            else:
                self.spectator_inline_notice("No promotion hosted a card in the next 24 weeks. The world still advanced normally.")

        self.spectator_advance_weeks(
            24,
            "Looking for the next hosted event",
            on_complete=completed,
            stop_condition=lambda: len(self.ai_event_archive) > before,
        )

    def fight_popularity_movement(self, winner, loser, fight, method):
        """Return restrained, context-sensitive popularity movement for a completed bout."""
        finish = method not in ("Decision", "Technical Decision", "Draw", "No Contest")
        rivalry = bool(self.rivalry_heat_between(winner, loser))
        upset = winner.overall + 5 < loser.overall or winner.popularity + 12 < loser.popularity
        winner_gain = 1 + int(bool(fight.get("main"))) + int(bool(fight.get("title")))
        winner_gain += int(finish) + int(rivalry) + int(upset)
        if winner.popularity < 25:
            winner_gain += 1
        # Established stars still benefit, but do not race to 100 on routine wins.
        if winner.popularity >= 85:
            winner_gain = max(1, winner_gain - 1)
        loser_loss = int(finish) + int(loser.popularity >= winner.popularity + 15)
        if fight.get("main") and loser.popularity < 35:
            loser_loss = max(0, loser_loss - 1)
        return min(6, winner_gain), min(3, loser_loss)

    def register_fight_popularity(self, winner, loser, fight, method):
        winner_gain, loser_loss = self.fight_popularity_movement(winner, loser, fight, method)
        winner.popularity = min(100, winner.popularity + winner_gain)
        loser.popularity = max(1, loser.popularity - loser_loss)

    def register_draw_popularity(self, a, b, fight):
        """Apply the modest shared visibility gain from a competitive draw."""
        stakes = int(bool(fight.get("main"))) + int(bool(fight.get("title")))
        rivalry = int(bool(self.rivalry_heat_between(a, b)))
        gain = min(2, stakes + rivalry)
        if gain:
            a.popularity = min(100, a.popularity + gain)
            b.popularity = min(100, b.popularity + gain)

    def add_fight_history_entry(self, fighter, entry):
        """Record a result once, even if a resumed world task repeats a write."""
        fighter.fight_history = fighter.fight_history or []
        if entry not in fighter.fight_history:
            fighter.fight_history.insert(0, entry)

    def scorecard_summary_from_lines(self, lines):
        """Extract official totals without retaining the commentary that led to them."""
        cards, collecting = [], False
        for raw in lines or []:
            text = str(raw).strip()
            if text == "Official scorecards:":
                collecting = True
                continue
            if collecting and text.startswith("Judges' vote:"):
                break
            if collecting:
                match = re.search(r":.*?(\d{2}).*?,.*?(\d{2})", text)
                if match:
                    cards.append(f"{match.group(1)}-{match.group(2)}")
        return " / ".join(cards)

    def bout_rating_snapshot(self, fighter):
        """Return the immutable rating state shown beside a historical result."""
        return {
            "overall": int(round(getattr(fighter, "overall", 0))),
            "elo": int(round(getattr(fighter, "elo_rating", 1500))),
            "record": str(getattr(fighter, "record", "0-0-0")),
        }

    def fighter_peak_overall(self, fighter):
        """Return the best rating retained by the live and archived career data."""
        def score_value(value):
            try:
                numeric = float(value)
            except (TypeError, ValueError):
                return 0
            return int(round(numeric)) if numeric == numeric else 0

        current = score_value(getattr(fighter, "overall", 0))
        stored_peak = score_value(getattr(fighter, "career_peak_overall", 0))
        # Once the migration has persisted a peak, normal monthly and bout
        # updates stay O(1). The more expensive archive scan is only needed to
        # repair saves made before this dedicated field existed.
        if stored_peak:
            return max(1, min(99, max(current, stored_peak)))
        scores = [current]
        scores.extend((getattr(fighter, "annual_overalls", None) or {}).values())
        for bout in getattr(fighter, "bout_rating_history", None) or []:
            if isinstance(bout, dict):
                scores.append(bout.get("self_overall", bout.get("overall", 0)))
        valid_scores = [score_value(score) for score in scores]
        return max(1, min(99, max(valid_scores, default=1)))

    def update_fighter_peak_overall(self, fighter):
        peak = self.fighter_peak_overall(fighter)
        fighter.career_peak_overall = peak
        return peak

    def bout_ranking_snapshots(self, fighters):
        """Freeze pre-bout employer and divisional positions without using UI filters."""
        fighters = tuple(fighter for fighter in fighters if fighter is not None)
        snapshots = {}

        def identity(fighter):
            return str(getattr(fighter, "fighter_id", "") or f"legacy-{id(fighter)}")

        # Combat-sport circuits own their own ranking ledgers. They currently
        # have one world table per sport, so the employer and world positions
        # intentionally share that table while remaining separate saved fields.
        mma_targets = []
        for fighter in fighters:
            if getattr(fighter, "sport_employer", ""):
                matched = False
                for sport, world in getattr(self, "combat_sport_worlds", {}).items():
                    roster = list(world.get("roster", []) or [])
                    if not any(candidate is fighter or identity(candidate) == identity(fighter) for candidate in roster):
                        continue
                    matched = True
                    employer = str(getattr(fighter, "sport_employer", "") or world.get("promotion", sport) or sport)
                    player_owned = employer == getattr(self, "player_company_name", "")
                    state = self.combat_sport_state(sport, world, player_owned)
                    key = self.combat_sport_division_key(fighter, sport)
                    title_id = str((state.get("title_ids", {}) or {}).get(key, "") or "")
                    title_name = str((state.get("titles", {}) or {}).get(key, "") or "")
                    fighter_id = identity(fighter)
                    champion = (title_id and title_id == fighter_id) or (not title_id and title_name == fighter.name)
                    names = list((state.get("rankings_by_division", {}) or {}).get(key, []) or [])
                    same_name = sum(candidate.name == fighter.name for candidate in roster)
                    rank = "C" if champion else (f"#{names.index(fighter.name) + 1}" if same_name == 1 and fighter.name in names else "-")
                    snapshots[fighter_id] = {"company": employer, "company_rank": rank, "world_rank": rank}
                    break
                if matched:
                    continue
            mma_targets.append(fighter)

        target_divisions = {(fighter.gender, fighter.weight) for fighter in mma_targets}
        if target_divisions:
            rows = [(getattr(self, "player_company_name", "Player Company"), fighter)
                    for fighter in getattr(self, "roster", [])]
            rows.extend(("Free Agent", fighter) for fighter in getattr(self, "free_agents", []))
            for promotion in getattr(self, "promotions", []):
                rows.extend((promotion.name, fighter) for fighter in getattr(promotion, "roster", []))
            filtered, seen = [], set()
            for company, fighter in rows:
                fighter_id = identity(fighter)
                if fighter_id in seen or (fighter.gender, fighter.weight) not in target_divisions:
                    continue
                seen.add(fighter_id)
                filtered.append((company, fighter))
            score = {identity(fighter): self.rank_value(fighter) for _company, fighter in filtered}
            world_groups = {}
            company_groups = {}
            company_by_fighter = {}
            for company, fighter in filtered:
                division = (fighter.gender, fighter.weight)
                fighter_id = identity(fighter)
                company_by_fighter[fighter_id] = company
                world_groups.setdefault(division, []).append(fighter)
                company_groups.setdefault((company, *division), []).append(fighter)
            world_ranks = {}
            company_ranks = {}
            for candidates in world_groups.values():
                for position, candidate in enumerate(sorted(candidates, key=lambda item: score[identity(item)], reverse=True), 1):
                    world_ranks[identity(candidate)] = f"#{position}"
            for (company, _gender, _weight), candidates in company_groups.items():
                for candidate in candidates:
                    if candidate.champion:
                        company_ranks[(company, identity(candidate))] = "C"
                contenders = sorted((candidate for candidate in candidates if not candidate.champion),
                                    key=lambda item: score[identity(item)], reverse=True)
                for position, candidate in enumerate(contenders, 1):
                    company_ranks[(company, identity(candidate))] = "IC" if candidate.interim_champion else f"#{position}"
            for fighter in mma_targets:
                fighter_id = identity(fighter)
                company = company_by_fighter.get(fighter_id, "Independent")
                snapshots[fighter_id] = {
                    "company": company,
                    "company_rank": company_ranks.get((company, fighter_id), "-"),
                    "world_rank": world_ranks.get(fighter_id, "-"),
                }
        return snapshots

    def record_bout_rating_history(self, a, b, a_result, b_result, fight=None):
        """Keep pre-bout ratings after card replays are trimmed from the archive."""
        self.update_fighter_peak_overall(a)
        self.update_fighter_peak_overall(b)
        date = f"Month {self.month} Week {self.week}"
        a_snapshot = self.bout_rating_snapshot(a)
        b_snapshot = self.bout_rating_snapshot(b)
        ranking_snapshots = self.bout_ranking_snapshots((a, b))
        a_ranking = ranking_snapshots.get(str(getattr(a, "fighter_id", "") or f"legacy-{id(a)}"), {})
        b_ranking = ranking_snapshots.get(str(getattr(b, "fighter_id", "") or f"legacy-{id(b)}"), {})
        a_snapshot.update(a_ranking)
        b_snapshot.update(b_ranking)
        fight = fight or {}

        def append_snapshot(fighter, opponent, own, other, result):
            fighter.bout_rating_history = list(getattr(fighter, "bout_rating_history", None) or [])
            entry = {
                "date": date,
                "opponent_name": opponent.name,
                "opponent_id": str(getattr(opponent, "fighter_id", "") or ""),
                "result": result,
                "self_overall": own["overall"],
                "self_elo": own["elo"],
                "self_record": own["record"],
                "self_company": own.get("company", "Independent"),
                "self_company_rank": own.get("company_rank", "-"),
                "self_world_rank": own.get("world_rank", "-"),
                "opponent_overall": other["overall"],
                "opponent_elo": other["elo"],
                "opponent_record": other["record"],
                "opponent_company": other.get("company", "Independent"),
                "opponent_company_rank": other.get("company_rank", "-"),
                "opponent_world_rank": other.get("world_rank", "-"),
                "weight": getattr(fighter, "weight", ""),
                "title": bool(fight.get("title", False)),
                "divisional_title": bool(fight.get("divisional_title", fight.get("title") and not fight.get("special_belt"))),
                "interim": bool(fight.get("interim", False)),
                "special_belt": str(fight.get("special_belt", "") or ""),
                "scorecard": str(fight.get("_scorecards", "") or "-"),
            }
            # A fighter cannot legitimately have two bouts with the same opponent
            # and pre-bout record on one card. This also keeps resumed tasks idempotent.
            key = (entry["date"], entry["opponent_id"] or entry["opponent_name"], entry["self_record"])
            existing = {
                (str(item.get("date", "")), str(item.get("opponent_id", "") or item.get("opponent_name", "")), str(item.get("self_record", "")))
                for item in fighter.bout_rating_history if isinstance(item, dict)
            }
            if key not in existing:
                fighter.bout_rating_history.insert(0, entry)
                fighter.bout_rating_history = fighter.bout_rating_history[:250]

        append_snapshot(a, b, a_snapshot, b_snapshot, a_result)
        append_snapshot(b, a, b_snapshot, a_snapshot, b_result)
        return {"a_rating": a_snapshot, "b_rating": b_snapshot}

    def extend_comeback_commitment(self, fighter, additional_fights):
        """Start a fresh, fight-counted comeback deal for a returning fighter."""
        additional = max(1, int(additional_fights or 1))
        previous_guaranteed = max(0, int(getattr(fighter, "guaranteed_fights", 0) or 0))
        previous_completed = max(0, int(getattr(fighter, "contract_fights_completed", 0) or 0))
        fighter.guaranteed_fights = additional
        fighter.contract_fights_completed = 0
        fighter.comeback_contract = True
        fighter.retirement_pending = False
        fighter.retirement_fight_completed = False
        fighter.retirement_fight_due_after_month = 0
        fighter.comeback_completion_prompted = False
        return {
            "previous_guaranteed": previous_guaranteed,
            "previous_completed": previous_completed,
            "additional": additional,
            "total": additional,
            "remaining": additional,
        }

    def record_contract_fight_completion(self, fighter):
        """Track a player comeback commitment only after an official bout."""
        if fighter not in self.roster:
            return
        guaranteed = max(0, int(getattr(fighter, "guaranteed_fights", 0) or 0))
        if not getattr(fighter, "comeback_contract", False) or guaranteed <= 0:
            return
        completed = min(guaranteed, max(0, int(getattr(fighter, "contract_fights_completed", 0) or 0)) + 1)
        fighter.contract_fights_completed = completed
        remaining = guaranteed - completed
        fighter.fight_history = fighter.fight_history or []
        fighter.fight_history.insert(0, f"Comeback commitment: {completed}/{guaranteed} guaranteed fights completed.")
        if remaining:
            self.inbox.append({"subject": "Comeback Commitment", "body": f"{fighter.name} has {remaining} guaranteed comeback fight{'s' if remaining != 1 else ''} remaining on their deal.", "type": "Contracts", "resolved": False})
        else:
            fighter.comeback_contract = False
            fighter.retirement_pending = True
            fighter.retirement_fight_completed = False
            fighter.retirement_fight_due_after_month = self.month
            fighter.retirement_requested_month = self.month
            fighter.retirement_reason = "Comeback commitment complete. Renew for another comeback or book one final retirement bout."
            fighter.comeback_completion_prompted = False
            self.inbox.append({"subject": "Comeback Commitment Complete", "body": f"{fighter.name} fulfilled all {guaranteed} guaranteed comeback fights. Renew their comeback deal from the fighter profile, or book their one final retirement bout.", "type": "Contracts", "resolved": False})
            if hasattr(self, "root") and hasattr(self, "prompt_comeback_completion"):
                self.root.after(0, lambda: self.prompt_comeback_completion(fighter))

    def apply_result(self, winner, loser, fight, method="Decision"):
        winner_was_champion = bool(getattr(winner, "champion", False))
        loser_was_champion = bool(getattr(loser, "champion", False))
        story_company = self.fighter_company_name(winner) or self.player_company_name
        # Weigh-in state is cleared later in this method, so career arcs that
        # track weight management must see the result before preparation resets.
        self.record_career_arc_result((winner, loser), fight)
        self.record_bout_rating_history(winner, loser, "W", "L", fight)
        self.complete_fight_observation(winner, loser, "Win", method, fight)
        self.complete_fight_observation(loser, winner, "Loss", method, fight)
        self.update_elo(winner, loser, fight, method)
        winner.record_w += 1
        loser.record_l += 1
        self.record_contract_fight_completion(winner)
        self.record_contract_fight_completion(loser)
        winner.career_win_streak = getattr(winner, "career_win_streak", 0) + 1
        loser.career_win_streak = 0
        winner.momentum = min(5, winner.momentum + 1)
        loser.momentum = max(-5, loser.momentum - 1)
        winner.morale = min(100, winner.morale + random.randint(3, 8))
        loser.morale = max(15, loser.morale - random.randint(4, 10))
        winner.motivation = min(99, winner.motivation + random.randint(1, 4))
        loser.motivation = max(1, loser.motivation - random.randint(1, 6))
        self.register_fight_popularity(winner, loser, fight, method)
        winner.fatigue = min(100, winner.fatigue + random.randint(18, 35))
        loser.fatigue = min(100, loser.fatigue + random.randint(22, 44))
        self.set_post_fight_recovery(winner, method, lost=False)
        self.set_post_fight_recovery(loser, method, lost=True)
        self.apply_visible_trauma_consequences(winner, lost=False)
        self.apply_visible_trauma_consequences(loser, lost=True)
        # Medical recovery and visible-trauma consequences must consume the
        # just-completed fight evidence before career aggregation clears the
        # transient ``last_fight_stats`` payload.
        self.commit_career_stats(winner, method, won=True)
        self.commit_career_stats(loser, method, won=False)
        winner.last_fight = f"W over {loser.name}"
        loser.last_fight = f"L to {winner.name}"
        self.stamp_last_fight_date(winner, loser)
        winner.rank_score = self.rank_value(winner)
        loser.rank_score = self.rank_value(loser)
        result_line = f"Month {self.month} Week {self.week}: {winner.name} def. {loser.name} by {method}"
        self.add_fight_history_entry(winner, result_line)
        self.add_fight_history_entry(loser, result_line)
        if self.rivalry_heat_between(winner, loser):
            self.resolve_rivalry_result(winner, loser, fight, method)
        else:
            series = self.matchup_series_record(winner, loser)
            if series["meetings"] >= 2 and series["a_wins"] == series["b_wins"]:
                heat = 48 + min(24, series["meetings"] * 4) + (8 if fight.get("main") or fight.get("title") else 0)
                if self.establish_rivalry(winner, loser, f"Level series at {series['a_wins']}-{series['b_wins']}", heat=heat, rematch_due=True):
                    note = (
                        f"Month {self.month}: The head-to-head series is tied "
                        f"{series['a_wins']}-{series['b_wins']}; both fighters want the decider."
                    )
                    winner.rivalry_history = (winner.rivalry_history or [])[-39:] + [note]
                    loser.rivalry_history = (loser.rivalry_history or [])[-39:] + [note]
        winner.last_fight = result_line
        loser.last_fight = result_line
        if winner.trait == "Fan Favourite":
            winner.popularity = min(100, winner.popularity + 2)
        if loser.trait == "Fan Favourite" and random.random() < 0.35:
            loser.popularity = min(100, loser.popularity + 1)
        recurrence = getattr(loser, "serious_injury_recurrence", 0)
        injury_chance = 0.07 + effective_injury_tendency(loser) / 420 + max(0, loser.fatigue - 35) / 500 + recurrence / 1500
        if random.random() < injury_chance:
            loser.injured = random.randint(1, 3)
            loser.available_week = max(getattr(loser, "available_week", 0), self.calendar_week_index() + loser.injured * 4)
        serious_chance = 0.0008 + effective_injury_tendency(loser) / 80_000 + max(0, loser.age - 33) / 12_000 + recurrence / 30_000
        if method == "Injury Stoppage":
            serious_chance += 0.012
        if random.random() < serious_chance:
            self.apply_serious_injury(loser, "fight injury")
        self.clear_post_fight_preparation(winner, loser)
        championship_won = False
        if fight.get("special_belt"):
            belt_name = fight["special_belt"]
            if self.award_special_belt(belt_name, winner, loser, method):
                championship_won = True
                self.news.insert(0, f"{winner.name} won the {belt_name} championship after beating {loser.name}.")
        divisional_title = bool(fight.get("divisional_title", fight.get("title") and not fight.get("special_belt")))
        if divisional_title and fight.get("interim"):
            championship_won = True
            self.interim_belts, self.belt_history = self.set_interim_champion(self.roster, self.interim_belts, self.belt_history, winner, f"Defeated {loser.name} by {method}.")
            self.news.insert(0, f"{winner.name} won the interim {winner.gender} {winner.weight} title after beating {loser.name}.")
        elif divisional_title:
            championship_won = True
            key = self.belt_key(winner.gender, winner.weight)
            self.belts, self.belt_history = self.set_primary_champion(self.roster, self.belts, self.belt_history, winner, f"Defeated {loser.name} by {method}.", defense=True)
            if self.interim_title_participates(self.interim_belts, winner, loser):
                self.interim_belts, self.belt_history = self.clear_interim_belt(self.roster, self.interim_belts, self.belt_history, key, "Unified with the primary title.")
            self.news.insert(0, f"{winner.name} is now the {winner.gender} {winner.weight} champion after beating {loser.name}.")
            # Champion's clause: winning/holding the belt auto-extends the deal.
            if getattr(winner, "champions_clause", False) and winner in self.roster and not getattr(winner, "comeback_contract", False):
                winner.contract_months = max(winner.contract_months, 12)
                self.news.insert(0, f"{winner.name}'s champion's clause automatically extends their contract while they hold the belt.")
            winner.owed_title_shot = False
        if championship_won:
            winner.title_shots += 1
        if divisional_title:
            # A divisional title fight fulfils an owed title-shot clause for BOTH
            # fighters, win or lose: the guaranteed shot has been granted, so stop
            # the alert and consume the one-time clause instead of re-triggering it.
            for participant in (winner, loser):
                if getattr(participant, "owed_title_shot", False) or getattr(participant, "title_shot_clause", False):
                    participant.owed_title_shot = False
                    participant.title_shot_clause = False
                    self.resolve_title_shot_inbox(participant)
                arc = self.active_career_arc(participant)
                if arc and arc.get("type") == "Veteran Final Run":
                    self.complete_career_arc(participant, "They received a final championship opportunity on merit.")
            winner_arc = self.active_career_arc(winner)
            if winner_arc and winner_arc.get("type") == "Homegrown Champion" and winner.champion:
                self.complete_career_arc(winner, "The academy graduate became the promotion's first homegrown champion.")
        # Title-shot clause: a win in a NON-title fight earns a guaranteed future shot.
        elif getattr(winner, "title_shot_clause", False) and winner in self.roster and not winner.champion:
            if not getattr(winner, "owed_title_shot", False) and not self.has_unresolved_title_shot_inbox(winner):
                winner.owed_title_shot = True
                self.inbox.append({
                    "subject": f"Title Shot Owed - {winner.name}",
                    "body": f"{winner.name}'s contract guarantees a title shot, and they have earned it with a win over {loser.name}. Book them in a {winner.gender} {winner.weight} title fight.",
                    "type": "Contract", "resolved": False,
                })
        if divisional_title:
            self.record_title_story_result(
                story_company, winner, loser, method,
                defense=winner_was_champion, loser_was_champion=loser_was_champion,
                title_label=f"{winner.gender} {winner.weight} championship",
            )
        self.record_redemption_story_result(
            story_company, winner, loser, method, fight,
            loser_was_champion=loser_was_champion and divisional_title,
        )
        self.record_crossroads_fight_story(story_company, winner, loser, method, fight)
        self.record_relationship_fight_story(story_company, winner, loser, method, fight)
        self.record_coaching_fight_outcome(story_company, winner, loser, method, fight)
        self.record_farewell_fight_story(story_company, winner, loser, method, fight)
        if getattr(winner, "feeder_story_key", "") or getattr(loser, "feeder_story_key", ""):
            self.record_feeder_fight_result(story_company, winner, loser, method, fight)
        self.evaluate_fight_achievements(winner, loser, fight, method, story_company)
        if not fight.get("_defer_retirement"):
            self.retire_after_final_fight_if_due(winner, story_company)
            self.retire_after_final_fight_if_due(loser, story_company)

    def apply_draw_result(self, a, b, fight):
        self.record_career_arc_result((a, b), fight)
        self.record_bout_rating_history(a, b, "D", "D", fight)
        self.complete_fight_observation(a, b, "Draw", "Draw", fight)
        self.complete_fight_observation(b, a, "Draw", "Draw", fight)
        self.update_draw_elo(a, b, fight)
        a.record_d = getattr(a, "record_d", 0) + 1
        b.record_d = getattr(b, "record_d", 0) + 1
        self.record_contract_fight_completion(a)
        self.record_contract_fight_completion(b)
        a.career_win_streak = 0
        b.career_win_streak = 0
        self.stamp_last_fight_date(a, b)
        a.momentum = max(-5, min(5, a.momentum))
        b.momentum = max(-5, min(5, b.momentum))
        a.morale = min(100, a.morale + random.randint(0, 3))
        b.morale = min(100, b.morale + random.randint(0, 3))
        self.register_draw_popularity(a, b, fight)
        a.fatigue = min(100, a.fatigue + random.randint(18, 34))
        b.fatigue = min(100, b.fatigue + random.randint(18, 34))
        self.set_post_fight_recovery(a, "Decision", lost=False)
        self.set_post_fight_recovery(b, "Decision", lost=False)
        self.apply_visible_trauma_consequences(a, lost=False)
        self.apply_visible_trauma_consequences(b, lost=False)
        self.commit_career_stats(a)
        self.commit_career_stats(b)
        self.clear_post_fight_preparation(a, b)
        a.rank_score = self.rank_value(a)
        b.rank_score = self.rank_value(b)
        result_line = f"Month {self.month} Week {self.week}: {a.name} and {b.name} fought to a draw"
        for fighter in (a, b):
            self.add_fight_history_entry(fighter, result_line)
            fighter.last_fight = result_line
        heat = self.rivalry_heat_between(a, b)
        if heat:
            next_heat = min(100, heat + random.randint(22, 38))
            for fighter in (a, b):
                fighter.rivalry_heat = next_heat
                fighter.rivalry_rematch_due = True
                fighter.rivalry_last_month = self.month
                fighter.rivalry_history = (fighter.rivalry_history or [])[-39:] + [f"Month {self.month}: Draw with {b.name if fighter is a else a.name}; rematch demand intensifies. Heat now {next_heat}/100."]
            story_key = self.rivalry_story_key(a, b)
            thread = self.record_rivalry_story(
                a, b, phase="rematch_due", status="active", importance=4 if fight.get("main") or fight.get("title") else 3,
                beat_kind="draw", beat_ref=f"{story_key}:draw:{self.month}:{self.week}",
                summary=f"{a.name} and {b.name} fought to a draw; rematch demand pushed the feud to {next_heat}/100.",
                stakes="The draw left the rivalry unresolved and created a clear rematch payoff.",
            )
            self.record_world_story(
                "Rivalry", f"{a.name} and {b.name} leave their rivalry unsettled.",
                "The draw increased demand for a rematch.", fighters=[a.name, b.name],
                importance=4 if fight.get("main") or fight.get("title") else 3,
                fighter_ids=[a.fighter_id, b.fighter_id],
                story_id=thread.get("story_id", "") if thread else "",
            )
        else:
            heat = 42 + (10 if fight.get("main") or fight.get("title") else 0)
            if self.establish_rivalry(a, b, "Unsettled draw", heat=heat, rematch_due=True):
                for fighter in (a, b):
                    opponent = b.name if fighter is a else a.name
                    fighter.rivalry_history = (fighter.rivalry_history or [])[-39:] + [
                        f"Month {self.month}: Draw with {opponent}; both camps want a rematch. Heat now {fighter.rivalry_heat}/100."
                    ]
        if fight.get("special_belt"):
            self.news.insert(0, f"The {fight['special_belt']} title fight between {a.name} and {b.name} ended in a draw; the holder remains unchanged.")
        if fight.get("divisional_title", fight.get("title") and not fight.get("special_belt")):
            title_kind = "interim title" if fight.get("interim") else "title"
            self.news.insert(0, f"The {a.gender} {a.weight} {title_kind} fight between {a.name} and {b.name} ended in a draw; title status remains unchanged.")
        if getattr(a, "feeder_story_key", "") or getattr(b, "feeder_story_key", ""):
            story_company = self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name
            self.record_feeder_fight_result(story_company, a, b, "Draw", fight)
        if getattr(a, "breakout_story_key", "") or getattr(b, "breakout_story_key", ""):
            story_company = self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name
            self.record_breakout_fight_story(story_company, a, b, "Draw", fight)
        if getattr(a, "crossroads_story_key", "") or getattr(b, "crossroads_story_key", ""):
            story_company = self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name
            self.record_crossroads_fight_story(story_company, a, b, "Draw", fight)
        self.record_relationship_fight_story(
            self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name,
            a, b, "Draw", fight,
        )
        self.record_farewell_fight_story(
            self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name,
            a, b, "Draw", fight,
        )
        if not fight.get("_defer_retirement"):
            self.retire_after_final_fight_if_due(a, self.fighter_company_name(a))
            self.retire_after_final_fight_if_due(b, self.fighter_company_name(b))

    def apply_no_contest_result(self, a, b, fight):
        """Settle participation and medical recovery without inventing a W/L/D or title change."""
        self.complete_fight_observation(a, b, "No Contest", "No Contest", fight)
        self.complete_fight_observation(b, a, "No Contest", "No Contest", fight)
        self.record_contract_fight_completion(a)
        self.record_contract_fight_completion(b)
        self.stamp_last_fight_date(a, b)
        for fighter, opponent in ((a, b), (b, a)):
            fighter.fatigue = min(100, fighter.fatigue + random.randint(18, 34))
            self.set_post_fight_recovery(fighter, "No Contest", lost=False)
            self.apply_visible_trauma_consequences(fighter, lost=False)
            result_line = (
                f"Month {self.month} Week {self.week}: {fighter.name} vs {opponent.name} "
                "was ruled a No Contest"
            )
            self.add_fight_history_entry(fighter, result_line)
            fighter.last_fight = result_line
        self.clear_post_fight_preparation(a, b)
        if fight.get("special_belt"):
            self.news.insert(0, f"The {fight['special_belt']} title fight between {a.name} and {b.name} ended in a No Contest; the holder remains unchanged.")
        if fight.get("divisional_title", fight.get("title") and not fight.get("special_belt")):
            self.news.insert(0, f"The {a.gender} {a.weight} title fight between {a.name} and {b.name} ended in a No Contest; title status remains unchanged.")
        self.record_farewell_fight_story(
            self.fighter_company_name(a) or self.fighter_company_name(b) or self.player_company_name,
            a, b, "No Contest", fight,
        )

    def update_elo(self, winner, loser, fight, method):
        winner_elo = getattr(winner, "elo_rating", 1500)
        loser_elo = getattr(loser, "elo_rating", 1500)
        expected = 1 / (1 + 10 ** ((loser_elo - winner_elo) / 400))
        stakes = 1.25 if fight.get("title") else 1.1 if fight.get("main") else 1.0
        finish = 1.0 if method in ("Decision", "Technical Decision") else 1.12
        k = round(28 * stakes * finish)
        delta = max(6, round(k * (1 - expected)))
        winner.elo_rating = max(900, min(2400, winner_elo + delta))
        loser.elo_rating = max(900, min(2400, loser_elo - delta))

    def update_draw_elo(self, a, b, fight):
        """Apply the standard 0.5 result to both fighters after an official draw."""
        a_elo = getattr(a, "elo_rating", 1500)
        b_elo = getattr(b, "elo_rating", 1500)
        expected_a = 1 / (1 + 10 ** ((b_elo - a_elo) / 400))
        stakes = 1.25 if fight.get("title") else 1.1 if fight.get("main") else 1.0
        delta = round(28 * stakes * (0.5 - expected_a))
        a.elo_rating = max(900, min(2400, a_elo + delta))
        b.elo_rating = max(900, min(2400, b_elo - delta))

    def clear_post_fight_preparation(self, *fighters):
        """Remove single-bout camp and weigh-in state once an official result exists."""
        for fighter in fighters:
            fighter.camp_boost = 0
            fighter.camp_weeks = 0
            fighter.weight_cut_penalty = 0
            fighter.missed_weight = False

    def calculate_revenue(self, total_hype, venue=None):
        venue_factor = {
            "Local Gym": 1100,
            "Regional Arena": 1850,
            "Casino Ballroom": 2400,
            "National Sports Hall": 3300,
            "National Stadium": 5600,
            "Mega Stadium": 8200,
            "Historic Amphitheatre": 3900,
            "Ceremonial Capital Grounds": 3000,
            "White House South Lawn": 2400,
        }.get(venue or self.venue.get(), 1850)
        sponsor = 15000 + self.company_pop * 700
        return round(total_hype * venue_factor + sponsor)

    def resolve_event_production_tier(self, event):
        """Resolve a card's production tier, tolerating old saves and AI events."""
        tier = str((event or {}).get("production_tier", "") or "").strip()
        if tier not in EVENT_PRODUCTION_TIERS:
            tier = DEFAULT_EVENT_PRODUCTION_TIER
        return tier, EVENT_PRODUCTION_TIERS[tier]

    def event_economics(self, event):
        """Per-event ticket price, marketing spend and production tier.

        Cards scheduled before these levers existed, and every AI card, fall
        back to the company-wide finance defaults so nothing changes for them.
        """
        self.ensure_finance_defaults()
        event = event or {}
        tier_name, tier = self.resolve_event_production_tier(event)
        try:
            ticket_price = int(event.get("ticket_price", self.finance["ticket_price"]))
        except (TypeError, ValueError):
            ticket_price = int(self.finance["ticket_price"])
        try:
            marketing = int(event.get("marketing_budget", self.finance["marketing_budget"]))
        except (TypeError, ValueError):
            marketing = int(self.finance["marketing_budget"])
        return {
            "ticket_price": max(EVENT_TICKET_PRICE_MIN, min(EVENT_TICKET_PRICE_MAX, ticket_price)),
            "marketing_budget": max(0, min(EVENT_MARKETING_BUDGET_MAX, marketing)),
            "production_tier": tier_name,
            "tier": tier,
        }

    def event_fair_ticket_price(self, total_hype, regional_pull=1.0, venue=None):
        """What this market will comfortably pay for this card.

        Used as the anchor for price elasticity: charging around this number
        fills the room, and moving away from it trades turnout against margin.
        """
        # The coefficients are deliberately shallow. An earlier curve let the
        # hype term compound with venue prestige, which inflated a mature
        # promotion's gate roughly sixfold against the rest of the economy:
        # purses, overhead and production did not grow anywhere near as fast.
        capacity = self.venue_capacity_for(venue or "Regional Arena")
        prestige = 1.0 + min(0.28, capacity / 260_000)
        base = 13 + self.company_pop * 0.28 + max(0, total_hype) * 0.040
        return max(EVENT_TICKET_PRICE_MIN, round(base * prestige * max(0.75, regional_pull)))

    def ticket_price_demand_factor(self, ticket_price, fair_price):
        """Turnout response to price. Cheap seats fill; greed empties the room.

        Demand decays to zero rather than resting on a floor. A floor made
        revenue climb forever past the point it bound, so the optimal play was
        to charge the maximum and sell to the handful of fans who still came.
        With no floor the gate has a true interior peak a little above the
        market rate, which is the decision this lever exists to create.
        """
        fair_price = max(1, int(fair_price or 1))
        ratio = max(0.1, int(ticket_price or 0) / fair_price)
        return max(0.0, min(1.28, 1.0 - (ratio - 1.0) * 0.62))

    def marketing_demand_factor(self, marketing_budget):
        """Spending above the company baseline buys turnout and awareness."""
        baseline = max(1, int(self.finance.get("marketing_budget", 18000) or 1))
        return max(0.82, min(1.35, 0.82 + (max(0, int(marketing_budget or 0)) / baseline) * 0.18))

    def venue_capacity_for(self, venue):
        return {
            "Local Gym": 900,
            "Regional Arena": 4200,
            "Casino Ballroom": 7500,
            "National Sports Hall": 14500,
            "National Stadium": 55000,
            "Mega Stadium": 90000,
            "Historic Amphitheatre": 22000,
            "Ceremonial Capital Grounds": 12000,
            "White House South Lawn": 2800,
        }.get(venue, 4200)

    def available_event_venues(self):
        base = ["Local Gym", "Regional Arena", "Casino Ballroom", "National Sports Hall"]
        unlocked = set(self.company_unlocked_milestone_ids()) if hasattr(self, "company_unlocked_milestone_ids") else set()
        if "national_power" in unlocked:
            base.append("National Stadium")
        if "major_organisation" in unlocked:
            base.extend(["Mega Stadium", "Historic Amphitheatre"])
        if "combat_sports_institution" in unlocked:
            base.append("Ceremonial Capital Grounds")
        if "legacy_empire" in unlocked:
            base.append("White House South Lawn")
        return base

    def fight_excitement(self, a, b, winner, loser, method, round_no, fight, hype=None):
        """Score the fight itself on 1-99, from what happened in the cage.

        Promotional heat sets a floor, but the bout decides the number. This was
        roughly three-quarters hype: who was fighting moved the score more than
        what they did, so Fight of the Night went to the biggest names rather
        than the best fight. It also paid more for later rounds than for a
        finish, so a five-round decision outscored a first-round knockout.

        Nothing here rewards when a fight happens. A fight is exciting or it is
        not, and the round it ends in does not change that.

        hype defaults to fight_hype so every caller is on one scale. The AI and
        regional paths used to pass raw combined popularity instead, which ran
        about fourteen points hot and made AI cards look far better than the
        player's for no gameplay reason.
        """
        if hype is None:
            hype = self.fight_hype(a, b, fight)
        stats_a = getattr(a, "last_fight_stats", None) or {}
        stats_b = getattr(b, "last_fight_stats", None) or {}

        def stat(source, key):
            try:
                return max(0, int(source.get(key, 0) or 0))
            except (TypeError, ValueError):
                return 0

        finished = method in FINISH_METHODS
        finish = 18 if finished else 0

        # Real drama from the engine: knocking someone down and hunting a
        # finish are the moments people remember.
        knockdowns = stat(stats_a, "knockdowns") + stat(stats_b, "knockdowns")
        sub_attempts = stat(stats_a, "sub_att") + stat(stats_b, "sub_att")
        drama = min(16, knockdowns * 6) + min(8, sub_attempts * 2.5)

        # Output per round rather than total, so a short violent fight is not
        # punished for finishing early.
        sig_a, sig_b = stat(stats_a, "sig"), stat(stats_b, "sig")
        rounds = max(1, stat(stats_a, "rounds") or round_no)
        pace = min(12, (sig_a + sig_b) / rounds / 4.0)

        # A shootout beats a shutout: reward both fighters landing.
        competitive = (min(sig_a, sig_b) / max(1, sig_a, sig_b)) * 10 if (sig_a or sig_b) else 0

        upset = 0 if method in ("Draw", "No Contest") else 9 if loser.overall > winner.overall + 4 else 0
        danger_styles = max(0, a.power + b.power + a.submissions + b.submissions - 260) * 0.05
        # Halved: with normal matchmaking this sat at 15-16 almost every bout,
        # so it was a flat offset rather than a discriminator.
        close_match = max(0, 16 - abs(a.overall - b.overall)) * 0.5
        return max(1, min(99, round(
            hype * 0.22 + finish + drama + pace + competitive + upset + danger_styles + close_match
        )))

    def regional_market_score(self, region):
        data = self.regions.get(region, {})
        economy = data.get("economy", "stable")
        economy_factor = {
            "struggling but improving": 0.86,
            "below average but improving": 0.94,
            "stable": 1.0,
            "strong": 1.12,
            "booming": 1.24,
        }.get(economy, 1.0)
        home_bonus = 1.08 if region == self.player_region else 0.98
        love_factor = 0.72 + data.get("mma_love", 50) / 100
        benefit = data.get("promo_benefit", REGION_PROMO_BENEFITS.get(region, {"media": 1.0, "gate": 1.0}))
        local_roster = len([fighter for fighter in self.roster if fighter.region == region])
        roster_factor = min(1.18, 1 + local_roster * 0.012)
        legality = data.get("legality", "")
        legal_factor = 0.9 if "restricted" in legality else 1.0
        return max(0.62, min(1.65, economy_factor * home_bonus * roster_factor * legal_factor * love_factor * benefit.get("gate", 1.0)))

    def regional_feasibility_snapshot(self, region, month=None, week=None):
        """Build a read-only regional/division feasibility brief.

        The brief deliberately uses current player-roster, free-agent and
        scheduled-event facts only.  It is not a booking quote, invitation or
        forecast ledger: opening the Regions page cannot reserve fighters,
        generate prices, reveal hidden AI plans or change any calendar state.
        """
        region = str(region or getattr(self, "player_region", "USA") or "USA")
        data = (getattr(self, "regions", {}) or {}).get(region, {}) or {}
        target_month = int(month if month is not None else getattr(self, "month", 1) or 1)
        target_week = max(1, min(4, int(week if week is not None else getattr(self, "week", 1) or 1)))
        roster = [fighter for fighter in (getattr(self, "roster", []) or [])
                  if not getattr(fighter, "retired", False)]
        local_roster = [fighter for fighter in roster if str(getattr(fighter, "region", "") or "") == region]

        def status(fighter):
            checker = getattr(self, "fighter_booking_status", None)
            if callable(checker):
                try:
                    return str(checker(fighter, target_month, target_week) or "Unknown")
                except (AttributeError, TypeError, ValueError):
                    pass
            if getattr(fighter, "injured", False):
                return "Injured"
            return "Ready" if int(getattr(fighter, "fatigue", 0) or 0) < 65 else "Fatigued"

        ready = [fighter for fighter in roster if status(fighter) == "Ready"]

        # The readiness label is intentionally broader than a committed-bout
        # quote.  Where the live app exposes the booking workbench's pure hard
        # blocker adapter, reuse it here so a fighter with a future booking,
        # closed division or other ordinary booking conflict is not counted as
        # a "bookable" regional pairing.  Small read-model harnesses and older
        # saves may not expose that adapter; their date/injury/fatigue checks
        # above remain the safe fallback rather than inventing a new rule.
        bookable_ready = []
        booking_blocked = 0
        hard_reasons = getattr(self, "_booking_hard_reasons", None)
        for fighter in ready:
            blocked = []
            if callable(hard_reasons):
                try:
                    blocked = list(hard_reasons(fighter, target_month, target_week, anchor=None) or [])
                except (AttributeError, TypeError, ValueError):
                    blocked = []
            if blocked:
                booking_blocked += 1
            else:
                bookable_ready.append(fighter)
        if not callable(hard_reasons):
            bookable_ready = list(ready)
        groups = {}
        for fighter in bookable_ready:
            groups.setdefault((str(getattr(fighter, "gender", "") or ""), str(getattr(fighter, "weight", "") or "")), []).append(fighter)
        pairings = sum(len(members) * (len(members) - 1) // 2 for members in groups.values())
        local_ready = [fighter for fighter in bookable_ready if fighter in local_roster]
        local_ready_count = len(local_ready)
        challenger_depth = sum(
            1 for fighter in bookable_ready
            if bool(getattr(fighter, "champion", False))
            or (int(getattr(fighter, "ranking_position", 0) or 0) > 0 and int(getattr(fighter, "ranking_position", 0) or 0) <= 10)
        )

        free_agents = [fighter for fighter in (getattr(self, "free_agents", []) or [])
                       if not getattr(fighter, "retired", False)
                       and not getattr(fighter, "retirement_pending", False)
                       and not getattr(fighter, "injured", False)
                       and not getattr(fighter, "ai_offer_company", "")
                       and str(getattr(fighter, "primary_discipline", "MMA") or "MMA") == "MMA"
                       and str(getattr(fighter, "region", "") or "") == region]
        available_for_date = getattr(self, "fighter_available_for_date", None)
        if callable(available_for_date):
            available_free_agents = []
            for fighter in free_agents:
                try:
                    available = bool(available_for_date(fighter, target_month, target_week))
                except (AttributeError, TypeError, ValueError):
                    available = True
                if available:
                    available_free_agents.append(fighter)
            free_agents = available_free_agents
        visible = getattr(self, "fighter_profile_stats_visible", None)
        known_recruitment = 0
        unknown_recruitment = 0
        for fighter in free_agents:
            try:
                known = bool(visible(fighter, getattr(self, "player_company_name", ""))) if callable(visible) else True
            except (AttributeError, TypeError, ValueError):
                known = True
            if known:
                known_recruitment += 1
            else:
                unknown_recruitment += 1

        events = []
        for event in getattr(self, "scheduled_events", []) or []:
            if not isinstance(event, dict):
                continue
            event_region = str(event.get("region", "") or "")
            if not event_region and callable(getattr(self, "venue_region", None)):
                event_region = str(self.venue_region(event.get("venue", "")) or "")
            if event_region == region:
                events.append({
                    "event_id": str(event.get("event_id", "") or ""),
                    "name": str(event.get("name", "Event") or "Event"),
                    "month": int(event.get("month", 0) or 0),
                    "week": int(event.get("week", 0) or 0),
                })
        venues = []
        for venue in (self.available_event_venues() if callable(getattr(self, "available_event_venues", None)) else []):
            venue_region = str(self.venue_region(venue) or "") if callable(getattr(self, "venue_region", None)) else ""
            if venue_region == region:
                venues.append(str(venue))
        payroll = sum(max(0, int(getattr(fighter, "purse", 0) or 0)) for fighter in local_roster)
        blockers = []
        if not venues:
            blockers.append("No currently unlocked venue is mapped to this region.")
        if pairings <= 0:
            blockers.append("No same-division player-roster pairing is currently bookable.")
        if challenger_depth <= 0:
            blockers.append("No ready top-10/champion fighter is available for a title path; merit is not waived.")
        if not free_agents:
            blockers.append("No regional free-agent fighters are currently visible.")
        elif unknown_recruitment:
            blockers.append(f"{unknown_recruitment} regional market option(s) remain unscouted; prices and ability are unknown.")
        return {
            "region": region,
            "as_of": {"month": target_month, "week": target_week},
            "market": {
                "economy": data.get("economy", "Unknown"),
                "legality": data.get("legality", "Unknown"),
                "mma_love": int(data.get("mma_love", 50) or 0),
                "drug_accuracy": int(data.get("drug_accuracy", 0) or 0),
                "regional_pull": round(float(self.regional_market_score(region)) if callable(getattr(self, "regional_market_score", None)) else 1.0, 3),
            },
            "roster": {
                "active": len(roster), "local": len(local_roster),
                "ready": len(ready), "bookable_ready": len(bookable_ready),
                "booking_blocked": booking_blocked, "local_ready": local_ready_count,
                "bookable_pairings": pairings, "eligible_challenger_depth": challenger_depth,
                "per_bout_local_purse_exposure": payroll,
            },
            "recruitment": {
                "regional_free_agents": len(free_agents),
                "known_or_scouted": known_recruitment,
                "unscouted_or_unknown": unknown_recruitment,
            },
            "venues": {"available": venues, "count": len(venues)},
            "scheduled_events": events,
            "blockers": blockers,
            "assumptions": [
                "Pairings use the current player roster and selected as-of week; this is not a booking quote.",
                "Regional free-agent counts distinguish visible/scouted options from unknown ability or price.",
                "AI future schedules and hidden rankings are not treated as confirmed conflicts.",
            ],
        }

    # ------------------------------------------------------------------
    # J9.b — deterministic regional-host invitations
    # ------------------------------------------------------------------
    def _regional_invitation_week_parts(self, absolute_week):
        """Return the save-stable ``(month, week)`` for a running week index."""
        try:
            absolute_week = max(1, int(absolute_week or 1))
        except (TypeError, ValueError):
            absolute_week = 1
        return (absolute_week - 1) // 4 + 1, (absolute_week - 1) % 4 + 1

    def regional_invitation_fixed_quote(self, region, venue):
        """Quote the fixed staging/venue basis without changing game state.

        This intentionally does not call ``ensure_finance_defaults`` or any
        offer generator.  A malformed/absent production basis is not a price
        of zero; it means the invitation is unavailable until the ordinary
        finance owner can provide a reliable quote.
        """
        region = str(region or "")
        venue = str(venue or "")
        data = (getattr(self, "regions", {}) or {}).get(region)
        finance = getattr(self, "finance", {})
        if not isinstance(data, dict) or not isinstance(finance, dict):
            return None
        try:
            production_base = int(finance.get("production_base"))
            popularity = int(getattr(self, "company_pop", 0) or 0)
            capacity = int(self.venue_capacity_for(venue))
        except (AttributeError, TypeError, ValueError):
            return None
        if production_base <= 0 or capacity <= 0:
            return None
        try:
            tier_name, tier = self.resolve_event_production_tier({})
            tier_cost = float((tier or {}).get("cost", 1.0) or 1.0)
        except (AttributeError, TypeError, ValueError):
            tier_name, tier_cost = DEFAULT_EVENT_PRODUCTION_TIER, 1.0
        if tier_cost <= 0:
            return None
        venue_ops = round(capacity * (5 + popularity / 16))
        fixed_component = round((production_base + venue_ops) * tier_cost)
        if fixed_component <= 0:
            return None
        return {
            "region": region, "venue": venue, "production_tier": tier_name,
            "fixed_component": fixed_component,
            "basis": f"${production_base:,} production base + ${venue_ops:,} venue operations",
        }

    def regional_invitation_candidates(self):
        """Return feasible region/venue pairs in deterministic priority order."""
        candidates = []
        regions = getattr(self, "regions", {}) or {}
        for region in sorted(str(key) for key in regions if key):
            try:
                snapshot = self.regional_feasibility_snapshot(region)
            except (AttributeError, TypeError, ValueError):
                continue
            roster = snapshot.get("roster", {}) if isinstance(snapshot, dict) else {}
            local_ready = int(roster.get("local_ready", 0) or 0) if isinstance(roster, dict) else 0
            venues = snapshot.get("venues", {}) if isinstance(snapshot, dict) else {}
            venue_names = sorted(str(value) for value in (venues.get("available", []) if isinstance(venues, dict) else []) if value)
            if local_ready < 2 or not venue_names:
                continue
            for venue in venue_names:
                quote = self.regional_invitation_fixed_quote(region, venue)
                if not quote:
                    continue
                candidates.append({
                    "region": region, "venue": venue, "quote": quote,
                    "local_ready": local_ready,
                    "challenger_depth": int(roster.get("eligible_challenger_depth", 0) or 0),
                    "regional_pull": float((snapshot.get("market", {}) or {}).get("regional_pull", 1.0) or 1.0),
                })
        candidates.sort(key=lambda row: (
            -int(row.get("local_ready", 0) or 0),
            -int(row.get("challenger_depth", 0) or 0),
            -float(row.get("regional_pull", 1.0) or 1.0),
            str(row.get("region", "")), str(row.get("venue", "")),
        ))
        return candidates

    def regional_invitation_open(self):
        """Return the current non-terminal invitation, if one exists."""
        rows = getattr(self, "regional_invitations", []) or []
        if not isinstance(rows, list):
            return None
        for row in rows:
            if isinstance(row, dict) and str(row.get("status", "")) in {"Offered", "Accepted", "Scheduled"}:
                return row
        return None

    def _regional_invitation_next_id(self):
        used = {
            str(row.get("invitation_id", "")) for row in list(getattr(self, "regional_invitations", []) or [])
            + list(getattr(self, "regional_invitation_history", []) or []) if isinstance(row, dict)
        }
        base = f"RI-{self.calendar_week_index()}"
        candidate = base
        suffix = 2
        while candidate in used:
            candidate = f"{base}-{suffix}"
            suffix += 1
        return candidate

    def generate_regional_invitation(self, force=False):
        """Create at most one deterministic regional invitation per quarter."""
        if getattr(self, "spectator_mode", False):
            return None
        if self.regional_invitation_open():
            return None
        try:
            current_week = int(self.calendar_week_index())
        except (AttributeError, TypeError, ValueError):
            return None
        quarter = (max(1, current_week) - 1) // 12
        if not force:
            previous = list(getattr(self, "regional_invitations", []) or []) + list(getattr(self, "regional_invitation_history", []) or [])
            def issued_quarter(row):
                if not isinstance(row, dict):
                    return None
                try:
                    return int(row.get("issued_quarter", -1) or -1)
                except (TypeError, ValueError):
                    return None
            if any(issued_quarter(row) == quarter for row in previous):
                return None
        candidates = self.regional_invitation_candidates()
        if not candidates:
            return None
        selected = candidates[0]
        quote = dict(selected["quote"])
        event_month, event_week = self._regional_invitation_week_parts(current_week + 8)
        invitation_id = self._regional_invitation_next_id()
        guarantee = min(25_000, round(int(quote["fixed_component"]) * 0.10))
        if guarantee <= 0:
            return None
        data = (getattr(self, "regions", {}) or {}).get(selected["region"], {}) or {}
        areas = list(data.get("areas", []) or []) if isinstance(data, dict) else []
        offer = {
            "schema_version": 1, "invitation_id": invitation_id,
            "entitlement_key": f"regional-host:{invitation_id}:guarantee",
            "status": "Offered", "region": selected["region"], "venue": selected["venue"],
            "city": str(areas[0]) if areas else selected["region"],
            "issued_week": current_week, "issued_quarter": quarter,
            "expires_week": current_week + 4,
            "event_month": event_month, "event_week": event_week,
            "event_window": {"min_weeks": 8, "max_weeks": 16},
            "fixed_component_quote": int(quote["fixed_component"]),
            "quote_basis": quote.get("basis", "Recorded fixed staging/venue component"),
            "production_tier": quote.get("production_tier", DEFAULT_EVENT_PRODUCTION_TIER),
            "guarantee": guarantee, "local_ready_count": int(selected.get("local_ready", 0) or 0),
            "minimum_local_completers": 2,
            "issued_month": int(getattr(self, "month", 1) or 1),
            "issued_week_of_month": int(getattr(self, "week", 1) or 1),
        }
        self.regional_invitations = [offer] + [
            row for row in list(getattr(self, "regional_invitations", []) or [])
            if isinstance(row, dict) and str(row.get("status", "")) in {"Offered", "Accepted", "Scheduled"}
        ]
        formatter = getattr(self, "format_game_date", None)
        date_label = formatter(event_month, event_week) if callable(formatter) else f"Month {event_month} Week {event_week}"
        news = getattr(self, "news", None)
        if isinstance(news, list):
            news.insert(0, f"Regional host invitation: {offer['region']} offers {offer['venue']} for {date_label}. Host guarantee ${guarantee:,} if two local roster fighters complete bouts.")
        inbox = getattr(self, "inbox", None)
        if isinstance(inbox, list):
            inbox.append({
                "subject": f"Regional host invitation — {offer['region']}",
                "body": f"Book a card at {offer['venue']} in {offer['region']} for {date_label}. The ${guarantee:,} host guarantee is paid only after two local roster fighters complete bouts.",
                "type": "Business", "resolved": False, "regional_invitation_id": invitation_id,
            })
        return offer

    def expire_regional_invitations(self):
        """Expire only unaccepted offers; accepted plans remain player-owned."""
        try:
            current_week = int(self.calendar_week_index())
        except (AttributeError, TypeError, ValueError):
            current_week = 1
        active, terminal = [], []
        for row in list(getattr(self, "regional_invitations", []) or []):
            if not isinstance(row, dict):
                continue
            status = str(row.get("status", ""))
            expiry_raw = row.get("expires_week", current_week)
            try:
                expiry_week = int(expiry_raw if expiry_raw is not None else current_week)
            except (TypeError, ValueError):
                if status in {"Offered", "Accepted", "Scheduled"}:
                    row.setdefault("invitation_review_required", True)
                    row.setdefault("invitation_review_reason", "Invitation expiry week is malformed; expiry was held.")
                    active.append(row)
                else:
                    terminal.append(row)
                continue
            if status == "Offered" and current_week > expiry_week:
                closed = dict(row, status="Expired", outcome="No invitation accepted", resolved_week=current_week)
                terminal.append(closed)
                news = getattr(self, "news", None)
                if isinstance(news, list):
                    news.insert(0, f"Regional host invitation expired: {row.get('region', 'Region')} — no penalty applied.")
            elif status in {"Offered", "Accepted", "Scheduled"}:
                active.append(row)
            else:
                terminal.append(row)
        self.regional_invitations = active
        if terminal:
            self.regional_invitation_history = (terminal + list(getattr(self, "regional_invitation_history", []) or []))[:120]
        return terminal

    def accept_regional_invitation(self, invitation_id):
        """Accept one offer for later booking through the ordinary editor."""
        self.expire_regional_invitations()
        key = str(invitation_id or "")
        offer = next((row for row in getattr(self, "regional_invitations", []) or [] if isinstance(row, dict) and str(row.get("invitation_id", "")) == key), None)
        if not offer or offer.get("status") != "Offered":
            return False, "That regional invitation is no longer open."
        offer.update({"status": "Accepted", "accepted_week": int(self.calendar_week_index()), "outcome": "Accepted for planning"})
        news = getattr(self, "news", None)
        if isinstance(news, list):
            news.insert(0, f"Regional host invitation accepted for {offer.get('region', 'the selected region')}. Book the proposed venue/date through Matchmaking.")
        return True, "Accepted. Book the proposed venue and date through Matchmaking; no deposit is charged."

    def decline_regional_invitation(self, invitation_id, reason="Player declined"):
        key = str(invitation_id or "")
        offer = next((row for row in getattr(self, "regional_invitations", []) or [] if isinstance(row, dict) and str(row.get("invitation_id", "")) == key), None)
        if not offer or offer.get("status") not in {"Offered", "Accepted"}:
            return False, "That regional invitation is no longer open."
        closed = dict(offer, status="Declined", outcome=str(reason or "Player declined"), resolved_week=int(self.calendar_week_index()))
        self.regional_invitations = [row for row in getattr(self, "regional_invitations", []) or [] if row is not offer]
        self.regional_invitation_history = [closed] + list(getattr(self, "regional_invitation_history", []) or [])
        news = getattr(self, "news", None)
        if isinstance(news, list):
            news.insert(0, f"Regional host invitation declined for {offer.get('region', 'the selected region')}; no penalty applied.")
        return True, "Invitation declined; no penalty or fee was applied."

    def bind_regional_invitation_to_event(self, event):
        """Attach an accepted invitation when the player books its exact date."""
        if not isinstance(event, dict):
            return None
        requested = str(event.get("regional_invitation_id", "") or "")
        rows = [row for row in getattr(self, "regional_invitations", []) or [] if isinstance(row, dict) and row.get("status") == "Accepted"]
        if requested:
            rows = [row for row in rows if str(row.get("invitation_id", "")) == requested]
        rows = [row for row in rows if str(row.get("region", "")) == str(event.get("region", "") or "")
                and str(row.get("venue", "")) == str(event.get("venue", "") or "")
                and self._regional_invitation_date_matches(row, event)]
        if not rows:
            return None
        offer = sorted(rows, key=lambda row: str(row.get("invitation_id", "")))[0]
        try:
            guarantee = int(offer.get("guarantee", 0) or 0)
            minimum_local_completers = int(offer.get("minimum_local_completers", 2) or 2)
        except (TypeError, ValueError):
            offer.setdefault("invitation_review_required", True)
            offer.setdefault("invitation_review_reason", "Invitation guarantee or completion threshold is malformed; binding was held.")
            return None
        event["regional_invitation_id"] = str(offer.get("invitation_id", ""))
        event["regional_invitation_entitlement_key"] = str(offer.get("entitlement_key", ""))
        event["regional_invitation"] = {
            "invitation_id": offer.get("invitation_id", ""), "region": offer.get("region", ""),
            "venue": offer.get("venue", ""), "guarantee": guarantee,
            "minimum_local_completers": minimum_local_completers,
        }
        offer.update({"status": "Scheduled", "scheduled_event_id": str(event.get("event_id", "") or "")})
        return offer

    @staticmethod
    def _regional_invitation_date_matches(row, event):
        """Compare invitation/event dates without coercing unknown evidence."""
        if not isinstance(row, dict) or not isinstance(event, dict):
            return False
        try:
            invitation_month = int(row.get("event_month", -1) or -1)
            invitation_week = int(row.get("event_week", -1) or -1)
            event_month = int(event.get("month", -2) or -2)
            event_week = int(event.get("week", -2) or -2)
        except (TypeError, ValueError):
            return False
        return invitation_month == event_month and invitation_week == event_week

    def cancel_regional_invitation_for_event(self, event, reason="Linked event cancelled"):
        """Close a linked invitation without charging or paying its guarantee."""
        key = ""
        if isinstance(event, dict):
            key = str(event.get("regional_invitation_id", "") or "")
        if not key:
            return None
        offer = next((row for row in getattr(self, "regional_invitations", []) or [] if isinstance(row, dict) and str(row.get("invitation_id", "")) == key), None)
        if not offer or offer.get("status") not in {"Accepted", "Scheduled"}:
            return None
        closed = dict(offer, status="Cancelled", outcome="Unfulfilled", outcome_reason=str(reason), resolved_week=int(self.calendar_week_index()), guarantee_paid=0)
        self.regional_invitations = [row for row in getattr(self, "regional_invitations", []) or [] if row is not offer]
        self.regional_invitation_history = [closed] + list(getattr(self, "regional_invitation_history", []) or [])
        return closed

    def settle_regional_invitation(self, event, package):
        """Pay one host guarantee after the linked event proves local delivery."""
        key = str((event or {}).get("regional_invitation_id", "") or "") if isinstance(event, dict) else ""
        if not key and isinstance(package, dict):
            key = str(package.get("regional_invitation_id", "") or "")
        if not key or not isinstance(package, dict):
            return None
        offer = next((row for row in getattr(self, "regional_invitations", []) or [] if isinstance(row, dict) and str(row.get("invitation_id", "")) == key), None)
        if not offer or offer.get("status") != "Scheduled":
            return None
        region = str(offer.get("region", "") or "")
        local_ids = set()
        results = package.get("results", [])
        if not isinstance(results, (list, tuple)):
            offer.setdefault("invitation_review_required", True)
            offer.setdefault("invitation_review_reason", "Settlement results are malformed; no guarantee was paid.")
            return None
        for result in results:
            if not isinstance(result, (list, tuple)) or len(result) < 2:
                continue
            winner, loser = result[0], result[1]
            for fighter in (winner, loser):
                if str(getattr(fighter, "region", "") or "") != region:
                    continue
                fighter_id = str(getattr(fighter, "fighter_id", "") or "")
                local_ids.add(fighter_id or str(getattr(fighter, "name", "") or ""))
        try:
            required = max(2, int(offer.get("minimum_local_completers", 2) or 2))
            guarantee = int(offer.get("guarantee", 0) or 0)
        except (TypeError, ValueError):
            offer.setdefault("invitation_review_required", True)
            offer.setdefault("invitation_review_reason", "Invitation guarantee or completion threshold is malformed; no payment was made.")
            return None
        paid = len({key for key in local_ids if key}) >= required
        amount = guarantee if paid else 0
        if amount:
            try:
                cash = int(self.cash)
            except (AttributeError, TypeError, ValueError):
                offer.setdefault("invitation_review_required", True)
                offer.setdefault("invitation_review_reason", "Saved cash balance is malformed; no guarantee was paid.")
                return None
            self.cash = cash + amount
            finance = package.get("finance") if isinstance(package.get("finance"), dict) else {}
            def safe_int(value, fallback=0):
                if isinstance(value, bool) or value is None or value == "":
                    return fallback
                try:
                    return int(value)
                except (TypeError, ValueError):
                    return fallback
            finance["regional_host_guarantee"] = amount
            finance["total_revenue"] = safe_int(finance.get("total_revenue", 0), 0) + amount
            finance["profit"] = safe_int(finance.get("profit", package.get("profit", 0)), 0) + amount
            package["finance"] = finance
            package["profit"] = safe_int(package.get("profit", 0), 0) + amount
            self.record_finance_transaction(
                f"Regional host guarantee: {region}", revenue=amount,
                category="Regional host", source="Regional invitation entitlement",
                event=package.get("event_name", ""), reference=str(offer.get("entitlement_key", key)),
            )
        outcome = "Paid" if paid else "Unfulfilled"
        closed = dict(offer, status=outcome, outcome=outcome, resolved_week=int(self.calendar_week_index()), guarantee_paid=amount, local_completers=sorted(local_ids))
        self.regional_invitations = [row for row in getattr(self, "regional_invitations", []) or [] if row is not offer]
        self.regional_invitation_history = [closed] + list(getattr(self, "regional_invitation_history", []) or [])
        package["regional_host_guarantee"] = amount
        package["regional_invitation_outcome"] = outcome
        return closed

    def event_atmosphere(self, event, results=None, excitement_score=50):
        """Describe the crowd and return small, explainable event modifiers."""
        region = event.get("region", self.player_region)
        data = self.regions.get(region, {})
        fanbase = getattr(self, "fanbase", {}) or {}
        # Saved event cards carry display names for legacy presentation, but
        # names are not unique identities.  Resolve through the aligned
        # fighter-id references and fail closed for an ambiguous/missing
        # legacy corner rather than charging the wrong career to the crowd
        # metrics.
        fighters = []
        for fight in event.get("fights", []):
            references = (self.event_fight_participant_references(fight)
                          if hasattr(self, "event_fight_participant_references")
                          else fight.get("fighters", []))
            resolver = getattr(self, "_resolve_event_fighter", None)
            for reference in references:
                if reference == "TBA":
                    continue
                fighter = resolver(reference) if callable(resolver) else None
                if fighter is not None:
                    fighters.append(fighter)
        connections = [self.fighter_event_connection(fighter, region, event.get("city", "")) for fighter in fighters if fighter]
        local_fighters = sum(1 for connection in connections if connection["strength"] >= 0.52)
        hometown_fighters = sum(1 for connection in connections if connection["level"] == "Hometown")
        home_pull = sum(connection["strength"] * (0.42 + connection["market_popularity"] / 145) for connection in connections)
        finishes = sum(1 for _winner, _loser, _fight, method in (results or []) if method not in ("Decision", "Technical Decision", "Draw", "No Contest"))
        preference = data.get("crowd_preference", "Competitive fights")
        love = data.get("mma_love", 50)
        core = fanbase.get("core_support", 42)
        casual = fanbase.get("casual_reach", 30)
        local_lift = min(0.18, home_pull * 0.030)
        finish_lift = min(0.09, finishes * 0.018) if any(word in preference.lower() for word in ("action", "finish", "aggressive")) else min(0.04, finishes * 0.008)
        technical_lift = min(0.06, max(0, excitement_score - 47) / 400) if any(word in preference.lower() for word in ("technical", "skill", "respect")) else 0
        home_lift = (core - 42) / 700 if region == fanbase.get("home_region", self.player_region) else 0
        intensity = max(15, min(100, round(love * 0.58 + core * 0.2 + casual * 0.12 + home_pull * 7 + hometown_fighters * 4 + excitement_score * 0.12)))
        mood = "Electric" if intensity >= 78 else "Loud" if intensity >= 62 else "Engaged" if intensity >= 46 else "Reserved"
        attendance_factor = max(0.84, min(1.18, 0.93 + intensity / 1200 + local_lift + technical_lift))
        merch_factor = max(0.84, min(1.22, 0.9 + intensity / 900 + local_lift + finish_lift))
        sponsor_factor = max(0.9, min(1.13, 0.94 + casual / 1000 + intensity / 1800))
        return {"mood": mood, "intensity": intensity, "identity": data.get("fan_identity", "Local MMA community"), "preference": preference,
                "attendance_factor": attendance_factor, "merch_factor": merch_factor, "sponsor_factor": sponsor_factor,
                "local_fighters": local_fighters, "hometown_fighters": hometown_fighters, "home_pull": round(home_pull, 2),
                "description": f"{mood} {data.get('fan_identity', 'local MMA')} crowd; they respond to {preference.lower()}."}

    def update_player_fanbase(self, package):
        """Carry each player event forward as a fanbase story, not an isolated gate number."""
        fanbase = getattr(self, "fanbase", {}) or {}
        finance = package.get("finance", {}) or {}
        atmosphere = finance.get("atmosphere", {}) or {}
        attendance_ratio = finance.get("attendance", 0) / max(1, finance.get("venue_capacity", 1))
        excitement = package.get("average_excitement", 50)
        # Top and bottom fifth of real card averages, rather than a 62 that a
        # card average could not reach.
        core_delta = (2 if excitement >= 50 else -1 if excitement < 43 else 0) + (1 if attendance_ratio >= 0.9 else 0)
        casual_delta = (2 if attendance_ratio >= 0.9 else 0) + (1 if package.get("profit", 0) > 0 else -1)
        fanbase["core_support"] = max(5, min(100, fanbase.get("core_support", 42) + core_delta))
        fanbase["casual_reach"] = max(5, min(100, fanbase.get("casual_reach", 30) + casual_delta))
        fanbase["event_history"] = ([{"month": self.month, "event": package.get("event_name", "Event"), "mood": atmosphere.get("mood", "Engaged"), "intensity": atmosphere.get("intensity", 50), "attendance": finance.get("attendance", 0)}] + fanbase.get("event_history", []))[:30]
        self.fanbase = fanbase

    def calculate_event_finance(self, total_hype, fighter_pay, event, results, excitement_score=50, build_score=50, regional_pull=1.0, contracted_fighter_pay=None):
        # Signed purses are obligations, not a difficulty-scaled suggestion.
        # Promotion stature affects revenue and affordability, never whether a
        # fighter silently receives only a fraction of the negotiated purse.
        contracted_fighter_pay = fighter_pay if contracted_fighter_pay is None else contracted_fighter_pay
        contracted_fighter_pay = max(0, round(contracted_fighter_pay))
        fighter_pay = max(contracted_fighter_pay, max(0, round(fighter_pay)))
        tier_purse_savings = 0
        venue_capacity = self.venue_capacity_for(event["venue"])
        super_event = event.get("super_event", {}) or {}
        novelty = float(super_event.get("novelty", 1.0) or 1.0)
        spectacle_multiplier = float(super_event.get("revenue_multiplier", 1.0) or 1.0) * novelty
        economics = self.event_economics(event)
        tier = economics["tier"]
        build_score = max(1, min(99, build_score + tier["build"]))
        media_heat = max(0.58, min(1.28, 0.64 + build_score / 165 + excitement_score / 260))
        prior_month_events = self.player_events_in_month(event.get("month", self.month), event)
        cadence_factor = max(0.45, 1.0 / (1.0 + prior_month_events * PLAYER_EVENT_CADENCE_DECAY))
        attendance_demand = total_hype * (24 + self.company_pop * 0.82 + self.company_stability * 0.22) / 14
        atmosphere = self.event_atmosphere(event, results, excitement_score)
        # Price and marketing decide turnout. Without this the ticket price was
        # free money: raising it lifted the gate and cost nothing.
        fair_price = self.event_fair_ticket_price(total_hype, regional_pull, event.get("venue"))
        demand_factor = self.ticket_price_demand_factor(economics["ticket_price"], fair_price)
        marketing_factor = self.marketing_demand_factor(economics["marketing_budget"])
        attendance_factor = max(0.0, atmosphere["attendance_factor"] + tier["atmosphere"])
        attendance_investment = self.strategic_event_multiplier("attendance", event)
        attendance = min(venue_capacity, max(0, round(
            attendance_demand * regional_pull * media_heat * attendance_factor * cadence_factor
            * demand_factor * marketing_factor
            * attendance_investment
            * (1 + max(0, spectacle_multiplier - 1) * 0.16)
        )))
        sellout_pressure = attendance / max(1, venue_capacity)
        grudge_gate_bonus = self.event_grudge_gate_bonus(event, results)
        ticket_price = economics["ticket_price"]
        ticket_revenue = round(attendance * ticket_price * self.business_settings.get("gate_multiplier", 1.0) * spectacle_multiplier * (1 + grudge_gate_bonus))
        selected_name = event.get("broadcaster", "No Coverage")
        best_broadcaster = next((b for b in self.broadcasters if b["name"] == selected_name), None)
        if best_broadcaster is None:
            best_broadcaster = {"name": "No Coverage", "reach": 0, "fee": 0, "type": "None"}
        self.ensure_finance_defaults()
        rights = self.finance["media_rights"]
        sponsor_deals = self.finance["sponsor_deals"]
        commentators = self.finance.get("commentators", [])
        commentary_quality = round(sum(c["quality"] + c["chemistry"] for c in commentators) / max(1, len(commentators)) / 2)
        broadcast_staff_lift = self.staff_effect("Broadcast Producer", 1.55)
        commentary_quality = max(0, min(100, round(commentary_quality + broadcast_staff_lift)))
        championship_value = 0
        for _winner, _loser, fight, _method in results:
            if fight.get("title"):
                championship_value += 18
            references = (self.event_fight_participant_references(fight)
                          if hasattr(self, "event_fight_participant_references")
                          else fight.get("fighters", []))
            resolver = getattr(self, "_resolve_event_fighter", None)
            for reference in references:
                fighter = resolver(reference) if callable(resolver) and reference != "TBA" else None
                if fighter is not None and fighter.champion:
                    championship_value += 6 + fighter.star_quality // 12
        contracted_events = rights.get("events_remaining", 0)
        rights_eligible = bool(contracted_events > 0 and selected_name != "No Coverage")
        if hasattr(self, "media_contract_eligibility") and rights_eligible:
            rights_eligible = self.media_contract_eligibility(rights, event)[0]
        rights_reach = rights.get("reach", 0) if rights_eligible else 0
        media_reach = best_broadcaster["reach"] + rights_reach + championship_value // 2 + commentary_quality // 8 + round(max(0, broadcast_staff_lift) * 0.55)
        if not best_broadcaster["reach"] and not rights_reach:
            media_reach = max(2, championship_value // 4)
        broadcast_income = round(total_hype * media_reach * self.finance["broadcast_cut"] * (38 + build_score * 0.68 + championship_value * 0.7) * media_heat * (1 + commentary_quality / 650) * spectacle_multiplier * tier["broadcast"] * cadence_factor * self.strategic_event_multiplier("broadcast", event))
        sponsor_portfolio_value = sum(self.sponsor_event_fee(deal) for deal in sponsor_deals)
        sponsorship = round((self.finance["sponsor_income"] + sponsor_portfolio_value + round(self.company_pop * total_hype * (6 + regional_pull * 3 + build_score / 16))) * atmosphere["sponsor_factor"] * cadence_factor * self.strategic_event_multiplier("sponsorship", event))
        broadcast_income += round(rights.get("fee", rights.get("guarantee_per_event", 0)) * cadence_factor * self.strategic_event_multiplier("broadcast", event)) if rights_eligible else 0
        merchandise = round(ticket_revenue * self.finance["merch_rate"] * (1 + self.company_pop / 130) * (0.85 + excitement_score / 110) * atmosphere["merch_factor"] * self.strategic_event_multiplier("merchandise", event))
        commentator_pay = sum(c["salary"] for c in commentators)
        venue_ops = round(venue_capacity * (5 + self.company_pop / 16))
        bout_count = max(len(event["fights"]), len(results))
        setup_cost = int(super_event.get("remaining_setup_cost", 0) or 0)
        security_cost = int(super_event.get("security_cost", 0) or 0)
        staged_production = round((self.finance["production_base"] + bout_count * 5200 + venue_ops) * tier["cost"])
        production_staging_saving = 0
        reduction_fn = getattr(self, "staff_specialty_cost_reduction", None)
        if callable(reduction_fn):
            production_staging_saving = reduction_fn(
                "Broadcast Producer", staged_production, cost_type="production_staging",
            )
            staged_production = max(0, staged_production - production_staging_saving)
        production = staged_production + best_broadcaster["fee"] + commentator_pay + setup_cost + security_cost
        production = max(round(self.finance["production_base"] * tier["cost"]), production - round(max(0, broadcast_staff_lift) * 700))
        medical = max(self.finance["medical_base"], round((self.finance["medical_base"] + bout_count * 1900 - round(max(0, self.staff_effect("Doctor", 1.1)) * 260)) * self.strategic_event_multiplier("medical", event)))
        marketing = economics["marketing_budget"] + round(max(0, build_score - 48) * 1100)
        drug_testing = 0 if self.rules["drug_testing"] == "None" else round(bout_count * 2 * self.finance["drug_test_cost"] * (1 - max(0, self.staff_effect("Drug Testing Officer", 0.7)) / 180))
        bonuses = self.post_show_bonuses["fight"]
        for _winner, _loser, _fight, method in results:
            if "KO" in method or "TKO" in method:
                bonuses += self.post_show_bonuses["ko"]
            if "Submission" in method:
                bonuses += self.post_show_bonuses["sub"]
        total_revenue = ticket_revenue + broadcast_income + sponsorship + merchandise
        pre_tax_expense = fighter_pay + production + medical + marketing + drug_testing + bonuses
        tax = round(max(0, total_revenue - pre_tax_expense) * self.finance["tax_rate"])
        total_expense = pre_tax_expense + tax
        return {
            "attendance": attendance,
            "atmosphere": atmosphere,
            "venue_capacity": venue_capacity,
            "ticket_price": ticket_price,
            "cadence_factor": round(cadence_factor, 4),
            "prior_month_events": prior_month_events,
            "media_reach": media_reach,
            "championship_media_value": championship_value,
            "commentary_quality": commentary_quality,
            "regional_pull": regional_pull,
            "excitement_score": round(excitement_score),
            "build_score": round(build_score),
            "ticket_revenue": ticket_revenue,
            "broadcast_income": broadcast_income,
            "sponsorship": sponsorship,
            "merchandise": merchandise,
            "total_revenue": total_revenue,
            "fighter_pay": fighter_pay,
            "contracted_fighter_pay": contracted_fighter_pay,
            "tier_purse_savings": tier_purse_savings,
            "bonuses": bonuses,
            "production": production,
            "production_staging": staged_production,
            "production_staging_saving": production_staging_saving,
            "super_event_setup": setup_cost + security_cost,
            "super_event_novelty": novelty,
            "medical": medical,
            "marketing": marketing,
            "drug_testing": drug_testing,
            "tax": tax,
            "total_expense": total_expense,
            "profit": total_revenue - total_expense,
        }

    def player_events_in_month(self, month, event=None):
        """Count settled and earlier-scheduled player cards in a month.

        Including earlier bookings keeps the Matchmaking forecast honest before
        either card has run. Completed events leave the schedule, so the two
        sources do not double count.
        """
        marker = f"Month {int(month)} "
        settled = sum(
            1 for record in getattr(self, "result_records", [])
            if record.get("company") == self.player_company_name
            and marker in str(record.get("date", ""))
        )
        if not isinstance(event, dict):
            return settled
        target = (
            int(event.get("week", 1) or 1), self.event_day(event),
            str(event.get("name", "")),
        )
        earlier = sum(
            1 for scheduled in getattr(self, "scheduled_events", [])
            if scheduled is not event and int(scheduled.get("month", 0) or 0) == int(month)
            and (
                int(scheduled.get("week", 1) or 1), self.event_day(scheduled),
                str(scheduled.get("name", "")),
            ) < target
        )
        return settled + earlier

    def player_monthly_office_cost(self):
        """Scale infrastructure cost as a regional company becomes global."""
        # Forecast/read-model callers may inspect a legacy or malformed
        # finance envelope.  Treat that input as unavailable rather than
        # repairing it (or crashing the Finance page) during a projection.
        finance = getattr(self, "finance", {})
        if not isinstance(finance, dict):
            finance = {}
        try:
            base = max(0, int(finance.get("monthly_office", 12_000) or 0))
        except (TypeError, ValueError, OverflowError):
            base = 12_000
        scale = max(0, int(getattr(self, "company_pop", 0) or 0) - 40)
        growth = round((scale * 1_200 + scale * scale * 35) / 500) * 500
        return base + growth

    def player_cash_runway_forecast(self, weeks=12, *, attendance_multipliers=None):
        """Return a read-only, settlement-aligned cash runway for the player.

        The runway is deliberately a planning view, not a second ledger.  It
        starts from the current cash balance (which already includes anything
        paid in the open week), places recurring bills on the same month
        boundary used by ``calendar_week_steps``, and prices only committed
        main-promotion cards.  Ticket/merchandise receipts are sensitivity
        assumptions at 80%, 100% and 120% of the baseline attendance; rights
        and sponsor money is reported separately because activation can still
        fail at settlement.  No RNG, reservations, ledger writes or schedule
        mutations are performed here.
        """
        try:
            horizon = max(1, min(52, int(weeks)))
        except (TypeError, ValueError):
            horizon = 12
        finance = getattr(self, "finance", {})
        if not isinstance(finance, dict):
            finance = {}
        current_abs = int(self.calendar_week_index())
        opening_cash = int(getattr(self, "cash", 0) or 0)
        company_name = str(getattr(self, "player_company_name", "Player") or "Player")
        company_pop = max(0, int(getattr(self, "company_pop", 0) or 0))
        company_stability = max(0, int(getattr(self, "company_stability", 0) or 0))
        rules = getattr(self, "rules", {}) if isinstance(getattr(self, "rules", {}), dict) else {}
        raw_multipliers = attendance_multipliers if isinstance(attendance_multipliers, dict) else {}
        scenario_multipliers = {}
        for label, default in (("conservative", 0.80), ("baseline", 1.00), ("strong", 1.20)):
            try:
                scenario_multipliers[label] = max(0.0, min(2.0, float(raw_multipliers.get(label, default))))
            except (TypeError, ValueError):
                scenario_multipliers[label] = default

        def nonnegative_int(raw, default=0):
            if isinstance(raw, bool) or raw is None or raw == "":
                return default
            try:
                return max(0, int(raw))
            except (TypeError, ValueError, OverflowError):
                return default

        def bounded_float(raw, default=0.0, *, minimum=None, maximum=None):
            """Coerce a planning input without allowing malformed finance data to escape."""
            if isinstance(raw, bool) or raw is None or raw == "":
                value = float(default)
            else:
                try:
                    value = float(raw)
                except (TypeError, ValueError, OverflowError):
                    value = float(default)
            if not math.isfinite(value):
                value = float(default)
            if minimum is not None:
                value = max(float(minimum), value)
            if maximum is not None:
                value = min(float(maximum), value)
            return value

        staff_payroll = sum(
            nonnegative_int(item.get("salary", 0))
            for item in (getattr(self, "staff", []) or []) if isinstance(item, dict)
        )
        office = max(0, int(self.player_monthly_office_cost())) if hasattr(self, "player_monthly_office_cost") else max(0, int(finance.get("monthly_office", 0) or 0))
        investment_upkeep = 0
        owned_investments = finance.get("strategic_investments", {})
        if isinstance(owned_investments, dict) and hasattr(self, "strategic_investment_registry"):
            investment_upkeep = sum(
                int(spec.get("upkeep", 0) or 0)
                for spec in self.strategic_investment_registry()
                if spec.get("id") in owned_investments
            )
        academy = getattr(self, "academy", {})
        academy_weekly = nonnegative_int(academy.get("weekly_cost", 0), 0) if isinstance(academy, dict) and academy.get("owned") else 0
        monthly_fixed = office + staff_payroll + investment_upkeep
        rights = finance.get("media_rights", {}) if isinstance(finance.get("media_rights", {}), dict) else {}
        raw_rights_events = rights.get("events_remaining", 0)
        try:
            rights_events = int(raw_rights_events or 0)
        except (TypeError, ValueError, OverflowError):
            rights_events = -1 if str(raw_rights_events).strip().lower() in {"unlimited", "ongoing"} else 0
        rights_receipt = nonnegative_int(rights.get("fee", rights.get("guarantee_per_event", 0)), 0) if rights_events != 0 else 0
        sponsor_receipt = nonnegative_int(finance.get("sponsor_income", 0), 0)
        sponsor_deals = finance.get("sponsor_deals", [])
        if isinstance(sponsor_deals, list):
            for deal in sponsor_deals:
                if isinstance(deal, dict):
                    # Use the signed face value as a conditional upside.  Do
                    # not call the settlement helper here: it may initialise
                    # media state and it would turn an unverified future duty
                    # into a half/full payment claim before the event closes.
                    sponsor_receipt += nonnegative_int(deal.get("fee", 0), 0)

        def value(source, key, default=0):
            if isinstance(source, dict):
                raw = source.get(key, default)
            else:
                raw = getattr(source, key, default)
            try:
                return int(raw or 0)
            except (TypeError, ValueError, OverflowError):
                return nonnegative_int(default, 0)

        def event_fighters(fight):
            if hasattr(self, "event_fight_fighters"):
                try:
                    return [fighter for fighter in self.event_fight_fighters(fight) if fighter is not None]
                except Exception:
                    pass
            found = []
            for key in ("red", "blue", "a", "b", "fighter_a", "fighter_b"):
                candidate = fight.get(key) if isinstance(fight, dict) else None
                if candidate is not None and candidate not in found:
                    found.append(candidate)
            return found

        def event_quote(event):
            fights = event.get("fights", event.get("bouts", [])) if isinstance(event, dict) else []
            if not isinstance(fights, list):
                fights = []
            fighters = []
            hype = 0
            for fight in fights:
                if not isinstance(fight, dict):
                    continue
                bout_fighters = event_fighters(fight)
                for fighter in bout_fighters:
                    if fighter not in fighters:
                        fighters.append(fighter)
                if len(bout_fighters) >= 2 and hasattr(self, "fight_hype"):
                    try:
                        hype += max(0, int(self.fight_hype(bout_fighters[0], bout_fighters[1], fight) or 0))
                    except Exception:
                        pass
                if len(bout_fighters) < 2:
                    hype += sum(max(0, value(fighter, "popularity", 0)) for fighter in bout_fighters) // 2
            if not hype:
                hype = sum(max(0, value(fighter, "popularity", 0)) for fighter in fighters)
            bout_count = len(fights)
            venue = str(event.get("venue", "Regional Arena") or "Regional Arena")
            region = str(event.get("region", getattr(self, "player_region", "")) or getattr(self, "player_region", ""))
            try:
                capacity = nonnegative_int(self.venue_capacity_for(venue), 4200) if hasattr(self, "venue_capacity_for") else 4200
            except Exception:
                capacity = 4200
            ticket_price = max(15, min(250, value(event, "ticket_price", finance.get("ticket_price", 55))))
            marketing = max(0, value(event, "marketing_budget", finance.get("marketing_budget", 18_000)))
            tier_name, tier = self.resolve_event_production_tier(event) if hasattr(self, "resolve_event_production_tier") else ("Standard", {"cost": 1.0, "atmosphere": 0.0})
            regional_pull = float(self.regional_market_score(region)) if hasattr(self, "regional_market_score") else 1.0
            fair = int(self.event_fair_ticket_price(hype, regional_pull, venue)) if hasattr(self, "event_fair_ticket_price") else max(15, ticket_price)
            demand = float(self.ticket_price_demand_factor(ticket_price, fair)) if hasattr(self, "ticket_price_demand_factor") else 1.0
            marketing_factor = float(self.marketing_demand_factor(marketing)) if hasattr(self, "marketing_demand_factor") else 1.0
            tier_atmosphere = bounded_float(tier.get("atmosphere", 0) if isinstance(tier, dict) else 0.0, 0.0)
            atmosphere_factor = 0.95 + tier_atmosphere
            if hasattr(self, "event_atmosphere"):
                try:
                    atmosphere_factor = bounded_float(
                        self.event_atmosphere({"region": region, "fights": fights}).get("attendance_factor", atmosphere_factor),
                        atmosphere_factor,
                    ) + tier_atmosphere
                except Exception:
                    pass
            attendance_demand = hype * (24 + company_pop * 0.82 + company_stability * 0.22) / 14
            baseline_attendance = 0 if hype <= 0 else min(capacity, max(80, round(attendance_demand * regional_pull * atmosphere_factor * demand * marketing_factor)))
            grudge_bonus = 0
            if hasattr(self, "event_grudge_gate_bonus"):
                try:
                    grudge_bonus = float(self.event_grudge_gate_bonus(event))
                except Exception:
                    grudge_bonus = 0
            fighter_pay = sum(max(0, value(fighter, "purse", 0)) for fighter in fighters)
            production_base = nonnegative_int(finance.get("production_base", 24_000), 24_000)
            tier_cost = bounded_float(tier.get("cost", 1.0) if isinstance(tier, dict) else 1.0, 1.0, minimum=0.0)
            production = round((production_base + bout_count * 5200 + round(capacity * (5 + company_pop / 16))) * tier_cost)
            doctor_lift = 0
            if hasattr(self, "staff_effect"):
                try:
                    doctor_lift = max(0, float(self.staff_effect("Doctor", 1.1)))
                except Exception:
                    doctor_lift = 0
            medical_base = nonnegative_int(finance.get("medical_base", 9000), 9000)
            medical = max(medical_base, round(medical_base + bout_count * 1900 - round(doctor_lift * 260)))
            drug_test_cost = nonnegative_int(finance.get("drug_test_cost", 2500), 2500)
            drug_testing = 0 if rules.get("drug_testing", "Standard") == "None" else round(bout_count * 2 * drug_test_cost)
            super_event = event.get("super_event", {}) if isinstance(event, dict) else {}
            super_cost = max(0, value(super_event, "remaining_setup_cost", 0) + value(super_event, "security_cost", 0))
            committed_cost = fighter_pay + production + medical + marketing + drug_testing + super_cost
            # Sponsor receipts are shown twice on purpose: the contracted
            # maximum remains a conditional upside, while the activation-
            # adjusted estimate explains what the current saved trust,
            # stability, campaign and delivery facts support for this card.
            # Use only the pure preview; settlement keeps the canonical
            # ``sponsor_activation_status`` owner and is never called here.
            sponsor_maximum = nonnegative_int(finance.get("sponsor_income", 0), 0)
            sponsor_estimate = sponsor_maximum
            sponsor_reasons = []
            for deal in sponsor_deals if isinstance(sponsor_deals, list) else []:
                if not isinstance(deal, dict):
                    continue
                fee = nonnegative_int(deal.get("fee", 0), 0)
                sponsor_maximum += fee
                preview_fn = getattr(self, "sponsor_activation_preview", None)
                if callable(preview_fn):
                    try:
                        ready, reason = preview_fn(deal, event=event)
                    except TypeError:
                        ready, reason = preview_fn(deal)
                    except Exception:
                        ready, reason = False, "activation status unavailable in forecast"
                else:
                    ready, reason = False, "activation status unavailable in forecast"
                sponsor_estimate += fee if ready else round(fee * .5)
                if not ready:
                    sponsor_reasons.append(f"{deal.get('name', 'Sponsor')}: {reason}")
            event_month = max(1, value(event, "month", getattr(self, "month", 1)))
            event_week = max(1, min(4, value(event, "week", 1)))
            scenario = {}
            for label, multiplier in scenario_multipliers.items():
                attendance = min(capacity, max(0, round(baseline_attendance * multiplier)))
                gate = round(attendance * ticket_price * (1 + grudge_bonus))
                merch_rate = bounded_float(finance.get("merch_rate", 0.12), 0.12, minimum=0.0)
                merchandise = round(gate * merch_rate * (1 + company_pop / 130) * 0.90)
                receipts = gate + merchandise
                tax_rate = bounded_float(finance.get("tax_rate", 0.18), 0.18, minimum=0.0)
                tax = round(max(0, receipts - committed_cost) * tax_rate)
                scenario[label] = {"attendance": attendance, "receipts": receipts, "tax": tax, "net": receipts - committed_cost - tax}
            # Break-even is a gate-and-merchandise threshold only.  Rights and
            # sponsor receipts stay outside the threshold because they are
            # conditional and are shown separately in the forecast.  The same
            # ticket, merchandise and grudge inputs as the scenario rows are
            # used, and the result is withheld when venue capacity cannot meet
            # the commitment.
            per_attendee_receipts = ticket_price * (1 + grudge_bonus) * (
                1 + merch_rate * (1 + company_pop / 130) * 0.90
            )
            if committed_cost <= 0:
                break_even_required = 0
            elif per_attendee_receipts > 0:
                break_even_required = max(0, math.ceil(committed_cost / per_attendee_receipts))
            else:
                break_even_required = None
            break_even_achievable = break_even_required is not None and break_even_required <= capacity
            event_id = str(event.get("event_id", event.get("id", "")) or "")
            return {
                "event_id": event_id or f"legacy:{event.get('name', 'event')}:{event.get('month', '')}:{event.get('week', '')}",
                "name": str(event.get("name", event.get("event_name", "Event")) or "Event"),
                "month": event_month, "week": event_week,
                "event_week": int(self.calendar_week_index(event_month, event_week)),
                "tier": tier_name, "capacity": capacity, "baseline_attendance": baseline_attendance,
                "break_even_attendance": break_even_required if break_even_achievable else None,
                "break_even_achievable": bool(break_even_achievable),
                "break_even_basis": "Gate + merchandise only; conditional rights/sponsors excluded",
                "committed_cost": committed_cost, "scenario": scenario,
                "conditional_rights": rights_receipt, "conditional_sponsors": sponsor_maximum,
                "conditional_sponsor_estimate": sponsor_estimate,
                "conditional_receipts": rights_receipt + sponsor_maximum,
                "conditional_expected_receipts": rights_receipt + sponsor_estimate,
                "sponsor_activation_reasons": sponsor_reasons,
                "unknowns": ["Result bonuses and final medical variance settle after the card.", "Rights and sponsor receipts remain conditional until activation is checked."],
            }

        quotes = []
        seen_event_ids = set()
        for event in getattr(self, "scheduled_events", []) or []:
            if not isinstance(event, dict) or event.get("cancelled") or event.get("completed"):
                continue
            quote = event_quote(event)
            if quote["event_week"] <= current_abs or quote["event_week"] > current_abs + horizon:
                continue
            if quote["event_id"] in seen_event_ids:
                continue
            seen_event_ids.add(quote["event_id"])
            quotes.append(quote)
        # A finite media package pays its guarantee once per remaining event,
        # in date order.  Do not show the same rights cheque against every
        # booked card when the horizon contains more cards than the contract.
        if rights_events > 0:
            rights_slots = rights_events
            for quote in sorted(quotes, key=lambda item: (item["event_week"], item["event_id"])):
                quote["conditional_rights"] = rights_receipt if rights_slots > 0 else 0
                rights_slots -= 1
                quote["conditional_receipts"] = quote["conditional_rights"] + quote.get("conditional_sponsors", 0)
                quote["conditional_expected_receipts"] = quote["conditional_rights"] + quote.get("conditional_sponsor_estimate", 0)

        # Historical finance shelves can contain partially written rows from
        # older builds. A runway preview must stay readable without coercing
        # malformed dates/costs into a different week or repairing the save.
        # Keep a diagnostic count so the player can see why the paid-to-date
        # figure may be incomplete; the raw transaction remains untouched.
        invalid_transaction_rows = 0

        def strict_int(value):
            if isinstance(value, bool):
                return None
            if isinstance(value, int):
                return value
            if isinstance(value, str) and value.strip().lstrip("-").isdigit():
                try:
                    return int(value.strip())
                except (TypeError, ValueError):
                    return None
            return None

        already_paid = 0
        transactions = finance.get("week_transactions", [])
        if not isinstance(transactions, list):
            # A malformed shelf is not the same as a confirmed empty one.
            # Keep the raw finance envelope untouched, but disclose that the
            # paid-to-date component is unavailable rather than implying that
            # no costs have been recorded.
            invalid_transaction_rows = 1
            transaction_rows = []
        else:
            transaction_rows = transactions
        for row in transaction_rows:
            if not isinstance(row, dict):
                invalid_transaction_rows += 1
                continue
            row_month = strict_int(row.get("month"))
            row_week = strict_int(row.get("week"))
            row_cost = strict_int(row.get("costs", 0))
            if row_month is None or row_week is None or row_cost is None:
                invalid_transaction_rows += 1
                continue
            if row_month == int(getattr(self, "month", 1)) and row_week == int(getattr(self, "week", 1)):
                already_paid += max(0, row_cost)

        rows = []
        cash = {"conservative": opening_cash, "baseline": opening_cash, "strong": opening_cash}
        for offset in range(1, horizon + 1):
            absolute_week = current_abs + offset
            month = (absolute_week - 1) // 4 + 1
            week = (absolute_week - 1) % 4 + 1
            monthly_bill = monthly_fixed if week == 1 else 0
            fixed_bills = monthly_bill + academy_weekly
            due = [quote for quote in quotes if quote["event_week"] == absolute_week]
            event_commitments = sum(int(quote["committed_cost"]) for quote in due)
            conditional = sum(int(quote["conditional_receipts"]) for quote in due)
            scenario_receipts = {}
            scenario_taxes = {}
            for label in ("conservative", "baseline", "strong"):
                scenario_receipts[label] = sum(int(quote["scenario"][label]["receipts"]) for quote in due)
                scenario_taxes[label] = sum(int(quote["scenario"][label]["tax"]) for quote in due)
                cash[label] += scenario_receipts[label] - fixed_bills - event_commitments - scenario_taxes[label]
            rows.append({
                "offset": offset, "month": month, "week": week, "date": self.format_game_date(month, week) if hasattr(self, "format_game_date") else f"Month {month} Week {week}",
                "opening": {label: (opening_cash if offset == 1 else rows[-1]["closing"][label]) for label in cash},
                "fixed_bills": fixed_bills, "event_commitments": event_commitments, "conditional_receipts": conditional,
                "conditional_expected_receipts": sum(int(quote.get("conditional_expected_receipts", 0) or 0) for quote in due),
                "receipts": scenario_receipts, "taxes": scenario_taxes, "closing": dict(cash),
                "events": [{"event_id": quote["event_id"], "name": quote["name"], "baseline_attendance": quote["baseline_attendance"], "cost": quote["committed_cost"]} for quote in due],
            })
        lowest = min(rows, key=lambda row: row["closing"]["baseline"]) if rows else None
        return {
            "as_of": {"month": int(getattr(self, "month", 1)), "week": int(getattr(self, "week", 1))},
            "horizon_weeks": horizon, "opening_cash": opening_cash, "already_paid": already_paid,
            "assumptions": {"attendance_multipliers": dict(scenario_multipliers)},
            "recurring": {"office": office, "staff_payroll": staff_payroll, "academy_weekly": academy_weekly, "investment_upkeep": investment_upkeep, "monthly_fixed": monthly_fixed},
            "conditional_basis": {
                "rights": sum(int(item.get("conditional_rights", 0) or 0) for item in quotes),
                "sponsors": sum(int(item.get("conditional_sponsors", 0) or 0) for item in quotes),
                "sponsor_estimate": sum(int(item.get("conditional_sponsor_estimate", 0) or 0) for item in quotes),
                "expected": sum(int(item.get("conditional_expected_receipts", 0) or 0) for item in quotes),
            },
            "rows": rows, "events": quotes,
            "lowest_baseline": {"date": lowest["date"], "cash": lowest["closing"]["baseline"], "events": [item["name"] for item in lowest["events"]]} if lowest else None,
            "unknowns": ["Forecast excludes child-promotion and Combat Sports wallets; each pays from its own owner ledger.", "Fight bonuses, final medical variance and activation outcomes are not known before settlement."] + ([f"{invalid_transaction_rows} retained finance transaction row(s) have malformed dates or costs and were excluded from the paid-to-date figure; the source rows remain available for audit."] if invalid_transaction_rows else []),
        }

    def _cash_runway_source_revision(self):
        """Return a pure identity for the inputs behind a runway snapshot.

        Scenario records are advice, not reservations.  The revision therefore
        fingerprints the current calendar/finance inputs so a saved snapshot
        can be labelled stale after a card, contract or rights term changes.
        It intentionally reads only plain persisted values and never repairs a
        save or calls an offer/settlement resolver.
        """
        finance = getattr(self, "finance", {})
        if not isinstance(finance, dict):
            finance = {}
        event_rows = []
        malformed_event_date_rows = 0

        def strict_int(value):
            if isinstance(value, bool):
                return None
            if isinstance(value, int):
                return value
            if isinstance(value, str) and value.strip().lstrip("-").isdigit():
                try:
                    return int(value.strip())
                except (TypeError, ValueError):
                    return None
            return None

        for event in getattr(self, "scheduled_events", []) or []:
            if not isinstance(event, dict):
                continue
            if ("month" in event and strict_int(event.get("month")) is None) or ("week" in event and strict_int(event.get("week")) is None):
                malformed_event_date_rows += 1
            def stable_participant(value):
                if isinstance(value, dict):
                    return {
                        "fighter_id": str(value.get("fighter_id", value.get("id", "")) or ""),
                        "name": str(value.get("name", "") or ""),
                        "popularity": value.get("popularity", ""), "purse": value.get("purse", ""),
                        "overall": value.get("overall", ""), "momentum": value.get("momentum", ""),
                        "champion": bool(value.get("champion", False)),
                    }
                return {
                    "fighter_id": str(getattr(value, "fighter_id", "") or ""),
                    "name": str(getattr(value, "name", "") or ""),
                    "popularity": getattr(value, "popularity", ""), "purse": getattr(value, "purse", ""),
                    "overall": getattr(value, "overall", ""), "momentum": getattr(value, "momentum", ""),
                    "champion": bool(getattr(value, "champion", False)),
                }

            fight_rows = []
            fights = event.get("fights", event.get("bouts", []))
            if isinstance(fights, list):
                for fight in fights:
                    if not isinstance(fight, dict):
                        fight_rows.append({"malformed": True})
                        continue
                    participants = []
                    for key in ("red", "blue", "a", "b", "fighter_a", "fighter_b"):
                        if key in fight and fight.get(key) is not None:
                            participants.append((key, stable_participant(fight.get(key))))
                    for key in ("fighter_ids", "fighters", "tournament_entrants"):
                        values = fight.get(key)
                        if isinstance(values, list):
                            participants.extend((key, stable_participant(value)) for value in values)
                    fight_rows.append({
                        "title": bool(fight.get("title", fight.get("divisional_title", False))),
                        "weight": str(fight.get("weight", fight.get("division", "")) or ""),
                        "participants": participants,
                    })
            event_rows.append({
                "event_id": str(event.get("event_id", event.get("id", "")) or ""),
                "name": str(event.get("name", event.get("event_name", "")) or ""),
                "month": event.get("month", 0), "week": event.get("week", 0),
                "status": str(event.get("status", "") or ""),
                "cancelled": bool(event.get("cancelled")), "completed": bool(event.get("completed")),
                "ticket_price": event.get("ticket_price", ""),
                "marketing_budget": event.get("marketing_budget", ""),
                "venue": str(event.get("venue", "") or ""),
                "region": str(event.get("region", "") or ""),
                "broadcaster": str(event.get("broadcaster", "") or ""),
                "production_tier": str(event.get("production_tier", "") or ""),
                "super_event": deepcopy(event.get("super_event", {})) if isinstance(event.get("super_event", {}), dict) else {},
                "fights": fight_rows,
            })
        staff_rows = []
        for member in getattr(self, "staff", []) or []:
            if isinstance(member, dict):
                staff_rows.append({
                    "staff_id": str(member.get("staff_id", "") or ""), "role": str(member.get("role", "") or ""),
                    "salary": member.get("salary", ""), "contract_months": member.get("contract_months", ""),
                    "skill": member.get("skill", ""), "morale": member.get("morale", ""),
                    "specialty": str(member.get("specialty", "") or ""),
                })
        academy = getattr(self, "academy", {})
        academy_revision = {}
        if isinstance(academy, dict):
            academy_revision = {
                "owned": bool(academy.get("owned", False)), "weekly_cost": academy.get("weekly_cost", ""),
                "level": academy.get("level", ""), "capacity": academy.get("capacity", ""),
            }
        cash_revision = strict_int(getattr(self, "cash", 0))
        company_revision = {
            "popularity": strict_int(getattr(self, "company_pop", 0)),
            "stability": strict_int(getattr(self, "company_stability", 0)),
        }
        try:
            current_month = strict_int(getattr(self, "month", 1) or 1)
            current_week = strict_int(getattr(self, "week", 1) or 1)
        except (TypeError, ValueError):
            current_month = current_week = None
        payload = {
            "calendar": {"month": current_month if current_month is not None else 1, "week": current_week if current_week is not None else 1},
            "cash": cash_revision if cash_revision is not None else 0,
            "company": company_revision,
            "rules": {"drug_testing": str(getattr(self, "rules", {}).get("drug_testing", "Standard") if isinstance(getattr(self, "rules", {}), dict) else "Standard")},
            "staff": sorted(staff_rows, key=lambda row: (row.get("staff_id", ""), row.get("role", ""), str(row.get("name", "")))),
            "academy": academy_revision,
            "events": sorted(event_rows, key=lambda row: (str(row.get("event_id", "")), strict_int(row.get("month")) if strict_int(row.get("month")) is not None else 0, strict_int(row.get("week")) if strict_int(row.get("week")) is not None else 0, str(row.get("name", "")))),
            "finance_revision": str(finance.get("revision", "") or ""),
            "ticket_price": finance.get("ticket_price", ""),
            "marketing_budget": finance.get("marketing_budget", ""),
            "media_rights": deepcopy(finance.get("media_rights", {})) if isinstance(finance.get("media_rights", {}), dict) else {},
            "sponsor_deals": deepcopy(finance.get("sponsor_deals", [])) if isinstance(finance.get("sponsor_deals", []), list) else [],
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str)
        return {
            "digest": hashlib.sha256(encoded.encode("utf-8")).hexdigest(),
            "payload": payload,
            "diagnostics": {"malformed_event_date_rows": malformed_event_date_rows},
        }

    def cash_runway_scenarios(self):
        """Return saved runway snapshots with a current/stale read-only label."""
        finance = getattr(self, "finance", {})
        rows = finance.get("cash_runway_scenarios", []) if isinstance(finance, dict) else []
        if not isinstance(rows, list):
            # Keep malformed retained finance visible as an explicit reader
            # state.  Returning an empty list would imply that no snapshots
            # were ever saved and would hide the repair boundary from the
            # player.  This projection is transient and never normalises the
            # raw envelope.
            return [{
                "schema_version": 1,
                "scenario_id": "cash-scenarios-unavailable",
                "name": "Unavailable saved scenarios",
                "_read_status": "Unavailable",
                "freshness": "Unavailable",
                "note": "Saved scenario history is malformed; repair is limited to the load/migration boundary.",
            }]
        current_digest = self._cash_runway_source_revision().get("digest", "")
        result = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            item = deepcopy(row)
            saved_revision = item.get("source_revision", {}) if isinstance(item.get("source_revision", {}), dict) else {}
            item["freshness"] = "Current" if str(saved_revision.get("digest", "")) == current_digest else "Stale inputs"
            result.append(item)
        return result

    def save_cash_runway_scenario(self, name="", *, horizon_weeks=12, assumptions=None, edits=None):
        """Save an explicit, non-binding runway snapshot for later comparison.

        This is the first A3 scenario slice: it records the exact forecast and
        its input identity, but does not move an event, alter a price, reserve
        cash, or apply any multi-event change.  Repeating the same request is
        idempotent and returns the original snapshot.
        """
        finance = getattr(self, "finance", None)
        if not isinstance(finance, dict):
            return False, "Finance data is unavailable; no scenario was saved.", None

        def safe_int(raw, default=0):
            if isinstance(raw, bool) or raw is None or raw == "":
                return default
            try:
                return int(raw)
            except (TypeError, ValueError, OverflowError):
                return default

        try:
            horizon = max(1, min(52, int(horizon_weeks)))
        except (TypeError, ValueError, OverflowError):
            horizon = 12
        assumptions = deepcopy(assumptions) if isinstance(assumptions, dict) else {}
        multipliers = assumptions.get("attendance_multipliers")
        if not isinstance(multipliers, dict):
            multipliers = {"conservative": 0.80, "baseline": 1.00, "strong": 1.20}
        normalized = {}
        for label, default in (("conservative", 0.80), ("baseline", 1.00), ("strong", 1.20)):
            try:
                normalized[label] = max(0.0, min(2.0, float(multipliers.get(label, default))))
            except (TypeError, ValueError):
                normalized[label] = default
        assumptions["attendance_multipliers"] = normalized
        edits = deepcopy(edits) if isinstance(edits, list) else []
        edits = [dict(item) for item in edits if isinstance(item, dict)][-24:]
        source_revision = self._cash_runway_source_revision()
        payload = {
            "name": str(name or "Runway snapshot").strip() or "Runway snapshot",
            "horizon_weeks": horizon, "assumptions": assumptions, "edits": edits,
            "source_digest": source_revision.get("digest", ""),
        }
        scenario_id = "cash-scenario:" + hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")).hexdigest()[:20]
        existing = next((row for row in finance.get("cash_runway_scenarios", []) if isinstance(row, dict) and str(row.get("scenario_id", "")) == scenario_id), None) if isinstance(finance.get("cash_runway_scenarios", []), list) else None
        if existing is not None:
            return True, f"Scenario {scenario_id} already exists; the saved snapshot was kept.", deepcopy(existing)
        forecast = deepcopy(self.player_cash_runway_forecast(
            horizon, attendance_multipliers=normalized,
        ))
        created_month = safe_int(getattr(self, "month", 1), 1)
        created_week = max(1, min(4, safe_int(getattr(self, "week", 1), 1)))
        scenario = {
            "schema_version": 1, "scenario_id": scenario_id, "name": payload["name"],
            "status": "Draft", "created_month": created_month,
            "created_week": created_week, "horizon_weeks": horizon,
            "assumptions": assumptions, "edits": edits, "source_revision": source_revision,
            "forecast": forecast,
            "note": "Planning evidence only. Applying changes remains an explicit action in the existing event/finance editors.",
        }
        rows = finance.setdefault("cash_runway_scenarios", [])
        if not isinstance(rows, list):
            rows = finance["cash_runway_scenarios"] = []
        rows.append(deepcopy(scenario))
        finance["cash_runway_scenarios"] = rows[-48:]
        return True, f"Saved {scenario_id}. It is a non-binding planning snapshot.", deepcopy(scenario)

    def cash_runway_scenario_by_id(self, scenario_id):
        requested = str(scenario_id or "")
        return next((row for row in self.cash_runway_scenarios() if str(row.get("scenario_id", "")) == requested), None)

    def strategic_investment_registry(self):
        """Late-career capital projects with permanent benefits and upkeep."""
        return (
            {"id": "performance_institute", "category": "Facility", "name": "Performance Institute", "cost": 3_000_000, "upkeep": 90_000, "min_pop": 65, "milestone": "national_power", "effects": {"medical": 0.90}, "effect": "10% lower event medical costs"},
            {"id": "broadcast_campus", "category": "Facility", "name": "Broadcast & Content Campus", "cost": 7_500_000, "upkeep": 180_000, "min_pop": 75, "milestone": "major_organisation", "effects": {"broadcast": 1.07}, "effect": "7% more event broadcast revenue"},
            {"id": "international_office", "category": "International", "name": "International Operations Office", "cost": 5_000_000, "upkeep": 125_000, "min_pop": 65, "milestone": "national_power", "effects": {"international_attendance": 1.08, "international_sponsorship": 1.04}, "effect": "8% overseas attendance and 4% overseas sponsor value"},
            {"id": "global_logistics", "category": "International", "name": "Global Logistics Network", "cost": 15_000_000, "upkeep": 350_000, "min_pop": 84, "milestone": "combat_sports_institution", "effects": {"attendance": 1.04, "broadcast": 1.04}, "effect": "4% attendance and broadcast value worldwide"},
            {"id": "sports_science_department", "category": "Department", "name": "Sports Science Department", "cost": 4_000_000, "upkeep": 140_000, "min_pop": 70, "milestone": "national_power", "effects": {"medical": 0.88}, "effect": "12% lower event medical costs"},
            {"id": "commercial_department", "category": "Department", "name": "Global Commercial Department", "cost": 6_000_000, "upkeep": 200_000, "min_pop": 75, "milestone": "major_organisation", "effects": {"sponsorship": 1.08}, "effect": "8% more event sponsorship revenue"},
            {"id": "hall_of_champions", "category": "Prestige", "name": "Hall of Champions", "cost": 12_000_000, "upkeep": 250_000, "min_pop": 84, "milestone": "combat_sports_institution", "effects": {"merchandise": 1.12}, "effect": "12% more event merchandise revenue"},
            {"id": "world_headquarters", "category": "Prestige", "name": "World Headquarters Complex", "cost": 30_000_000, "upkeep": 600_000, "min_pop": 90, "milestone": "legacy_empire", "effects": {"attendance": 1.03, "broadcast": 1.03, "sponsorship": 1.03, "merchandise": 1.03}, "effect": "3% lift to every major event revenue stream"},
        )

    def owned_strategic_investments(self, *, repair=True):
        """Return owned strategic investments with an explicit repair boundary.

        Management actions and calendar owners use the default repairing path
        so legacy finance envelopes are brought to the canonical shape before
        a write.  Finance/runway readers pass ``repair=False`` and receive a
        defensive projection instead; opening those pages must not seed or
        rewrite a malformed ``finance`` envelope merely to calculate upkeep.
        """
        if repair:
            self.ensure_finance_defaults()
            if not isinstance(getattr(self, "finance", None), dict):
                self.finance = {}
            owned = self.finance.setdefault("strategic_investments", {})
            if not isinstance(owned, dict):
                self.finance["strategic_investments"] = owned = {}
            return owned
        finance = getattr(self, "finance", {})
        if not isinstance(finance, dict):
            return {}
        owned = finance.get("strategic_investments", {})
        return dict(owned) if isinstance(owned, dict) else {}

    def strategic_investment_upkeep(self, *, repair=True):
        owned = self.owned_strategic_investments(repair=repair)
        return sum(
            int(spec["upkeep"]) for spec in self.strategic_investment_registry()
            if spec["id"] in owned
        )

    def strategic_event_multiplier(self, effect, event=None):
        multiplier = 1.0
        region = str((event or {}).get("region", self.player_region))
        home = str(getattr(self, "player_region", ""))
        for spec in self.strategic_investment_registry():
            if spec["id"] not in self.owned_strategic_investments():
                continue
            effects = spec.get("effects", {})
            multiplier *= float(effects.get(effect, 1.0))
            if region != home:
                multiplier *= float(effects.get(f"international_{effect}", 1.0))
        return multiplier

    def strategic_investment_status(self, spec, *, repair=True):
        """Project a project's status without forcing finance repair in readers."""
        if spec["id"] in self.owned_strategic_investments(repair=repair):
            return "Owned", "Installed"
        unlocked = self.company_unlocked_milestone_ids() if hasattr(self, "company_unlocked_milestone_ids") else set()
        blockers = []
        if spec.get("milestone") and spec["milestone"] not in unlocked:
            blockers.append(spec["milestone"].replace("_", " ").title())
        if self.company_pop < int(spec.get("min_pop", 0)):
            blockers.append(f"Popularity {spec['min_pop']}")
        if self.cash < int(spec["cost"]):
            blockers.append(f"${spec['cost']:,} cash")
        return ("Locked", ", ".join(blockers)) if blockers else ("Available", "Ready to approve")

    def purchase_strategic_investment(self, investment_id):
        spec = next((row for row in self.strategic_investment_registry() if row["id"] == investment_id), None)
        if not spec:
            return False, "That strategic project no longer exists."
        status, reason = self.strategic_investment_status(spec)
        if status == "Owned":
            return False, f"{spec['name']} is already operating."
        if status != "Available":
            return False, f"{spec['name']} is locked: {reason}."
        before_cash = self.cash
        before_owned = deepcopy(self.finance["strategic_investments"])
        before_news = list(getattr(self, "news", []))
        before_transactions = deepcopy(self.finance.get("week_transactions", []))
        before_ledger = deepcopy(self.finance.get("ledger", []))
        before_changes = deepcopy(getattr(self, "change_journal", []))
        try:
            self.cash -= int(spec["cost"])
            self.finance["strategic_investments"][spec["id"]] = {
                "name": spec["name"], "category": spec["category"],
                "purchased_month": self.month, "cost": int(spec["cost"]), "upkeep": int(spec["upkeep"]),
            }
            self.record_finance_transaction(
                f"Strategic investment: {spec['name']}", costs=spec["cost"], category="Investment",
                source=spec["category"], counterparty=spec["name"], reference=f"investment:{spec['id']}",
            )
            self.news.insert(0, f"{self.player_company_name} opens {spec['name']}. Monthly upkeep is ${spec['upkeep']:,}.")
        except Exception:
            self.cash = before_cash
            self.finance["strategic_investments"] = before_owned
            self.finance["week_transactions"] = before_transactions
            self.finance["ledger"] = before_ledger
            self.news = before_news
            self.change_journal = before_changes
            raise
        return True, f"Opened {spec['name']} for ${spec['cost']:,}; monthly upkeep ${spec['upkeep']:,}."

    def record_roster_cost_snapshot(self):
        self.ensure_finance_defaults()
        active = [fighter for fighter in self.roster if not getattr(fighter, "retired", False)]
        purses = sorted((max(0, int(getattr(fighter, "purse", 0) or 0)) for fighter in active), reverse=True)
        booked = sum(
            max(0, int(getattr(fighter, "purse", 0) or 0))
            for event in getattr(self, "scheduled_events", []) for fight in event.get("fights", [])
            for fighter in self.event_fight_fighters(fight)
        )
        staff_payroll = 0
        for staff in (getattr(self, "staff", []) or []):
            if not isinstance(staff, dict):
                continue
            raw_salary = staff.get("salary", 0)
            if isinstance(raw_salary, bool):
                continue
            try:
                staff_payroll += max(0, int(raw_salary or 0))
            except (TypeError, ValueError):
                continue
        row = {
            "month": self.month, "year": self.calendar_parts(self.month, 1)[0], "roster": len(active),
            "purse_pool": sum(purses), "top_10_purses": sum(purses[:10]), "booked_exposure": booked,
            "office": self.player_monthly_office_cost(),
            "staff_payroll": staff_payroll,
            "investment_upkeep": self.strategic_investment_upkeep(),
        }
        history = self.finance["roster_cost_history"]
        if history and int(history[-1].get("month", 0) or 0) == self.month:
            history[-1] = row
        else:
            history.append(row)
        self.finance["roster_cost_history"] = history[-240:]
        return row

    def update_annual_finance_history(self):
        self.ensure_finance_defaults()
        self.finance.setdefault("annual_history", [])
        year = self.calendar_parts(self.month, self.week)[0]
        weeks = [
            row for row in self.finance["weekly_history"]
            if self.calendar_parts(int(row.get("month", 1) or 1), int(row.get("week", 1) or 1))[0] == year
        ]
        revenue = sum(int(row.get("revenue", 0) or 0) for row in weeks)
        costs = sum(int(row.get("costs", 0) or 0) for row in weeks)
        events = sum(
            1 for record in getattr(self, "result_records", [])
            if record.get("company") == self.player_company_name
            and self.result_record_year(record) == year
        )
        row = {"year": year, "revenue": revenue, "costs": costs, "net": revenue - costs, "ending": self.cash, "events": events}
        history = self.finance["annual_history"]
        existing = next((index for index, item in enumerate(history) if int(item.get("year", 0) or 0) == year), None)
        if existing is None:
            history.append(row)
        else:
            history[existing] = row
        self.finance["annual_history"] = sorted(history, key=lambda item: int(item.get("year", 0) or 0))[-30:]
        return row

    def result_record_year(self, record):
        text = str((record or {}).get("date", ""))
        match = re.search(r"Month\s+(\d+)", text, re.IGNORECASE)
        if match:
            return self.calendar_parts(int(match.group(1)), 1)[0]
        match = re.search(r"\b(20\d{2})\b", text)
        return int(match.group(1)) if match else self.calendar_parts(self.month, self.week)[0]

    def player_revenue_mix(self, months=12):
        def safe_int(value, fallback=0):
            if isinstance(value, bool) or value is None or value == "":
                return fallback
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return fallback

        current_month = safe_int(getattr(self, "month", 1), 1)
        horizon = max(1, safe_int(months, 12))
        earliest = max(1, current_month - horizon + 1)
        totals = {"Ticket sales": 0, "Broadcast": 0, "Sponsorship": 0, "Merchandise": 0, "Other": 0}
        archived_event_names = set()
        archives = getattr(self, "player_event_archive", [])
        if not isinstance(archives, (list, tuple)):
            archives = []
        for package in archives:
            if not isinstance(package, dict):
                continue
            month = safe_int(package.get("month", 0), 0)
            if month < earliest:
                continue
            finance = package.get("finance", {})
            finance = finance if isinstance(finance, dict) else {}
            totals["Ticket sales"] += safe_int(finance.get("ticket_revenue", 0), 0)
            totals["Broadcast"] += safe_int(finance.get("broadcast_income", 0), 0)
            totals["Sponsorship"] += safe_int(finance.get("sponsorship", 0), 0)
            totals["Merchandise"] += safe_int(finance.get("merchandise", 0), 0)
            archived_event_names.add(str(package.get("event_name", "")))
        raw_finance = getattr(self, "finance", {})
        finance = raw_finance if isinstance(raw_finance, dict) else {}
        weekly_history = finance.get("weekly_history", [])
        if not isinstance(weekly_history, (list, tuple)):
            weekly_history = []
        for week in weekly_history:
            if not isinstance(week, dict) or safe_int(week.get("month", 0), 0) < earliest:
                continue
            transactions = week.get("transactions", [])
            if not isinstance(transactions, (list, tuple)):
                continue
            for row in transactions:
                if not isinstance(row, dict):
                    continue
                revenue = safe_int(row.get("revenue", 0), 0)
                if not revenue:
                    continue
                if row.get("category") == "Event" or str(row.get("event", "")) in archived_event_names:
                    continue
                totals["Other"] += revenue
        # Include the open current week before it has been compacted into
        # weekly history. Stable IDs prevent a row already stored at close from
        # being counted twice during a same-week refresh.
        stored_ids = {
            str(row.get("id", "")) for week in weekly_history if isinstance(week, dict)
            for row in (week.get("transactions", []) if isinstance(week.get("transactions", []), (list, tuple)) else [])
            if isinstance(row, dict)
        }
        week_transactions = finance.get("week_transactions", [])
        if not isinstance(week_transactions, (list, tuple)):
            week_transactions = []
        for row in week_transactions:
            if not isinstance(row, dict):
                continue
            revenue = safe_int(row.get("revenue", 0), 0)
            if str(row.get("id", "")) in stored_ids or safe_int(row.get("month", 0), 0) < earliest:
                continue
            if revenue and row.get("category") != "Event" and str(row.get("event", "")) not in archived_event_names:
                totals["Other"] += revenue
        return totals

    def company_milestone_projection(self, rule):
        """Project milestone progress without repairing malformed finance data."""
        finance = getattr(self, "finance", {})
        finance = finance if isinstance(finance, dict) else {}

        def safe_int(value, fallback=0):
            if isinstance(value, bool) or value is None or value == "":
                return fallback
            if isinstance(value, float) and not math.isfinite(value):
                return fallback
            try:
                parsed = int(value)
            except (TypeError, ValueError, OverflowError):
                return fallback
            # Keep malformed legacy magnitudes from producing an unbounded
            # milestone gap/ETA while retaining ordinary historical values.
            return max(-1_000_000_000, min(1_000_000_000, parsed))

        rule = rule if isinstance(rule, dict) else {}
        recent_value = finance.get("weekly_history", [])
        recent = [row for row in recent_value if isinstance(row, dict)] if isinstance(recent_value, list) else []
        recent = recent[-48:]
        weeks = max(1, len(recent))
        monthly_net = round(sum(safe_int(row.get("net", 0)) for row in recent) / weeks * 4)
        current_cash = safe_int(getattr(self, "cash", 0))
        cash_gap = max(0, safe_int(rule.get("cash", 0)) - current_cash)
        cash_months = 0 if not cash_gap else math.ceil(cash_gap / monthly_net) if monthly_net > 0 else None
        records = getattr(self, "result_records", [])
        records = records if isinstance(records, (list, tuple)) else []
        company_name = str(getattr(self, "player_company_name", "") or "")
        valid_records = [record for record in records if isinstance(record, dict)]
        event_count = sum(1 for record in valid_records if record.get("company") == company_name)
        event_gap = max(0, safe_int(rule.get("events", 0)) - event_count)
        current_month = safe_int(getattr(self, "month", 1), 1)
        recent_events = 0
        for record in valid_records:
            if record.get("company") != company_name:
                continue
            try:
                record_month = safe_int(self.result_record_month(record), current_month)
            except (AttributeError, TypeError, ValueError):
                record_month = current_month
            if current_month - record_month < 12:
                recent_events += 1
        event_months = 0 if not event_gap else math.ceil(event_gap / max(1 / 12, recent_events / 12))
        blockers = []
        company_pop = safe_int(getattr(self, "company_pop", 0))
        company_stability = safe_int(getattr(self, "company_stability", 0))
        company_safety = safe_int(getattr(self, "company_safety", 0))
        for label, actual, target in (
            ("popularity", company_pop, safe_int(rule.get("popularity", 0))),
            ("stability", company_stability, safe_int(rule.get("stability", 0))),
            ("safety", company_safety, safe_int(rule.get("safety", 0))),
        ):
            if actual < target:
                blockers.append(f"{label} {actual}/{target}")
        eta = None if cash_months is None else max(safe_int(rule.get("months", 0)), cash_months, event_months)
        return {"monthly_net": monthly_net, "cash_gap": cash_gap, "event_gap": event_gap, "eta_months": eta, "blockers": blockers}

    def result_record_month(self, record):
        match = re.search(r"Month\s+(\d+)", str((record or {}).get("date", "")), re.IGNORECASE)
        return int(match.group(1)) if match else self.month

    def request_advance_week(self):
        """UI command for one responsive week of world simulation."""
        return self.begin_advance_sequence(1, status_prefix="Advancing week")

    def monthly_player_business_steps(self):
        """Return the player's month-end tasks as independently paintable work."""
        if getattr(self, "spectator_mode", False):
            return []

        def update_morale():
            changed = 0
            total_delta = 0
            for fighter in self.roster:
                old = fighter.morale
                fighter.morale = max(10, fighter.morale - 2)
                changed += fighter.morale != old
                total_delta += fighter.morale - old
            if changed:
                self.record_change("Morale", f"Roster total ({changed} fighters)", total_delta, "Routine month-end morale drift; bouts, promises and bonuses can offset it")

        def pay_overhead():
            payroll = 0
            for staff in (getattr(self, "staff", []) or []):
                if not isinstance(staff, dict):
                    continue
                raw_salary = staff.get("salary", 0)
                if isinstance(raw_salary, bool):
                    continue
                try:
                    payroll += max(0, int(raw_salary or 0))
                except (TypeError, ValueError):
                    continue
            office = self.player_monthly_office_cost()
            overhead = office + payroll
            self.cash -= overhead
            self.record_finance_transaction("Monthly office and payroll", costs=overhead)
            self.finance["ledger"].insert(0, f"Month {self.month}: Monthly overhead ${overhead:,} (scaled office ${office:,}, payroll ${payroll:,})")
            self.event_log.insert(0, f"Month {self.month}: overhead paid. Injured fighters recovered one month.")
            self.record_roster_cost_snapshot()

        def pay_strategic_upkeep():
            upkeep = self.strategic_investment_upkeep()
            if not upkeep:
                return
            reference = f"investment-upkeep:{self.month}"
            if any(row.get("reference") == reference for row in self.finance.get("week_transactions", [])):
                return
            before_cash = self.cash
            before_transactions = deepcopy(self.finance.get("week_transactions", []))
            before_changes = deepcopy(getattr(self, "change_journal", []))
            try:
                self.cash -= upkeep
                self.record_finance_transaction(
                    "Strategic facilities and departments upkeep", costs=upkeep, category="Investment",
                    source="Monthly strategic operations", reference=reference,
                )
            except Exception:
                self.cash = before_cash
                self.finance["week_transactions"] = before_transactions
                self.change_journal = before_changes
                raise

        return [
            ("Player roster morale", update_morale),
            ("Office and payroll", pay_overhead),
            ("Strategic investment upkeep", pay_strategic_upkeep),
            ("Financial pressure review", self.apply_player_financial_pressure),
            ("Business agreements", self.tick_business_deals),
            ("Broadcast contracts", self.tick_broadcast_contracts),
        ]

    def apply_player_financial_pressure(self):
        """Apply modest, persistent consequences for ending a month in debt."""
        if getattr(self, "spectator_mode", False):
            return
        self.finance.setdefault("negative_cash_months", 0)
        previous = max(0, int(self.finance.get("negative_cash_months", 0) or 0))
        if self.cash >= 0:
            if previous:
                self.finance["negative_cash_months"] = 0
                self.inbox.append({
                    "subject": "Financial Pressure Eased",
                    "body": f"{self.player_company_name} has returned to positive cash reserves after {previous} month(s) in debt.",
                    "type": "Finance", "resolved": False,
                })
            return

        streak = previous + 1
        self.finance["negative_cash_months"] = streak
        stability_loss = min(6, 1 + streak)
        morale_loss = min(3, 1 + streak // 3)
        old_stability = self.company_stability
        self.company_stability = max(1, self.company_stability - stability_loss)
        affected = 0
        for fighter in self.roster:
            old_morale = fighter.morale
            fighter.morale = max(10, fighter.morale - morale_loss)
            affected += fighter.morale != old_morale
        self.record_change(
            "Financial Pressure", "Company stability", self.company_stability - old_stability,
            f"Month-end cash was ${self.cash:,}; debt streak is {streak} month(s)",
        )
        if streak == 1 or streak % 3 == 0:
            self.inbox.append({
                "subject": f"Financial Pressure - {streak} Month{'s' if streak != 1 else ''} in Debt",
                "body": (
                    f"Cash reserves ended the month at ${self.cash:,}. Stability fell {stability_loss} point(s) "
                    f"and morale fell {morale_loss} point(s) for {affected} roster member(s). Return to positive "
                    "cash to reset the pressure streak."
                ),
                "type": "Finance", "resolved": False,
            })
        self.news.insert(0, f"Financial pressure is building at {self.player_company_name} after {streak} month(s) in debt.")

    def calendar_week_steps(self, include_autosave=True):
        """Build one calendar week's ordered work without touching Tk widgets."""
        month_changed = self.week >= 4
        completed_month = self.month
        completed_week = self.week
        old_year = 2026 + (self.month - 1) // 12
        steps = list(self.world_week_steps())

        if not month_changed:
            steps.append(("Updating the calendar", lambda: setattr(self, "week", self.week + 1)))
            steps.append(("Scheduled combat-sport cards", self.process_due_player_combat_events))
        else:
            def roll_month():
                self.week = 1
                self.month += 1

            steps.append(("Starting the next month", roll_month))
            steps.append(("Scheduled combat-sport cards", self.process_due_player_combat_events))
            steps.extend(self.world_month_steps(self.player_ran_show_in_month(completed_month)))
            new_year = 2026 + completed_month // 12
            if new_year != old_year:
                steps.append((f"{old_year} awards", lambda old_year=old_year: self.run_end_of_year_awards(old_year)))
                steps.append(("Aging the world", self.age_world_one_year))
                steps.append(("Year-end regional call-ups", self.promote_year_end_regional_candidates))
            steps.extend(self.monthly_player_business_steps())

        # Staff work is evaluated only after the completed week's cards,
        # settlement and (at month end) monthly business tasks.  Pass the
        # boundary that just finished because the calendar may already have
        # rolled into the next week/month by the time this worker runs.
        if hasattr(self, "process_staff_autonomy_boundary"):
            steps.append((
                "Staff autonomy review",
                lambda completed_month=completed_month, completed_week=completed_week: self.process_staff_autonomy_boundary(
                    completed_month, completed_week,
                ),
            ))

        # Owner objectives observe the fully settled week/month boundary. The
        # observed date is captured before the calendar rolls so a month-end
        # result is credited to its inclusive final week rather than the next
        # month's display date.
        steps.append((
            "Sealing owner objective evidence",
            lambda completed_month=completed_month, completed_week=completed_week: self.process_owner_goals_boundary(
                completed_month, completed_week,
            ),
        ))

        interval = max(1, int(self.rules.get("autosave_interval_months", 2)))
        autosave_due = (
            month_changed
            and completed_month % interval == 0
            and self.rules.get("autosave_enabled", True)
            and not getattr(self, "suppress_autosaves", False)
        )
        if include_autosave and autosave_due and hasattr(self, "run_automatic_save_cycle"):
            steps.append((
                "Creating autosave",
                lambda month_changed=month_changed: self.run_automatic_save_cycle(month_changed=month_changed),
            ))
        if month_changed and getattr(self, "spectator_mode", False) and hasattr(self, "write_spectator_decade_snapshot"):
            steps.append(("Archiving spectator decade", self.write_spectator_decade_snapshot))
        return steps, month_changed

    def advance_month(self):
        """Synchronously advance one week for tests, audits, and non-UI callers."""
        if any(self.is_event_due(event) for event in self.scheduled_events):
            self.prompt_due_event()
            return
        steps, _month_changed = self.calendar_week_steps(include_autosave=True)
        for label, task in steps:
            started = perf_counter()
            try:
                task()
            finally:
                timings = getattr(self, "_advance_task_timings", None)
                if timings is None:
                    timings = self._advance_task_timings = []
                timings.append((str(label), max(0.0, perf_counter() - started)))
                # Timing evidence is diagnostic only and deliberately bounded;
                # it is never part of the saved game state.
                del timings[:-200]
        self.refresh_all()
        self.write_log()
        if not getattr(self, "spectator_mode", False):
            self.show_pending_broadcast_notices()
        self.present_advance_notice_summary()
        self.prompt_due_event()

    def queue_advance_notice(self, category, title, body):
        """Collect routine progression notices for one post-advance summary."""
        queue = getattr(self, "advance_notice_queue", None)
        if queue is None:
            queue = self.advance_notice_queue = []
        queue.append({"category": str(category), "title": str(title), "body": str(body)})

    def present_advance_notice_summary(self):
        """Write one inbox item for routine notices; decisions stay on themed workflows."""
        notices = list(getattr(self, "advance_notice_queue", []) or [])
        self.advance_notice_queue = []
        if not notices:
            return
        sections = [f"{notice['title']}\n{notice['body']}" for notice in notices]
        body = "Routine updates from the latest calendar advance:\n\n" + "\n\n".join(sections)
        inbox = getattr(self, "inbox", None)
        if inbox is not None:
            inbox.insert(0, {"subject": "Calendar advance summary", "body": body, "type": "Simulation", "resolved": False})
        news = getattr(self, "news", None)
        if news is not None:
            news.insert(0, f"Calendar advance summary: {len(notices)} routine update(s). Open Inbox for details.")
        if getattr(self, "current_tab_name", "") == "inbox" and hasattr(self, "refresh_inbox"):
            self.refresh_inbox()

    def begin_advance_sequence(self, weeks=1, status_prefix="Advancing", on_complete=None, stop_condition=None):
        """Advance cooperatively through Tk's event queue so the app stays responsive."""
        if getattr(self, "_advance_in_progress", False):
            return False
        # Keep the source-revision guard at the common scheduling boundary as
        # well as the public spectator helpers.  A legacy caller (or a future
        # UI action) can invoke begin_advance_sequence directly; it must not
        # bypass an armed policy that was authored by an incompatible build.
        if getattr(self, "spectator_mode", False):
            raw_pause_policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
            if (
                isinstance(raw_pause_policy, dict)
                and raw_pause_policy.get("enabled")
                and not self._simulation_pause_policy_source_compatible(raw_pause_policy)
            ):
                return self.spectator_inline_notice(
                    "The saved stop policy was created by a different game revision. "
                    "Clear it or arm a new policy before fast-forwarding."
                )
        if any(self.is_event_due(event) for event in self.scheduled_events):
            self.prompt_due_event()
            return False
        weeks = max(1, int(weeks))
        self._advance_in_progress = True
        pause_policy = deepcopy(getattr(self, "rules", {}).get("simulation_pause_policy", {}))
        if isinstance(pause_policy, dict) and pause_policy.get("enabled") and pause_policy.get("stop_on_event") and not pause_policy.get("event_cursor"):
            pause_policy["event_cursor"] = self._simulation_event_keys()
        self._advance_job = {
            "total": weeks,
            "completed": 0,
            "steps": [],
            "step_index": 0,
            "prefix": status_prefix,
            "on_complete": on_complete,
            "stop_condition": stop_condition,
            "pause_policy": pause_policy,
            "stop_reason": "",
            "previous_award_suppression": getattr(self, "suppress_award_popups", False),
        }
        if getattr(self, "spectator_mode", False):
            self.suppress_award_popups = True
        self.set_advance_ui_busy(True, f"{status_prefix}: preparing world", 0)
        self.root.after(20, self._begin_queued_week)
        return True

    def _begin_queued_week(self):
        job = getattr(self, "_advance_job", None)
        if not job:
            return
        try:
            next_week = job["completed"] + 1
            month_changed = self.week >= 4
            # Automatic saves are considered only at month boundaries. The save
            # cycle itself enforces the configured two-month cadence.
            include_autosave = month_changed
            job["steps"], _ = self.calendar_week_steps(include_autosave=include_autosave)
            job["step_index"] = 0
            self._run_next_advance_step()
        except Exception:
            self._fail_advance_sequence(*sys.exc_info())

    def _run_next_advance_step(self):
        job = getattr(self, "_advance_job", None)
        if not job:
            return
        try:
            if job["step_index"] >= len(job["steps"]):
                job["completed"] += 1
                stop_reason = str(job.get("stop_reason", "") or "")
                pause_policy = job.get("pause_policy") if isinstance(job.get("pause_policy"), dict) else {}
                if not stop_reason and pause_policy.get("enabled"):
                    stop_reason = self.evaluate_simulation_pause_policy(job)
                if not stop_reason and job.get("stop_condition"):
                    condition_result = job["stop_condition"]()
                    stop_reason = str(condition_result) if isinstance(condition_result, str) else (
                        "Selected simulation stop condition met" if condition_result else ""
                    )
                job["stop_reason"] = stop_reason
                should_stop = bool(job.get("stop_requested")) or bool(stop_reason)
                if should_stop or job["completed"] >= job["total"]:
                    self.root.after(1, self._finish_advance_sequence)
                else:
                    self.root.after(1, self._begin_queued_week)
                return

            label, task = job["steps"][job["step_index"]]
            fraction = (job["completed"] + job["step_index"] / max(1, len(job["steps"]))) / job["total"]
            status = f"{job['prefix']} {job['completed'] + 1}/{job['total']}: {label}"
            self.set_advance_ui_progress(status, fraction * 100)
            started = perf_counter()
            try:
                task()
            finally:
                elapsed = perf_counter() - started
                timings = getattr(self, "_advance_task_timings", None)
                if timings is None:
                    timings = self._advance_task_timings = []
                timings.append((label, elapsed))
                del timings[:-200]
            job["step_index"] += 1
            self.root.after(1, self._run_next_advance_step)
        except Exception:
            self._fail_advance_sequence(*sys.exc_info())

    def _finish_advance_sequence(self):
        job = getattr(self, "_advance_job", None)
        if not job:
            return
        try:
            self.set_advance_ui_progress("Refreshing screens", 99)
            self.refresh_all()
            self.write_log()
            pause_reason = str(job.get("stop_reason", "") or "")
            pause_policy = job.get("pause_policy") if isinstance(job.get("pause_policy"), dict) else {}
            if pause_reason:
                policy = getattr(self, "rules", {}).get("simulation_pause_policy", {})
                if pause_policy.get("enabled") and isinstance(policy, dict):
                    policy.update({
                        "enabled": False,
                        "last_completed_boundary": {"month": int(self.month), "week": int(self.week)},
                        "stop_reason": pause_reason[:240],
                        "event_cursor": self._simulation_event_keys(),
                    })
                    self.refresh_spectator_pause_policy_ui()
                self.event_log.insert(0, f"Simulation paused at {self.format_game_date()}: {pause_reason}.")
            callback = None if job.get("stop_requested") else job.get("on_complete")
            self._complete_advance_cleanup()
            if pause_reason and getattr(self, "spectator_mode", False):
                self.set_advance_ui_progress(f"Paused: {pause_reason}", 100)
            if not getattr(self, "spectator_mode", False):
                self.show_final_month_contract_alerts()
                self.show_pending_broadcast_notices()
                self.present_advance_notice_summary()
                self.prompt_due_event()
            if callback:
                callback()
        except Exception:
            self._fail_advance_sequence(*sys.exc_info())

    def _complete_advance_cleanup(self):
        job = getattr(self, "_advance_job", None) or {}
        self.suppress_award_popups = job.get("previous_award_suppression", getattr(self, "suppress_award_popups", False))
        self._advance_job = None
        self._advance_in_progress = False
        self.set_advance_ui_busy(False, "Ready", 100)

    def _fail_advance_sequence(self, exc_type, exc_value, exc_tb):
        self._complete_advance_cleanup()
        if hasattr(self, "handle_uncaught_exception"):
            self.handle_uncaught_exception(exc_type, exc_value, exc_tb)
        else:
            raise exc_value.with_traceback(exc_tb)

    def player_ran_show_in_month(self, month):
        """Return whether the player completed a recorded event in a month.

        Deriving this from result records keeps old saves compatible and avoids a
        transient flag being lost when a game is saved between the show and the
        end-of-month rollover.
        """
        marker = f"Month {int(month)} "
        return any(
            record.get("company") == self.player_company_name
            and marker in str(record.get("date", ""))
            for record in getattr(self, "result_records", [])
        )
    def world_week_steps(self):
        """Small, ordered world tasks usable by sync and responsive UI advances."""
        steps = [
            ("Development-loan return boundary", self.process_child_promotion_loan_returns),
            ("Scouting reports", self.process_scouting_reports),
            ("Rival academies", self.process_rival_academies),
            ("Academy training", self.process_academy_week),
            ("Rebooking cancelled bouts", self.process_pending_rebookings),
            ("Regional interest", self.fluctuate_region_interest),
            ("Fighter stories", self.random_fighter_events),
            ("World activity", self.generate_weekly_world_activity),
            ("Rivalries and media", self.process_rivalry_activity),
            ("AI staff market", self.simulate_ai_staff_market),
        ]
        if self.month == 1 and self.week == 1 and not self.rules.get("opening_division_depth_seeded", False):
            steps.append(("Opening division depth", self.seed_opening_ai_division_depth))
        # Every promotion still receives exactly one monthly review, but the
        # reviews are spread evenly across the four weekly advances instead of
        # stacking development and dozens of possible cards on week four. The
        # sorted assignment is stable across saves and consumes no RNG.
        monthly_groups = (
            sorted(
                (promo for promo in self.promotions if not getattr(promo, "is_regional_feeder", False)),
                key=lambda promo: promo.name,
            ),
            sorted(
                (promo for promo in self.promotions if getattr(promo, "is_regional_feeder", False)),
                key=lambda promo: promo.name,
            ),
        )
        monthly_week_slots = {
            id(promo): index % WEEKS_PER_MONTH + 1
            for group in monthly_groups
            for index, promo in enumerate(group)
        }
        for promo in list(self.promotions):
            if getattr(promo, "is_regional_feeder", False):
                if monthly_week_slots.get(id(promo)) == self.week:
                    steps.append((
                        f"{promo.name} regional circuit",
                        lambda promo=promo: self.process_promotion_month_review(promo),
                    ))
                continue
            steps.append((
                f"{promo.name} booking",
                lambda promo=promo: self.simulate_ai_promotion_month(promo) if self.ai_should_run_show(promo) else None,
            ))
            if monthly_week_slots.get(id(promo)) == self.week:
                steps.append((
                    f"{promo.name} monthly review",
                    lambda promo=promo: self.process_promotion_month_review(promo),
                ))
        for index in range(self.independent_showcases_due()):
            steps.append((f"Independent showcase {index + 1}", self.simulate_free_agent_showcases))
        steps.extend([
            ("Transfer market", lambda: self.market_churn() if random.random() < 0.22 else None),
            ("Outside fights", lambda: self.simulate_nonexclusive_outside_fights() if random.random() < 0.18 else None),
        ])
        if not getattr(self, "spectator_mode", False):
            steps.append(("Weekly finances", self.close_finance_week))
        steps.append(("Finalising world news", lambda: setattr(self, "news", self.news[:160])))
        steps.append(("Updating gym membership", self.sync_gym_membership))
        return steps

    def seed_opening_ai_division_depth(self):
        """One-time opening-week depth contracts for imported or thin databases."""
        if self.rules.get("opening_division_depth_seeded", False):
            return 0
        self.rules["opening_division_depth_seeded"] = True
        additions = []
        for promo in [item for item in self.promotions if not getattr(item, "is_regional_feeder", False)]:
            weights = list(getattr(promo, "weight_classes", None) or WEIGHTS)
            for gender in ("Male", "Female"):
                for weight in weights:
                    if not self.promotion_division_open(promo, gender, weight):
                        continue
                    division = [fighter for fighter in promo.roster if not fighter.retired and fighter.gender == gender and fighter.weight == weight]
                    while len(division) < 6:
                        candidates = [
                            fighter for fighter in self.free_agents
                            if not fighter.retired and not fighter.injured and fighter.gender == gender and fighter.weight == weight
                            and fighter.overall <= 66
                        ]
                        if not candidates:
                            candidates = [
                                fighter for fighter in self.free_agents
                                if not fighter.retired and not fighter.injured and fighter.gender == gender and fighter.weight == weight
                                and fighter.overall <= 72
                            ]
                        if candidates:
                            desired = max(50, min(64, promo.size - 18))
                            candidates.sort(key=lambda fighter: (abs(fighter.overall - desired), fighter.potential, fighter.age))
                            fighter = random.choice(candidates[:min(12, len(candidates))])
                        else:
                            fighter = self.create_generated_fighter(2, 14, 42, 58, weight=weight, gender=gender, region=promo.region)
                            self.avoid_name_collision(fighter, self.active_fighter_names())
                            fighter.potential = min(76, max(fighter.overall + 3, fighter.potential))
                        membership_recorded = False
                        membership = getattr(self, "record_membership_event", None)
                        if callable(membership):
                            membership(
                                fighter, "join", promotion=promo,
                                reason="Opening roster depth contract",
                                source_transaction=f"opening-depth:{getattr(fighter, 'fighter_id', fighter.name)}:{promo.name}:{self.month}:{self.week}",
                            )
                            membership_recorded = True
                        if fighter in self.free_agents:
                            self.free_agents.remove(fighter)
                        fighter.purse = max(1_500, min(8_000, round(max(1_500, fighter.purse) / 500) * 500))
                        fighter.contract_months = random.randint(6, 10)
                        fighter.contract_type = "Depth Contract"
                        fighter.exclusive = True
                        fighter.ai_offer_company = ""
                        fighter.ai_offer_purse = 0
                        fighter.ai_offer_months = 0
                        fighter.ai_offer_signing_bonus = 0
                        fighter.ai_offer_deadline_month = 0
                        fighter.free_agent_months = 0
                        fighter.camp = self.suggest_camp_for_fighter(fighter, promo.region)
                        promo.roster.append(fighter)
                        self.record_contract_signing(
                            fighter, promo.name, source="Opening roster depth contract",
                            record_membership=not membership_recorded,
                        )
                        division.append(fighter)
                        additions.append((promo.name, fighter.name))
        if additions:
            summary = ", ".join(f"{name} ({sum(1 for company, _fighter in additions if company == name)})" for name in dict.fromkeys(company for company, _fighter in additions))
            headline = f"Opening roster stabilization: short-term depth contracts completed for {summary}."
            self.news.insert(0, headline)
            self.record_world_story("Opening Roster Depth", headline, "Each affected gender and weight class was brought to a six-fighter booking floor. These low-cost depth contracts expire quickly.", list(dict.fromkeys(company for company, _fighter in additions)), [fighter for _company, fighter in additions[:12]], 3)
        return len(additions)

    def process_world_week(self):
        for _label, task in self.world_week_steps():
            task()

    def process_owner_goals_boundary(self, observed_month=None, observed_week=None):
        """Seal owner-objective evidence once per completed calendar boundary.

        Goal pages are readers; this worker is the only routine path that
        records observations or terminal outcomes. It runs after the week's
        cards, finance and monthly business tasks have settled, so a goal
        cannot complete merely because a page was opened mid-week.
        """
        if getattr(self, "spectator_mode", False) or not callable(getattr(self, "owner_goal_evaluate", None)):
            return []
        observed_month = int(self.month if observed_month is None else observed_month)
        observed_week = max(1, min(WEEKS_PER_MONTH, int(self.week if observed_week is None else observed_week)))
        boundary = f"{observed_month}:{observed_week}"
        rules = getattr(self, "rules", None)
        if not isinstance(rules, dict):
            rules = self.rules = {}
        if str(rules.get("owner_goals_last_boundary", "") or "") == boundary:
            return []
        ensure = getattr(self, "ensure_owner_goal_records", None)
        if callable(ensure):
            ensure()
        outcomes = []
        for goal in getattr(self, "owner_goals", []) or []:
            if not isinstance(goal, dict) or str(goal.get("status", "Active") or "Active") in ("Complete", "Failed"):
                continue
            current = self.owner_goal_measure(goal) if callable(getattr(self, "owner_goal_measure", None)) else 0
            status, progress, reason = self.owner_goal_evaluate(
                goal, current=current, month=observed_month, week=observed_week,
                record=True, seal=True,
            )
            goal.setdefault("observations", [])
            observation_key = f"{goal.get('goal_id', 'goal')}:{boundary}"
            if not any(isinstance(row, dict) and row.get("observation_key") == observation_key for row in goal["observations"]):
                goal["observations"].append({
                    "observation_key": observation_key, "month": observed_month,
                    "week": observed_week, "value": current, "progress": progress,
                    "status": status, "reason": reason,
                })
            prior = str(goal.get("status", "Active") or "Active")
            if status in ("Complete", "Failed") and prior not in ("Complete", "Failed"):
                goal["status"] = status
                goal["outcome_month"] = observed_month
                goal["outcome_week"] = observed_week
                goal["outcome_value"] = current
                goal["outcome_reason"] = reason
                goal["resolution"] = {
                    "status": status, "month": observed_month, "week": observed_week,
                    "value": current, "reason": reason,
                }
                outcomes.append((goal, status, progress, reason))
        rules["owner_goals_last_boundary"] = boundary
        for goal, status, progress, reason in outcomes:
            label = str(goal.get("goal", "Owner objective") or "Owner objective")
            subject = f"Owner objective {status.lower()}: {label}"
            body = f"{label}\nBoundary: {self.format_game_date(observed_month, observed_week)}\nProgress: {progress}\n{reason}"
            self.inbox.insert(0, {"subject": subject, "body": body, "type": "Owner Objectives", "goal_id": goal.get("goal_id", ""), "created_month": observed_month, "created_week": observed_week, "resolved": False})
            self.news.insert(0, f"Owner objective {status.lower()}: {label}.")
        return outcomes

    def process_pending_rebookings(self):
        """Move a cancelled bout to a future card, or retain it for review.

        A Rebook Fight decision is an explicit player request, not permission
        to silently discard the bout when the calendar is temporarily full.
        Keep the plain-data entry until a suitable card exists; transition to
        ``needs_review`` once and avoid repeating Inbox/news noise on every
        calendar boundary.  Stable IDs and the saved fight snapshot remain the
        only action target, so a later retry cannot resolve a different career.
        """
        pending = list(getattr(self, "pending_rebookings", []))
        outcomes = []
        for entry in pending:
            if not isinstance(entry, dict):
                # A malformed legacy row has no safe identity to route.  Keep
                # the existing cleanup behaviour, but do not let it crash the
                # calendar worker or borrow a visible row position.
                try:
                    self.pending_rebookings.remove(entry)
                except ValueError:
                    pass
                continue
            names = list(entry.get("fighters", []) or [])
            fighter_ids = list(entry.get("fighter_ids", []) or [])

            def resolve_pending_fighter(index, name):
                reference = str(fighter_ids[index] if index < len(fighter_ids) else "" or "").strip()
                if reference and reference != str(name or ""):
                    resolver = getattr(self, "resolve_fighter", None)
                    try:
                        fighter = resolver(reference) if callable(resolver) else None
                    except (LookupError, TypeError, ValueError):
                        fighter = None
                    if fighter is None and hasattr(self, "get_fighter"):
                        try:
                            fighter = self.get_fighter(reference)
                        except (LookupError, TypeError, ValueError):
                            fighter = None
                    return fighter
                # Name-only legacy rows are compatible only when the name is
                # unique across the retained active sources.  A duplicate name
                # is ambiguous and must not rebook the other career.
                matches = []
                for source in (
                    getattr(self, "roster", []), getattr(self, "free_agents", []),
                    getattr(self, "retired_fighters", []),
                ):
                    for candidate in source or []:
                        if getattr(candidate, "name", None) == name and candidate not in matches:
                            matches.append(candidate)
                return matches[0] if len(matches) == 1 else None

            fighters = [resolve_pending_fighter(index, name) for index, name in enumerate(names)]
            future_cards = sorted(
                (event for event in self.scheduled_events
                 if (event.get("month", 1), event.get("week", 1)) > (self.month, self.week)
                 and len(event.get("fights", [])) < 16),
                key=lambda event: (event.get("month", 1), event.get("week", 1)),
            )
            target = None
            if len(fighters) == 2 and all(fighter is not None and not fighter.injured for fighter in fighters):
                for candidate in future_cards:
                    already_booked = {
                        reference for fight in candidate.get("fights", [])
                        for reference in self.event_fight_participant_references(fight) if reference != "TBA"
                    }
                    participant_tokens = {
                        str(getattr(fighter, "fighter_id", "") or fighter.name)
                        for fighter in fighters
                    }
                    if (not (participant_tokens & {str(value) for value in already_booked})
                            and not (set(names) & already_booked)
                            and all(self.fighter_available_for_date(fighter, candidate.get("month", self.month), candidate.get("week", 1)) for fighter in fighters)):
                        target = candidate
                        break
            if target:
                snapshot = entry.get("fight_snapshot", {})
                snapshot = snapshot if isinstance(snapshot, dict) else {}
                fight = {
                    "fighters": [fighter.name for fighter in fighters],
                    "fighter_ids": [str(getattr(fighter, "fighter_id", "") or "") for fighter in fighters],
                    "title": bool(snapshot.get("title", False)),
                    "divisional_title": bool(snapshot.get("divisional_title", snapshot.get("title", False))),
                    "interim": bool(snapshot.get("interim", False)),
                    "special_belt": str(snapshot.get("special_belt", "") or ""),
                    "main": bool(snapshot.get("main", False)),
                    "tier": snapshot.get("tier", entry.get("tier", "Main Card")),
                }
                for key in ("region", "city", "weight", "gender", "tournament", "tournament_name", "championship"):
                    if key in snapshot:
                        fight[key] = deepcopy(snapshot[key])
                if isinstance(snapshot.get("fight_plans"), dict):
                    fight["fight_plans"] = deepcopy(snapshot["fight_plans"])
                # The old weigh-in evidence belongs to the cancelled source
                # event.  Keep an audit link, but do not copy the terminal
                # decision into the new fight: its rescheduled card receives a
                # fresh official weigh-in and, if necessary, a fresh prompt.
                fight["rebooked_from"] = str(entry.get("rebooking_id", "") or "")
                fight["rebooked_from_event_id"] = str(entry.get("source_event_id", "") or "")
                if entry.get("source_title_miss"):
                    fight["rebooked_from_title_miss"] = deepcopy(entry["source_title_miss"])
                target["fights"].append(fight)
                self.normalize_card_order(target["fights"])
                assign_camps = getattr(self, "assign_event_camps", None)
                if callable(assign_camps):
                    assign_camps({"month": target["month"], "week": target.get("week", 1), "fights": [fight]})
                note = f"{fight['fighters'][0]} vs {fight['fighters'][1]} moved to {target['name']} after its weigh-in cancellation."
                if fight.get("title") or fight.get("divisional_title") or fight.get("special_belt"):
                    note += " Championship terms were preserved for the new official weigh-in."
                subject = "Cancelled Bout Moved"
            else:
                note = f"{' vs '.join(names)} was not rebooked because no suitable future player card was available."
                subject = "Cancelled Bout Dropped"
            if target:
                # A successful move seals the pending request exactly once.
                self.pending_rebookings.remove(entry)
                self.inbox.append({"subject": subject, "body": note, "type": "Roster", "resolved": False})
                self.news.insert(0, note)
                outcomes.append(note)
                continue

            # Keep an unresolved request in the save.  The first failed scan
            # becomes a visible review item; subsequent weekly scans remain
            # quiet until the player or calendar supplies a suitable card.
            prior_status = str(entry.get("status", "queued") or "queued")
            entry["status"] = "needs_review"
            entry["review_required"] = True
            entry["last_checked_month"] = int(getattr(self, "month", 0) or 0)
            entry["last_checked_week"] = int(getattr(self, "week", 0) or 0)
            entry["outcome"] = note
            if prior_status != "needs_review":
                review_note = note.replace("was not rebooked", "is awaiting rebooking review")
                entry["review_reason"] = review_note
                self.inbox.append({"subject": "Rebooking Needs Review", "body": review_note, "type": "Roster", "resolved": False})
                self.news.insert(0, review_note)
                outcomes.append(review_note)
        return outcomes

    def academy_defaults(self):
        return {
            "schema_version": 6,
            "owned": False, "level": 0, "capacity": 0, "prospects": [], "talent_pool": [],
            "weekly_cost": 0, "auto_train": True, "network_weeks": 0, "network_active": False,
            "network_region": "", "network_scout": "", "network_scout_id": "", "network_scout_skill": 0,
            "showcase_weeks": 0, "auto_showcases": True, "auto_card_min_bouts": 2, "last_scout_report": "",
            "philosophy": "Balanced MMA", "reputation": 10, "card_history": [], "alumni": [],
            "total_cards": 0, "total_bouts": 0, "total_graduates": 0, "build_spend": 0, "operating_spend": 0,
            "signing_spend": 0, "upgrade_spend": 0, "network_spend": 0,
            "lost_leads": [], "last_alumni_review_month": 0,
            "network_potential_skill": 0, "network_networking": 0, "network_reliability": 0,
            "network_leads_found": 0, "last_showcase_week": -99, "last_showcase_recap": "",
            "development_events": [], "active_challenge": {}, "challenge_history": [],
            "challenge_count": 0, "last_challenge_week": -99,
            "season_history": [], "released_rights": [], "departed_prospects": [],
            "competition_history": [], "total_tournaments": 0,
            # An Academy Coach is an explicit assignment, never an implicit
            # replacement for the legacy gym/head-coach Trainer fallback.
            "coach_assignment": {}, "coach_assignment_review": "",
        }

    def repair_academy(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        if not isinstance(academy, dict):
            academy = {}
        previous_schema = int(academy.get("schema_version", 1) or 1)
        for key, value in self.academy_defaults().items():
            academy.setdefault(key, value if not isinstance(value, list) else [])
        # JSON saves can legitimately contain null for collections written by
        # older builds.  Repair those values before any list operation, and
        # discard malformed rows rather than turning strings into character
        # lists or crashing an otherwise recoverable career.
        for key in (
            "prospects", "talent_pool", "card_history", "alumni", "lost_leads",
            "development_events", "challenge_history", "season_history", "released_rights",
            "departed_prospects", "competition_history",
        ):
            rows = academy.get(key)
            academy[key] = [row for row in rows if isinstance(row, dict)] if isinstance(rows, list) else []
        if academy.get("network_scout") and not academy.get("network_scout_id"):
            matches = [
                member for member in getattr(self, "staff", []) or []
                if isinstance(member, dict)
                and member.get("role") == "Scout" and member.get("name") == academy.get("network_scout")
            ]
            if len(matches) == 1:
                academy["network_scout_id"] = self.scout_identity_key(matches[0])
        if academy.get("owned"):
            academy["capacity"] = max(8, academy.get("capacity", 8))
            academy["weekly_cost"] = max(4500, academy.get("weekly_cost", 4500))
            academy["reputation"] = max(1, min(100, int(academy.get("reputation", 10))))
        academy["card_history"] = academy["card_history"][:24]
        academy["alumni"] = academy["alumni"][:100]
        academy["lost_leads"] = academy["lost_leads"][:30]
        academy["total_cards"] = max(int(academy.get("total_cards", 0)), len(academy["card_history"]))
        if academy["card_history"] and not academy.get("total_bouts"):
            academy["total_bouts"] = sum(len(card.get("results", [])) for card in academy["card_history"])
        for prospect in academy.get("prospects", []) + academy.get("talent_pool", []):
            self.repair_academy_prospect(prospect)
        if previous_schema < 3 and academy.get("owned"):
            # Older saves ran the entire squad every other week. Move the next
            # automatic card onto the balanced youth schedule without deleting
            # any existing records or development.
            academy["showcase_weeks"] = max(6, int(academy.get("showcase_weeks", 8) or 8))
        academy["auto_card_min_bouts"] = max(1, min(12, int(academy.get("auto_card_min_bouts", 2) or 2)))
        academy["challenge_history"] = academy["challenge_history"][:40]
        academy["challenge_count"] = max(0, int(academy.get("challenge_count", 0) or 0))
        academy["last_challenge_week"] = int(academy.get("last_challenge_week", -99) or -99)
        if not isinstance(academy.get("active_challenge"), dict):
            academy["active_challenge"] = {}
        if not isinstance(academy.get("coach_assignment"), dict):
            academy["coach_assignment"] = {}
        academy["coach_assignment_review"] = str(academy.get("coach_assignment_review", "") or "")
        academy["total_tournaments"] = max(0, int(academy.get("total_tournaments", 0) or 0))
        academy["schema_version"] = 6
        return academy

    def academy_philosophy_fields(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        return {
            "Balanced MMA": ("striking", "wrestling", "grappling", "cardio", "fight_iq"),
            "Striking Academy": ("striking", "power", "cardio", "chin"),
            "Wrestling Pipeline": ("wrestling", "cardio", "fight_iq", "toughness"),
            "Submission School": ("grappling", "fight_iq", "wrestling", "toughness"),
            "Athletic Development": ("cardio", "power", "toughness", "chin"),
            "Multi-Sport Pathway": ("striking", "wrestling", "grappling", "fight_iq"),
        }.get(academy.get("philosophy", "Balanced MMA"), ("striking", "wrestling", "grappling"))

    def academy_weight_band(self, weight):
        if weight in ("Strawweight", "Flyweight", "Bantamweight"):
            return "Youth Flyweight"
        if weight in ("Featherweight", "Lightweight"):
            return "Youth Lightweight"
        if weight in ("Welterweight", "Middleweight"):
            return "Youth Welterweight"
        return "Youth Heavyweight"

    def academy_region_distance(self, region):
        if region == self.player_region:
            return 0
        visited = {self.player_region}
        frontier = [(self.player_region, 0)]
        while frontier:
            current, distance = frontier.pop(0)
            for linked in REGIONAL_MIGRATION_LINKS.get(current, []):
                if linked == region:
                    return distance + 1
                if linked in REGIONS and linked not in visited:
                    visited.add(linked)
                    frontier.append((linked, distance + 1))
        return 3

    def academy_scouting_network_cost(self, region):
        distance = self.academy_region_distance(region)
        return round((12_000 + self.academy.get("level", 1) * 2_500) * (1 + distance * 0.55))

    def academy_signing_cost(self, prospect):
        distance = self.academy_region_distance(prospect.get("region", self.player_region))
        potential = prospect.get("potential", 70)
        rating = prospect.get("rating", 40)
        upside = max(0, potential - rating)
        high_potential = max(0, potential - 78)
        elite_potential = max(0, potential - 88)
        current = max(0, rating - 35)
        confidence_tax = max(0, prospect.get("scout_confidence", 50) - 55) * 55
        base = 5_500 + current * 135 + upside * 210 + high_potential * 720 + elite_potential * 1_250 + confidence_tax
        reputation_discount = max(0.88, 1 - max(0, self.academy.get("reputation", 10) - 30) / 500)
        return round(base * (1 + distance * 0.42) * reputation_discount)

    def academy_scout_range(self, value, confidence, minimum=1, maximum=99):
        spread = max(2, round((100 - confidence) / 7))
        low = max(minimum, value - random.randint(max(1, spread // 2), spread))
        high = min(maximum, value + random.randint(max(1, spread // 2), spread + 2))
        return low, high

    def academy_skill_defaults(self, prospect):
        rating = prospect.get("rating", 42)
        fields = ("striking", "wrestling", "grappling", "cardio", "chin", "power", "toughness", "fight_iq")
        for index, key in enumerate(fields):
            if key not in prospect:
                # Legacy-save migration must never consume the live simulation RNG.
                noise = self.academy_stable_number(prospect, f"skill-{index}", -8, 8)
                prospect[key] = max(20, min(95, rating + noise))
        return prospect

    def academy_stable_number(self, prospect, salt, minimum, maximum):
        """Return a process-stable value for deterministic old-save repair."""
        text = f"{prospect.get('name', 'Unknown')}|{prospect.get('region', self.player_region)}|{salt}"
        value = sum((index + 1) * ord(char) for index, char in enumerate(text))
        return minimum + value % max(1, maximum - minimum + 1)

    def academy_prospect_id(self, prospect):
        text = f"{prospect.get('name', 'Unknown')}|{prospect.get('region', self.player_region)}|{prospect.get('age', 0)}"
        value = sum((index + 11) * ord(char) for index, char in enumerate(text))
        return f"academy-{value:08x}"

    def repair_academy_prospect(self, prospect):
        # Avoid random-valued setdefault calls here: this repair method is also
        # used by UI refreshes, and merely opening the academy must not advance
        # the global simulation RNG or alter future fight outcomes.
        static_defaults = {
            "name": "Unknown Prospect", "region": self.player_region, "gender": "Male",
            "plan": "Automatic", "amateur_w": 0, "amateur_l": 0, "amateur_d": 0,
            "amateur_history": [], "amateur_bout_records": [], "weeks": 0, "development": 0,
            "fatigue": 0, "injured": 0, "scout_confidence": 45,
            "training_intensity": "Standard", "preferred_sport": "MMA", "rating_history": [],
            "training_log": [], "milestones": [], "last_amateur_bout": {}, "opponent_counts": {},
            "last_amateur_week": -99, "plateau_weeks": 0, "academy_member": False,
            "bout_experience": 0, "last_development": "No recorded gain yet",
            "medical_history": [], "scouting_observations": 0, "signed_cost": 0,
            "development_plan": {}, "development_reports": [], "amateur_titles": [],
            "promise": {}, "retention_history": [],
            "move_mastery": {},
        }
        for key, value in static_defaults.items():
            if key not in prospect:
                prospect[key] = list(value) if isinstance(value, list) else dict(value) if isinstance(value, dict) else value
        for key in ("amateur_history", "amateur_bout_records", "rating_history", "training_log", "milestones", "medical_history",
                    "development_reports", "amateur_titles", "retention_history"):
            if not isinstance(prospect.get(key), list):
                prospect[key] = []
        for key in ("last_amateur_bout", "opponent_counts", "development_plan", "promise", "move_mastery"):
            if not isinstance(prospect.get(key), dict):
                prospect[key] = {}

        def normalized_int(key, default, minimum=None, maximum=None):
            try:
                value = int(prospect.get(key, default))
            except (TypeError, ValueError):
                value = default
            if minimum is not None:
                value = max(minimum, value)
            if maximum is not None:
                value = min(maximum, value)
            prospect[key] = value
            return value

        def normalized_float(key, default, minimum=None, maximum=None):
            try:
                value = float(prospect.get(key, default))
            except (TypeError, ValueError):
                value = default
            if minimum is not None:
                value = max(minimum, value)
            if maximum is not None:
                value = min(maximum, value)
            prospect[key] = value
            return value
        if "age" not in prospect:
            prospect["age"] = self.academy_stable_number(prospect, "age", 12, 15)
        normalized_int("age", 15, 10, 40)
        if "rating" not in prospect:
            prospect["rating"] = self.academy_stable_number(prospect, "rating", 38, 54)
        normalized_int("rating", 42, 20, 99)
        if "potential" not in prospect:
            prospect["potential"] = max(prospect["rating"] + 8, self.academy_stable_number(prospect, "potential", 62, 92))
        normalized_int("potential", max(62, prospect["rating"] + 8), prospect["rating"], 99)
        if "weight" not in prospect:
            prospect["weight"] = WEIGHTS[self.academy_stable_number(prospect, "weight", 0, len(WEIGHTS) - 1)]
        if prospect.get("weight") not in WEIGHTS:
            prospect["weight"] = "Lightweight"
        if "weeks_to_sign" not in prospect:
            prospect["weeks_to_sign"] = self.academy_stable_number(prospect, "window", 2, 3)
        normalized_int("weeks_to_sign", 2, 0, 52)
        if "dedication" not in prospect:
            prospect["dedication"] = self.academy_stable_number(prospect, "dedication", 40, 92)
        normalized_int("dedication", 55, 0, 99)
        if "coachability" not in prospect:
            prospect["coachability"] = self.academy_stable_number(prospect, "coachability", 38, 94)
        normalized_int("coachability", 55, 0, 99)
        if "confidence" not in prospect:
            prospect["confidence"] = self.academy_stable_number(prospect, "confidence", 45, 72)
        normalized_int("confidence", 55, 0, 99)
        normalized_int("scout_confidence", 45, 0, 100)
        normalized_int("fatigue", 0, 0, 100)
        normalized_int("injured", 0, 0)
        prospect.setdefault("prospect_id", self.academy_prospect_id(prospect))
        prospect.setdefault("amateur_weight", self.academy_weight_band(prospect.get("weight", "Lightweight")))
        prospect.setdefault("joined_month", self.month if hasattr(self, "month") else 1)
        prospect.setdefault("baseline_rating", prospect.get("rating", 42))
        stable_personality = self.academy_stable_number(prospect, "youth-personality", 0, 6)
        prospect.setdefault("youth_trait", (
            "Ambitious", "Patient", "Loyal", "Big-Stage Performer", "Homesick",
            "Academically Focused", "Volatile",
        )[stable_personality])
        prospect.setdefault("loyalty", self.academy_stable_number(prospect, "loyalty", 48, 82))
        prospect.setdefault("satisfaction", self.academy_stable_number(prospect, "satisfaction", 52, 78))
        prospect.setdefault("competition_tier", "Local")
        prospect.setdefault("amateur_quality_points", 0)
        prospect.setdefault("strength_of_schedule", 0.0)
        prospect.setdefault("notable_wins", 0)
        prospect.setdefault("retention_status", "Committed")
        prospect.setdefault("last_retention_week", -99)
        normalized_int("loyalty", 60, 0, 100)
        normalized_int("satisfaction", 60, 0, 100)
        normalized_int("amateur_quality_points", 0, 0)
        normalized_float("strength_of_schedule", 0.0, 0.0, 100.0)
        normalized_int("notable_wins", 0, 0)
        normalized_int("last_retention_week", -99, -99)
        if prospect.get("competition_tier") not in self.ACADEMY_COMPETITION_TIERS:
            prospect["competition_tier"] = "Local"
        if prospect.get("retention_status") not in ("Committed", "At risk", "Departed", "Graduated"):
            prospect["retention_status"] = "Committed"
        plan = prospect.get("development_plan") or {}
        if plan:
            try:
                duration = int(plan.get("duration", 8) or 8)
                weeks_remaining = int(plan.get("weeks_remaining", duration) or 0)
            except (TypeError, ValueError):
                prospect["development_plan"] = {}
            else:
                duration = min((4, 8, 12), key=lambda value: abs(value - max(4, min(12, duration))))
                plan["duration"] = duration
                plan["weeks_remaining"] = max(0, min(duration, weeks_remaining))
                if not isinstance(plan.get("start_skills", {}), dict):
                    plan["start_skills"] = {}
        self.academy_skill_defaults(prospect)
        if "current_range" not in prospect:
            spread = max(2, round((100 - prospect["scout_confidence"]) / 7))
            prospect["current_range"] = (max(20, prospect["rating"] - spread), min(99, prospect["rating"] + spread))
        if "potential_range" not in prospect:
            spread = max(2, round((100 - prospect["scout_confidence"]) / 7))
            prospect["potential_range"] = (max(45, prospect["potential"] - spread - 1), min(99, prospect["potential"] + spread + 1))
        prospect["signing_cost"] = prospect.get("signing_cost") or self.academy_signing_cost(prospect)
        return prospect

    def create_academy_scout_prospect(self, scout_score=45, region=None):
        region = region or self.player_region
        fighter = self.create_generated_fighter(0, 4, 32, 53, region=region)
        existing = self.active_fighter_names()
        existing.update(item.get("name", "") for item in getattr(self, "academy", {}).get("prospects", []))
        existing.update(item.get("name", "") for item in getattr(self, "academy", {}).get("talent_pool", []))
        self.avoid_name_collision(fighter, existing)
        fighter.age = random.randint(12, 15)
        academy_reputation = getattr(self, "academy", {}).get("reputation", 10)
        confidence = max(30, min(94, round(scout_score + academy_reputation * 0.08 + random.randint(-12, 10))))
        quality_rolls = 1 + int(scout_score >= 70)
        potential_roll = max(random.randint(60, 94) for _ in range(quality_rolls))
        # Scout quality should affect immediate readiness as well as ceiling and
        # report confidence; the tighter scale makes elite networks visibly
        # better at identifying athletes who can contribute sooner.
        quality_shift = round((scout_score - 50) / 10 + (academy_reputation - 20) / 35)
        target_rating = max(30, min(60, fighter.overall + quality_shift + random.randint(-2, 2)))
        stat_shift = target_rating - fighter.overall
        potential_bonus = round((scout_score - 50) / 25 + (academy_reputation - 20) / 55)
        potential = max(target_rating + 8, min(98, potential_roll + potential_bonus))
        # Exceptional academies can occasionally uncover a genuine generational
        # teenager.  This needs both a strong scout and some academy credibility,
        # so 99-100 potential stays a memorable find rather than normal output.
        elite_chance = 0.0
        if scout_score >= 78 and academy_reputation >= 35:
            elite_chance = min(0.055, 0.006 + (scout_score - 78) / 380 + (academy_reputation - 35) / 900)
        if random.random() < elite_chance:
            potential = random.choices((96, 97, 98, 99, 100), weights=(45, 33, 18, 3, 1), k=1)[0]
        prospect = {
            "name": fighter.name, "age": fighter.age, "potential": potential,
            "region": region, "gender": fighter.gender, "weight": fighter.weight,
            "amateur_weight": self.academy_weight_band(fighter.weight), "rating": target_rating,
            "style": fighter.style, "stance": fighter.stance, "trait": fighter.trait,
            "nationality": fighter.nationality, "birth_country": fighter.birth_country,
            "birth_region": fighter.birth_region, "hometown": fighter.hometown, "residence": fighter.residence,
            "training_location": fighter.training_location, "fighting_base": fighter.fighting_base,
            "cultural_connections": fighter.cultural_connections, "regional_popularity": fighter.regional_popularity,
            "scout_confidence": confidence, "weeks_to_sign": random.randint(2, 3),
            "striking": max(20, min(95, fighter.striking + stat_shift)),
            "wrestling": max(20, min(95, fighter.wrestling + stat_shift)),
            "grappling": max(20, min(95, fighter.grappling + stat_shift)),
            "cardio": max(20, min(95, fighter.cardio + stat_shift)),
            "chin": max(20, min(95, fighter.chin + stat_shift)),
            "power": max(20, min(95, fighter.power + stat_shift)),
            "toughness": max(20, min(95, fighter.toughness + stat_shift)),
            "fight_iq": max(20, min(95, fighter.fight_iq + stat_shift)),
            "dedication": random.randint(35, 96), "coachability": random.randint(35, 96),
            "confidence": random.randint(42, 70), "source_network": region,
            "source_scout_quality": round(scout_score),
        }
        prospect["current_range"] = self.academy_scout_range(target_rating, confidence, 20, 99)
        prospect["potential_range"] = self.academy_scout_range(potential, confidence, 45, 99)
        return self.repair_academy_prospect(prospect)

    def refine_academy_lead(self, prospect, academy):
        """Improve report accuracy while a lead remains on the live shortlist."""
        self.repair_academy_prospect(prospect)
        skill = academy.get("network_scout_skill", 45)
        potential_skill = academy.get("network_potential_skill", skill)
        reliability = academy.get("network_reliability", skill)
        distance = self.academy_region_distance(prospect.get("region", self.player_region))
        gain = max(1, round((skill + potential_skill + reliability) / 96 + academy.get("reputation", 10) / 45 - distance * 0.35))
        prospect["scout_confidence"] = min(97, prospect.get("scout_confidence", 45) + gain)
        prospect["scouting_observations"] = prospect.get("scouting_observations", 0) + 1
        spread = max(1, round((101 - prospect["scout_confidence"]) / 8))
        prospect["current_range"] = (max(20, prospect["rating"] - spread), min(99, prospect["rating"] + spread))
        prospect["potential_range"] = (max(45, prospect["potential"] - spread - 1), min(99, prospect["potential"] + spread + 1))
        return prospect

    def academy_lead_report(self, prospect):
        self.repair_academy_prospect(prospect)
        current = prospect.get("current_range", (prospect["rating"], prospect["rating"]))
        potential = prospect.get("potential_range", (prospect["potential"], prospect["potential"]))
        strongest = sorted(("striking", "wrestling", "grappling", "cardio", "power", "fight_iq"), key=lambda key: prospect.get(key, 40), reverse=True)[:3]
        personality_accuracy = prospect.get("scout_confidence", 45)
        personality = (
            f"Dedication approximately {max(20, prospect['dedication'] - (100-personality_accuracy)//8)}-"
            f"{min(99, prospect['dedication'] + (100-personality_accuracy)//8)}; coachability approximately "
            f"{max(20, prospect['coachability'] - (100-personality_accuracy)//8)}-{min(99, prospect['coachability'] + (100-personality_accuracy)//8)}."
        )
        rival = prospect.get("rival_offer") if isinstance(prospect.get("rival_offer"), dict) else {}
        rival_line = f"\nRecruitment pressure: {rival.get('promotion')} has made a competing approach." if rival else ""
        return (
            f"{prospect['name']} — {prospect['gender']} age {prospect['age']} from {prospect['region']}\n\n"
            f"Projected current ability: {current[0]}-{current[1]}\nProjected potential: {potential[0]}-{potential[1]}\n"
            f"Report confidence: {personality_accuracy}% | Signing cost: ${prospect.get('signing_cost', 0):,} | Decision window: {prospect.get('weeks_to_sign', 0)} week(s)\n\n"
            f"Observed strengths: {', '.join(key.replace('_', ' ').title() for key in strongest)}.\n{personality}\n\n"
            f"Likely pathway: {self.academy_preferred_sport(prospect)}. Reports narrow each week while the lead remains available.{rival_line}"
        )

    def academy_recruitment_label(self, prospect):
        self.repair_academy_prospect(prospect)
        current = prospect.get("current_range", (prospect.get("rating", 40), prospect.get("rating", 40)))
        potential = prospect.get("potential_range", (prospect.get("potential", 70), prospect.get("potential", 70)))
        gender = str(prospect.get("gender", "")).strip()[:1].upper() or "?"
        return (
            f"{prospect['name']} | {gender} | {prospect['age']} | {prospect['region']} | {prospect['amateur_weight']} | "
            f"Cur {current[0]}-{current[1]} | Pot {potential[0]}-{potential[1]} | "
            f"Conf {prospect.get('scout_confidence', 0)}% | ${prospect.get('signing_cost', 0):,} | {prospect.get('weeks_to_sign', 0)}w"
        )

    def start_academy_network(self, region, scout_name):
        academy = self.repair_academy(getattr(self, "academy", {}))
        if not academy.get("owned"):
            return False, "Build the academy first."
        if academy.get("network_weeks", 0) > 0 or academy.get("network_active"):
            return False, "Cancel the current youth network before setting up a new one."
        scout_key = self.scout_identity_key(scout_name)
        scout = next((member for member in (getattr(self, "staff", []) or [])
                      if isinstance(member, dict) and member.get("role") == "Scout" and self.scout_identity_key(member) == scout_key), None)
        if not scout:
            return False, "Hire a Scout from the Staff screen before establishing a youth network."
        if self.scout_workload(scout) >= self.scout_capacity(scout):
            return False, f"{scout_name} has no free assignment slot for an academy network. Finish or cancel another scouting assignment first."
        cost = self.academy_scouting_network_cost(region)
        if self.cash < cost:
            return False, f"Need ${cost:,} to establish a {region} youth scouting network."
        scout_skill = scout.get("fighter_judging", scout.get("skill", 45))
        potential_skill = scout.get("potential_judging", scout.get("skill", 45))
        networking = scout.get("networking", scout.get("skill", 45))
        reliability = round((scout.get("reliability", scout.get("skill", 45)) + scout.get("professionalism", scout.get("skill", 45))) / 2)
        self.cash -= cost
        self.record_finance_transaction(f"Academy scouting network: {region}", costs=cost)
        academy.update({"network_weeks": 8, "network_active": False, "network_region": region, "network_scout": scout.get("name", scout_name),
                        "network_scout_id": self.scout_identity_key(scout),
                        "network_scout_skill": round(scout_skill), "network_potential_skill": round(potential_skill),
                        "network_networking": round(networking), "network_reliability": reliability, "talent_pool": []})
        academy["network_spend"] = academy.get("network_spend", 0) + cost
        academy["last_scout_report"] = f"{academy['network_scout']} is setting up a {region} youth network. Setup takes 8 weeks."
        return True, academy["last_scout_report"]

    def cancel_academy_network(self):
        academy = self.repair_academy(getattr(self, "academy", {}))
        if not academy.get("network_active") and academy.get("network_weeks", 0) <= 0:
            return False, "There is no youth scouting network to cancel."
        region = academy.get("network_region") or "regional"
        lead_count = len(academy.get("talent_pool", []))
        academy.update({"network_weeks": 0, "network_active": False, "network_region": "", "network_scout": "", "network_scout_id": "", "network_scout_skill": 0,
                        "network_potential_skill": 0, "network_networking": 0, "network_reliability": 0, "talent_pool": []})
        academy["last_scout_report"] = f"Cancelled the {region} youth network. {lead_count} open lead(s) were removed."
        return True, academy["last_scout_report"]

    def academy_training_fields(self, plan, prospect=None):
        if plan == "Automatic" and prospect:
            weak = sorted(("striking", "wrestling", "grappling", "cardio", "fight_iq"), key=lambda key: prospect.get(key, 45))[:2]
            recommendation = self.recommended_academy_focus(prospect)
            recommended_fields = () if recommendation in ("Automatic", "Balanced") else self.academy_training_fields(recommendation, prospect)
            return tuple(dict.fromkeys(weak + list(recommended_fields) + list(self.academy_philosophy_fields())))
        return {
            "Balanced": ("striking", "wrestling", "grappling", "cardio", "fight_iq"),
            "Boxing": ("striking", "power", "chin"), "Muay Thai": ("striking", "power", "toughness"),
            "Wrestling": ("wrestling", "cardio", "fight_iq"), "BJJ": ("grappling", "fight_iq", "toughness"),
            "Judo": ("wrestling", "grappling", "fight_iq"), "Sambo": ("wrestling", "grappling", "power"),
            "Clinch": ("wrestling", "striking", "toughness"), "Cardio": ("cardio", "toughness"),
            "Strength": ("power", "toughness", "chin"), "Fight IQ": ("fight_iq", "cardio"),
        }.get(plan, ("striking", "wrestling", "grappling"))

    def academy_preferred_sport(self, prospect):
        self.repair_academy_prospect(prospect)
        scores = {
            "Boxing": prospect.get("striking", 40) + prospect.get("power", 40) * 0.35,
            "Kickboxing": prospect.get("striking", 40) + prospect.get("cardio", 40) * 0.22,
            "Muay Thai": prospect.get("striking", 40) + prospect.get("toughness", 40) * 0.28,
            "Wrestling": prospect.get("wrestling", 40) * 1.25 + prospect.get("cardio", 40) * 0.18,
            "Brazilian Jiu-Jitsu": prospect.get("grappling", 40) * 1.25 + prospect.get("fight_iq", 40) * 0.18,
            "MMA": min(prospect.get("striking", 40), prospect.get("wrestling", 40), prospect.get("grappling", 40)) * 0.8 + prospect.get("fight_iq", 40) * 0.4,
        }
        preferred = max(scores, key=scores.get)
        prospect["preferred_sport"] = preferred
        return preferred

    def academy_graduation_readiness(self, prospect):
        self.repair_academy_prospect(prospect)
        bouts = self.academy_amateur_fight_count(prospect)
        age_score = max(0, min(28, (prospect.get("age", 15) - 15) * 9))
        ability = max(0, min(30, (prospect.get("rating", 40) - 42) * 1.2))
        quality_points = int(prospect.get("amateur_quality_points", 0) or 0)
        schedule = self.academy_strength_of_schedule(prospect)
        experience = min(18, bouts * 2) + min(8, quality_points / 5) + min(4, len(prospect.get("amateur_titles", [])) * 2)
        schedule_bonus = max(-2, min(4, (schedule - prospect.get("rating", 40)) / 4)) if schedule else 0
        mentality = (prospect.get("confidence", 55) + prospect.get("dedication", 55)) / 12
        injury_drag = prospect.get("injured", 0) * 3 + max(0, prospect.get("fatigue", 0) - 55) / 4
        return max(0, min(100, round(age_score + ability + experience + schedule_bonus + mentality - injury_drag)))

    def academy_graduation_recommendation(self, prospect):
        """A scout-style call on whether a prospect should turn professional now.

        Returns (label, reason). Labels: TOO YOUNG, NEEDS BOUTS, KEEP DEVELOPING,
        ALMOST READY, GRADUATE NOW."""
        self.repair_academy_prospect(prospect)
        age = int(prospect.get("age", 15) or 15)
        if age < 16:
            return "TOO YOUNG", "Must be at least 16 to turn professional."
        readiness = self.academy_graduation_readiness(prospect)
        rating = int(prospect.get("rating", 40) or 40)
        potential = int(prospect.get("potential", 70) or 70)
        gap = max(0, potential - rating)
        bouts = self.academy_amateur_fight_count(prospect)
        if bouts < 3 and age < 20:
            return "NEEDS BOUTS", f"Only {bouts} amateur bout(s); showcase experience will sharpen them before they turn pro."
        if readiness >= 78 and (gap <= 6 or age >= 21):
            return "GRADUATE NOW", f"Near their ceiling ({rating}/{potential}) with {readiness}% readiness — ready to turn professional."
        if readiness >= 62 and gap <= 12:
            return "ALMOST READY", f"{readiness}% ready; a little more polish or a bout or two completes the development."
        return "KEEP DEVELOPING", f"Still {gap} points from a {potential} ceiling; keep training and building the amateur record."

    def process_academy_graduations(self, academy):
        """Fire a one-time 'ready to turn pro' alert and, if the player opts in,
        auto-graduate clearly-ready adult prospects into the MMA roster."""
        auto = bool(academy.get("auto_graduate", False))
        spectator = getattr(self, "spectator_mode", False)
        auto_graduated = 0
        for prospect in list(academy.get("prospects", [])):
            label, reason = self.academy_graduation_recommendation(prospect)
            ready = label == "GRADUATE NOW"
            if ready and not prospect.get("graduation_alerted"):
                prospect["graduation_alerted"] = True
                if not spectator:
                    self.inbox.append({
                        "subject": f"Academy Prospect Ready - {prospect['name']}",
                        "body": f"{prospect['name']} ({prospect.get('age')}) is ready to turn professional. {reason} "
                                f"Promote them from the Fight Academy, or turn on Auto Graduate to have staff handle it.",
                        "type": "Academy", "fighter": prospect["name"], "resolved": False,
                    })
            elif not ready:
                # Reset so a later return to readiness re-alerts once.
                prospect["graduation_alerted"] = False
            # Auto-graduation is deliberately limited per week so a backlog does
            # not dump a whole intake onto the roster at once.
            if auto and ready and int(prospect.get("age", 0) or 0) >= 18 and auto_graduated < 2:
                ok, note, _fighter = self.promote_academy_prospect_to_sport(prospect, "MMA")
                if ok:
                    if prospect in academy.get("prospects", []):
                        academy["prospects"].remove(prospect)
                    auto_graduated += 1
                    self.news.insert(0, f"Auto-graduation: {note}")

    def academy_prospect_trend(self, prospect):
        history = prospect.get("rating_history", [])
        if len(history) < 2:
            return prospect.get("rating", 40) - prospect.get("baseline_rating", prospect.get("rating", 40))
        return history[-1].get("rating", prospect.get("rating", 40)) - history[-2].get("rating", prospect.get("rating", 40))

    def recommended_academy_focus(self, prospect):
        self.repair_academy_prospect(prospect)
        if prospect.get("grappling", 0) >= max(prospect.get("striking", 0), prospect.get("wrestling", 0)) + 5:
            return "BJJ"
        if prospect.get("wrestling", 0) >= max(prospect.get("striking", 0), prospect.get("grappling", 0)) + 5:
            return "Wrestling"
        if prospect.get("striking", 0) >= max(prospect.get("wrestling", 0), prospect.get("grappling", 0)) + 5:
            return "Boxing"
        if prospect.get("cardio", 0) < prospect.get("rating", 40) - 3:
            return "Cardio"
        if prospect.get("fight_iq", 0) < prospect.get("rating", 40) - 3:
            return "Fight IQ"
        return "Automatic" if prospect.get("potential", 70) - prospect.get("rating", 40) >= 12 else "Balanced"

    def academy_focus_recommendation(self, prospect):
        focus = self.recommended_academy_focus(prospect)
        fields = self.academy_training_fields(focus if focus != "Automatic" else "Balanced", prospect)
        weakest = min(("striking", "wrestling", "grappling", "cardio", "fight_iq"), key=lambda key: prospect.get(key, 45))
        if focus in ("Boxing", "Wrestling", "BJJ"):
            reason = f"Build around the athlete's strongest base while improving {weakest.replace('_', ' ')}."
        elif focus in ("Cardio", "Fight IQ"):
            reason = f"{focus} is limiting the prospect's current readiness and consistency."
        else:
            reason = f"Balanced work is appropriate; {weakest.replace('_', ' ')} is the main weakness."
        return focus, reason, fields

    def record_academy_progress(self, prospect, reason="Monthly development review"):
        snapshot = {"month": self.month, "week": self.week, "rating": prospect.get("rating", 40),
                    "readiness": self.academy_graduation_readiness(prospect), "reason": reason}
        for key in ("striking", "wrestling", "grappling", "cardio", "chin", "power", "toughness", "fight_iq"):
            snapshot[key] = prospect.get(key, 40)
        history = prospect.setdefault("rating_history", [])
        if history and (history[-1].get("month"), history[-1].get("week")) == (self.month, self.week):
            history[-1] = snapshot
        else:
            history.append(snapshot)
        prospect["rating_history"] = history[-60:]
        return snapshot

    ACADEMY_PLAN_OBJECTIVES = (
        "Balanced Growth", "Fix a Weakness", "Tournament Preparation",
        "Graduation Preparation", "Recovery Block",
    )

    def academy_coach_members(self):
        """Return active Academy Coach employees in stable roster order."""
        return [
            member for member in (getattr(self, "staff", []) or [])
            if isinstance(member, dict)
            and member.get("role") == "Academy Coach"
            and self.staff_contract_remaining(member) > 0
        ]

    def academy_coach_assignment(self, academy=None):
        """Read the one-coach/one-cohort assignment without mutating it."""
        academy = academy if isinstance(academy, dict) else getattr(self, "academy", {}) or {}
        assignment = academy.get("coach_assignment", {})
        return deepcopy(assignment) if isinstance(assignment, dict) else {}

    def assign_academy_coach(self, staff_id, prospect_id, academy=None):
        """Explicitly assign one hired coach to one existing development block.

        Assignment is deliberately separate from hiring and from plan creation:
        the player can review the current cohort before committing the coach.
        """
        academy = self.repair_academy(academy if isinstance(academy, dict) else getattr(self, "academy", {}))
        staff_key = str(staff_id or "").strip()
        prospect_key = str(prospect_id or "").strip()
        coach = next((member for member in self.academy_coach_members()
                      if str(member.get("staff_id", "")) == staff_key), None)
        if not coach:
            return False, "Hire an active Academy Coach before assigning a development block."
        prospect = next((item for item in academy.get("prospects", [])
                         if str(item.get("prospect_id", "")) == prospect_key), None)
        if not prospect:
            return False, "Select a current academy prospect."
        current = self.academy_coach_assignment(academy)
        if current and str(current.get("staff_id", "")) == staff_key and str(current.get("prospect_id", "")) == prospect_key:
            return True, f"{coach.get('name', 'The Academy Coach')} is already assigned to {prospect.get('name', 'this prospect')}."
        if current and current.get("staff_id") and current.get("prospect_id"):
            current_plan = next((item.get("development_plan") or {} for item in academy.get("prospects", [])
                                 if str(item.get("prospect_id", "")) == str(current.get("prospect_id", ""))), {})
            if current_plan and int(current_plan.get("weeks_remaining", 0) or 0) > 0:
                return False, "This coach is already supervising an active development block. Complete or end that block before reassigning them."
        academy["coach_assignment"] = {
            "staff_id": staff_key, "prospect_id": prospect_key,
            "assigned_month": int(getattr(self, "month", 1) or 1),
            "assigned_week": int(getattr(self, "week", 1) or 1),
        }
        academy["coach_assignment_review"] = ""
        return True, f"Assigned {coach.get('name', 'the Academy Coach')} to {prospect.get('name', 'the prospect')}."

    def release_academy_coach(self, staff_id="", academy=None, reason="Assignment ended"):
        """End an assignment while retaining completed development reports."""
        academy = self.repair_academy(academy if isinstance(academy, dict) else getattr(self, "academy", {}))
        assignment = self.academy_coach_assignment(academy)
        if staff_id and str(assignment.get("staff_id", "")) != str(staff_id):
            return False, "That coach has no active academy assignment."
        if not assignment:
            return False, "There is no active Academy Coach assignment."
        academy["coach_assignment"] = {}
        academy["coach_assignment_review"] = str(reason or "Assignment ended")
        return True, "Academy Coach assignment ended; completed blocks and reports were retained."

    def academy_coach_for_prospect(self, prospect, academy=None):
        """Return the assigned active coach, if any, for this prospect."""
        assignment = self.academy_coach_assignment(academy)
        prospect_key = str((prospect or {}).get("prospect_id", "") or "")
        staff_key = str(assignment.get("staff_id", "") or "")
        if not prospect_key or str(assignment.get("prospect_id", "")) != prospect_key or not staff_key:
            return None
        return next((member for member in self.academy_coach_members()
                     if str(member.get("staff_id", "")) == staff_key), None)

    def academy_coach_link_for_fighter(self, fighter):
        """Return an active coaching link for a retired fighter, if any.

        This read is used by comeback validation.  It never changes the
        assignment or the fighter record; a player must explicitly end the
        assignment from the Academy page before the same person can return to
        full-time fighting.
        """
        fighter_id = str(getattr(fighter, "fighter_id", "") or "").strip()
        if not fighter_id:
            return None
        assignment = self.academy_coach_assignment()
        assigned_staff_id = str(assignment.get("staff_id", "") or "").strip()
        assigned_prospect_id = str(assignment.get("prospect_id", "") or "").strip()
        if not assigned_staff_id or not assigned_prospect_id:
            return None
        coach = next((member for member in self.academy_coach_members()
                      if str(member.get("staff_id", "")) == assigned_staff_id), None)
        if not coach or str(coach.get("origin_fighter_id", "") or "").strip() != fighter_id:
            return None
        return {
            "staff_id": assigned_staff_id,
            "prospect_id": assigned_prospect_id,
            "coach_name": str(coach.get("name", "Academy Coach") or "Academy Coach"),
        }

    def academy_training_quality(self, prospect=None, academy=None):
        """Return legacy Trainer quality plus one bounded coach adjustment."""
        academy = academy if isinstance(academy, dict) else getattr(self, "academy", {}) or {}
        baseline = float(self.staff_skill("Trainer"))
        coach = self.academy_coach_for_prospect(prospect, academy) if prospect else None
        if not coach:
            return baseline, None
        effective = float(coach.get("skill", 45) or 45) * (
            0.72 + float(coach.get("morale", 65) or 65) / 230.0
        )
        adjustment = max(-2.0, min(2.0, (effective - 45.0) * 0.05))
        return baseline + adjustment, {"staff_id": str(coach.get("staff_id", "")),
                                       "name": str(coach.get("name", "Academy Coach")),
                                       "effective_quality": round(effective, 2),
                                       "adjustment": round(adjustment, 2)}

    def start_academy_development_plan(self, prospect, focus="Automatic", intensity="Standard", objective="Balanced Growth", duration=8, coach_staff_id=""):
        """Commit a prospect to a measurable development block."""
        self.repair_academy_prospect(prospect)
        duration = max(4, min(12, int(duration or 8)))
        if duration not in (4, 8, 12):
            duration = min((4, 8, 12), key=lambda value: abs(value - duration))
        objective = objective if objective in self.ACADEMY_PLAN_OBJECTIVES else "Balanced Growth"
        focus = focus if focus in ("Automatic", "Balanced", "Boxing", "Wrestling", "BJJ", "Cardio", "Fight IQ") else "Automatic"
        intensity = intensity if intensity in ("Recovery", "Light", "Standard", "High") else "Standard"
        if objective == "Recovery Block":
            intensity = "Recovery"
        prospect["plan"] = focus or "Automatic"
        prospect["training_intensity"] = intensity or "Standard"
        skills = {
            key: int(prospect.get(key, 40) or 40)
            for key in ("striking", "wrestling", "grappling", "cardio", "chin", "power", "toughness", "fight_iq")
        }
        # Keep the legacy Trainer fallback and apply an assigned Academy Coach
        # once, via the bounded quality adjustment only.
        if coach_staff_id:
            ok, note = self.assign_academy_coach(coach_staff_id, prospect.get("prospect_id", ""))
            if not ok:
                return False, note
        trainer_quality, coach_snapshot = self.academy_training_quality(prospect)
        plan = {
            "id": f"academy-plan-{prospect.get('prospect_id', 'legacy')}-{self.calendar_week_index()}",
            "objective": objective, "focus": prospect["plan"], "intensity": prospect["training_intensity"],
            "duration": duration, "weeks_remaining": duration,
            "started_month": self.month, "started_week": self.week,
            "start_rating": int(prospect.get("rating", 40) or 40),
            "start_readiness": self.academy_graduation_readiness(prospect),
            "start_fatigue": int(prospect.get("fatigue", 0) or 0),
            "start_bouts": self.academy_amateur_fight_count(prospect),
            "start_skills": skills, "coach": (coach_snapshot or {}).get("name", "Academy Head Coach"),
            "coach_staff_id": (coach_snapshot or {}).get("staff_id", ""),
            "coach_quality": trainer_quality, "coach_adjustment": (coach_snapshot or {}).get("adjustment", 0.0),
        }
        prospect["development_plan"] = plan
        prospect["last_development"] = f"Started {duration}-week {objective.lower()} block"
        self.record_academy_progress(prospect, f"Development block started: {objective}")
        return True, f"{prospect['name']} started a {duration}-week {objective.lower()} block."

    def academy_development_plan_status(self, prospect):
        plan = prospect.get("development_plan") or {}
        if not plan:
            return "No active block"
        return f"{plan.get('objective', 'Development')} · {plan.get('weeks_remaining', 0)}w left"

    def complete_academy_development_plan(self, prospect, academy=None):
        academy = academy or getattr(self, "academy", {})
        plan = prospect.get("development_plan") or {}
        if not plan:
            return None
        start_skills = plan.get("start_skills") if isinstance(plan.get("start_skills"), dict) else {}
        skill_gains = {
            key: int(prospect.get(key, 40) or 40) - int(start_skills.get(key, prospect.get(key, 40)) or 40)
            for key in ("striking", "wrestling", "grappling", "cardio", "chin", "power", "toughness", "fight_iq")
        }
        rating_gain = int(prospect.get("rating", 40) or 40) - int(plan.get("start_rating", prospect.get("rating", 40)) or 40)
        readiness_gain = self.academy_graduation_readiness(prospect) - int(plan.get("start_readiness", 0) or 0)
        bouts_gained = self.academy_amateur_fight_count(prospect) - int(plan.get("start_bouts", 0) or 0)
        objective = plan.get("objective", "Balanced Growth")
        if objective == "Fix a Weakness":
            target_fields = self.academy_training_fields(plan.get("focus", "Balanced"), prospect)
            success = any(skill_gains.get(field, 0) > 0 for field in target_fields)
        elif objective == "Tournament Preparation":
            success = bouts_gained > 0 and prospect.get("fatigue", 0) < 65
        elif objective == "Graduation Preparation":
            success = readiness_gain >= 4 or self.academy_graduation_readiness(prospect) >= 75
        elif objective == "Recovery Block":
            success = prospect.get("fatigue", 0) <= max(15, int(plan.get("start_fatigue", 0) or 0) - 10)
        else:
            success = rating_gain > 0 or sum(max(0, gain) for gain in skill_gains.values()) >= 2
        report = {
            "plan_id": plan.get("id", ""), "month": self.month, "week": self.week,
            "objective": objective, "focus": plan.get("focus", "Automatic"),
            "intensity": plan.get("intensity", "Standard"), "duration": plan.get("duration", 8),
            "rating_gain": rating_gain, "readiness_gain": readiness_gain, "bouts": bouts_gained,
            "fatigue_change": int(prospect.get("fatigue", 0) or 0) - int(plan.get("start_fatigue", 0) or 0),
            "skill_gains": skill_gains, "success": bool(success),
        }
        prospect["development_reports"] = ([report] + prospect.get("development_reports", []))[:24]
        academy["season_history"] = ([dict(report, prospect_id=prospect.get("prospect_id", ""), prospect_name=prospect.get("name", ""))]
                                     + academy.get("season_history", []))[:80]
        prospect["development_plan"] = {}
        prospect["satisfaction"] = max(0, min(100, int(prospect.get("satisfaction", 60) or 60) + (5 if success else -4)))
        outcome = "met" if success else "missed"
        prospect["last_development"] = f"{objective} block {outcome} its objective ({rating_gain:+} rating, {readiness_gain:+} readiness)"
        prospect["training_log"] = ([f"M{self.month} W{self.week}: {prospect['last_development']}."] + prospect.get("training_log", []))[:30]
        return report

    def process_academy_development_plan(self, prospect, academy=None):
        plan = prospect.get("development_plan") or {}
        if not plan or not (academy or getattr(self, "academy", {})).get("auto_train", True):
            return None
        plan["weeks_remaining"] = max(0, int(plan.get("weeks_remaining", 0) or 0) - 1)
        if plan["weeks_remaining"]:
            return None
        return self.complete_academy_development_plan(prospect, academy)

    # Original academy prices, kept for saves started before the rise. A career
    # already part-way through its facility build-out should not have the
    # remaining purchases repriced underneath it.
    ACADEMY_UPGRADE_LEGACY_COSTS = {
        "elite_coaches": 90_000, "conditioning_centre": 60_000, "analysis_lab": 50_000,
        "medical_suite": 75_000, "recovery_nutrition": 45_000,
    }

    def academy_upgrade_pricing_version(self):
        """Saves without the marker predate the price rise and keep the old costs."""
        return int((getattr(self, "rules", None) or {}).get("academy_upgrade_pricing_version", 1) or 1)

    def academy_upgrade_catalog(self):
        """Purchasable academy facilities. Each is a one-off spend with a permanent
        effect on how fast and safely prospects develop.

        Priced as a long-term ambition rather than an early purchase: a permanent
        promotion-wide development bonus was reachable in the opening months at
        the original cost, so the academy stopped being a real decision.
        """
        catalog = [
            {"id": "elite_coaches", "name": "Elite Coaching Team", "cost": 1_800_000,
             "effect": "Faster skill development in every session (+9% growth).", "growth": 0.09},
            {"id": "conditioning_centre", "name": "Strength & Conditioning Centre", "cost": 1_200_000,
             "effect": "+5% growth and biases training toward cardio, power, and toughness.", "growth": 0.05, "emphasis": "physical"},
            {"id": "analysis_lab", "name": "Video & Analysis Lab", "cost": 1_050_000,
             "effect": "+3% growth and sharper Fight IQ development.", "growth": 0.03, "emphasis": "mental"},
            {"id": "medical_suite", "name": "Sports Medicine Suite", "cost": 1_500_000,
             "effect": "Halves training-injury risk and heals injuries a week sooner.", "injury_mult": 0.5, "heal": 1},
            {"id": "recovery_nutrition", "name": "Recovery & Nutrition Programme", "cost": 1_000_000,
             "effect": "+4 weekly fatigue recovery so prospects train harder without burning out.", "recovery": 4},
        ]
        if self.academy_upgrade_pricing_version() < 2:
            for upgrade in catalog:
                upgrade["cost"] = self.ACADEMY_UPGRADE_LEGACY_COSTS.get(upgrade["id"], upgrade["cost"])
        return catalog

    def academy_facility_profile(self, academy=None):
        """Aggregate the effects of every installed academy facility upgrade."""
        academy = academy if academy is not None else getattr(self, "academy", {}) or {}
        owned = set(academy.get("upgrades", []) or [])
        profile = {"growth": 0.0, "injury_mult": 1.0, "recovery": 0, "heal": 0, "emphasis": []}
        for upgrade in self.academy_upgrade_catalog():
            if upgrade["id"] in owned:
                profile["growth"] += upgrade.get("growth", 0.0)
                profile["injury_mult"] *= upgrade.get("injury_mult", 1.0)
                profile["recovery"] += upgrade.get("recovery", 0)
                profile["heal"] += upgrade.get("heal", 0)
                if upgrade.get("emphasis"):
                    profile["emphasis"].append(upgrade["emphasis"])
        return profile

    def purchase_academy_upgrade(self, academy, upgrade_id):
        """Buy a facility upgrade if affordable and not already installed."""
        academy = academy if academy is not None else getattr(self, "academy", {}) or {}
        catalog = {upgrade["id"]: upgrade for upgrade in self.academy_upgrade_catalog()}
        upgrade = catalog.get(upgrade_id)
        if not upgrade:
            return False, "Unknown upgrade."
        owned = list(academy.get("upgrades", []) or [])
        if upgrade_id in owned:
            return False, f"{upgrade['name']} is already installed."
        if self.cash < upgrade["cost"]:
            return False, f"{upgrade['name']} costs ${upgrade['cost']:,}."
        self.cash -= upgrade["cost"]
        owned.append(upgrade_id)
        academy["upgrades"] = owned
        academy["upgrade_spend"] = academy.get("upgrade_spend", 0) + upgrade["cost"]
        academy["reputation"] = min(100, academy.get("reputation", 10) + 2)
        self.record_finance_transaction(f"Academy facility: {upgrade['name']}", costs=upgrade["cost"])
        academy["last_scout_report"] = f"Installed {upgrade['name']} at the academy (${upgrade['cost']:,})."
        return True, academy["last_scout_report"]

    def train_academy_prospect(self, prospect, academy):
        self.repair_academy_prospect(prospect)
        profile = self.academy_facility_profile(academy)
        prospect["weeks"] = prospect.get("weeks", 0) + 1
        if prospect.get("injured", 0):
            prospect["injured"] = max(0, prospect.get("injured", 0) - 1 - profile["heal"])
            return
        intensity = prospect.get("training_intensity", "Standard")
        # Ordinary training should create a real workload choice. Previously
        # every intensity recovered more fatigue than it added below, leaving a
        # healthy prospect permanently near zero fatigue. Recovery sessions and
        # the dedicated facility remain the ways to erase accumulated load.
        recovery = {"Light": (1, 2), "Standard": (0, 1), "Intensive": (0, 1), "Recovery": (12, 18)}.get(intensity, (0, 1))
        prospect["fatigue"] = max(0, prospect.get("fatigue", 0) - random.randint(*recovery) - profile["recovery"])
        if not academy.get("auto_train", True):
            return
        if intensity == "Recovery" or prospect.get("fatigue", 0) >= 65:
            prospect["confidence"] = min(99, prospect.get("confidence", 55) + (1 if random.random() < 0.28 else 0))
            return
        fields = self.academy_training_fields(prospect.get("plan", "Automatic"), prospect)
        philosophy = self.academy_philosophy_fields(academy)
        level = max(1, academy.get("level", 1))
        trainer_quality, _coach_snapshot = self.academy_training_quality(prospect, academy)
        facility = level * 7 + trainer_quality * 0.25 + academy.get("reputation", 10) * 0.10
        potential_gap = max(0, prospect.get("potential", 70) - prospect.get("rating", 40))
        mentality = (prospect.get("dedication", 55) + prospect.get("coachability", 55)) / 200
        intensity_factor = {"Light": 0.72, "Standard": 1.0, "Intensive": 1.35}.get(intensity, 1.0)
        fatigue_drag = max(0, prospect.get("fatigue", 0) - 35) / 180
        facility_bonus = max(0, level - 1) * 0.012
        growth_chance = min(0.58, (0.05 + facility / 400 + potential_gap / 360) * mentality * intensity_factor + facility_bonus + profile["growth"] - fatigue_drag)
        if random.random() < max(0.025, growth_chance):
            emphasis_fields = []
            if "physical" in profile["emphasis"]:
                emphasis_fields += [field for field in ("cardio", "power", "toughness") if field in fields]
            if "mental" in profile["emphasis"]:
                emphasis_fields += [field for field in ("fight_iq",) if field in fields]
            weighted_fields = list(fields) + [field for field in philosophy if field in fields] + emphasis_fields
            field = random.choice(weighted_fields)
            prospect[field] = min(prospect.get("potential", 99), prospect.get(field, prospect.get("rating", 40)) + 1)
            prospect["development"] = prospect.get("development", 0) + 1
            plan_moves = {
                "Boxing": ("one_two", "body_head_change"), "Muay Thai": ("clinch_knee", "body_round_kick"),
                "Wrestling": ("double_leg_entry", "double_leg_finish"), "BJJ": ("guard_submission_chain", "back_take_transition"),
                "Judo": ("hip_toss", "outside_trip"), "Sambo": ("body_lock_trip", "straight_ankle_lock"),
                "Clinch": ("pummel_to_underhook", "fence_pressure"),
            }.get(prospect.get("plan"), ())
            if plan_moves:
                move_id = plan_moves[prospect.get("weeks", 0) % len(plan_moves)]
                prospect["move_mastery"][move_id] = min(100, int(prospect["move_mastery"].get(move_id, 30)) + 1)
            prospect["plateau_weeks"] = 0
            prospect["training_log"] = ([f"M{self.month} W{self.week}: {field.replace('_', ' ').title()} improved under {prospect.get('plan', 'Automatic')} training."] + prospect.get("training_log", []))[:30]
        else:
            prospect["plateau_weeks"] = prospect.get("plateau_weeks", 0) + 1
        fatigue_gain = {"Light": 1, "Standard": 2, "Intensive": 4}.get(intensity, 2)
        prospect["fatigue"] = min(100, prospect.get("fatigue", 0) + fatigue_gain)
        injury_risk = ({
            "Light": 0.0015, "Standard": 0.0035, "Intensive": 0.010, "Recovery": 0.0008,
        }.get(intensity, 0.0035) + max(0, prospect["fatigue"] - 75) / 1700) * profile["injury_mult"]
        if random.random() < injury_risk:
            prospect["injured"] = random.randint(1, 4)
            injury_note = f"M{self.month} W{self.week}: Training injury; out {prospect['injured']} week(s)."
            prospect["training_log"] = ([injury_note] + prospect.get("training_log", []))[:30]
            prospect["medical_history"] = ([injury_note] + prospect.get("medical_history", []))[:20]
        if prospect.get("weeks", 0) % 5 == 0 and prospect.get("rating", 40) < prospect.get("potential", 70):
            self.recalculate_academy_rating(prospect)
        if prospect.get("weeks", 0) % 4 == 0:
            self.record_academy_progress(prospect)

    def recalculate_academy_rating(self, prospect):
        rating = round((prospect.get("striking", 40) + prospect.get("wrestling", 40) + prospect.get("grappling", 40) + prospect.get("cardio", 40) + prospect.get("chin", 40) + prospect.get("fight_iq", 40)) / 6)
        prospect["rating"] = max(prospect.get("rating", 40), min(prospect.get("potential", 70), rating))
        return prospect["rating"]

    def apply_academy_bout_development(self, prospect, method, won=False):
        self.repair_academy_prospect(prospect)
        fields = ["cardio", "fight_iq", "toughness"]
        if method in ("KO", "TKO"):
            fields += ["striking", "power", "chin"]
        elif "Submission" in method:
            fields += ["grappling", "fight_iq"]
        else:
            fields += ["wrestling", "grappling", "striking"]
        prospect["bout_experience"] = prospect.get("bout_experience", 0) + 1
        gap = max(0, prospect.get("potential", 70) - prospect.get("rating", 40))
        mentality = (prospect.get("dedication", 55) + prospect.get("coachability", 55)) / 200
        gain_chance = min(0.72, (0.26 + gap / 120 + (0.12 if won else 0)) * mentality)
        gains = int(random.random() < gain_chance) + int(won and gap >= 15 and random.random() < 0.12)
        improved = []
        for _ in range(gains):
            field = random.choice(fields)
            prospect[field] = min(prospect.get("potential", 99), prospect.get(field, 45) + 1)
            prospect["development"] = prospect.get("development", 0) + 1
            improved.append(field.replace("_", " ").title())
        prospect["fatigue"] = min(100, prospect.get("fatigue", 0) + random.randint(8, 16))
        prospect["confidence"] = max(20, min(99, prospect.get("confidence", 55) + (random.randint(2, 5) if won else random.randint(-3, 1))))
        if random.random() < 0.025:
            prospect["injured"] = max(prospect.get("injured", 0), random.randint(1, 3))
            note = f"M{self.month} W{self.week}: Bout injury; out {prospect['injured']} week(s)."
            prospect["medical_history"] = ([note] + prospect.get("medical_history", []))[:20]
        self.recalculate_academy_rating(prospect)
        prospect["last_development"] = ", ".join(improved) if improved else "Experience gained; no immediate skill increase"
        self.record_academy_progress(prospect, "Amateur bout")

    def academy_prospect_to_fighter(self, prospect):
        self.repair_academy_prospect(prospect)
        fighter = self.create_generated_fighter(2, 14, max(35, prospect["rating"] - 6), min(86, prospect["rating"] + 6), weight=prospect["weight"], gender=prospect["gender"], region=prospect["region"])
        fighter.name = prospect["name"]; fighter.age = prospect["age"]; fighter.potential = prospect["potential"]
        fighter.style = prospect.get("style", fighter.style)
        fighter.stance = prospect.get("stance", fighter.stance)
        fighter.trait = prospect.get("trait", fighter.trait)
        fighter.record_w = fighter.record_l = fighter.record_d = 0
        for key in ("striking", "wrestling", "grappling", "cardio", "chin", "power", "toughness", "fight_iq"):
            setattr(fighter, key, max(1, min(99, prospect.get(key, getattr(fighter, key, 50)))))
        group_targets = {
            "Standing": prospect.get("striking", 45), "Ground": prospect.get("grappling", 45),
            "Wrestling": prospect.get("wrestling", 45),
            "Muay Thai Clinch": round((prospect.get("striking", 45) + prospect.get("wrestling", 45)) / 2),
            "Mental": prospect.get("fight_iq", 45),
            "Physical": round((prospect.get("cardio", 45) + prospect.get("chin", 45) + prospect.get("power", 45) + prospect.get("toughness", 45)) / 4),
        }
        fighter.detailed_skills = {
            key: max(1, min(99, group_targets.get(group, prospect.get("rating", 45))))
            for group, keys in DETAILED_SKILL_GROUPS.items() for key in keys
        }
        fighter.detailed_skills.update({
            "conditioning": prospect.get("cardio", 45), "resilience": prospect.get("toughness", 45),
            "chin_strength": prospect.get("chin", 45), "stun_recovery": prospect.get("chin", 45),
            "strength": prospect.get("power", 45), "dedication": prospect.get("dedication", 55),
            "confidence": prospect.get("confidence", 55),
        })
        fighter.move_mastery = normalize_move_mastery(prospect.get("move_mastery", {}),
            registry=getattr(self, "_fight_move_registry", MOVE_REGISTRY))
        learned_signatures = [
            move_id for move_id, value in sorted(fighter.move_mastery.items(), key=lambda row: (-row[1], row[0]))
            if not move_id.startswith("defense:") and value >= 70
        ]
        fighter.signature_moves = normalize_signature_moves(learned_signatures or fighter.signature_moves,
            registry=getattr(self, "_fight_move_registry", MOVE_REGISTRY))
        fighter.move_mastery_last_month = self.month
        for key in ("nationality", "birth_country", "birth_region", "hometown", "residence", "training_location", "fighting_base", "cultural_connections", "regional_popularity"):
            if key in prospect:
                setattr(fighter, key, prospect[key])
        # Academy bouts are background, not professional fights. Keep their
        # structured ledger for the profile and begin the pro ledger cleanly.
        fighter.amateur_w = int(prospect.get("amateur_w", 0) or 0)
        fighter.amateur_l = int(prospect.get("amateur_l", 0) or 0)
        fighter.amateur_d = int(prospect.get("amateur_d", 0) or 0)
        fighter.amateur_bout_history = [dict(record) for record in prospect.get("amateur_bout_records", []) if isinstance(record, dict)]
        fighter.amateur_history_migration_version = 1
        fighter.fight_history = ["Promoted from the Fighting Academy."]
        fighter.record_history_baseline_w = 0
        fighter.record_history_baseline_l = 0
        fighter.record_history_baseline_d = 0
        fighter.contract_months = 24
        fighter.feeder_origin = f"{self.player_company_name} Fighting Academy"
        fighter.academy_graduate = True
        fighter.academy_graduated_month = self.month
        fighter.academy_prospect_id = str(prospect.get("prospect_id", "") or "")
        fighter.motivation = max(35, min(99, prospect.get("dedication", fighter.motivation)))
        fighter.professionalism = max(30, min(99, round((prospect.get("dedication", 55) + prospect.get("coachability", 55)) / 2)))
        fighter.career_achievements = list(fighter.career_achievements or []) + [
            f"Graduated from {self.player_company_name}'s academy with a {prospect.get('amateur_w', 0)}-{prospect.get('amateur_l', 0)}-{prospect.get('amateur_d', 0)} amateur record."
        ]
        fighter.rank_score = self.rank_value(fighter)
        return fighter

    def record_academy_graduate(self, prospect, fighter, destination):
        academy = self.repair_academy(getattr(self, "academy", {}))
        fighter_id = str(getattr(fighter, "fighter_id", "") or "")
        entry = {
            "fighter_id": fighter_id, "prospect_id": prospect.get("prospect_id", ""),
            "name": fighter.name, "destination": destination, "graduated_month": self.month,
            "amateur_record": f"{prospect.get('amateur_w', 0)}-{prospect.get('amateur_l', 0)}-{prospect.get('amateur_d', 0)}",
            "graduation_rating": prospect.get("rating", fighter.overall), "potential": prospect.get("potential", fighter.potential),
            "current_rating": fighter.overall, "professional_record": fighter.record, "title_wins": 0,
            "last_wins": fighter.record_w, "active": True,
        }
        academy["alumni"] = ([entry] + [
            row for row in academy.get("alumni", [])
            if not fighter_id or str(row.get("fighter_id", "") or "") != fighter_id
        ])[:100]
        academy["total_graduates"] = academy.get("total_graduates", 0) + 1
        academy["reputation"] = min(100, academy.get("reputation", 10) + 1 + int(prospect.get("rating", 40) >= 65))
        prospect["milestones"] = ([f"M{self.month}: Graduated to {destination} at rating {prospect.get('rating', fighter.overall)}."] + prospect.get("milestones", []))[:20]
        story = self.upsert_story_thread(
            self.academy_lineage_story_key(fighter), "Academy Lineage", status="active",
            phase="professional_graduate", importance=3, fighters=[fighter], companies=[self.player_company_name],
            origin_ref=f"{self.academy_lineage_story_key(fighter)}:graduation:{self.month}:{self.week}",
            beat_kind="academy_graduation", beat_ref=f"{self.academy_lineage_story_key(fighter)}:graduation:{self.month}:{self.week}",
            summary=f"{fighter.name} graduated from the academy to {destination} with an amateur record of {entry['amateur_record']}.",
            stakes="The graduate's senior career will test the value of the academy pathway.",
        )
        mentorship_key = self.academy_mentorship_story_key(prospect)
        if self.story_thread(mentorship_key):
            mentorship_summary = f"{fighter.name}'s academy mentorship reached graduation and now follows the senior career."
            self.record_academy_mentorship_story(
                prospect, phase="senior_transition", fighter=fighter, status="active",
                summary=mentorship_summary,
            )
        self.record_world_story(
            "Academy Graduate", f"{fighter.name} graduates from {self.player_company_name}'s academy.",
            f"Destination {destination}; amateur record {entry['amateur_record']}; potential {fighter.potential}.",
            [self.player_company_name], [fighter.name], 2,
            fighter_ids=[fighter.fighter_id], story_id=story.get("story_id", "") if story else "",
        )
        if destination in ("MMA", "MMA Main Roster", "MMA Developmental") and fighter in self.roster:
            self.start_career_arc(fighter, "Homegrown Champion", "Academy graduation")

    def academy_alumnus_fighter(self, name="", fighter_id=""):
        """Resolve an alumnus by durable identity, with unique-name legacy fallback."""
        candidates = list(self.all_database_fighters(include_retired=True))
        for world in getattr(self, "combat_sport_worlds", {}).values():
            candidates.extend(world.get("roster", []))
        unique = {}
        for candidate in candidates:
            unique.setdefault(self.fighter_identity_key(candidate), candidate)
        fighter_id = str(fighter_id or "")
        if fighter_id:
            return next((candidate for candidate in unique.values()
                         if str(getattr(candidate, "fighter_id", "") or "") == fighter_id), None)
        matches = [candidate for candidate in unique.values() if candidate.name == name]
        return matches[0] if len(matches) == 1 else None

    def update_academy_alumni(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        if not academy.get("owned") or academy.get("last_alumni_review_month") == self.month:
            return
        academy["last_alumni_review_month"] = self.month
        # Build the world lookup once. Previously every alumnus independently
        # sorted the entire fighter database, which became costly in long saves.
        fighters = list(self.all_database_fighters(include_retired=True))
        for world in getattr(self, "combat_sport_worlds", {}).values():
            fighters.extend(world.get("roster", []))
        fighters = list({self.fighter_identity_key(fighter): fighter for fighter in fighters}.values())
        fighter_index = {
            str(getattr(fighter, "fighter_id", "") or ""): fighter
            for fighter in fighters if getattr(fighter, "fighter_id", "")
        }
        fighters_by_name = {}
        for fighter in fighters:
            fighters_by_name.setdefault(fighter.name, []).append(fighter)
        for entry in academy.get("alumni", []):
            entry_id = str(entry.get("fighter_id", "") or "")
            fighter = fighter_index.get(entry_id) if entry_id else None
            if not fighter and not entry_id:
                legacy_matches = fighters_by_name.get(entry.get("name", ""), [])
                fighter = legacy_matches[0] if len(legacy_matches) == 1 else None
                if fighter:
                    entry["fighter_id"] = str(getattr(fighter, "fighter_id", "") or "")
            if not fighter:
                entry["active"] = False
                continue
            prior_wins = entry.get("last_wins", 0)
            prior_titles = entry.get("title_wins", 0)
            entry.update({"current_rating": fighter.overall, "professional_record": fighter.record,
                          "title_wins": getattr(fighter, "title_wins", 0), "last_wins": fighter.record_w,
                          "active": not getattr(fighter, "retired", False)})
            gained_wins = max(0, fighter.record_w - prior_wins)
            gained_titles = max(0, getattr(fighter, "title_wins", 0) - prior_titles)
            if gained_wins or gained_titles:
                academy["reputation"] = min(100, academy.get("reputation", 10) + min(2, gained_wins) + gained_titles * 3)
                if gained_titles:
                    note = f"Academy alumnus {fighter.name} won a professional title; academy reputation rose to {academy['reputation']}."
                    academy["last_scout_report"] = note
                    self.news.insert(0, note)

    def academy_graduation_destinations(self):
        return ["MMA Main Roster", "MMA Developmental", "Regional Feeder"] + sorted(getattr(self, "player_combat_divisions", {}).keys())

    def academy_matching_right(self, fighter_id):
        academy = self.repair_academy(getattr(self, "academy", {}))
        return next((row for row in academy.get("released_rights", [])
                     if str(row.get("fighter_id", "") or "") == str(fighter_id)
                     and row.get("status") == "Matching rights"), None)

    def exercise_academy_matching_right(self, fighter_id):
        right = self.academy_matching_right(fighter_id)
        if not right:
            return False, "No active academy matching right exists for that fighter."
        if self.month > int(right.get("expires_month", 0) or 0):
            right["status"] = "Expired"
            return False, "The academy matching-right window has expired."
        promo = next((item for item in getattr(self, "promotions", []) if item.name == right.get("promotion")), None)
        fighter = next((item for item in (promo.roster if promo else [])
                        if str(getattr(item, "fighter_id", "") or "") == str(fighter_id)), None)
        if not promo or not fighter:
            right["status"] = "Unavailable"
            return False, "The graduate is no longer available in the recorded feeder."
        division_key = self.belt_key(fighter.gender, fighter.weight)
        if division_key in set(getattr(self, "closed_divisions", set()) or set()):
            return False, f"Reopen the {fighter.gender} {fighter.weight} division before exercising this right."
        cost = max(15_000, round((int(getattr(fighter, "purse", 0) or 0) * 2 + fighter.overall * 350) / 500) * 500)
        if self.cash < cost:
            return False, f"Exercising the matching right requires a ${cost:,} signing package."
        cash_before = self.cash
        finance_before = deepcopy(getattr(self, "finance", {}))
        player_roster_before = list(self.roster)
        promo_roster_before = list(promo.roster)
        belts_before = deepcopy((promo.belts, promo.interim_belts, promo.belt_history))
        fighter_before = deepcopy(fighter.__dict__)
        right_before = deepcopy(right)
        news_before = list(getattr(self, "news", []))
        foundation_before = deepcopy(getattr(self, "_foundation_state", None))
        try:
            promo.belts, promo.interim_belts, promo.belt_history = self.vacate_fighter_belts(
                fighter, promo.roster, promo.belts or {}, promo.interim_belts or {}, promo.belt_history or {},
                "Academy matching right exercised.",
            )
            self.vacate_special_belts_held_by(fighter, "Academy matching right exercised.", owner=promo)
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                transition_key = f"academy-matching-right:{fighter.fighter_id}:{promo.name}:{self.month}:{self.week}"
                membership(
                    fighter, "leave", promotion=promo,
                    reason="Academy matching right exercised.", source_transaction=transition_key,
                )
                membership(
                    fighter, "join", company_name=self.player_company_name,
                    reason=f"Academy matching right exercised from {promo.name}.", source_transaction=transition_key,
                )
            self.cash -= cost
            self.record_finance_transaction(
                f"Academy matching right: {fighter.name}", costs=cost, category="Contracts",
                source="Academy graduate signing", counterparty=fighter.name,
                reference=f"academy-right:{fighter.fighter_id}:{self.month}:{self.week}",
            )
            promo.roster.remove(fighter)
            self.roster.append(fighter)
            fighter.contract_type = "Exclusive"
            fighter.contract_months = 24
            fighter.exclusive = True
            fighter.camp = self.player_company_name
            right["status"] = "Exercised"
            right["exercised_month"] = self.month
            note = f"Exercised academy matching rights: {fighter.name} returns from {promo.name} on a 24-month contract."
            self.news.insert(0, note)
            return True, note
        except Exception:
            self.cash = cash_before
            if isinstance(getattr(self, "finance", None), dict):
                self.finance.clear()
                self.finance.update(finance_before)
            else:
                self.finance = finance_before
            self.roster[:] = player_roster_before
            promo.roster[:] = promo_roster_before
            promo.belts, promo.interim_belts, promo.belt_history = belts_before
            fighter.__dict__.clear()
            fighter.__dict__.update(fighter_before)
            right.clear()
            right.update(right_before)
            if foundation_before is None:
                self.__dict__.pop("_foundation_state", None)
            else:
                self._foundation_state = foundation_before
            if isinstance(getattr(self, "news", None), list):
                self.news[:] = news_before
            return False, "The matching-right signing failed; roster, belts, and finance state were restored."

    def expire_academy_matching_rights(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        for right in academy.get("released_rights", []):
            if right.get("status") == "Matching rights" and self.month > int(right.get("expires_month", 0) or 0):
                right["status"] = "Expired"

    def academy_regional_feeder_for(self, prospect):
        feeders = [
            promo for promo in getattr(self, "promotions", [])
            if getattr(promo, "is_regional_feeder", False)
            and self.promotion_division_open(promo, prospect.get("gender", "Male"), prospect.get("weight", "Lightweight"))
        ]
        if not feeders:
            return None
        return min(feeders, key=lambda promo: (promo.region != prospect.get("region"), len(promo.roster), promo.name))

    def promote_academy_prospect_to_sport(self, prospect, sport):
        """Graduate atomically so a late story, finance, or roster hook cannot leave a partial move."""
        self.repair_academy_prospect(prospect)
        if prospect.get("age", 0) < 16:
            return False, "A prospect must be at least 16 to turn professional.", None
        academy = self.repair_academy(getattr(self, "academy", {}))
        academy_before = deepcopy(academy)
        prospect_before = deepcopy(prospect)
        roster_before = list(self.roster)
        promotion_rosters_before = [(promo, list(promo.roster)) for promo in getattr(self, "promotions", [])]
        combat_rosters_before = {
            name: list(world.get("roster", []))
            for name, world in getattr(self, "combat_sport_worlds", {}).items()
        }
        divisions_before = deepcopy(getattr(self, "player_combat_divisions", {}))
        cash_before = self.cash
        finance_before = deepcopy(getattr(self, "finance", {}))
        news_before = list(getattr(self, "news", []))
        inbox_before = list(getattr(self, "inbox", []))
        chronicle_before = list(getattr(self, "world_chronicle", []))
        story_threads_before = deepcopy(getattr(self, "story_threads", []))
        rng_before = random.getstate()
        try:
            return self._promote_academy_prospect_to_sport(prospect, sport)
        except Exception:
            self.cash = cash_before
            if isinstance(getattr(self, "finance", None), dict):
                self.finance.clear()
                self.finance.update(finance_before)
            else:
                self.finance = finance_before
            self.roster[:] = roster_before
            for promo, prior_roster in promotion_rosters_before:
                promo.roster[:] = prior_roster
            for name, prior_roster in combat_rosters_before.items():
                world = getattr(self, "combat_sport_worlds", {}).get(name)
                if isinstance(world, dict):
                    world["roster"] = prior_roster
            if isinstance(getattr(self, "player_combat_divisions", None), dict):
                self.player_combat_divisions.clear()
                self.player_combat_divisions.update(divisions_before)
            else:
                self.player_combat_divisions = divisions_before
            academy.clear()
            academy.update(academy_before)
            prospect.clear()
            prospect.update(prospect_before)
            prospect_id = str(prospect.get("prospect_id", "") or "")
            for collection_name in ("prospects", "talent_pool"):
                collection = academy.get(collection_name, [])
                for index, row in enumerate(collection):
                    if str(row.get("prospect_id", "") or "") == prospect_id:
                        collection[index] = prospect
                        break
            if isinstance(getattr(self, "news", None), list):
                self.news[:] = news_before
            if isinstance(getattr(self, "inbox", None), list):
                self.inbox[:] = inbox_before
            self.world_chronicle = chronicle_before
            self.story_threads = story_threads_before
            self.rebuild_story_thread_index()
            random.setstate(rng_before)
            return False, "Academy graduation failed; roster, finance, and academy state were restored.", None

    def _promote_academy_prospect_to_sport(self, prospect, sport):
        self.repair_academy_prospect(prospect)
        fighter = self.academy_prospect_to_fighter(prospect)
        if sport in ("MMA", "MMA Main Roster", "MMA Developmental"):
            developmental = sport == "MMA Developmental"
            fighter.contract_type = "Developmental" if developmental else "Exclusive"
            fighter.contract_months = 12 if developmental else 24
            membership_recorded = False
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                membership(
                    fighter, "join", company_name=self.player_company_name,
                    reason=(
                        "Academy graduation to MMA Developmental"
                        if developmental else "Academy graduation to MMA Main Roster"
                    ),
                    source_transaction=f"academy-mma-graduation:{fighter.fighter_id}:{self.player_company_name}:{self.month}:{self.week}",
                )
                membership_recorded = True
            self.roster.append(fighter)
            self.record_contract_signing(
                fighter, self.player_company_name,
                source="Academy graduation to MMA Developmental" if developmental else "Academy graduation to MMA Main Roster",
                record_membership=not membership_recorded,
            )
            destination = "MMA Developmental" if developmental else "MMA Main Roster"
            self.fulfill_academy_promise(prospect, "Graduation Review")
            self.record_academy_graduate(prospect, fighter, destination)
            return True, f"Academy graduate: {fighter.name} joined {self.player_company_name} on a {'12-month developmental' if developmental else '24-month main-roster'} contract.", fighter
        if sport == "Regional Feeder":
            feeder = self.academy_regional_feeder_for(prospect)
            if not feeder:
                return False, "No regional feeder has an open division for this prospect.", None
            fighter.contract_type = "Developmental"
            fighter.contract_months = 0
            fighter.exclusive = False
            fighter.feeder_origin = feeder.name
            fighter.camp = feeder.name
            fighter.regional_entry_w = fighter.record_w
            fighter.regional_entry_l = fighter.record_l
            fighter.regional_entry_d = fighter.record_d
            membership_recorded = False
            membership = getattr(self, "record_membership_event", None)
            if callable(membership):
                membership(
                    fighter, "join", promotion=feeder,
                    reason=f"Academy graduation to regional feeder: {feeder.name}",
                    source_transaction=f"academy-regional-graduation:{fighter.fighter_id}:{feeder.name}:{self.month}:{self.week}",
                )
                membership_recorded = True
            feeder.roster.append(fighter)
            self.record_contract_signing(
                fighter, feeder.name, source=f"Academy graduation to regional feeder: {feeder.name}",
                record_membership=not membership_recorded,
            )
            rights = {
                "fighter_id": fighter.fighter_id, "name": fighter.name, "promotion": feeder.name,
                "expires_month": self.month + 12, "status": "Matching rights",
            }
            academy = self.repair_academy(getattr(self, "academy", {}))
            academy["released_rights"] = ([rights] + academy.get("released_rights", []))[:60]
            self.fulfill_academy_promise(prospect, "Graduation Review")
            self.record_academy_graduate(prospect, fighter, f"Regional Feeder: {feeder.name}")
            return True, f"Academy graduate: {fighter.name} joined {feeder.name}; {self.player_company_name} retains 12 months of matching rights.", fighter
        ok, division = self.open_player_combat_division(sport)
        if not ok:
            return False, division, None
        world = self.combat_sport_worlds.get(sport)
        # A player-owned child division is a distinct company in the timeline.
        # Record the join before changing the employer or appending the athlete
        # so a failed downstream mutation cannot leave a phantom roster fact.
        membership = getattr(self, "record_membership_event", None)
        if callable(membership):
            child_company = str((division or {}).get("promotion_name", "") or f"{self.player_company_name} {sport}")
            membership(
                fighter, "join", company_name=child_company,
                reason=f"Academy graduation into {child_company}.",
                source_transaction=f"academy-sport-graduation:{sport}:{fighter.fighter_id}:{self.month}:{self.week}",
            )
        fighter.primary_discipline = sport if sport != "Brazilian Jiu-Jitsu" else "Brazilian Jiu-Jitsu"
        fighter.sport_employer = self.player_company_name
        fighter.contract_type = f"{sport} Developmental"
        self.assign_combat_sport_weight(sport, fighter, reset_walk_weight=True)
        fighter.multi_sport_records = fighter.multi_sport_records or {}
        fighter.multi_sport_records[sport] = "0-0-0"
        fighter.crossover_history = fighter.crossover_history or []
        fighter.crossover_history.append(f"Month {self.month}: Graduated from {self.player_company_name}'s academy into {sport}.")
        world["roster"].append(fighter)
        self.add_player_combat_member(sport, fighter, world)
        self.fulfill_academy_promise(prospect, "Graduation Review")
        self.record_academy_graduate(prospect, fighter, sport)
        return True, f"Academy graduate: {fighter.name} joined {self.player_company_name}'s {sport} division.", fighter

    def academy_bout_fighter(self, prospect):
        """Build a disposable fighter so amateur bouts use the complete MMA engine."""
        fighter = self.academy_prospect_to_fighter(prospect)
        fighter.age = max(16, fighter.age)
        fighter.camp = f"{self.player_company_name} Fighting Academy"
        fighter.camp_quality = min(96, 48 + getattr(self, "academy", {}).get("level", 1) * 7)
        fighter.camp_weeks = 4
        fighter.camp_boost = max(0, min(8, getattr(self, "academy", {}).get("level", 1) + prospect.get("coachability", 50) // 25))
        fighter.morale = prospect.get("confidence", 55)
        fighter.motivation = prospect.get("dedication", 55)
        fighter.fatigue = prospect.get("fatigue", 0)
        fighter.walk_weight = self.default_walk_weight(fighter)
        fighter.scale_weight = float(WEIGHT_LIMITS.get(fighter.weight, fighter.walk_weight))
        return fighter

    ACADEMY_COMPETITION_TIERS = {
        "Local": {"quality": 1, "rating_offset": -4, "cost": 5_000, "bouts": 0, "rating": 0},
        "Regional": {"quality": 3, "rating_offset": 0, "cost": 10_000, "bouts": 2, "rating": 45},
        "National": {"quality": 6, "rating_offset": 3, "cost": 20_000, "bouts": 5, "rating": 55},
        "International": {"quality": 10, "rating_offset": 6, "cost": 35_000, "bouts": 8, "rating": 65},
    }

    def academy_competition_tier(self, prospect):
        bouts = self.academy_amateur_fight_count(prospect)
        rating = int(prospect.get("rating", 40) or 40)
        available = [
            tier for tier, profile in self.ACADEMY_COMPETITION_TIERS.items()
            if bouts >= profile["bouts"] and rating >= profile["rating"]
        ]
        tier = available[-1] if available else "Local"
        prospect["competition_tier"] = tier
        return tier

    def academy_strength_of_schedule(self, prospect):
        records = [row for row in prospect.get("amateur_bout_records", []) if isinstance(row, dict)]
        if not records:
            prospect["strength_of_schedule"] = 0.0
            return 0.0
        value = round(sum(float(row.get("opponent_rating", prospect.get("rating", 40)) or 40) for row in records) / len(records), 1)
        prospect["strength_of_schedule"] = value
        return value

    def apply_academy_competition_credit(self, prospect, opponent, result, tier):
        profile = self.ACADEMY_COMPETITION_TIERS.get(tier, self.ACADEMY_COMPETITION_TIERS["Local"])
        base = profile["quality"]
        opponent_rating = int(opponent.get("rating", prospect.get("rating", 40)) or 40)
        upset = max(0, opponent_rating - int(prospect.get("rating", 40) or 40))
        credit = max(1, round(base * ({"W": 1.0, "D": 0.55, "L": 0.30}.get(result, 0.3)) + upset / 5))
        prospect["amateur_quality_points"] = int(prospect.get("amateur_quality_points", 0) or 0) + credit
        if result == "W" and (tier in ("National", "International") or upset >= 5):
            prospect["notable_wins"] = int(prospect.get("notable_wins", 0) or 0) + 1
        self.academy_strength_of_schedule(prospect)

    def simulate_academy_amateur_bout(self, a, b, label, event_name="Academy Showcase", competition_tier=None):
        self.repair_academy_prospect(a); self.repair_academy_prospect(b)
        competition_tier = competition_tier or self.academy_competition_tier(a)
        a_fighter, b_fighter = self.academy_bout_fighter(a), self.academy_bout_fighter(b)
        fight = {"main": False, "title": False, "tier": event_name, "region": a.get("region", self.player_region), "ai_controlled": True}
        winner_fighter, loser_fighter, method, round_no, lines = self.simulate_fight(a_fighter, b_fighter, fight)
        detail = {"heading": f"{a['name']} vs {b['name']}", "label": f"{label} AMATEUR",
                  "a": a["name"], "b": b["name"], "a_id": a.get("prospect_id", ""),
                  "b_id": b.get("prospect_id", ""), "weight": label, "lines": list(lines)}
        absolute_week = self.calendar_week_index()
        for prospect, opponent in ((a, b), (b, a)):
            prospect["last_amateur_week"] = absolute_week
            counts = prospect.setdefault("opponent_counts", {})
            opponent_key = opponent.get("prospect_id") or opponent["name"]
            counts[opponent_key] = counts.get(opponent_key, 0) + 1
            if len(counts) > 20:
                prospect["opponent_counts"] = dict(list(counts.items())[-20:])
        if method == "No Contest":
            line = f"Month {self.month}: Amateur No Contest - {a['name']} vs {b['name']} ({label}, {event_name}, R{round_no})."
            for prospect, opponent in ((a, b), (b, a)):
                prospect["amateur_history"].insert(0, line)
                prospect["amateur_bout_records"] = ([{
                    "month": self.month, "week": self.week, "event": event_name, "opponent": opponent["name"],
                    "opponent_id": opponent.get("prospect_id", ""),
                    "opponent_rating": opponent.get("rating", 40), "competition_tier": competition_tier,
                    "result": "NC", "method": "No Contest", "round": round_no, "weight": label,
                }] + prospect.get("amateur_bout_records", []))[:100]
            detail.update({"result": line, "winner": "", "winner_id": "", "method": "No Contest", "round": round_no, "draw": False, "no_contest": True})
            detail["lines"] += ["", f"Result: {line}"]
            a["last_amateur_bout"] = b["last_amateur_bout"] = detail
            return line
        if method == "Draw":
            a["amateur_d"] += 1; b["amateur_d"] += 1
            line = f"Month {self.month}: Amateur draw - {a['name']} vs {b['name']} ({label}, {event_name}, R{round_no})."
            a["amateur_history"].insert(0, line); b["amateur_history"].insert(0, line)
            for prospect, opponent in ((a, b), (b, a)):
                prospect["amateur_bout_records"] = ([{
                    "month": self.month, "week": self.week, "event": event_name, "opponent": opponent["name"],
                    "opponent_id": opponent.get("prospect_id", ""),
                    "opponent_rating": opponent.get("rating", 40), "competition_tier": competition_tier,
                    "result": "D", "method": "Draw", "round": round_no, "weight": label,
                }] + prospect.get("amateur_bout_records", []))[:100]
                self.apply_academy_competition_credit(prospect, opponent, "D", competition_tier)
            self.apply_academy_bout_development(a, method, False); self.apply_academy_bout_development(b, method, False)
            detail.update({"result": line, "winner": "Draw", "winner_id": "", "method": "Draw", "round": round_no, "draw": True})
            detail["lines"] += ["", f"Result: {line}"]
            a["last_amateur_bout"] = b["last_amateur_bout"] = detail
            return line
        winner, loser = (a, b) if winner_fighter is a_fighter else (b, a)
        winner["amateur_w"] += 1; loser["amateur_l"] += 1
        line = f"Month {self.month}: Amateur - {winner['name']} def. {loser['name']} by {method} (R{round_no}, {label}, {event_name})."
        winner["amateur_history"].insert(0, line); loser["amateur_history"].insert(0, line)
        for prospect, opponent, result in ((winner, loser, "W"), (loser, winner, "L")):
            prospect["amateur_bout_records"] = ([{
                "month": self.month, "week": self.week, "event": event_name, "opponent": opponent["name"],
                "opponent_id": opponent.get("prospect_id", ""),
                "opponent_rating": opponent.get("rating", 40), "competition_tier": competition_tier,
                "result": result, "method": method, "round": round_no, "weight": label,
            }] + prospect.get("amateur_bout_records", []))[:100]
            self.apply_academy_competition_credit(prospect, opponent, result, competition_tier)
        self.apply_academy_bout_development(winner, method, True); self.apply_academy_bout_development(loser, method, False)
        detail.update({"result": line, "winner": winner["name"], "winner_id": winner.get("prospect_id", ""),
                       "method": method, "round": round_no, "draw": False})
        detail["lines"] += ["", f"Result: {line}"]
        a["last_amateur_bout"] = b["last_amateur_bout"] = detail
        if winner.get("academy_member") and (winner["amateur_w"] in (1, 5, 10) or (winner["amateur_w"] >= 6 and winner["amateur_l"] == 0)):
            milestone = f"M{self.month}: Reached {winner['amateur_w']} amateur wins ({winner['amateur_w']}-{winner['amateur_l']}-{winner.get('amateur_d', 0)})."
            winner["milestones"] = ([milestone] + winner.get("milestones", []))[:20]
        return line

    def academy_amateur_fight_count(self, prospect):
        return prospect.get("amateur_w", 0) + prospect.get("amateur_l", 0) + prospect.get("amateur_d", 0)

    def create_academy_guest_opponent(self, prospect, reserved_names=None, competition_tier=None):
        """Create a same-gender regional amateur for an isolated prospect.

        Academy capacity is intentionally small, so requiring an internal match
        can strand a lone woman or weight-band outlier for years.  Guest amateurs
        give every healthy prospect real simulated experience without signing a
        permanent ninth academy member.
        """
        reserved = set(reserved_names or ()) | {item.get("name", "") for item in self.academy.get("prospects", [])}
        competition_tier = competition_tier or self.academy_competition_tier(prospect)
        tier_profile = self.ACADEMY_COMPETITION_TIERS.get(competition_tier, self.ACADEMY_COMPETITION_TIERS["Local"])
        rating = max(30, min(88, prospect.get("rating", 40) + tier_profile["rating_offset"] + random.randint(-4, 4)))
        fighter = self.create_generated_fighter(
            2, 12, max(28, rating - 6), min(82, rating + 6),
            weight=prospect.get("weight", "Lightweight"),
            gender=prospect.get("gender", "Male"),
            region=prospect.get("region", self.player_region),
        )
        self.avoid_name_collision(fighter, self.active_fighter_names() | reserved)
        guest = {
            "name": fighter.name,
            "age": max(15, min(20, prospect.get("age", 17) + random.choice([-1, 0, 0, 1]))),
            "potential": max(rating, min(88, rating + random.randint(5, 16))),
            "region": prospect.get("region", self.player_region),
            "gender": prospect.get("gender", "Male"),
            "weight": prospect.get("weight", "Lightweight"),
            "amateur_weight": prospect.get("amateur_weight", "Youth Openweight"),
            "rating": rating,
            "style": fighter.style,
            "nationality": fighter.nationality,
            "striking": max(25, min(85, rating + random.randint(-7, 7))),
            "wrestling": max(25, min(85, rating + random.randint(-7, 7))),
            "grappling": max(25, min(85, rating + random.randint(-7, 7))),
            "cardio": max(30, min(88, rating + random.randint(-5, 8))),
            "chin": max(30, min(88, rating + random.randint(-6, 7))),
            "power": max(25, min(86, rating + random.randint(-7, 7))),
            "toughness": max(30, min(88, rating + random.randint(-5, 8))),
            "fight_iq": max(25, min(86, rating + random.randint(-7, 7))),
            "plan": "Regional Club",
            "competition_tier": competition_tier,
            "amateur_w": random.randint(0, 4), "amateur_l": random.randint(0, 3), "amateur_d": 0,
            "amateur_history": [], "weeks": 0, "development": 0, "fatigue": 0, "injured": 0,
        }
        return self.repair_academy_prospect(guest)

    def academy_tournament_eligibility(self, prospect, tier):
        profile = self.ACADEMY_COMPETITION_TIERS.get(tier)
        if not profile:
            return False, "Unknown amateur competition tier."
        bouts = self.academy_amateur_fight_count(prospect)
        if bouts < profile["bouts"] or int(prospect.get("rating", 40) or 40) < profile["rating"]:
            return False, f"{tier} competition requires {profile['bouts']} bouts and rating {profile['rating']}."
        if prospect.get("injured", 0) or prospect.get("fatigue", 0) >= 55:
            return False, "The prospect must be healthy and below 55 fatigue."
        if self.calendar_week_index() - int(prospect.get("last_amateur_week", -99) or -99) < 6:
            return False, "The prospect is still inside the six-week amateur recovery window."
        return True, "Eligible"

    def run_academy_tournament(self, prospect, tier=None, academy=None):
        """Enter one prospect in a four-person, two-bout amateur tournament."""
        academy = academy or getattr(self, "academy", {})
        self.repair_academy_prospect(prospect)
        tier = tier or self.academy_competition_tier(prospect)
        ok, message = self.academy_tournament_eligibility(prospect, tier)
        if not ok:
            return False, message, []
        cost = self.ACADEMY_COMPETITION_TIERS[tier]["cost"]
        if self.cash < cost:
            return False, f"The {tier.lower()} tournament entry costs ${cost:,}.", []
        cash_before = self.cash
        finance_before = deepcopy(getattr(self, "finance", {}))
        prospect_before = deepcopy(prospect)
        academy_before = {
            key: deepcopy(academy.get(key))
            for key in ("operating_spend", "total_tournaments", "competition_history", "reputation", "last_scout_report")
        }
        news_before = list(getattr(self, "news", []))
        rng_before = random.getstate()
        try:
            self.cash -= cost
            academy["operating_spend"] = academy.get("operating_spend", 0) + cost
            self.record_finance_transaction(f"Academy {tier.lower()} tournament: {prospect['name']}", costs=cost)
            event_name = f"{tier} Amateur Tournament"
            results = []
            wins_before = int(prospect.get("amateur_w", 0) or 0)
            semifinal = self.create_academy_guest_opponent(prospect, competition_tier=tier)
            results.append(self.simulate_academy_amateur_bout(prospect, semifinal, prospect.get("amateur_weight", "Youth"), event_name, tier))
            won_semifinal = int(prospect.get("amateur_w", 0) or 0) > wins_before
            champion = False
            if won_semifinal and not prospect.get("injured", 0):
                final_wins = int(prospect.get("amateur_w", 0) or 0)
                final = self.create_academy_guest_opponent(prospect, {semifinal.get("name", "")}, tier)
                results.append(self.simulate_academy_amateur_bout(prospect, final, prospect.get("amateur_weight", "Youth"), event_name, tier))
                champion = int(prospect.get("amateur_w", 0) or 0) > final_wins
            academy["total_tournaments"] = academy.get("total_tournaments", 0) + 1
            tournament = {
                "month": self.month, "week": self.week, "prospect_id": prospect.get("prospect_id", ""),
                "prospect_name": prospect.get("name", ""), "tier": tier, "cost": cost,
                "results": list(results), "champion": champion,
            }
            academy["competition_history"] = ([tournament] + academy.get("competition_history", []))[:60]
            if champion:
                title = f"{tier} Amateur Champion"
                prospect["amateur_titles"] = ([{"title": title, "month": self.month, "week": self.week}] + prospect.get("amateur_titles", []))[:20]
                prospect["confidence"] = min(99, prospect.get("confidence", 55) + 6)
                prospect["satisfaction"] = min(100, prospect.get("satisfaction", 60) + 6)
                academy["reputation"] = min(100, academy.get("reputation", 10) + self.ACADEMY_COMPETITION_TIERS[tier]["quality"])
                self.fulfill_academy_promise(prospect, "Tournament Opportunity")
            note = f"{prospect['name']} {'won' if champion else 'competed in'} the {tier.lower()} amateur tournament."
            academy["last_scout_report"] = note
            return True, note, results
        except Exception:
            self.cash = cash_before
            if isinstance(getattr(self, "finance", None), dict):
                self.finance.clear()
                self.finance.update(finance_before)
            else:
                self.finance = finance_before
            prospect.clear()
            prospect.update(prospect_before)
            for key, value in academy_before.items():
                academy[key] = value
            if isinstance(getattr(self, "news", None), list):
                self.news[:] = news_before
            random.setstate(rng_before)
            return False, "The tournament failed before completion; academy and finance state were restored.", []

    ACADEMY_PROMISE_TYPES = ("Tournament Opportunity", "Graduation Review", "Recovery Support")

    def make_academy_promise(self, prospect, promise_type, weeks=12):
        self.repair_academy_prospect(prospect)
        if prospect.get("promise"):
            return False, f"{prospect['name']} already has an active academy promise."
        if promise_type not in self.ACADEMY_PROMISE_TYPES:
            return False, "Choose a valid academy promise."
        prospect["promise"] = {
            "type": promise_type, "made_month": self.month, "made_week": self.week,
            "deadline_week": self.calendar_week_index() + max(4, int(weeks or 12)), "fulfilled": False,
        }
        prospect["retention_history"] = ([f"M{self.month} W{self.week}: Academy promised {promise_type.lower()}."]
                                         + prospect.get("retention_history", []))[:30]
        return True, f"Promised {prospect['name']} a {promise_type.lower()} within {max(4, int(weeks or 12))} weeks."

    def fulfill_academy_promise(self, prospect, promise_type):
        promise = prospect.get("promise") or {}
        if promise.get("type") != promise_type:
            return False
        prospect["promise"] = {}
        prospect["satisfaction"] = min(100, int(prospect.get("satisfaction", 60) if prospect.get("satisfaction") is not None else 60) + 9)
        prospect["loyalty"] = min(100, int(prospect.get("loyalty", 60) if prospect.get("loyalty") is not None else 60) + 5)
        prospect["retention_history"] = ([f"M{self.month} W{self.week}: Academy fulfilled {promise_type.lower()}."]
                                         + prospect.get("retention_history", []))[:30]
        return True

    def academy_departure_risk(self, prospect):
        satisfaction = int(prospect.get("satisfaction", 60) if prospect.get("satisfaction") is not None else 60)
        loyalty = int(prospect.get("loyalty", 60) if prospect.get("loyalty") is not None else 60)
        trait = prospect.get("youth_trait", "Patient")
        trait_risk = 0.05 if trait in ("Ambitious", "Volatile", "Homesick") else -0.03 if trait in ("Loyal", "Patient") else 0.0
        return max(0.0, min(0.45, (28 - satisfaction) / 70 + (45 - loyalty) / 180 + trait_risk))

    def process_academy_retention(self, prospect, academy=None):
        academy = academy or getattr(self, "academy", {})
        self.repair_academy_prospect(prospect)
        satisfaction = int(prospect.get("satisfaction", 60) if prospect.get("satisfaction") is not None else 60)
        if prospect.get("development_plan"):
            satisfaction += 1
        if prospect.get("fatigue", 0) >= 80:
            satisfaction -= 4
        elif prospect.get("fatigue", 0) >= 65:
            satisfaction -= 2
        if prospect.get("injured", 0):
            satisfaction -= 1
        trait = prospect.get("youth_trait", "Patient")
        if trait == "Ambitious" and self.calendar_week_index() - int(prospect.get("last_amateur_week", -99) or -99) > 10:
            satisfaction -= 2
        elif trait == "Academically Focused" and prospect.get("training_intensity") == "Intensive":
            satisfaction -= 1
        elif trait == "Loyal":
            satisfaction += 1
        promise = prospect.get("promise") or {}
        if promise.get("type") == "Recovery Support" and prospect.get("fatigue", 0) <= 25 and not prospect.get("injured", 0):
            self.fulfill_academy_promise(prospect, "Recovery Support")
            promise = {}
            satisfaction = int(prospect.get("satisfaction", satisfaction) if prospect.get("satisfaction") is not None else satisfaction)
        if promise and self.calendar_week_index() > int(promise.get("deadline_week", 0) or 0):
            satisfaction -= 12
            prospect["loyalty"] = max(0, int(prospect.get("loyalty", 60) if prospect.get("loyalty") is not None else 60) - 8)
            prospect["retention_history"] = ([f"M{self.month} W{self.week}: Academy broke its {promise.get('type', 'development').lower()} promise."]
                                             + prospect.get("retention_history", []))[:30]
            prospect["promise"] = {}
        prospect["satisfaction"] = max(0, min(100, satisfaction))
        risk = self.academy_departure_risk(prospect)
        prospect["retention_status"] = "At Risk" if risk >= 0.18 else "Unsettled" if risk >= 0.06 else "Committed"
        if risk and random.random() < risk:
            if prospect in academy.get("prospects", []):
                academy["prospects"].remove(prospect)
            departure = {
                "prospect_id": prospect.get("prospect_id", ""), "name": prospect.get("name", ""),
                "age": prospect.get("age", 0), "rating": prospect.get("rating", 0),
                "potential": prospect.get("potential", 0), "month": self.month, "week": self.week,
                "reason": f"Left with {prospect.get('satisfaction', 0)} satisfaction",
            }
            academy["departed_prospects"] = ([departure] + academy.get("departed_prospects", []))[:60]
            academy["last_scout_report"] = f"{prospect['name']} left the academy after becoming dissatisfied with their pathway."
            self.news.insert(0, academy["last_scout_report"])
            return True
        return False

    def choose_academy_showcase_card(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        absolute_week = self.calendar_week_index()
        ready = [item for item in academy.get("prospects", [])
                 if not item.get("injured", 0) and item.get("fatigue", 0) < 70
                 and absolute_week - item.get("last_amateur_week", -99) >= 6]
        ready.sort(key=lambda item: (self.academy_amateur_fight_count(item), item.get("fatigue", 0), random.random()))
        # Every healthy, rested academy member receives a bout on a due card.
        # Guest amateurs fill isolated gender/weight slots rather than forcing
        # unsafe youth open-weight pairings.
        target_bouts = max(1, len(ready))
        bouts, used = [], set()
        identity = lambda item: item.get("prospect_id") or self.academy_prospect_id(item)
        for a in ready:
            if len(bouts) >= target_bouts:
                break
            if identity(a) in used:
                continue
            candidates = [b for b in ready if identity(b) not in used and identity(b) != identity(a)
                          and b.get("gender") == a.get("gender") and b.get("amateur_weight") == a.get("amateur_weight")]
            same_weight = [b for b in candidates if b.get("amateur_weight") == a.get("amateur_weight")]
            pool = same_weight
            if not pool:
                continue
            b = min(pool, key=lambda item: abs(item.get("rating", 40) - a.get("rating", 40)) + abs(self.academy_amateur_fight_count(item) - self.academy_amateur_fight_count(a)) + max(a.get("opponent_counts", {}).get(identity(item), 0), a.get("opponent_counts", {}).get(item.get("name"), 0)) * 14)
            if max(a.get("opponent_counts", {}).get(identity(b), 0), a.get("opponent_counts", {}).get(b.get("name"), 0)) >= 3:
                continue
            label = a.get("amateur_weight", "Youth Openweight") if b in same_weight else "Open Youth"
            bouts.append((a, b, label)); used.update([identity(a), identity(b)])
        # Fill any odd or isolated slots with regional guest amateurs.  The guest
        # is simulated normally but is not retained in the owned academy roster.
        reserved = {item.get("name", "") for item in ready}
        for prospect in ready:
            if len(bouts) >= target_bouts:
                break
            if identity(prospect) in used:
                continue
            guest = self.create_academy_guest_opponent(prospect, reserved)
            reserved.add(guest["name"])
            bouts.append((prospect, guest, prospect.get("amateur_weight", "Youth Openweight")))
            used.add(identity(prospect))
        return bouts

    def run_academy_showcase_card(self, academy=None, bouts=None):
        academy = academy or getattr(self, "academy", {})
        results, fight_logs = [], []
        for a, b, label in (bouts if bouts is not None else self.choose_academy_showcase_card(academy)):
            results.append(self.simulate_academy_amateur_bout(a, b, label))
            fight_logs.append(dict(a.get("last_amateur_bout", {})))
        if results:
            academy["total_cards"] = academy.get("total_cards", 0) + 1
            card_number = academy["total_cards"]
            card = {"event_name": f"{self.player_company_name} Academy Showcase {card_number}",
                    "date": f"Month {self.month} Week {self.week}", "results": list(results),
                    "fight_logs": fight_logs, "recap": f"{len(results)} amateur bout(s) completed."}
            academy["card_history"] = ([card] + academy.get("card_history", []))[:24]
            academy["last_showcase_week"] = self.calendar_week_index()
            academy["last_showcase_recap"] = "\n".join(results)
            academy["total_bouts"] = academy.get("total_bouts", 0) + len(results)
            academy["reputation"] = min(100, academy.get("reputation", 10) + (1 if academy["total_bouts"] % 12 < len(results) else 0))
        return results

    def run_academy_showcase_if_due(self, academy=None):
        academy = academy or getattr(self, "academy", {})
        if not academy.get("owned") or not academy.get("auto_showcases", True):
            return None
        absolute_week = self.calendar_week_index()
        if absolute_week - int(academy.get("last_showcase_week", -99)) < 4:
            return None
        bouts = self.choose_academy_showcase_card(academy)
        required = max(1, min(12, int(academy.get("auto_card_min_bouts", 2) or 2)))
        if len(bouts) < required:
            academy["showcase_weeks"] = 1
            return None
        results = self.run_academy_showcase_card(academy, bouts=bouts)
        academy["showcase_weeks"] = 4
        academy["last_scout_report"] = f"Academy auto-card: {len(results)} bout(s) completed after reaching the {required}-fight requirement."
        if results:
            self.news.insert(0, academy["last_scout_report"])
        return academy["last_scout_report"]

    def academy_showcase_status(self, academy=None):
        """Return an observational status derived from the actual card clock."""
        academy = academy or getattr(self, "academy", {})
        if not academy.get("auto_showcases", True):
            return "Automatic cards off"
        elapsed = self.calendar_week_index() - int(academy.get("last_showcase_week", -99) or -99)
        remaining = max(0, 4 - elapsed)
        if remaining:
            return f"Next eligibility check in {remaining} week(s)"
        return "Eligible-card check due"

    def create_academy_challenge(self, academy=None):
        """Create a player-facing development decision for a signed prospect.

        Challenges are deliberately infrequent and persistent. They turn the
        academy from a passive weekly queue into a small coaching story without
        interrupting the normal calendar with a modal dialog.
        """
        academy = academy or getattr(self, "academy", {})
        prospects = [item for item in academy.get("prospects", []) if not item.get("injured")]
        if not prospects or academy.get("active_challenge"):
            return None
        prospect = random.choice(prospects)
        focus, _reason, fields = self.academy_focus_recommendation(prospect)
        challenge_types = [
            ("breakthrough", "Breakthrough Camp", f"{prospect['name']} is close to a breakthrough in {focus}. Do you push for a defining camp or protect the long build?"),
            ("pressure", "Pressure Test", f"{prospect['name']} needs experience against a live opponent. Do you accept a difficult test or keep developing in the gym?"),
            ("mentor", "Mentor's Choice", f"The coaching staff disagree about {prospect['name']}. A specialist wants to sharpen {fields[0].replace('_', ' ')}, while the head coach prefers a broader plan."),
        ]
        challenge_type, title, prompt = random.choice(challenge_types)
        challenge = {
            "id": f"academy-challenge-{self.month}-{self.week}-{academy.get('challenge_count', 0) + 1}",
            "type": challenge_type, "title": title, "prompt": prompt,
            "prospect_id": prospect.get("prospect_id", ""), "prospect_name": prospect.get("name", "Unknown Prospect"),
            "created_month": self.month, "created_week": self.week,
            "expires_week": self.calendar_week_index() + 6,
            "focus": focus,
        }
        academy["active_challenge"] = challenge
        academy["last_challenge_week"] = self.calendar_week_index()
        academy["challenge_count"] = academy.get("challenge_count", 0) + 1
        academy["last_scout_report"] = f"Academy decision available: {title} for {prospect['name']}."
        if not getattr(self, "spectator_mode", False):
            self.inbox.append({
                "subject": f"Academy Decision - {title}", "body": prompt,
                "type": "Academy", "fighter": prospect.get("name", ""), "resolved": False,
            })
        return challenge

    def resolve_academy_challenge(self, choice, academy=None):
        """Resolve the active academy challenge and return (ok, message)."""
        academy = academy or getattr(self, "academy", {})
        challenge = academy.get("active_challenge") or {}
        if not challenge:
            return False, "There is no active academy decision."
        challenge_prospect_id = str(challenge.get("prospect_id", "") or "")
        if challenge_prospect_id:
            prospect = next((item for item in academy.get("prospects", [])
                             if str(item.get("prospect_id", "") or "") == challenge_prospect_id), None)
        else:
            legacy_matches = [item for item in academy.get("prospects", [])
                              if item.get("name") == challenge.get("prospect_name")]
            prospect = legacy_matches[0] if len(legacy_matches) == 1 else None
        if not prospect:
            academy["active_challenge"] = {}
            return False, "The prospect attached to this decision is no longer in the academy."
        self.repair_academy_prospect(prospect)
        choice = str(choice or "").lower()
        result = ""
        if choice == "camp":
            cost = 25_000 + max(0, academy.get("level", 1) - 1) * 5_000
            if self.cash < cost:
                return False, f"The specialist camp needs ${cost:,}."
            self.cash -= cost
            academy["operating_spend"] = academy.get("operating_spend", 0) + cost
            self.record_finance_transaction(f"Academy challenge camp: {prospect['name']}", costs=cost)
            fields = self.academy_training_fields(challenge.get("focus", "Balanced"), prospect)
            for field in fields[:2]:
                prospect[field] = min(prospect.get("potential", 99), prospect.get(field, 40) + 1)
            prospect["development"] = prospect.get("development", 0) + 2
            prospect["confidence"] = min(99, prospect.get("confidence", 55) + 5)
            prospect["fatigue"] = min(100, prospect.get("fatigue", 0) + 8)
            prospect["last_development"] = f"Specialist camp focused on {challenge.get('focus', 'balanced development')}"
            result = f"{prospect['name']} completed a specialist camp and gained confidence and development."
        elif choice == "test":
            if prospect.get("fatigue", 0) >= 60 or prospect.get("injured", 0):
                return False, f"{prospect['name']} is not healthy enough for a pressure test."
            guest = self.create_academy_guest_opponent(prospect)
            line = self.simulate_academy_amateur_bout(prospect, guest, prospect.get("amateur_weight", "Youth Openweight"))
            academy["reputation"] = min(100, academy.get("reputation", 10) + 1)
            result = f"Pressure test complete: {line}"
        elif choice == "mentor":
            prospect["plan"] = challenge.get("focus", "Balanced") if challenge.get("focus") not in ("Automatic", "Balanced") else "Balanced"
            prospect["coachability"] = min(99, prospect.get("coachability", 55) + 4)
            prospect["confidence"] = min(99, prospect.get("confidence", 55) + 2)
            prospect["fatigue"] = max(0, prospect.get("fatigue", 0) - 6)
            result = f"The staff aligned around {prospect['name']}'s {prospect['plan']} plan."
            self.record_academy_mentorship_story(
                prospect, phase="coaches_aligned", summary=result,
            )
        else:
            return False, "Choose a valid academy decision."
        record = dict(challenge)
        record.update({"choice": choice, "resolved_month": self.month, "resolved_week": self.week, "result": result})
        academy["challenge_history"] = ([record] + academy.get("challenge_history", []))[:40]
        academy["active_challenge"] = {}
        academy["last_scout_report"] = result
        academy.setdefault("development_events", []).insert(0, {"month": self.month, "week": self.week, "note": result})
        academy["development_events"] = academy["development_events"][:80]
        self.news.insert(0, f"Academy decision: {result}")
        self.record_academy_progress(prospect, f"Academy decision: {choice}")
        return True, result

    def process_academy_week(self):
        academy = self.repair_academy(getattr(self, "academy", {}))
        if not academy.get("owned") or getattr(self, "spectator_mode", False):
            return
        self.cash -= academy.get("weekly_cost", 0)
        academy["operating_spend"] = academy.get("operating_spend", 0) + academy.get("weekly_cost", 0)
        self.record_finance_transaction("Academy operating costs", costs=academy.get("weekly_cost", 0))
        for prospect in list(academy.get("prospects", [])):
            self.train_academy_prospect(prospect, academy)
            self.process_academy_development_plan(prospect, academy)
            self.process_academy_retention(prospect, academy)
        self.process_academy_graduations(academy)
        for prospect in list(academy.get("talent_pool", [])):
            self.refine_academy_lead(prospect, academy)
            prospect["weeks_to_sign"] = prospect.get("weeks_to_sign", 2) - 1
            if prospect["weeks_to_sign"] < 0:
                academy["talent_pool"].remove(prospect)
                joined_rival = self.place_academy_lead_with_rival(prospect)
                academy["lost_leads"] = ([{"name": prospect.get("name", "Unknown"), "region": prospect.get("region", ""),
                                                    "potential_range": list(prospect.get("potential_range", (0, 0))), "lost_month": self.month,
                                                    "destination": (prospect.get("rival_offer") or {}).get("promotion", "") if joined_rival else ""}]
                                                 + academy.get("lost_leads", []))[:30]
                academy["last_scout_report"] = (
                    f"The signing window closed for {prospect.get('name', 'a youth prospect')}; "
                    + (f"they joined {(prospect.get('rival_offer') or {}).get('promotion')}." if joined_rival else "the lead left your network.")
                )
        if academy.get("network_weeks", 0) > 0:
            academy["network_weeks"] -= 1
            if academy["network_weeks"] <= 0:
                academy["network_active"] = True
                academy["last_scout_report"] = f"{academy.get('network_scout', 'Scout')} established a youth scouting network in {academy.get('network_region', self.player_region)}."
                self.inbox.append({"subject": "Academy Network Ready", "body": academy["last_scout_report"], "type": "Scouting", "resolved": False})
        if academy.get("network_active") and len(academy.get("talent_pool", [])) < 8:
            open_slots = max(0, 8 - len(academy.get("talent_pool", [])))
            judging = (academy.get("network_scout_skill", 45) + academy.get("network_potential_skill", 45)) / 2
            networking = academy.get("network_networking", 45)
            reliability = academy.get("network_reliability", 45)
            lead_chance = max(0.20, min(0.80, 0.20 + networking / 210 + reliability / 500))
            added = 0
            for _ in range(open_slots):
                if random.random() < lead_chance:
                    academy["talent_pool"].append(self.create_academy_scout_prospect(judging, region=academy.get("network_region", self.player_region)))
                    added += 1
            if added:
                academy["network_leads_found"] = academy.get("network_leads_found", 0) + added
                academy["last_scout_report"] = f"{academy.get('network_region', self.player_region)} network produced {added} youth lead(s). Leads expire after 2-3 weeks."
        self.process_academy_recruitment_competition(academy)
        self.run_academy_showcase_if_due(academy)
        if academy.get("active_challenge") and self.calendar_week_index() >= academy["active_challenge"].get("expires_week", 0):
            expired = academy["active_challenge"].get("prospect_name", "the prospect")
            academy["challenge_history"] = ([dict(academy["active_challenge"], choice="deferred", resolved_month=self.month, resolved_week=self.week, result="Decision window expired; the coaching staff kept the standard plan.")] + academy.get("challenge_history", []))[:40]
            academy["active_challenge"] = {}
            academy["last_scout_report"] = f"The academy decision window for {expired} expired; staff kept the standard plan."
        if not academy.get("active_challenge") and self.calendar_week_index() - academy.get("last_challenge_week", -99) >= 8:
            if random.random() < 0.70:
                self.create_academy_challenge(academy)
        self.expire_academy_matching_rights(academy)
        self.update_academy_alumni(academy)

    def all_scoutable_fighters(self):
        """Return one live object per permanent fighter identity."""
        rows = list(getattr(self, "roster", [])) + list(getattr(self, "free_agents", []))
        rows += list(getattr(self, "retired_fighters", []))
        for promo in getattr(self, "promotions", []):
            rows.extend(promo.roster)
        unique = {}
        for fighter in rows:
            unique.setdefault(str(getattr(fighter, "fighter_id", "") or fighter.name), fighter)
        return list(unique.values())

    def scouting_report_key(self, fighter):
        return str(getattr(fighter, "fighter_id", "") or fighter.name)

    SCOUTING_DECISION_STATES = ("Considering", "Needs report", "Ready for negotiation", "Archived")

    @staticmethod
    def _legacy_scouting_decision_pack_id(pack):
        """Return a deterministic identity for an ID-less retained decision pack."""
        pack = pack if isinstance(pack, dict) else {}
        candidate_ids = pack.get("candidate_ids", [])
        if not isinstance(candidate_ids, (list, tuple)):
            candidate_ids = []
        payload = {
            "name": str(pack.get("name", "") or ""),
            "purpose": str(pack.get("purpose", "") or ""),
            "watchlist_id": str(pack.get("watchlist_id", "") or ""),
            "candidate_ids": [str(value) for value in candidate_ids if value],
            "created_week": pack.get("created_week", 0),
        }
        digest = hashlib.sha1(
            json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest()[:20]
        return f"PACK-legacy-{digest}"

    def ensure_scouting_decision_packs(self):
        """Repair the small, ID-backed recruitment decision shelf.

        Packs are player notes over existing watchlist/report records.  This
        migration is deliberately conservative: it keeps unavailable fighter
        IDs and old snapshots so a departed candidate remains explainable.
        """
        rows = getattr(self, "scouting_decision_packs", None)
        if not isinstance(rows, list):
            rows = []
        normalized, seen = [], set()
        for raw in rows[:40]:
            if not isinstance(raw, dict):
                continue
            pack = dict(raw)
            pack_id = str(pack.get("pack_id", "") or "").strip()[:48]
            if not pack_id:
                base_pack_id = self._legacy_scouting_decision_pack_id(pack)
                pack_id = base_pack_id
                suffix = 2
                while pack_id in seen:
                    pack_id = f"{base_pack_id}#{suffix}"
                    suffix += 1
            if not pack_id or pack_id in seen:
                continue
            seen.add(pack_id)
            state = str(pack.get("decision_state", "Considering") or "Considering")
            if state not in self.SCOUTING_DECISION_STATES:
                state = "Considering"
            candidate_ids = list(dict.fromkeys(str(value) for value in (pack.get("candidate_ids", []) or []) if value))[:4]
            notes = pack.get("player_notes", {})
            if not isinstance(notes, dict):
                notes = {}
            notes = {str(key): str(value)[:800] for key, value in notes.items() if key in candidate_ids}
            snapshots = pack.get("candidate_snapshots", {})
            if not isinstance(snapshots, dict):
                snapshots = {}
            snapshots = {str(key): dict(value) for key, value in snapshots.items() if key in candidate_ids and isinstance(value, dict)}
            criteria = pack.get("comparison_criteria", [])
            if not isinstance(criteria, list):
                criteria = []
            pack.update({
                "pack_id": pack_id,
                "name": str(pack.get("name", "Recruitment Decision") or "Recruitment Decision")[:60],
                "purpose": str(pack.get("purpose", "") or "")[:240],
                "watchlist_id": str(pack.get("watchlist_id", "") or ""),
                "candidate_ids": candidate_ids,
                "player_notes": notes,
                "candidate_snapshots": snapshots,
                "comparison_criteria": [str(value)[:80] for value in criteria[:8] if value],
                "decision_state": state,
                "created_week": max(0, int(pack.get("created_week", 0) or 0)),
                "updated_week": max(0, int(pack.get("updated_week", pack.get("created_week", 0)) or 0)),
                "archived": bool(state == "Archived" or pack.get("archived", False)),
            })
            normalized.append(pack)
        self.scouting_decision_packs = normalized
        return normalized

    def _scouting_decision_candidate_map(self):
        return {
            self.scouting_report_key(fighter): fighter
            for fighter in self.all_scoutable_fighters()
            if self.scouting_report_key(fighter)
        }

    def create_scouting_decision_pack(self, name, purpose, candidate_ids, watchlist_id=""):
        """Create a two-to-four-candidate pack from existing IDs only."""
        self.migrate_scouting_state()
        self.ensure_scouting_decision_packs()
        ids = list(dict.fromkeys(str(value) for value in (candidate_ids or []) if value))
        if not 2 <= len(ids) <= 4:
            return False, "Choose between two and four visible candidates."
        candidates = self._scouting_decision_candidate_map()
        if any(candidate_id not in candidates for candidate_id in ids):
            return False, "One or more candidates are no longer available in the identity index."
        existing_ids = {str(row.get("pack_id", "")) for row in self.scouting_decision_packs}
        sequence = len(self.scouting_decision_packs) + 1
        pack_id = f"PACK-{sequence:04d}"
        while pack_id in existing_ids:
            sequence += 1
            pack_id = f"PACK-{sequence:04d}"
        snapshots = {}
        for candidate_id in ids:
            fighter = candidates[candidate_id]
            report = self.scouting_report_for(fighter, migrate=False)
            snapshots[candidate_id] = {
                "fighter_id": candidate_id,
                "fighter_name": str(getattr(fighter, "name", "") or ""),
                "captured_week": self.calendar_week_index(),
                "company": self.scouting_target_company_for(fighter) if hasattr(self, "scouting_target_company_for") else "",
                "weight": str(getattr(fighter, "weight", "") or ""),
                "gender": str(getattr(fighter, "gender", "") or ""),
                "record": str(getattr(fighter, "record", "") or ""),
                "age": int(getattr(fighter, "age", 0) or 0),
                "purse": int(getattr(fighter, "purse", 0) or 0),
                "report": self.scouting_report_snapshot(self.scouting_intel_report(report)),
            }
        pack = {
            "pack_id": pack_id, "name": str(name or "Recruitment Decision")[:60],
            "purpose": str(purpose or "")[:240], "watchlist_id": str(watchlist_id or ""),
            "candidate_ids": ids, "player_notes": {}, "candidate_snapshots": snapshots,
            "comparison_criteria": ["Division fit", "Current evidence", "Upside", "Affordability"],
            "decision_state": "Considering", "archived": False,
            "created_week": self.calendar_week_index(), "updated_week": self.calendar_week_index(),
        }
        self.scouting_decision_packs.insert(0, pack)
        self.scouting_decision_packs = self.scouting_decision_packs[:40]
        return True, pack

    def update_scouting_decision_pack(self, pack_id, *, name=None, purpose=None, state=None, notes=None):
        """Apply explicit player edits while retaining prior evidence snapshots."""
        self.ensure_scouting_decision_packs()
        key = str(pack_id or "")
        pack = next((row for row in self.scouting_decision_packs if row.get("pack_id") == key), None)
        if not pack:
            return False, "Decision pack not found."
        if name is not None:
            pack["name"] = str(name or "Recruitment Decision")[:60]
        if purpose is not None:
            pack["purpose"] = str(purpose or "")[:240]
        if state is not None:
            state = str(state)
            if state not in self.SCOUTING_DECISION_STATES:
                return False, "Choose a valid decision state."
            pack["decision_state"] = state
            pack["archived"] = state == "Archived"
        if notes is not None:
            candidate_ids = set(pack.get("candidate_ids", []))
            if not isinstance(notes, dict):
                return False, "Candidate notes must be a mapping."
            pack["player_notes"] = {str(key): str(value)[:800] for key, value in notes.items() if str(key) in candidate_ids}
        pack["updated_week"] = self.calendar_week_index()
        return True, pack

    def scouting_decision_pack_read_model(self, pack):
        """Build a display-safe comparison card without updating reports."""
        pack = pack if isinstance(pack, dict) else {}
        live = self._scouting_decision_candidate_map()
        candidates = []
        snapshots = pack.get("candidate_snapshots", {}) if isinstance(pack.get("candidate_snapshots"), dict) else {}
        notes = pack.get("player_notes", {}) if isinstance(pack.get("player_notes"), dict) else {}
        candidate_values = pack.get("candidate_ids", [])
        if not isinstance(candidate_values, list):
            candidate_values = []
        for candidate_id in list(dict.fromkeys(str(value) for value in candidate_values if value))[:4]:
            fighter = live.get(candidate_id)
            snapshot = dict(snapshots.get(candidate_id, {}) or {})
            report = snapshot.get("report", {}) if isinstance(snapshot.get("report"), dict) else {}
            current_report = self.scouting_report_for(fighter, migrate=False) if fighter else {}
            current_status = str(current_report.get("status", "Unscouted") or "Unscouted")
            candidates.append({
                "fighter_id": candidate_id,
                "name": str(getattr(fighter, "name", "") or snapshot.get("fighter_name", "Unavailable")),
                "available": bool(fighter and not getattr(fighter, "retired", False)),
                "warning": "Retired or unavailable" if not fighter or getattr(fighter, "retired", False) else "",
                "company_now": self.scouting_target_company_for(fighter) if fighter and hasattr(self, "scouting_target_company_for") else snapshot.get("company", "Unknown"),
                "division": str(getattr(fighter, "weight", "") or snapshot.get("weight", "-")) if fighter else str(snapshot.get("weight", "-")),
                "record_now": str(getattr(fighter, "record", "") or snapshot.get("record", "-")) if fighter else str(snapshot.get("record", "-")),
                "report_status": current_status if fighter else ("Historical snapshot" if report else "No evidence"),
                "captured_week": self._safe_nonnegative_int(snapshot.get("captured_week", 0)),
                "captured_report": report,
                "player_note": str(notes.get(candidate_id, "") or ""),
            })
        return {
            "pack_id": str(pack.get("pack_id", "") or ""), "name": str(pack.get("name", "Recruitment Decision") or "Recruitment Decision"),
            "purpose": str(pack.get("purpose", "") or ""), "decision_state": str(pack.get("decision_state", "Considering") or "Considering"),
            "archived": bool(pack.get("archived", False)), "watchlist_id": str(pack.get("watchlist_id", "") or ""),
            "created_week": self._safe_nonnegative_int(pack.get("created_week", 0)),
            "updated_week": self._safe_nonnegative_int(pack.get("updated_week", 0)),
            "comparison_criteria": list(pack.get("comparison_criteria", []) or []) if isinstance(pack.get("comparison_criteria", []), list) else [],
            "candidates": candidates,
        }

    @staticmethod
    def _safe_nonnegative_int(value, default=0):
        try:
            return max(0, int(value or 0))
        except (TypeError, ValueError):
            return max(0, int(default or 0))

    def scouting_report_for(self, fighter, migrate=True):
        if migrate:
            self.migrate_scouting_state()
        reports = getattr(self, "scouting_reports", {})
        key = self.scouting_report_key(fighter)
        return reports.get(key, {}) or {}

    @staticmethod
    def scouting_report_snapshot(report):
        """Return a bounded, JSON-safe dossier snapshot without recursive prior state."""
        if not isinstance(report, dict) or report.get("status") != "Complete":
            return {}
        keys = (
            "schema_version", "fighter_id", "fighter_name", "kind", "status", "started_week",
            "completed_week", "confidence", "reveal", "scout", "scout_id", "region", "notes",
            "estimates", "recommendation", "recommendation_reason", "evidence", "look_number",
        )
        return deepcopy({key: report.get(key) for key in keys if key in report})

    def scouting_report_history(self, report):
        rows = self._scouting_dict_rows(report.get("history", []) if isinstance(report, dict) else [])
        return rows[-12:]

    def append_scouting_history(self, event_type, fighter=None, detail="", report=None, assignment_id=""):
        """Persist an audit trail separately from the mutable current-report index."""
        rows = self._scouting_dict_rows(getattr(self, "scouting_history", []))
        fighter_id = self.scouting_report_key(fighter) if fighter else str((report or {}).get("fighter_id", "") or "")
        fighter_name = getattr(fighter, "name", "") if fighter else str((report or {}).get("fighter_name", "") or "")
        rows.append({
            "history_id": f"SCOUT-{self.calendar_week_index()}-{len(rows) + 1}",
            "week": self.calendar_week_index(), "type": str(event_type), "fighter_id": fighter_id,
            "fighter_name": fighter_name, "assignment_id": str(assignment_id or ""),
            "detail": str(detail or ""), "report_snapshot": self.scouting_report_snapshot(report or {}),
        })
        self.scouting_history = rows[-1000:]

    def scouting_region_knowledge(self, region):
        row = (getattr(self, "scouting_knowledge", {}) or {}).get(str(region), {})
        value = int(row.get("knowledge", 0) or 0) if isinstance(row, dict) else 0
        return max(0, min(100, value))

    def update_scouting_region_knowledge(self, region, gain, source=""):
        if not region:
            return 0
        knowledge = dict(getattr(self, "scouting_knowledge", {}) or {})
        row = dict(knowledge.get(str(region), {}) or {})
        before = max(0, min(100, int(row.get("knowledge", 0) or 0)))
        row.update({
            "knowledge": min(100, before + max(0, int(gain or 0))),
            "last_week": self.calendar_week_index(), "looks": int(row.get("looks", 0) or 0) + 1,
            "source": str(source or row.get("source", "")),
        })
        knowledge[str(region)] = row
        self.scouting_knowledge = knowledge
        return row["knowledge"]

    def scouting_report_notes(self, fighter, confidence, evidence=None):
        """Create opinion notes only when evidence has actually been delivered."""
        notes = []
        if confidence >= 35:
            notes.append("Strong striking base" if fighter.striking >= fighter.wrestling else "Reliable wrestling base")
        if confidence >= 50:
            notes.append("High upside" if fighter.potential >= fighter.overall + 12 else "Limited upside")
        if confidence >= 65:
            notes.append("Durable and well-conditioned" if fighter.cardio + fighter.chin >= 145 else "Conditioning or durability concern")
        if confidence >= 80:
            notes.append("Professional preparation" if fighter.professionalism >= 70 else "Preparation consistency concern")
        if evidence:
            notes.append("Live-fight evidence supports this assessment.")
        return notes

    def active_scouting_watchlist_ids(self):
        """Return the active ID-safe watchlist while preserving the legacy shortlist mirror."""
        watchlists = self._scouting_dict_rows(getattr(self, "scouting_watchlists", []))
        if not watchlists:
            watchlists = [{
                "watchlist_id": "WATCH-main", "name": "Main Watchlist",
                "fighter_ids": list(dict.fromkeys(str(value) for value in getattr(self, "scouting_shortlist", []) if value)),
                "alerts_enabled": True, "created_week": self.calendar_week_index(),
            }]
            self.scouting_watchlists = watchlists
        active_id = str(getattr(self, "rules", {}).get("scouting_active_watchlist_id", "WATCH-main") or "WATCH-main")
        active = next((row for row in watchlists if row.get("watchlist_id") == active_id and not row.get("archived", False)), None)
        if active is None:
            active = next((row for row in watchlists if not row.get("archived", False)), watchlists[0])
        ids = list(dict.fromkeys(str(value) for value in active.get("fighter_ids", []) if value))[-2000:]
        active["fighter_ids"] = ids
        if active.get("watchlist_id") == "WATCH-main":
            self.scouting_shortlist = list(ids)
        return ids

    def scouting_watchlist_read_model(self):
        """Return a defensive named-watchlist index without repairing the save.

        The Target Board uses this projection for its selector.  Normalising
        malformed legacy rows remains the explicit load/migration boundary;
        merely opening or refreshing Scouting must not invent a list or rewrite
        a retained candidate collection.
        """
        raw = getattr(self, "scouting_watchlists", None)
        if not isinstance(raw, list):
            return []
        rows = []
        seen = set()
        for index, value in enumerate(raw, 1):
            if not isinstance(value, dict):
                continue
            saved_watchlist_id = str(value.get("watchlist_id", "") or "").strip()
            watchlist_id = saved_watchlist_id
            if not watchlist_id:
                payload = {
                    "raw_type": type(value).__name__,
                    "name": value.get("name", ""),
                    "fighter_ids": value.get("fighter_ids", []),
                    "created_week": value.get("created_week", 0),
                    "alerts_enabled": value.get("alerts_enabled", True),
                    "archived": value.get("archived", False),
                }
                digest = hashlib.sha1(
                    json.dumps(payload, sort_keys=True, default=str, separators=(",", ":")).encode("utf-8", "replace")
                ).hexdigest()[:16]
                watchlist_id = f"legacy-watchlist:{digest}"
            elif watchlist_id in seen:
                # Preserve the established duplicate-ID reader behaviour for
                # malformed saved envelopes.  Only generated legacy keys can
                # be disambiguated here without changing an authored ID.
                continue
            base_watchlist_id = watchlist_id
            duplicate = 2
            while not saved_watchlist_id and watchlist_id in seen:
                watchlist_id = f"{base_watchlist_id}#{duplicate}"
                duplicate += 1
            seen.add(watchlist_id)
            fighter_ids = value.get("fighter_ids", [])
            if not isinstance(fighter_ids, list):
                fighter_ids = []
            rows.append({
                "watchlist_id": watchlist_id,
                "name": str(value.get("name", "Watchlist") or "Watchlist")[:40],
                "fighter_ids": list(dict.fromkeys(str(item) for item in fighter_ids if item))[:2000],
                "fighter_count": len(list(dict.fromkeys(str(item) for item in fighter_ids if item))),
                "alerts_enabled": bool(value.get("alerts_enabled", True)),
                "archived": bool(value.get("archived", False)),
                "created_week": value.get("created_week", 0),
            })
        return rows

    def create_scouting_watchlist(self, name):
        """Create a named, ID-backed watchlist through an explicit player action."""
        self.migrate_scouting_state()
        self.ensure_scouting_decision_packs()
        rows = self._scouting_dict_rows(getattr(self, "scouting_watchlists", []))
        if not rows:
            # A fresh/legacy runtime may not have built the compatibility list
            # yet.  Seed only the existing main-list mirror before adding the
            # explicitly requested named list.
            self.active_scouting_watchlist_ids()
            rows = self._scouting_dict_rows(getattr(self, "scouting_watchlists", []))
        if len(rows) >= 20:
            return False, "The scouting desk can retain at most 20 named watchlists. Archive one before creating another."
        value = str(name or "").strip()[:40]
        if not value:
            return False, "Enter a name for the watchlist."
        sequence = len(rows) + 1
        used = {str(row.get("watchlist_id", "")) for row in rows}
        watchlist_id = f"WATCH-{sequence:04d}"
        while watchlist_id in used:
            sequence += 1
            watchlist_id = f"WATCH-{sequence:04d}"
        row = {
            "watchlist_id": watchlist_id, "name": value, "fighter_ids": [],
            "alerts_enabled": True, "archived": False,
            "created_week": self.calendar_week_index(),
        }
        self.scouting_watchlists.insert(0, row)
        return True, row

    def rename_scouting_watchlist(self, watchlist_id, name):
        """Rename exactly one saved watchlist; candidate/report evidence is untouched."""
        self.migrate_scouting_state()
        key = str(watchlist_id or "").strip()
        row = next((item for item in self.scouting_watchlists if item.get("watchlist_id") == key), None)
        if not row:
            return False, "Watchlist not found."
        value = str(name or "").strip()[:40]
        if not value:
            return False, "Enter a name for the watchlist."
        row["name"] = value
        return True, row

    def set_active_scouting_watchlist(self, watchlist_id):
        """Select one non-archived watchlist by ID for the Target Board."""
        self.migrate_scouting_state()
        key = str(watchlist_id or "").strip()
        row = next((item for item in self.scouting_watchlists if item.get("watchlist_id") == key and not item.get("archived", False)), None)
        if not row:
            return False, "That watchlist is unavailable or archived."
        self.rules["scouting_active_watchlist_id"] = key
        ids = list(dict.fromkeys(str(value) for value in row.get("fighter_ids", []) if value))[-2000:]
        if key == "WATCH-main":
            self.scouting_shortlist = list(ids)
        return True, row

    def archive_scouting_watchlist(self, watchlist_id):
        """Archive a list without deleting its members, reports or decision packs."""
        self.migrate_scouting_state()
        key = str(watchlist_id or "").strip()
        row = next((item for item in self.scouting_watchlists if item.get("watchlist_id") == key), None)
        if not row:
            return False, "Watchlist not found."
        if key == "WATCH-main":
            return False, "Main Watchlist is the compatibility list and cannot be archived."
        row["archived"] = True
        if str(self.rules.get("scouting_active_watchlist_id", "WATCH-main") or "WATCH-main") == key:
            self.rules["scouting_active_watchlist_id"] = "WATCH-main"
        return True, row

    def scouting_watchlist_fighter_ids(self):
        ids = set()
        for watchlist in self._scouting_dict_rows(getattr(self, "scouting_watchlists", [])):
            if watchlist.get("alerts_enabled", True) and not watchlist.get("archived", False):
                ids.update(str(value) for value in watchlist.get("fighter_ids", []) if value)
        if not ids:
            ids.update(self.active_scouting_watchlist_ids())
        return ids

    def scouting_watch_snapshot(self, fighter):
        company = "Free Agent" if fighter in getattr(self, "free_agents", []) else "Independent"
        for promo in getattr(self, "promotions", []):
            if fighter in getattr(promo, "roster", []):
                company = promo.name
                break
        report = self.scouting_intel_report(self.scouting_report_for(fighter))
        return {
            "company": company, "contract_months": int(getattr(fighter, "contract_months", 0) or 0),
            "injured": int(getattr(fighter, "injured", 0) or 0), "weight": str(getattr(fighter, "weight", "")),
            "record": str(getattr(fighter, "record", "")), "offer_company": str(getattr(fighter, "ai_offer_company", "") or ""),
            "report_completed_week": int(report.get("completed_week", 0) or 0) if report.get("status") == "Complete" else 0,
            "report_stale": bool(report.get("status") == "Complete" and not self.scouting_report_blocks_discovery(report)),
        }

    def process_scouting_watchlist_alerts(self):
        """Emit one Inbox item for material changes to watched fighters."""
        fighters = {self.scouting_report_key(fighter): fighter for fighter in self.all_scoutable_fighters()}
        state = dict(getattr(self, "scouting_alert_state", {}) or {})
        for fighter_id in self.scouting_watchlist_fighter_ids():
            fighter = fighters.get(str(fighter_id))
            if not fighter:
                continue
            current = self.scouting_watch_snapshot(fighter)
            previous = state.get(str(fighter_id))
            state[str(fighter_id)] = current
            if not isinstance(previous, dict):
                continue
            messages = []
            if current["company"] != previous.get("company"):
                messages.append(f"employer changed from {previous.get('company', 'Unknown')} to {current['company']}")
            if current["weight"] != previous.get("weight"):
                messages.append(f"moved from {previous.get('weight', 'Unknown')} to {current['weight']}")
            if current["record"] != previous.get("record"):
                messages.append(f"record changed from {previous.get('record', '-')} to {current['record']}")
            if current["injured"] and not int(previous.get("injured", 0) or 0):
                messages.append(f"suffered an injury ({current['injured']} week(s))")
            if current["offer_company"] and current["offer_company"] != previous.get("offer_company"):
                messages.append(f"received an offer from {current['offer_company']}")
            if current["report_stale"] and not previous.get("report_stale"):
                messages.append("their scouting dossier became stale")
            prior_months = int(previous.get("contract_months", 0) or 0)
            if current["contract_months"] in (6, 3, 1) and current["contract_months"] != prior_months:
                messages.append(f"contract has {current['contract_months']} month(s) remaining")
            if not messages:
                continue
            detail = "; ".join(messages) + "."
            self.inbox.append({
                "subject": f"Watchlist Update - {fighter.name}", "body": detail,
                "type": "Scouting", "resolved": False, "fighter_id": fighter_id,
            })
            self.append_scouting_history("Watchlist Alert", fighter, detail)
        self.scouting_alert_state = state

    @staticmethod
    def _scouting_dict_rows(value):
        return [dict(row) for row in value if isinstance(row, dict)] if isinstance(value, list) else []

    def scout_identity_key(self, scout):
        """Return a durable scout key while accepting legacy name callers."""
        if isinstance(scout, dict):
            return str(scout.get("staff_id", "") or scout.get("name", ""))
        reference = str(scout or "")
        if not reference:
            return ""
        if reference.startswith("STF-") or reference == "Independent Contractor":
            return reference
        matches = [
            member for member in getattr(self, "staff", [])
            if isinstance(member, dict) and member.get("role") == "Scout" and member.get("name") == reference
        ]
        return str(matches[0].get("staff_id", reference)) if len(matches) == 1 else reference

    def scout_for_assignment(self, assignment, default=None):
        """Resolve persisted scout identity first and a unique legacy name second."""
        assignment = assignment if isinstance(assignment, dict) else {}
        scout_id = str(assignment.get("scout_id", "") or "")
        if scout_id:
            match = next((member for member in getattr(self, "staff", []) or []
                          if isinstance(member, dict) and member.get("staff_id") == scout_id), None)
            if match:
                return match
        name = str(assignment.get("scout", "") or "")
        matches = [member for member in getattr(self, "staff", []) or []
                   if isinstance(member, dict) and member.get("role") == "Scout" and member.get("name") == name]
        return matches[0] if len(matches) == 1 else (default if default is not None else {})

    def scouting_assignment_matches_scout(self, assignment, scout):
        assignment = assignment if isinstance(assignment, dict) else {}
        key = self.scout_identity_key(scout)
        member = scout if isinstance(scout, dict) else next(
            (item for item in getattr(self, "staff", []) or []
             if isinstance(item, dict) and item.get("staff_id") == key), None
        )
        display_name = str(member.get("name", "") if member else scout or "")
        assignment_id = str(assignment.get("scout_id", "") or "")
        if assignment_id:
            return assignment_id == key
        return bool(display_name) and str(assignment.get("scout", "") or "") == display_name

    def _deterministic_scouting_rng(self, fighter, report):
        payload = "|".join((
            self.scouting_report_key(fighter), str(report.get("kind", "basic")),
            str(report.get("started_week", 0)), str(report.get("confidence", report.get("reveal", 0))),
            str(report.get("scout_id", report.get("scout", ""))),
        ))
        return random.Random(int(hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16], 16))

    def prune_scouting_state(self):
        """Bound historical scouting data without discarding live assignments."""
        history = list(getattr(self, "scouting", []) or [])
        self.scouting = history[-500:]
        searches = self._scouting_dict_rows(getattr(self, "scouting_searches", []))
        active = [row for row in searches if row.get("status") in ("In progress", "Monitoring")]
        historical = [row for row in searches if row.get("status") not in ("In progress", "Monitoring")][-500:]
        self.scouting_searches = active + historical
        shortlist = [str(value) for value in list(getattr(self, "scouting_shortlist", []) or []) if value]
        self.scouting_shortlist = list(dict.fromkeys(shortlist))[-2000:]
        self.scouting_history = self._scouting_dict_rows(getattr(self, "scouting_history", []))[-1000:]
        self.scouting_watchlists = self._scouting_dict_rows(getattr(self, "scouting_watchlists", []))[:20]
        for watchlist in self.scouting_watchlists:
            watchlist["fighter_ids"] = list(dict.fromkeys(
                str(value) for value in watchlist.get("fighter_ids", []) if value
            ))[-2000:]
        self.ensure_scouting_decision_packs()
        alert_state = getattr(self, "scouting_alert_state", {})
        self.scouting_alert_state = dict(list(alert_state.items())[-4000:]) if isinstance(alert_state, dict) else {}
        quarantined = self._scouting_dict_rows(getattr(self, "scouting_quarantined_reports", []))
        self.scouting_quarantined_reports = quarantined[-250:]
        reports = getattr(self, "scouting_reports", {})
        if isinstance(reports, dict) and len(reports) > 6000:
            live_ids = {self.scouting_report_key(fighter) for fighter in self.all_scoutable_fighters()}
            protected = {
                key: report for key, report in reports.items()
                if key in live_ids or (isinstance(report, dict) and report.get("status") == "In progress")
            }
            historical = [
                (key, report) for key, report in reports.items()
                if key not in protected and isinstance(report, dict)
            ]
            historical.sort(key=lambda row: int(row[1].get("completed_week", row[1].get("started_week", -1)) or -1))
            self.scouting_reports = {**dict(historical[-500:]), **protected}

    def migrate_scouting_state(self):
        """Upgrade name-keyed reports without guessing between duplicate names."""
        if getattr(self, "_scouting_state_migrated", False):
            return
        raw_reports = getattr(self, "scouting_reports", {})
        self.scouting_reports = dict(raw_reports) if isinstance(raw_reports, dict) else {}
        self.scouting_searches = self._scouting_dict_rows(getattr(self, "scouting_searches", []))
        self.scouting_history = self._scouting_dict_rows(getattr(self, "scouting_history", []))
        self.scouting_watchlists = self._scouting_dict_rows(getattr(self, "scouting_watchlists", []))
        self.scouting_knowledge = dict(getattr(self, "scouting_knowledge", {}) or {}) if isinstance(getattr(self, "scouting_knowledge", {}), dict) else {}
        self.scouting_alert_state = dict(getattr(self, "scouting_alert_state", {}) or {}) if isinstance(getattr(self, "scouting_alert_state", {}), dict) else {}
        self.scouting_quarantined_reports = self._scouting_dict_rows(getattr(self, "scouting_quarantined_reports", []))
        by_name = {}
        fighters = self.all_scoutable_fighters()
        by_id = {self.scouting_report_key(fighter): fighter for fighter in fighters}
        for fighter in fighters:
            by_name.setdefault(fighter.name, []).append(fighter)
        migrated_shortlist = []
        for old_key in list(getattr(self, "scouting_shortlist", []) or []):
            old_key = str(old_key)
            if old_key in by_id:
                migrated_shortlist.append(old_key)
            elif len(by_name.get(old_key, [])) == 1:
                migrated_shortlist.append(self.scouting_report_key(by_name[old_key][0]))
        self.scouting_shortlist = list(dict.fromkeys(migrated_shortlist))
        live_ids = set(by_id)
        if not self.scouting_watchlists:
            self.scouting_watchlists = [{
                "watchlist_id": "WATCH-main", "name": "Main Watchlist",
                "fighter_ids": list(self.scouting_shortlist), "alerts_enabled": True,
                "created_week": self.calendar_week_index(),
            }]
        seen_watchlists = set()
        normalized_watchlists = []
        for index, raw_watchlist in enumerate(self.scouting_watchlists[:20]):
            watchlist = dict(raw_watchlist)
            watchlist_id = str(watchlist.get("watchlist_id", "") or ("WATCH-main" if index == 0 else f"WATCH-{index + 1}"))
            if watchlist_id in seen_watchlists:
                continue
            seen_watchlists.add(watchlist_id)
            fighter_ids = []
            for value in watchlist.get("fighter_ids", []):
                value = str(value)
                if value in live_ids:
                    fighter_ids.append(value)
                elif len(by_name.get(value, [])) == 1:
                    fighter_ids.append(self.scouting_report_key(by_name[value][0]))
            watchlist.update({
                "watchlist_id": watchlist_id,
                "name": str(watchlist.get("name", "Watchlist") or "Watchlist")[:40],
                "fighter_ids": list(dict.fromkeys(fighter_ids))[-2000:],
                "alerts_enabled": bool(watchlist.get("alerts_enabled", True)),
            })
            normalized_watchlists.append(watchlist)
        self.scouting_watchlists = normalized_watchlists or [{
            "watchlist_id": "WATCH-main", "name": "Main Watchlist", "fighter_ids": [],
            "alerts_enabled": True, "created_week": self.calendar_week_index(),
        }]
        self.ensure_scouting_decision_packs()
        self.active_scouting_watchlist_ids()
        for search in self.scouting_searches:
            scout = self.scout_for_assignment(search)
            if scout:
                search.setdefault("scout_id", self.scout_identity_key(scout))
            result_id = str(search.get("result_fighter_id", "") or "")
            if result_id and result_id not in by_id and len(by_name.get(result_id, [])) == 1:
                search["result_fighter_id"] = self.scouting_report_key(by_name[result_id][0])
        migrated = {}
        for old_key, raw in self.scouting_reports.items():
            if not isinstance(raw, dict):
                continue
            report = dict(raw)
            fighter = None
            embedded_id = str(report.get("fighter_id", "") or "")
            if embedded_id in by_id:
                fighter = by_id[embedded_id]
            elif str(old_key) in by_id:
                fighter = by_id[str(old_key)]
            elif len(by_name.get(str(old_key), [])) == 1:
                fighter = by_name[str(old_key)][0]
            elif len(by_name.get(str(old_key), [])) > 1:
                report.setdefault("fighter_name", str(old_key))
                report["status"] = "Quarantined"
                report["quarantine_reason"] = "Legacy fighter name matches multiple identities."
                self.scouting_quarantined_reports.append(report)
                continue
            report.setdefault("fighter_name", getattr(fighter, "name", str(old_key)))
            report.setdefault("fighter_id", self.scouting_report_key(fighter) if fighter else str(old_key))
            report.setdefault("started_week", self.calendar_week_index())
            report.setdefault("confidence", int(report.get("reveal", 0) or 0))
            report.setdefault("schema_version", 2)
            report["history"] = self.scouting_report_history(report)
            scout = self.scout_for_assignment(report)
            if scout:
                report.setdefault("scout_id", self.scout_identity_key(scout))
            if fighter and report.get("status") == "Complete" and not report.get("estimates"):
                scout = scout or {"skill": 42, "fighter_judging": 42, "potential_judging": 38, "reliability": 40}
                report["estimates"] = self.build_scouting_estimates(
                    fighter, scout, report.get("kind", "basic"), report.get("confidence", 50),
                    rng=self._deterministic_scouting_rng(fighter, report),
                )
            if report.get("status") == "Complete" and "completed_week" not in report:
                # Unknown-age legacy intel must not be refreshed by loading it.
                report["completed_week"] = self.calendar_week_index() - 53
                report["legacy_completion_unknown"] = True
            migrated[report["fighter_id"]] = report
        self.scouting_reports = migrated
        self._scouting_state_migrated = True
        self.prune_scouting_state()

    def scout_capacity(self, scout):
        if not isinstance(scout, dict):
            return 0
        raw_efficiency = scout.get("efficiency", scout.get("skill", 45))
        try:
            efficiency = int(raw_efficiency or 45) if not isinstance(raw_efficiency, bool) else 45
        except (TypeError, ValueError):
            efficiency = 45
        return 1 + int(efficiency >= 68) + int(efficiency >= 88)

    def academy_network_uses_scout(self, scout):
        academy = getattr(self, "academy", {}) or {}
        if not isinstance(academy, dict):
            return False
        scout_key = self.scout_identity_key(scout)
        if academy.get("network_scout_id"):
            return academy.get("network_scout_id") == scout_key
        display_name = scout.get("name") if isinstance(scout, dict) else str(scout or "")
        return bool(display_name) and academy.get("network_scout") == display_name

    def scout_workload(self, scout, include_active_academy=True):
        scout_key = self.scout_identity_key(scout)
        reports = sum(
            isinstance(report, dict) and report.get("status") == "In progress" and self.scouting_assignment_matches_scout(report, scout_key)
            for report in (getattr(self, "scouting_reports", {}) or {}).values()
        )
        searches = sum(
            isinstance(search, dict) and search.get("status") in ("In progress", "Monitoring") and self.scouting_assignment_matches_scout(search, scout_key)
            for search in (getattr(self, "scouting_searches", []) or [])
        )
        academy = getattr(self, "academy", {}) or {}
        if not isinstance(academy, dict):
            return reports + searches
        owns_network = self.academy_network_uses_scout(scout)
        try:
            network_weeks = int(academy.get("network_weeks", 0) or 0)
        except (TypeError, ValueError):
            network_weeks = 0
        academy_slot = int(owns_network and (network_weeks > 0 or (include_active_academy and academy.get("network_active"))))
        return reports + searches + academy_slot

    def scouting_effective_confidence(self, report):
        try:
            confidence = int(report.get("confidence", report.get("reveal", 0)) or 0)
        except (TypeError, ValueError):
            confidence = 0
        if report.get("status") != "Complete":
            return confidence
        completed_value = report.get("completed_week")
        try:
            completed = self.calendar_week_index() if completed_value is None else int(completed_value)
        except (TypeError, ValueError):
            return confidence
        age_weeks = max(0, self.calendar_week_index() - completed)
        return max(20, confidence - max(0, age_weeks - 26) // 13 * 4)

    @staticmethod
    def scouting_prior_report(report):
        prior = report.get("prior_report") if isinstance(report, dict) else None
        return prior if isinstance(prior, dict) else {}

    def scouting_intel_report(self, report):
        """Keep completed intel visible while a replacement assignment runs."""
        if not isinstance(report, dict):
            return {}
        if report.get("status") == "Complete":
            return report
        prior = self.scouting_prior_report(report)
        return prior if prior.get("status") == "Complete" else report

    def scouting_report_is_current_full(self, report):
        report = self.scouting_intel_report(report)
        if report.get("status") != "Complete" or report.get("kind") != "full" or not report.get("comprehensive", report.get("reveal", 0) >= 100):
            return False
        completed_value = report.get("completed_week")
        try:
            completed = self.calendar_week_index() if completed_value is None else int(completed_value)
        except (TypeError, ValueError):
            return False
        return self.calendar_week_index() - completed <= 26

    def scouting_report_blocks_discovery(self, report):
        """Only active or current completed intel removes a fighter from searches."""
        if not isinstance(report, dict):
            return False
        if report.get("status") == "In progress":
            return True
        if report.get("status") != "Complete":
            return False
        completed_value = report.get("completed_week")
        if completed_value is None:
            return False
        try:
            completed = int(completed_value)
        except (TypeError, ValueError):
            return False
        return self.calendar_week_index() - completed <= 52

    def scouting_estimate(self, fighter, field, default=None, report=None):
        report = self.scouting_intel_report(self.scouting_report_for(fighter) if report is None else report)
        if report.get("status") != "Complete":
            return default
        estimates = report.get("estimates", {}) or {}
        if field in estimates:
            estimate = dict(estimates[field])
            completed_value = report.get("completed_week")
            try:
                completed = self.calendar_week_index() if completed_value is None else int(completed_value)
            except (TypeError, ValueError):
                return default
            report_age = self.calendar_week_index() - completed
            if report_age > 26:
                stale_periods = max(1, (report_age - 14) // 13)
                spread = min(14, 1 + stale_periods * 2)
                centre = int(estimate.get("mid", (estimate.get("low", 50) + estimate.get("high", 50)) / 2))
                estimate.update({
                    "low": min(int(estimate.get("low", centre)), max(1, centre - spread)),
                    "high": max(int(estimate.get("high", centre)), min(99, centre + spread)),
                })
            return estimate
        return default

    def build_scouting_estimates(self, fighter, scout, kind, confidence, rng=None, look_count=1):
        """Create a report snapshot once; UI refreshes must never reroll it."""
        rng = rng or random
        reliability = int(scout.get("reliability", scout.get("skill", 45)) or 45)
        judging = int(scout.get("fighter_judging", scout.get("skill", 45)) or 45)
        potential_judging = int(scout.get("potential_judging", scout.get("skill", 45)) or 45)
        current_spread = max(2, round((108 - (confidence + judging) / 2) / 7))
        potential_spread = max(3, round((118 - (confidence + potential_judging) / 2) / 6))
        specialty = str(scout.get("specialty", ""))
        if specialty == "Prospect eye" and fighter.age <= 27:
            potential_spread = max(2, potential_spread - 2)
        if specialty == "Women’s divisions" and fighter.gender == "Female":
            current_spread = max(1, current_spread - 2)
        if specialty == "International network" and fighter.region != self.player_region:
            current_spread = max(1, current_spread - 1)
        current_error = max(1, round((118 - reliability - judging * 0.35) / 18))
        potential_error = max(1, round((124 - reliability - potential_judging * 0.35) / 17))
        current_bias = rng.randint(-current_error, current_error)
        potential_bias = rng.randint(-potential_error, potential_error)

        def estimate(value, spread=current_spread, bias=current_bias):
            centre = max(1, min(99, int(value) + bias))
            return {"low": max(1, centre - spread), "high": min(99, centre + spread), "mid": centre}

        # A single desk report never collapses the fog entirely. Exact current
        # ratings require a high-confidence full evaluation backed by at least
        # one previous completed look.
        exact_current = kind == "full" and int(look_count or 1) >= 2 and int(confidence or 0) >= 85
        fields = {
            "overall": estimate(fighter.overall),
            "popularity": estimate(fighter.popularity, max(2, current_spread + 1)),
            "star_quality": estimate(fighter.star_quality, max(3, current_spread + 2)),
            "media_presence": estimate(fighter.media_presence, max(3, current_spread + 2)),
            "professionalism": estimate(fighter.professionalism, max(3, current_spread + 1)),
            "potential": estimate(fighter.potential, potential_spread, potential_bias),
        }
        if kind == "full":
            # Technical evidence is a dated snapshot, not permission to read
            # live skills. Reuse this report's bias without extra random draws.
            for key in ("striking", "wrestling", "grappling", "cardio", "chin", "takedown_defence",
                        "ground_control", "submissions", "submission_defence", "fight_iq"):
                fields[key] = estimate(getattr(fighter, key))
        if exact_current:
            for key in ("overall", "popularity", "star_quality", "media_presence", "professionalism"):
                value = int(getattr(fighter, key))
                fields[key] = {"low": value, "high": value, "mid": value}
        return fields

    def process_scouting_reports(self):
        self.migrate_scouting_state()
        fighters = {self.scouting_report_key(fighter): fighter for fighter in self.all_scoutable_fighters()}
        for fighter_id, report in list(self.scouting_reports.items()):
            if report.get("status") != "In progress":
                continue
            if report.get("kind") == "observation":
                current_week = self.calendar_week_index()
                weeks_remaining = max(0, int(report.get("weeks_remaining", 26)))
                expiry_due_week = report.get("expiry_due_week")
                if weeks_remaining > 0:
                    report["weeks_remaining"] = weeks_remaining - 1
                    if report["weeks_remaining"] == 0:
                        # AI/player fights run later in this same weekly pipeline.
                        # Leave the assignment active through its final week.
                        report["expiry_due_week"] = current_week
                    continue
                if expiry_due_week is None:
                    report["expiry_due_week"] = current_week
                    continue
                if int(expiry_due_week) < current_week:
                    name = report.get("fighter_name", fighter_id)
                    prior = self.scouting_prior_report(report)
                    if prior:
                        self.scouting_reports[fighter_id] = prior
                    else:
                        report["status"] = "Expired"
                    self.inbox.append({"subject": f"Observation Expired - {name}", "body": f"{name} did not compete during the observation window. The scout assignment has been released.", "type": "Scouting", "resolved": False, "fighter_id": fighter_id})
                continue
            report["weeks_remaining"] = max(0, int(report.get("weeks_remaining", 0)) - 1)
            if report["weeks_remaining"] == 0:
                report["status"] = "Complete"
                report["completed_week"] = self.calendar_week_index()
                fighter = fighters.get(fighter_id)
                scout = self.scout_for_assignment(report, {"skill": 42, "fighter_judging": 42, "potential_judging": 38, "reliability": 40})
                if fighter:
                    look_count = max(1, int(report.get("look_number", len(self.scouting_report_history(report)) + 1) or 1))
                    report["estimates"] = self.build_scouting_estimates(
                        fighter, scout, report.get("kind", "basic"), report.get("confidence", 50),
                        look_count=look_count,
                    )
                    report["notes"] = self.scouting_report_notes(fighter, int(report.get("confidence", 50) or 50))
                    report["comprehensive"] = bool(
                        report.get("kind") == "full" and look_count >= 2
                        and int(report.get("confidence", 0) or 0) >= 85
                    )
                    report["reveal"] = 100 if report["comprehensive"] else int(report.get("confidence", 50) or 50)
                    self.update_scouting_region_knowledge(
                        fighter.region, 10 if report.get("kind") == "full" else 5,
                        f"{report.get('kind', 'basic')} fighter report",
                    )
                else:
                    report["reveal"] = int(report.get("confidence", 50) or 50)
                detail = "; ".join(report.get("notes", [])) or "Initial read complete; a full evaluation can narrow the uncertainty."
                name = report.get("fighter_name", fighter_id)
                recommendation, reason = ("REPORT COMPLETE", "Open Scouting to review the recruitment case.")
                if fighter and hasattr(self, "scout_signing_recommendation"):
                    recommendation, reason = self.scout_signing_recommendation(fighter, report)
                report["recommendation"] = recommendation
                report["recommendation_reason"] = reason
                if scout in getattr(self, "staff", []) and (
                    report.get("comprehensive")
                    or (recommendation == "RECOMMEND SIGNING" and int(report.get("confidence", 0) or 0) >= 70)
                ):
                    contribution_kind = "comprehensive_dossier" if report.get("comprehensive") else "talent_identified"
                    contribution_summary = (
                        f"{scout.get('name', 'The scout')} completed a comprehensive dossier on {name}."
                        if report.get("comprehensive") else
                        f"{scout.get('name', 'The scout')} identified {name} as a recommended signing at {report.get('confidence', 0)}% confidence."
                    )
                    self.record_staff_contribution(
                        "Scout", contribution_kind, contribution_summary, member=scout,
                        event_ref=f"staff-scout-report:{scout.get('staff_id', '')}:{fighter_id}:{report.get('completed_week', 0)}:{contribution_kind}",
                        importance=4 if report.get("comprehensive") else 3,
                    )
                self.append_scouting_history("Report Complete", fighter, f"{report.get('kind', 'basic').title()} report completed at {report.get('confidence', 0)}% confidence.", report)
                meaning = SCOUTING_VERDICT_DESCRIPTORS.get(recommendation, "")
                meaning = f"\n\nWhat {recommendation} means: {meaning}" if meaning else ""
                self.inbox.append({"subject": f"Scouting Report Complete - {name}", "body": f"{report.get('kind', 'basic').title()} evaluation by {report.get('scout', 'staff')} is complete ({report.get('confidence', 0)}% confidence). {detail}\n\n{recommendation}: {reason}{meaning}", "type": "Scouting", "resolved": False, "fighter_id": fighter_id})
        self.process_talent_searches()
        self.process_scouting_watchlist_alerts()
        self.auto_assign_idle_scouts()
        self.prune_scouting_state()

    def auto_assign_idle_scouts(self):
        """Keep spare scout capacity working without overriding player briefs."""
        if not getattr(self, "rules", {}).get("auto_assign_idle_scouts", True):
            return
        current_week = self.calendar_week_index()
        if int(getattr(self, "rules", {}).get("scouting_auto_last_week", -1) or -1) == current_week:
            return
        scouts = [member for member in (getattr(self, "staff", []) or [])
                  if isinstance(member, dict) and member.get("role") == "Scout"]
        # A scout with two slots holding one player brief used to sit at half
        # capacity forever, because only a completely idle scout qualified.
        # Every free slot is filled now, which is where most of the lost
        # scouting throughput was going.
        idle_scouts = []
        for member in scouts:
            free_slots = self.scout_capacity(member) - self.scout_workload(member)
            idle_scouts.extend([member] * max(0, free_slots))
        if not idle_scouts or not hasattr(self, "start_scout_report_for_fighter"):
            return
        player_ids = {self.scouting_report_key(fighter) for fighter in getattr(self, "roster", [])}
        shortlist = set(self.active_scouting_watchlist_ids())
        employers = {}
        candidates = []
        for fighter in getattr(self, "free_agents", []):
            employers[self.scouting_report_key(fighter)] = "Free Agent"
            candidates.append(fighter)
        for promo in getattr(self, "promotions", []):
            for fighter in promo.roster:
                employers[self.scouting_report_key(fighter)] = promo.name
                candidates.append(fighter)
        eligible = []
        seen = set()
        for fighter in candidates:
            key = self.scouting_report_key(fighter)
            if key in seen or key in player_ids or getattr(fighter, "retired", False):
                continue
            seen.add(key)
            report = self.scouting_report_for(fighter)
            if self.scouting_report_blocks_discovery(report):
                continue
            division_depth = sum(member.gender == fighter.gender and member.weight == fighter.weight for member in getattr(self, "roster", []))
            public_form = fighter.record_w * 1.6 - fighter.record_l * 0.8 + fighter.record_d * 0.2
            youth_interest = max(0, 30 - fighter.age) * 0.8
            market_interest = min(15, fighter.popularity * 0.18)
            need = max(0, 10 - division_depth) * 2.5
            availability = 10 if employers.get(key) == "Free Agent" else 0
            watch = 30 if key in shortlist else 0
            regional = 6 if fighter.region == self.player_region else 0
            eligible.append((watch + need + availability + regional + youth_interest + market_interest + public_form + random.uniform(-8, 8), fighter))
        if not eligible:
            return
        eligible.sort(key=lambda row: row[0], reverse=True)
        used = set()
        # Department delegation commissions at most one discounted dossier per
        # week. Extra capacity remains available for explicit player briefs.
        for scout in sorted(idle_scouts, key=lambda row: int(row.get("efficiency", row.get("skill", 45)) or 45), reverse=True)[:1]:
            specialty = scout.get("specialty", "")
            ranked = []
            for base_score, fighter in eligible:
                key = self.scouting_report_key(fighter)
                if key in used:
                    continue
                fit = 0
                if specialty == "Prospect eye" and fighter.age <= 27:
                    fit += 10
                elif specialty == "Women’s divisions" and fighter.gender == "Female":
                    fit += 10
                elif specialty == "International network" and fighter.region != self.player_region:
                    fit += 8
                ranked.append((base_score + fit, fighter))
            if not ranked:
                break
            target = max(ranked, key=lambda row: row[0])[1]
            if self.start_scout_report_for_fighter(target, "basic", scout_name=self.scout_identity_key(scout), automatic=True):
                used.add(self.scouting_report_key(target))
                self.rules["scouting_auto_last_week"] = current_week

    def complete_fight_observation(self, fighter, opponent=None, outcome="Observed", method="", fight=None):
        report = self.scouting_report_for(fighter)
        if not report or report.get("status") != "In progress" or report.get("kind") != "observation":
            return
        scout = self.scout_for_assignment(report, {})
        stats = dict(getattr(fighter, "last_fight_stats", {}) or {})
        rounds = max(1, int(stats.get("rounds", 1) or 1))
        sig_accuracy = round(int(stats.get("sig", 0) or 0) / max(1, int(stats.get("sig_att", 0) or 0)) * 100)
        td_accuracy = round(int(stats.get("td", 0) or 0) / max(1, int(stats.get("td_att", 0) or 0)) * 100) if stats.get("td_att") else 0
        evidence_quality = min(12, rounds * 2 + int(bool(stats.get("knockdowns"))) * 2 + int(bool(stats.get("td") or stats.get("sub_att"))) * 2)
        confidence = min(92, max(
            int(report.get("prior_confidence", 0)),
            max(48, int(report.get("confidence", 45)) + 10 + int(scout.get("fighter_judging", 45)) // 10 + evidence_quality),
        ))
        evidence = {
            "week": self.calendar_week_index(), "opponent_id": self.scouting_report_key(opponent) if opponent else "",
            "opponent_name": getattr(opponent, "name", "") if opponent else "", "outcome": str(outcome),
            "method": str(method or ""), "rounds": rounds, "sig": int(stats.get("sig", 0) or 0),
            "sig_att": int(stats.get("sig_att", 0) or 0), "sig_accuracy": sig_accuracy,
            "td": int(stats.get("td", 0) or 0), "td_att": int(stats.get("td_att", 0) or 0),
            "td_accuracy": td_accuracy, "sub_att": int(stats.get("sub_att", 0) or 0),
            "control_secs": int(stats.get("control_secs", 0) or 0), "knockdowns": int(stats.get("knockdowns", 0) or 0),
            "damage_taken": int(stats.get("damage_taken", 0) or 0),
            "weight": str(getattr(fighter, "weight", "")), "title_fight": bool((fight or {}).get("title", False)),
        }
        look_count = max(1, int(report.get("look_number", len(self.scouting_report_history(report)) + 1) or 1))
        report.update({"status": "Complete", "weeks_remaining": 0, "confidence": confidence, "reveal": confidence, "observed_fight": True, "completed_week": self.calendar_week_index(), "evidence": evidence, "comprehensive": False, "look_number": look_count})
        report["estimates"] = self.build_scouting_estimates(fighter, scout, "observation", confidence, look_count=look_count)
        report["notes"] = list(dict.fromkeys(list(report.get("prior_notes", [])) + self.scouting_report_notes(fighter, confidence, evidence=True)))
        self.update_scouting_region_knowledge(fighter.region, 8, "live fight observation")
        if hasattr(self, "scout_signing_recommendation"):
            report["recommendation"], report["recommendation_reason"] = self.scout_signing_recommendation(fighter, report)
        name = fighter.name
        advice = f"\n\n{report.get('recommendation')}: {report.get('recommendation_reason')}" if report.get("recommendation") else ""
        self.append_scouting_history("Fight Observed", fighter, f"{outcome} vs {getattr(opponent, 'name', 'opponent')} by {method or 'official result'}; {rounds} round(s), {sig_accuracy}% significant-strike accuracy.", report)
        self.inbox.append({"subject": f"Fight Observation Complete - {name}", "body": f"{report.get('scout', 'Your scout')} observed {name}'s latest fight. The live evidence produced a {confidence}% confidence report; a full evaluation is still required for exact current ratings.{advice}", "type": "Scouting", "resolved": False, "fighter_id": self.scouting_report_key(fighter)})

    def normalize_scouting_focus(self, focus):
        return focus if focus in SCOUTING_SEARCH_FOCUSES else "Free Agent Pool"

    def normalize_scouting_priority(self, priority):
        return priority if priority in SCOUTING_SEARCH_PRIORITIES else "Balanced"

    def normalize_scouting_brief_level(self, level):
        return level if level in SCOUTING_BRIEF_LEVELS else "Standard"

    @staticmethod
    def scouting_age_band_matches(fighter, age_band):
        return {
            "Under 23": fighter.age < 23, "Under 26": fighter.age < 26,
            "Under 30": fighter.age < 30, "30+": fighter.age >= 30,
        }.get(age_band, True)

    def scouting_search_candidate_rows(self, focus):
        focus = self.normalize_scouting_focus(focus)
        player_ids = {self.scouting_report_key(fighter) for fighter in getattr(self, "roster", [])}
        rows, seen = [], set()

        def add(source, roster):
            for fighter in roster:
                key = self.scouting_report_key(fighter)
                if key in seen or key in player_ids or getattr(fighter, "retired", False):
                    continue
                if getattr(fighter, "sport_employer", "") and getattr(fighter, "primary_discipline", "MMA") != "MMA":
                    continue
                seen.add(key)
                rows.append((fighter, source))

        if focus in ("Free Agent Pool", "Any Market", "Regional Prospects", "Young Prospects"):
            add("Free Agent", getattr(self, "free_agents", []))
        if focus in ("Rival Rosters", "Any Market", "Young Prospects"):
            for promo in getattr(self, "promotions", []):
                if focus == "Rival Rosters" and getattr(promo, "is_regional_feeder", False):
                    continue
                add(promo.name, promo.roster)
        if focus == "Regional Prospects":
            for promo in getattr(self, "promotions", []):
                if getattr(promo, "is_regional_feeder", False):
                    add(promo.name, promo.roster)
            rows = [(fighter, source) for fighter, source in rows if fighter.age <= 27 or fighter.potential >= fighter.overall + 10]
        elif focus == "Young Prospects":
            rows = [(fighter, source) for fighter, source in rows if fighter.age <= 25 or fighter.potential >= fighter.overall + 14]
        return rows

    def scouting_search_score(self, fighter, scout, focus, source, priority="Balanced"):
        focus = self.normalize_scouting_focus(focus)
        priority = self.normalize_scouting_priority(priority)
        skill = int(scout.get("skill", 45) or 45)
        fighter_judging = int(scout.get("fighter_judging", skill) or skill)
        potential_judging = int(scout.get("potential_judging", skill) or skill)
        networking = int(scout.get("networking", skill) or skill)
        regional = int(scout.get("regional_knowledge", skill) or skill)
        reliability = int(scout.get("reliability", skill) or skill)
        noise = random.uniform(-18, 18) * max(0.35, (112 - reliability) / 70)
        scout_lift = (networking - 50) * 0.12 + (regional - 50) * 0.08
        overall_read = fighter.overall * (0.25 + fighter_judging / 260)
        upside_read = fighter.potential * (0.20 + potential_judging / 240)
        youth = max(0, 29 - fighter.age) * 1.1
        market = fighter.popularity * 0.12 + fighter.star_quality * 0.10
        affordability = max(-6, min(8, (60_000 / max(1, fighter.purse)) - 3))
        source_bonus = 5 if source == "Free Agent" else 0
        if focus == "Free Agent Pool":
            source_bonus += 12 if source == "Free Agent" else -8
            affordability *= 1.25
        elif focus == "Rival Rosters":
            source_bonus += 10 if source != "Free Agent" else -10
            market += getattr(fighter, "record_w", 0) * 0.6
        elif focus == "Regional Prospects":
            upside_read *= 1.18
            youth *= 1.3
            market *= 0.7
        elif focus == "Young Prospects":
            upside_read *= 1.25
            youth *= 1.45
        if scout.get("specialty") == "Prospect eye" and (fighter.age <= 27 or fighter.potential >= fighter.overall + 10):
            scout_lift += 8
        if scout.get("specialty") == "Women’s divisions" and fighter.gender == "Female":
            scout_lift += 8
        if scout.get("specialty") == "International network" and fighter.region != self.player_region:
            scout_lift += 7
        if priority == "Immediate Ability":
            overall_read *= 1.55
            upside_read *= 0.45
            youth *= 0.35
        elif priority == "High Potential":
            upside_read *= 1.45
            youth *= 1.35
        elif priority == "Value":
            affordability *= 1.7
            market *= 0.75
        elif priority == "Marketability":
            market *= 1.75
        elif priority == "Roster Need":
            depth = sum(member.gender == fighter.gender and member.weight == fighter.weight for member in getattr(self, "roster", []))
            scout_lift += max(0, 10 - depth) * 3
        return overall_read + upside_read + youth + market + affordability + source_bonus + scout_lift + noise

    def talent_search_cost(self, region, scout=None, focus="Free Agent Pool", priority="Balanced", level="Standard"):
        distance = 0 if region == self.player_region else 1
        raw_efficiency = (scout or {}).get("efficiency", 45) if isinstance(scout, dict) else 45
        try:
            efficiency = int(raw_efficiency or 45) if not isinstance(raw_efficiency, bool) else 45
        except (TypeError, ValueError):
            efficiency = 45
        focus = self.normalize_scouting_focus(focus)
        multiplier = {"Free Agent Pool": 1.0, "Rival Rosters": 1.22, "Regional Prospects": 0.95, "Young Prospects": 1.05, "Any Market": 1.08}.get(focus, 1.0)
        priority_multiplier = {"Immediate Ability": 1.12, "High Potential": 1.10, "Marketability": 1.08}.get(self.normalize_scouting_priority(priority), 1.0)
        level_multiplier = 1.35 if self.normalize_scouting_brief_level(level) == "Priority" else 1.0
        return max(3500, round((6500 + distance * 4500) * multiplier * priority_multiplier * level_multiplier * (1.12 - efficiency / 500)))

    def talent_search_duration(self, scout, region, level="Standard"):
        if not isinstance(scout, dict):
            return 5 if self.normalize_scouting_brief_level(level) != "Priority" else 4
        raw_efficiency = scout.get("efficiency", scout.get("skill", 45))
        try:
            efficiency = int(raw_efficiency or 45) if not isinstance(raw_efficiency, bool) else 45
        except (TypeError, ValueError):
            efficiency = 45
        weeks = max(2, 5 - int(efficiency >= 65) - int(efficiency >= 88))
        if scout.get("specialty") == "International network" and region != self.player_region:
            weeks = max(2, weeks - 1)
        return max(1, weeks - 1) if self.normalize_scouting_brief_level(level) == "Priority" else weeks

    def start_talent_search(self, scout_name, region, gender="All", weight="All", focus="Free Agent Pool", priority="Balanced", age_band="Any Age", style="All", level="Standard"):
        scout_key = self.scout_identity_key(scout_name)
        scout = next((member for member in (getattr(self, "staff", []) or [])
                      if isinstance(member, dict) and member.get("role") == "Scout" and self.scout_identity_key(member) == scout_key), None)
        if not scout:
            return False, "Select a hired scout."
        if self.scout_workload(scout) >= self.scout_capacity(scout):
            return False, f"{scout.get('name', scout_name)} has no free assignment slots."
        focus = self.normalize_scouting_focus(focus)
        priority = self.normalize_scouting_priority(priority)
        level = self.normalize_scouting_brief_level(level)
        age_band = age_band if age_band in SCOUTING_AGE_BANDS else "Any Age"
        style = style if style == "All" or style in STYLES else "All"
        cost = self.talent_search_cost(region, scout, focus, priority, level)
        if self.cash < cost:
            return False, f"This search needs ${cost:,}."
        weeks = self.talent_search_duration(scout, region, level)
        assignment = {"assignment_id": f"SEARCH-{self.calendar_week_index()}-{len(getattr(self, 'scouting_searches', [])) + 1}", "type": "Talent Search", "scout": scout.get("name", scout_name), "scout_id": self.scout_identity_key(scout), "region": region, "gender": gender, "weight": weight, "focus": focus, "priority": priority, "age_band": age_band, "style": style, "level": level, "status": "In progress", "weeks_remaining": weeks, "started_week": self.calendar_week_index(), "cost": cost}
        self.scouting_searches = list(getattr(self, "scouting_searches", []))
        self.scouting_searches.append(assignment)
        self.cash -= cost
        self.record_finance_transaction(f"Talent search: {focus} ({region})", costs=cost)
        self.scouting.append(f"{scout.get('name', scout_name)} began a {focus} search in {region} ({gender}, {weight}); due in {weeks} week(s).")
        self.append_scouting_history("Search Started", detail=f"{level} {focus} / {priority} in {region}; {gender} {weight}, {age_band}, {style}.", assignment_id=assignment["assignment_id"])
        self.prune_scouting_state()
        ongoing_note = " Ongoing reviews repeat every 13 weeks, covered by staff salary with no repeat search fee; one slot stays occupied until cancelled." if level == "Ongoing" else ""
        return True, f"{scout.get('name', scout_name)} started the {focus} search in {region}. Report due in {weeks} week(s)." + ongoing_note

    def process_talent_searches(self):
        for search in getattr(self, "scouting_searches", []):
            if search.get("status") not in ("In progress", "Monitoring"):
                continue
            search["weeks_remaining"] = max(0, int(search.get("weeks_remaining", 0)) - 1)
            if search["weeks_remaining"] > 0:
                continue
            scout = self.scout_for_assignment(search, {"skill": 45, "fighter_judging": 45, "potential_judging": 45, "networking": 45, "regional_knowledge": 45, "reliability": 45})
            focus = self.normalize_scouting_focus(search.get("focus", "Free Agent Pool"))
            priority = self.normalize_scouting_priority(search.get("priority", "Balanced"))
            level = self.normalize_scouting_brief_level(search.get("level", "Standard"))
            candidate_rows = self.scouting_search_candidate_rows(focus)
            broad_rows = [(fighter, source) for fighter, source in candidate_rows if (search.get("region") in ("All", "Worldwide") or fighter.region == search.get("region")) and (search.get("gender") == "All" or fighter.gender == search.get("gender"))]
            exact_rows = [(fighter, source) for fighter, source in broad_rows if (search.get("weight") == "All" or fighter.weight == search.get("weight")) and self.scouting_age_band_matches(fighter, search.get("age_band", "Any Age")) and (search.get("style", "All") == "All" or fighter.style == search.get("style"))]
            exact_ids = {self.scouting_report_key(fighter) for fighter, _source in exact_rows}
            unseen = [
                (fighter, source, "Exact Match") for fighter, source in exact_rows
                if not self.scouting_report_blocks_discovery(self.scouting_report_for(fighter))
            ]
            if len(unseen) < 3:
                unseen.extend(
                    (fighter, source, "Near Match") for fighter, source in broad_rows
                    if self.scouting_report_key(fighter) not in exact_ids
                    and not self.scouting_report_blocks_discovery(self.scouting_report_for(fighter))
                )
            if unseen:
                networking = int(scout.get("networking", scout.get("skill", 45)) or 45)
                sample_size = min(len(unseen), max(6, 4 + networking // 8))
                exact_pool = [row for row in unseen if row[2] == "Exact Match"]
                near_pool = [row for row in unseen if row[2] == "Near Match"]
                sampled = random.sample(exact_pool, k=min(sample_size, len(exact_pool)))
                remaining = sample_size - len(sampled)
                if remaining:
                    sampled.extend(random.sample(near_pool, k=min(remaining, len(near_pool))))
                sampled.sort(key=lambda row: (row[2] == "Exact Match", self.scouting_search_score(row[0], scout, focus, row[1], priority)), reverse=True)
                # A search used to cost 2.5x a basic report, hold a scout slot
                # for weeks, and surface exactly one name, so breadth was never
                # affordable. It now returns a shortlist the player can triage.
                shortlist_size = min(len(sampled), max(3, 2 + networking // 25))
                confidence_base = (
                    scout.get("fighter_judging", 45) * 0.34
                    + scout.get("potential_judging", 45) * 0.27
                    + scout.get("reliability", 45) * 0.24
                    + scout.get("regional_knowledge", 45) * 0.08
                    + scout.get("networking", 45) * 0.07
                )
                leads = []
                for index, (candidate, source, match_quality) in enumerate(sampled[:shortlist_size]):
                    # The headline lead gets the scout's best read; the rest of
                    # the shortlist is a thinner sweep, so a dedicated report is
                    # still worth buying on anyone the player takes seriously.
                    depth_penalty = 0 if index == 0 else 8 + index * 3
                    confidence = max(35, min(88, round(
                        confidence_base - depth_penalty
                        + random.randint(-max(2, (100 - int(scout.get("reliability", 45))) // 18), 5)
                    )))
                    key = self.scouting_report_key(candidate)
                    previous = self.scouting_report_for(candidate)
                    history = self.scouting_report_history(previous)
                    previous_snapshot = self.scouting_report_snapshot(previous)
                    if previous_snapshot:
                        history = (history + [previous_snapshot])[-12:]
                    look_count = len(history) + 1
                    notes = self.scouting_report_notes(candidate, confidence)
                    notes.extend([
                        f"Identified through a {focus.lower()} scouting brief.",
                        f"Current market: {source}.",
                        "Headline lead of the brief." if index == 0 else "Secondary shortlist name from the same sweep.",
                        match_quality + ".",
                    ])
                    if match_quality == "Near Match":
                        mismatches = []
                        if search.get("weight") != "All" and candidate.weight != search.get("weight"):
                            mismatches.append(f"division is {candidate.weight}, not {search.get('weight')}")
                        if not self.scouting_age_band_matches(candidate, search.get("age_band", "Any Age")):
                            mismatches.append(f"age {candidate.age} is outside {search.get('age_band')}")
                        if search.get("style", "All") != "All" and candidate.style != search.get("style"):
                            mismatches.append(f"style is {candidate.style_label}, not {search.get('style')}")
                        notes.append("Brief differences: " + "; ".join(mismatches) + ".")
                    self.scouting_reports[key] = {
                        "schema_version": 4, "fighter_id": key, "fighter_name": candidate.name,
                        "kind": "basic", "status": "Complete",
                        "started_week": search.get("started_week", self.calendar_week_index()),
                        "completed_week": self.calendar_week_index(), "weeks_remaining": 0,
                        "confidence": confidence, "reveal": confidence, "scout": search.get("scout"),
                        "scout_id": search.get("scout_id", ""), "region": candidate.region,
                        "notes": notes, "history": history, "look_number": look_count,
                        "comprehensive": False,
                        "evidence": {"source": "Talent Search", "focus": focus, "priority": priority, "market": source, "match_quality": match_quality},
                        "estimates": self.build_scouting_estimates(candidate, scout, "basic", confidence, look_count=look_count),
                    }
                    if hasattr(self, "scout_signing_recommendation"):
                        verdict, reason = self.scout_signing_recommendation(candidate, self.scouting_reports[key])
                        self.scouting_reports[key]["recommendation"] = verdict
                        self.scouting_reports[key]["recommendation_reason"] = reason
                    else:
                        verdict = "REPORT COMPLETE"
                    leads.append((candidate, source, confidence, verdict, match_quality))
                target, source, headline_confidence, _verdict, _match_quality = leads[0]
                key = self.scouting_report_key(target)
                search.update({
                    "status": "Complete", "result_fighter_id": key, "result_name": target.name,
                    "result_fighter_ids": [self.scouting_report_key(candidate) for candidate, _source, _confidence, _verdict, _quality in leads],
                    "result_names": [candidate.name for candidate, _source, _confidence, _verdict, _quality in leads],
                    "result_match_quality": [quality for _candidate, _source, _confidence, _verdict, quality in leads],
                    "result_count": len(leads),
                })
                self.update_scouting_region_knowledge(search.get("region"), 7, f"{focus} talent search")
                self.append_scouting_history("Search Complete", target, f"{focus} / {priority} returned {len(leads)} lead(s).", assignment_id=search.get("assignment_id", ""))
                lead_lines = "\n".join(
                    f"- {candidate.name} ({candidate.gender} {candidate.weight}, {candidate.region}, {lead_source}) - {quality} - {lead_confidence}% dossier - {lead_verdict}"
                    for candidate, lead_source, lead_confidence, lead_verdict, quality in leads
                )
                body = (
                    f"{search.get('scout')} completed the {focus} brief and returned {len(leads)} lead(s), headlined by "
                    f"{target.name}, a {target.gender} {target.weight} from {target.region} ({source}) on a {headline_confidence}% dossier.\n\n"
                    f"{lead_lines}\n\nEvery name above now carries a basic dossier. Commission a full evaluation on anyone you intend to sign."
                )
            else:
                search.update({"status": "Complete", "result_name": "No suitable lead"})
                body = f"{search.get('scout')} completed the {focus} search in {search.get('region')} but found no suitable unscouted lead matching the brief."
                self.append_scouting_history("Search Complete", detail=f"{focus} / {priority}: no suitable existing lead.", assignment_id=search.get("assignment_id", ""))
            self.inbox.append({"subject": f"Talent Search Complete - {focus}", "body": body, "type": "Scouting", "resolved": False, "fighter_id": search.get("result_fighter_id", "")})
            if level == "Ongoing":
                search["status"] = "Monitoring"
                search["weeks_remaining"] = 13
                search["next_review_week"] = self.calendar_week_index() + 13

    def _finance_transaction_row(self, label, revenue=0, costs=0, category="Operating", source="", counterparty="", event="", reference="", entity=""):
        """Build the canonical, auditable shape shared by player and AI ledgers."""
        revenue = max(0, round(revenue))
        costs = max(0, round(costs))
        transaction_number = int(getattr(self, "_finance_transaction_number", 0) or 0) + 1
        self._finance_transaction_number = transaction_number
        return {
            "id": f"FIN-{self.month}-{self.week}-{transaction_number}",
            "month": int(self.month), "week": int(self.week),
            "label": str(label), "category": str(category or "Operating"),
            "source": str(source or label), "counterparty": str(counterparty or ""),
            "event": str(event or ""), "reference": str(reference or ""),
            "entity": str(entity or getattr(self, "player_company_name", "")),
            "revenue": revenue, "costs": costs, "net": revenue - costs,
        }

    def _append_finance_transaction(self, finance, row, ledger_text=None):
        finance.setdefault("week_transactions", []).append(row)
        finance["week_transactions"] = finance["week_transactions"][-240:]
        if ledger_text:
            finance.setdefault("ledger", []).insert(0, ledger_text)
            finance["ledger"] = finance["ledger"][:240]

    def record_finance_transaction(self, label, revenue=0, costs=0, category="Operating", source="", counterparty="", event="", reference=""):
        self.ensure_finance_defaults()
        row = self._finance_transaction_row(label, revenue, costs, category, source, counterparty, event, reference)
        self._append_finance_transaction(self.finance, row)
        net = round(revenue) - round(costs)
        if net:
            parts = []
            if revenue:
                parts.append(f"${round(revenue):,} income")
            if costs:
                parts.append(f"${round(costs):,} costs")
            self.record_change("Finance", label, net, " and ".join(parts))

    def ensure_promotion_finance_defaults(self, promo):
        finance = getattr(promo, "finance", None)
        if not isinstance(finance, dict):
            finance = {}
            promo.finance = finance
        finance.setdefault("ledger", [])
        finance.setdefault("week_transactions", [])
        finance.setdefault("weekly_history", [])
        if not isinstance(finance["ledger"], list):
            finance["ledger"] = []
        if not isinstance(finance["week_transactions"], list):
            finance["week_transactions"] = []
        if not isinstance(finance["weekly_history"], list):
            finance["weekly_history"] = []
        finance.setdefault("parent_distributions", 0)
        finance.setdefault("transfer_fees_received", 0)
        return finance

    def record_promotion_finance_transaction(self, promo, label, revenue=0, costs=0, category="Operating", source="", counterparty="", event="", reference=""):
        """Record a cash movement belonging to an AI or child promotion."""
        finance = self.ensure_promotion_finance_defaults(promo)
        row = self._finance_transaction_row(
            label, revenue, costs, category, source, counterparty, event, reference,
            entity=getattr(promo, "name", ""),
        )
        self._append_finance_transaction(finance, row)
        net = row["net"]
        if net:
            finance.setdefault("ledger", []).insert(0, f"Month {self.month} Week {self.week}: {label} {'+' if net >= 0 else '-'}${abs(net):,}.")
            finance["ledger"] = finance["ledger"][:240]
        return row

    def reconcile_promotion_finance(self, promo, repair=True):
        """Reconcile a promotion's cash to its canonical transactions for the week."""
        finance = self.ensure_promotion_finance_defaults(promo)
        period = (int(self.month), int(self.week))
        transactions = [row for row in finance["week_transactions"] if (row.get("month"), row.get("week")) == period]
        revenue = sum(int(row.get("revenue", 0) or 0) for row in transactions)
        costs = sum(int(row.get("costs", 0) or 0) for row in transactions)
        history = finance["weekly_history"]
        if history and (history[-1].get("month"), history[-1].get("week")) == period:
            opening = history[-1].get("opening", promo.cash - revenue + costs)
        else:
            opening = history[-1].get("ending", promo.cash - revenue + costs) if history else promo.cash - revenue + costs
        expected = opening + revenue - costs
        difference = int(promo.cash - expected)
        if difference and repair and not any(row.get("reference") == f"reconcile:{promo.name}:{self.month}:{self.week}" for row in transactions):
            self.record_promotion_finance_transaction(
                promo, "Unattributed cash reconciliation", revenue=max(0, difference), costs=max(0, -difference),
                category="Reconciliation", source="Weekly cash-balance check", reference=f"reconcile:{promo.name}:{self.month}:{self.week}",
            )
            transactions = [row for row in finance["week_transactions"] if (row.get("month"), row.get("week")) == period]
            revenue = sum(int(row.get("revenue", 0) or 0) for row in transactions)
            costs = sum(int(row.get("costs", 0) or 0) for row in transactions)
        return {"opening": opening, "revenue": revenue, "costs": costs, "ending": promo.cash, "difference": promo.cash - (opening + revenue - costs)}

    def close_promotion_finance_week(self, promo):
        finance = self.ensure_promotion_finance_defaults(promo)
        report = self.reconcile_promotion_finance(promo, repair=True)
        row = {"month": self.month, "week": self.week, **report,
               "net": report["ending"] - report["opening"],
               "transactions": [item for item in finance["week_transactions"] if (item.get("month"), item.get("week")) == (self.month, self.week)]}
        history = finance["weekly_history"]
        if history and (history[-1].get("month"), history[-1].get("week")) == (self.month, self.week):
            history[-1] = row
        else:
            history.append(row)
        finance["weekly_history"] = history[-192:]
        return row

    def finance_reconciliation_status(self, finance=None, cash=None):
        """Return the latest stored cash/ledger balance check without mutating state."""
        finance = finance if isinstance(finance, dict) else getattr(self, "finance", {})
        history_value = finance.get("weekly_history", [])
        history = list(history_value) if isinstance(history_value, (list, tuple)) else []
        if not history:
            return {"balanced": True, "difference": 0, "period": None}
        row = history[-1]
        if not isinstance(row, dict):
            return {"balanced": False, "difference": 0, "period": None, "diagnostics": ["latest retained finance row is unavailable"]}

        def safe_int(value, fallback=0):
            if isinstance(value, bool) or value is None or value == "":
                return fallback
            try:
                return int(value)
            except (TypeError, ValueError):
                return fallback

        diagnostics = []
        fields = {
            "opening": row.get("opening", 0),
            "revenue": row.get("revenue", 0),
            "costs": row.get("costs", 0),
            "ending": row.get("ending", cash if cash is not None else 0),
        }
        for name, value in fields.items():
            if isinstance(value, bool):
                diagnostics.append(f"{name} is malformed")
                continue
            try:
                int(value or 0)
            except (TypeError, ValueError):
                diagnostics.append(f"{name} is malformed")
        expected = safe_int(fields["opening"]) + safe_int(fields["revenue"]) - safe_int(fields["costs"])
        actual = safe_int(fields["ending"], safe_int(cash, 0))
        difference = actual - expected
        return {"balanced": difference == 0 and not diagnostics, "difference": difference, "period": (row.get("month"), row.get("week")), "diagnostics": diagnostics}

    # ---- Crossover superfights (player-only) -------------------------------

    def crossover_promotion_of(self, fighter):
        for promo in getattr(self, "promotions", []):
            if fighter in promo.roster:
                return promo
        return None

    def crossover_weight_gap(self, weight_a, weight_b):
        """Number of divisions between two weight classes (None if unrecognised)."""
        if weight_a not in WEIGHTS or weight_b not in WEIGHTS:
            return None
        return abs(WEIGHTS.index(weight_a) - WEIGHTS.index(weight_b))

    def eligible_crossover_champions(self, gender=None, weight=None, max_class_gap=1):
        """Rival AI champions available for a non-title superfight.

        A superfight is same-division by default; a one-class gap is allowed as a
        catchweight. A Lightweight can never be matched with a Heavyweight."""
        champions = []
        for promo in getattr(self, "promotions", []):
            if getattr(promo, "is_regional_feeder", False):
                continue
            for fighter in promo.roster:
                if getattr(fighter, "champion", False) and not getattr(fighter, "retired", False) and not getattr(fighter, "injured", 0):
                    if gender and fighter.gender != gender:
                        continue
                    if weight is not None:
                        gap = self.crossover_weight_gap(weight, fighter.weight)
                        if gap is None or gap > max_class_gap:
                            continue
                    champions.append((fighter, promo))
        champions.sort(key=lambda item: -(item[0].overall + item[0].popularity))
        return champions

    def crossover_sanctioning_fee(self, rival):
        """The extra fee a rival promotion charges to sanction a superfight."""
        promo = self.crossover_promotion_of(rival)
        prestige = getattr(promo, "reputation_score", 50) if promo else 50
        return int(25000 + getattr(rival, "popularity", 40) * 1500 + prestige * 700)

    def crossover_acceptance_chance(self, rival, offer, fee=None):
        """Chance the rival promotion agrees, given your standing and the offer."""
        fee = self.crossover_sanctioning_fee(rival) if fee is None else fee
        promo = self.crossover_promotion_of(rival)
        prestige = getattr(promo, "reputation_score", 50) if promo else 50
        generosity = (offer / max(1, fee)) - 1.0
        base = 0.32 + (self.company_pop - prestige) / 130 + generosity * 0.6
        return max(0.08, min(0.95, base))

    def run_superfight_night(self, event_name, venue, region, bouts):
        """Simulate a superfight-night card in isolation.

        `bouts` is an ordered list of {"a": player_fighter, "b": opponent,
        "crossover": bool}. Every bout is non-title, so no belt ever changes
        hands; guest champions keep their belts and stay in their promotion.
        Results are real (records update). Returns a watchable package."""
        fight_logs, results, event_log = [], [], [f"{event_name} - {venue}", "=" * 60, ""]
        total_purse = 0
        star_power = 0
        crossover_count = sum(1 for bout in bouts if bout.get("crossover"))
        for index, bout in enumerate(bouts):
            a, b = bout["a"], bout["b"]
            crossover = bool(bout.get("crossover"))
            main = index == 0
            fight = {"main": main, "title": False, "tier": "Superfight" if crossover else "Prelim", "region": region, "crossover": crossover, "ai_controlled": True}
            a_record, b_record = a.record, b.record
            a_rating, b_rating = self.bout_rating_snapshot(a), self.bout_rating_snapshot(b)
            winner, loser, method, round_no, lines = self.simulate_fight(a, b, fight)
            excitement = self.fight_excitement(a, b, winner, loser, method, round_no, fight)
            if method == "Draw":
                self.apply_draw_result(a, b, fight)
                result_line = f"{a.name} vs {b.name} - Draw (R{round_no})"
            elif method == "No Contest":
                self.apply_no_contest_result(a, b, fight)
                result_line = f"{a.name} vs {b.name} - No Contest (R{round_no})"
            else:
                self.apply_result(winner, loser, fight, method)
                result_line = f"{winner.name} def. {loser.name} by {method} (R{round_no})"
            label = ("CROSSOVER SUPERFIGHT" if crossover else "PRELIM") + (" - MAIN EVENT" if main else "")
            if crossover:
                subject = a if a in self.roster else b if b in self.roster else a
                opponent = b if subject is a else a
                summary = (
                    f"{subject.name}'s crossover showcase against {opponent.name} ended in a {method.lower()}."
                    if method in ("Draw", "No Contest")
                    else f"{subject.name} {'won' if winner is subject else 'lost'} the crossover showcase against {opponent.name} by {method}."
                )
                self.record_crossover_story(
                    subject, opponent, phase="superfight_result", status="resolved",
                    summary=summary, resolution=summary,
                )
                if method not in ("Draw", "No Contest"):
                    winner_company = self.fighter_company_name(winner)
                    loser_company = self.fighter_company_name(loser)
                    self.record_promotion_war_event(
                        winner_company, loser_company, "sanctioned_superfight", summary,
                        fighters=[winner, loser], points=2, importance=4,
                        event_ref=(
                            f"superfight:{self.story_company_key(event_name)}:{self.month}:{self.week}:"
                            f"{getattr(winner, 'fighter_id', '')}:{getattr(loser, 'fighter_id', '')}"
                        ),
                    )
                    self.record_contract_revenge_fight(
                        winner, loser, winner_company, loser_company, method, event_name,
                    )
            if crossover and method not in ("Draw", "No Contest"):
                if winner in self.roster:
                    gain = 2 + min(5, getattr(loser, "popularity", 40) // 20)
                    self.company_pop = min(100, self.company_pop + gain)
                    winner.star_quality = min(100, getattr(winner, "star_quality", 40) + 3)
                    winner.popularity = min(100, winner.popularity + 4)
                    winner.fight_history = ([f"Crossover superfight win over {loser.name} ({self.fighter_company_name(loser)})."] + (winner.fight_history or []))[:60]
                    self.record_world_story("Superfight", f"{winner.name} beats {loser.name} in a crossover superfight.",
                                            f"{self.player_company_name} lands a marquee cross-promotional win at {event_name}.",
                                            [self.player_company_name], [winner.name, loser.name], 3)
                elif loser in self.roster:
                    self.company_pop = max(1, self.company_pop - 1)
            fight_logs.append({
                "heading": f"{a.name} vs {b.name}", "label": label,
                "a": a.name, "b": b.name, "a_id": getattr(a, "fighter_id", ""), "b_id": getattr(b, "fighter_id", ""),
                "a_record": a_record, "b_record": b_record, "a_rating": a_rating, "b_rating": b_rating,
                "weight": a.weight, "result": result_line, "lines": list(lines) + ["", result_line],
            })
            event_log.extend([f"{label}: {a.name} vs {b.name}", result_line, ""])
            results.append((a, b, result_line, excitement))
            guest_premium = getattr(b, "popularity", 40) * 2500 if crossover else 0
            total_purse += getattr(a, "purse", 0) + getattr(b, "purse", 0) + guest_premium
            star_power += a.popularity + b.popularity
        gate = int((star_power * 4200 + self.company_pop * 9000) * (1 + 0.28 * crossover_count))
        profit = gate - total_purse
        self.cash += profit
        self.record_finance_transaction(f"Superfight Night: {event_name}", revenue=gate, costs=total_purse)
        self.company_stability = min(100, self.company_stability + 1)
        summary = f"{event_name}: {len(results)} bout(s), {crossover_count} crossover superfight(s). Gate ${gate:,}, profit ${profit:,}."
        package = {
            "date": f"Month {self.month} Week {self.week}", "company": self.player_company_name,
            "event_name": event_name, "summary": summary, "fight_count": len(results), "profit": profit,
            "finance": {"ticket_revenue": gate, "total_revenue": gate, "total_expense": total_purse, "profit": profit, "attendance": 0, "venue_capacity": 1},
            "log": [summary, ""] + event_log, "fight_logs": fight_logs,
        }
        self.archive_result_record({
            "date": package["date"], "company": self.player_company_name, "event": event_name,
            "summary": summary, "fights": len(results), "gate": f"${gate:,}", "profit": f"${profit:,}",
            "log": package["log"], "fight_logs": fight_logs, "finance": package["finance"],
        })
        self.news.insert(0, summary)
        return package

    def record_change(self, category, subject, delta, reason, importance=1):
        """Record a compact, attributed state change for weekly player reporting."""
        if getattr(self, "spectator_mode", False) and category not in {"World", "Event"}:
            return
        journal = getattr(self, "change_journal", None)
        if journal is None:
            self.change_journal = journal = []
        entry = {
            "month": int(self.month), "week": int(self.week),
            "date": self.format_game_date(), "category": str(category),
            "subject": str(subject), "delta": delta, "reason": str(reason),
            "importance": max(1, min(3, int(importance))),
        }
        journal.append(entry)
        self.change_journal = journal[-400:]

    def capture_player_change_snapshot(self):
        return {
            "cash": self.cash,
            "popularity": self.company_pop,
            "stability": self.company_stability,
            "fighters": {
                getattr(fighter, "fighter_id", "") or fighter.name: {
                    "name": fighter.name, "overall": fighter.overall,
                    "popularity": fighter.popularity, "morale": fighter.morale,
                }
                for fighter in self.roster
            },
        }

    def record_snapshot_changes(self, before, context, include_finance=True):
        """Compare two real states and retain only changes the player can act on."""
        if not before or getattr(self, "spectator_mode", False):
            return
        if include_finance and self.cash != before["cash"]:
            self.record_change("Finance", self.player_company_name, self.cash - before["cash"], context, 2)
        if self.company_pop != before["popularity"]:
            self.record_change("Popularity", self.player_company_name, self.company_pop - before["popularity"], context, 2)
        if self.company_stability != before["stability"]:
            self.record_change("Stability", self.player_company_name, self.company_stability - before["stability"], context, 2)
        changes = []
        for fighter in self.roster:
            key = getattr(fighter, "fighter_id", "") or fighter.name
            old = before["fighters"].get(key)
            if not old:
                continue
            for field, label in (("overall", "Development"), ("popularity", "Popularity"), ("morale", "Morale")):
                delta = getattr(fighter, field) - old[field]
                if delta:
                    changes.append((abs(delta), fighter.name, label, delta))
        for _magnitude, name, category, delta in sorted(changes, reverse=True)[:10]:
            reason = context
            if category == "Development":
                reason = "Monthly training, gym quality, age curve, potential and recent form"
            self.record_change(category, name, delta, reason)

    def close_finance_week(self):
        """Persist a compact, truthful weekly cashflow row for the finance dashboard."""
        self.ensure_finance_defaults()
        history = self.finance["weekly_history"]
        period = (self.month, self.week)
        transactions = [item for item in self.finance["week_transactions"] if (item["month"], item["week"]) == period]
        revenue = sum(item["revenue"] for item in transactions)
        costs = sum(item["costs"] for item in transactions)
        if history and (history[-1].get("month"), history[-1].get("week")) == period:
            previous = history[-1].get("opening", self.cash - revenue + costs)
        else:
            previous = history[-1]["ending"] if history else self.cash - revenue + costs
        difference = self.cash - (previous + revenue - costs)
        if difference and not any(item.get("reference") == f"reconcile:player:{self.month}:{self.week}" for item in transactions):
            self.record_finance_transaction(
                "Unattributed cash reconciliation", revenue=max(0, difference), costs=max(0, -difference),
                category="Reconciliation", source="Weekly cash-balance check",
                reference=f"reconcile:player:{self.month}:{self.week}",
            )
            transactions = [item for item in self.finance["week_transactions"] if (item["month"], item["week"]) == period]
            revenue = sum(item["revenue"] for item in transactions)
            costs = sum(item["costs"] for item in transactions)
        row = {
            "month": self.month, "week": self.week, "opening": previous,
            "revenue": revenue, "costs": costs, "net": self.cash - previous,
            "ending": self.cash, "transactions": transactions,
        }
        if history and (history[-1]["month"], history[-1]["week"]) == period:
            history[-1] = row
        else:
            history.append(row)
        self.finance["weekly_history"] = history[-192:]
        self.update_annual_finance_history()
        for promo in [item for item in getattr(self, "promotions", []) if not getattr(item, "is_regional_feeder", False)]:
            self.close_promotion_finance_week(promo)

    def fluctuate_region_interest(self):
        for data in self.regions.values():
            baseline = data.setdefault("interest_baseline", min(80, data.get("mma_love", 50)))
            if data.get("interest_review_month") != self.month:
                data["interest_review_month"] = self.month
                if data.get("mma_love", 50) > baseline + 5:
                    data["mma_love"] = max(15, data["mma_love"] - 1)
        if random.random() > 0.28:
            return
        region = random.choice(list(self.regions.keys()))
        data = self.regions[region]
        old = data.get("mma_love", 50)
        delta = random.choice([-6, -4, -2, 2, 4, 6])
        data["mma_love"] = max(15, min(100, old + delta))
        direction = "rising" if delta > 0 else "cooling"
        self.news.insert(0, f"Week {self.week}: MMA interest in {region} is {direction}; regional love is now {data['mma_love']}%.")

    def random_fighter_events(self):
        pool = [f for f in self.roster if not f.retired]
        if not pool or random.random() > 0.45:
            return
        fighter = random.choice(pool)
        event = random.choice(["viral", "badcamp", "charity", "weight", "gym"])
        if event == "viral":
            fighter.media_heat = min(100, fighter.media_heat + random.randint(6, 14))
            fighter.popularity = min(100, fighter.popularity + random.randint(1, 3))
            self.news.insert(0, f"Week {self.week}: {fighter.name} went viral after a media clip; popularity and media heat rose.")
        elif event == "badcamp":
            fighter.camp_boost = max(0, fighter.camp_boost - random.randint(1, 3))
            fighter.morale = max(1, fighter.morale - random.randint(3, 8))
            self.news.insert(0, f"Week {self.week}: {fighter.name}'s camp hit problems; morale dipped.")
        elif event == "charity":
            fighter.sponsor_appeal = min(99, fighter.sponsor_appeal + random.randint(3, 8))
            fighter.morale = min(100, fighter.morale + random.randint(2, 6))
            self.news.insert(0, f"Week {self.week}: {fighter.name} helped a local charity; sponsors took notice.")
        elif event == "weight":
            fighter.fatigue = min(100, fighter.fatigue + random.randint(4, 12))
            fighter.morale = max(1, fighter.morale - random.randint(1, 5))
            self.news.insert(0, f"Week {self.week}: {fighter.name} had a rough weight-management week.")
        else:
            gym = self.gym_by_name(fighter.camp)
            swing = random.choice([-5, -3, 3, 5])
            fighter.morale = max(1, min(100, fighter.morale + swing))
            if gym:
                gym.morale = max(25, min(95, gym.morale + (1 if swing > 0 else -1)))
            direction = "clicked with the room" if swing > 0 else "had a difficult week with the room"
            self.news.insert(0, f"Week {self.week}: {fighter.name} {direction} at {fighter.camp}; morale {'rose' if swing > 0 else 'fell'}.")

    def gym_fit_base_score(self, fighter, gym, promotion_region=""):
        local = 18 if gym.region == fighter.region else 9 if gym.region == promotion_region else 0
        style = self.gym_specialty_bonus(fighter, gym)
        attention = self.gym_attention_multiplier(gym)
        overfull = max(0.0, gym.member_count / max(1, gym.capacity) - 1.0) if gym.capacity < 500 else 0
        prospect = 5 if fighter.age < fighter.prime_start and "Prospect Development" in gym.specialties else 0
        return self.gym_effective_training(gym, fighter) * 0.70 + gym.reputation * 0.12 + style + local + prospect - overfull * 24 + attention * 4

    def gym_fit_score(self, fighter, gym, promotion_region="", randomize=False):
        affordability = -max(0, gym.monthly_fee - max(1200, fighter.purse // 8)) / 650
        noise = random.uniform(-4, 4) if randomize else 0
        return self.gym_fit_base_score(fighter, gym, promotion_region) + affordability + noise

    def move_fighter_to_gym(self, fighter, gym, reason="Career move"):
        if not gym or fighter.camp == gym.name:
            return False
        old = fighter.camp or "Independent"
        old_key = self.coaching_loyalty_story_key(fighter, old)
        old_thread = self.story_thread(old_key) if old_key else None
        prior_tenure = max(0, self.month - int(getattr(fighter, "camp_joined_month", 0) or 0))
        significant = bool(
            fighter in getattr(self, "roster", [])
            or getattr(fighter, "academy_graduate", False)
            or getattr(fighter, "champion", False)
            or getattr(fighter, "interim_champion", False)
            or getattr(fighter, "popularity", 0) >= 55
            or getattr(fighter, "overall", 0) >= 72
        )
        history = getattr(fighter, "camp_history", None) or []
        fit = round(self.gym_fit_score(fighter, gym, getattr(fighter, "region", "")))
        history.append({"month": self.month, "from": old, "to": gym.name, "reason": reason, "fit": fit})
        fighter.camp_history = history[-20:]
        fighter.camp = gym.name
        fighter.camp_joined_month = self.month
        fighter.camp_quality = gym.quality
        fighter.training_location = gym.region
        self.record_gym_story(gym, f"{fighter.name} joined the room", reason, fighter=fighter)
        move_phase = "gym_split" if old != "Independent" and any(word in reason.lower() for word in ("attention", "fit", "strained")) else "camp_move"
        if old != "Independent" and (old_thread or (significant and prior_tenure >= 6)):
            departure = f"{fighter.name} ended a {prior_tenure}-month partnership with {old} and moved to {gym.name}. {reason}"
            self.record_coaching_loyalty_story(
                fighter, old, phase="gym_split" if move_phase == "gym_split" else "chapter_closed",
                status="resolved", importance=3, summary=departure, resolution=departure,
                event_ref=f"{old_key}:departure:{self.month}:{self.week}:{self.story_company_key(gym.name)}",
            )
        self.record_gym_journey_story(
            fighter, phase=move_phase,
            summary=f"{fighter.name} left {old} for {gym.name}. {reason} New fit: {fit:+d}.",
            importance=3,
        )
        if significant:
            self.record_coaching_loyalty_story(
                fighter, gym.name, phase="new_partnership",
                summary=f"{fighter.name} began a new coaching partnership at {gym.name}. {reason}",
                importance=2,
                event_ref=f"{self.coaching_loyalty_story_key(fighter, gym.name)}:arrival:{self.month}:{self.week}",
            )
        return True

    def record_gym_story(self, gym, event, detail="", fighter=None):
        """Keep gym history as a career chronicle, not just quarterly telemetry."""
        if not gym:
            return
        entry = {
            "month": self.month, "event": event, "detail": detail,
            "members": getattr(gym, "member_count", 0), "capacity": getattr(gym, "capacity", 0),
            "effective": self.gym_effective_training(gym), "morale": getattr(gym, "morale", 0),
            "momentum": getattr(gym, "momentum", 0),
        }
        if fighter:
            entry["fighter"] = fighter.name
            entry["overall"] = fighter.overall
        gym.history = ([entry] + list(getattr(gym, "history", []) or []))[:60]

    def normalize_gym_assignments(self):
        """Place legacy promotion-camp labels into persistent world gyms once."""
        if not getattr(self, "gyms", None):
            return 0
        self.sync_gym_membership()
        gym_pool = getattr(self, "gyms", [])
        gym_lookup = {gym.name: gym for gym in gym_pool}
        viable_gyms = [gym for gym in gym_pool if gym.capacity >= 500 or gym.member_count < gym.capacity * 1.18]
        viable_gyms = viable_gyms or gym_pool
        gym_score_cache = {}
        rows = [(fighter, self.player_region) for fighter in self.roster + self.free_agents]
        for promo in self.promotions:
            rows.extend((fighter, promo.region) for fighter in promo.roster)
        for sport_world in getattr(self, "combat_sport_worlds", {}).values():
            rows.extend((fighter, getattr(fighter, "region", "")) for fighter in sport_world.get("roster", []))
        seen, moved = set(), 0
        for fighter, owner_region in rows:
            if id(fighter) in seen or fighter.retired or gym_lookup.get(fighter.camp):
                continue
            seen.add(id(fighter))
            target = gym_lookup.get(self.suggest_camp_for_fighter(fighter, owner_region, gym_pool=viable_gyms, gym_score_cache=gym_score_cache))
            if not target:
                continue
            old = fighter.camp or "Independent"
            fighter.camp = target.name
            fighter.camp_quality = target.quality
            fighter.camp_joined_month = self.month
            fighter.training_location = target.region
            if self.month > 1:
                fighter.camp_history = ((getattr(fighter, "camp_history", None) or []) + [{"month": self.month, "from": old, "to": target.name, "reason": "Joined the recognised world gym network"}])[-20:]
            moved += 1
        self.sync_gym_membership()
        return moved

    def suggest_camp_for_fighter(self, fighter, promotion_region, gym_pool=None, gym_score_cache=None):
        gyms = gym_pool if gym_pool is not None else (getattr(self, "gyms", []) or self.seed_gyms())
        pool = gyms or getattr(self, "gyms", []) or self.seed_gyms()
        if gym_score_cache is not None:
            cache_key = (
                getattr(fighter, "region", ""),
                promotion_region,
                getattr(fighter, "style", ""),
                bool(getattr(fighter, "age", 0) < getattr(fighter, "prime_start", 27)),
            )
            scored = gym_score_cache.get(cache_key)
            if scored is None:
                scored = [(gym, self.gym_fit_base_score(fighter, gym, promotion_region)) for gym in pool]
                gym_score_cache[cache_key] = scored
            affordability_floor = max(1200, int(getattr(fighter, "purse", 0) or 0) // 8)
            ranked = [
                gym for gym, _score in sorted(
                    scored,
                    key=lambda item: item[1] - max(0, item[0].monthly_fee - affordability_floor) / 650 + random.uniform(-4, 4),
                    reverse=True,
                )[:4]
            ]
        else:
            ranked = sorted(pool, key=lambda gym: self.gym_fit_score(fighter, gym, promotion_region, True), reverse=True)[:4]
        if not ranked:
            return "Independent"
        weights = [8, 5, 3, 1][:len(ranked)]
        return random.choices(ranked, weights=weights, k=1)[0].name

    def generate_weekly_world_activity(self):
        active = [f for f in self.roster if not f.injured]
        for fighter in self.roster:
            rival = self.resolve_rivalry_target(fighter)
            if rival and (rival.gender != fighter.gender or rival.weight != fighter.weight):
                fighter.rival = ""
                fighter.rival_fighter_id = ""
        if active and random.random() < 0.55:
            fighter = random.choice(active)
            if fighter.media_presence + fighter.charisma + random.randint(-30, 30) > 115:
                rivals = [f for f in self.roster if f.gender == fighter.gender and f.weight == fighter.weight and f.name != fighter.name]
                if rivals:
                    target = random.choice(rivals)
                    fighter.media_heat = min(100, fighter.media_heat + random.randint(4, 10))
                    target.media_heat = min(100, target.media_heat + random.randint(2, 7))
                    self.establish_rivalry(fighter, target, "Public callout", heat=random.randint(30, 52))
                    self.news.insert(0, f"Week {self.week}: {fighter.name} called out {target.name}; media heat is rising in the {fighter.weight} division.")
        if active and random.random() < 0.18:
            fighter = random.choice(active)
            if random.random() < effective_injury_tendency(fighter) / 180:
                fighter.injured = random.randint(1, 2)
                self.inbox.append({"subject": "Training Injury", "body": f"{fighter.name} suffered a minor training injury and is out {fighter.injured} month(s).", "type": "Medical", "resolved": False})
                self.news.insert(0, f"Week {self.week}: {fighter.name} picked up an injury in camp.")
        if self.promotions and random.random() < 0.35:
            promo = random.choice(self.promotions)
            note = random.choice([
                f"{promo.name} is rumored to be chasing a new broadcast package.",
                f"{promo.name} teased a title eliminator for its next card.",
                f"{promo.name} scouts were seen at a regional show.",
                f"Executives at {promo.name} are reviewing roster cuts and contract renewals.",
            ])
            self.news.insert(0, f"Week {self.week}: {note}")
        if random.random() < 0.32:
            self.simulate_gym_world_activity()
        if random.random() < 0.2:
            scout = self.create_generated_fighter(4, 30, 35, 72)
            self.free_agents.append(scout)
            self.news.insert(0, f"Week {self.week}: {scout.name} entered the market after a strong local performance.")
        if random.random() < 0.4:
            self.surface_division_storylines()

    def surface_division_storylines(self):
        """Let the title picture move on its own: hot streaks become contenders."""
        pools = [(self.roster, self.player_company_name, self.belts)]
        for promo in self.promotions:
            pools.append((promo.roster, promo.name, promo.belts or {}))
        random.shuffle(pools)
        for roster, company, belts in pools:
            surging = [f for f in roster if not f.retired and not f.champion and f.momentum >= 3 and f.record_w >= 5]
            if not surging:
                continue
            contender = max(surging, key=lambda f: (f.momentum, f.rank_score))
            key = self.belt_key(contender.gender, contender.weight)
            champ_name = belts.get(key) if isinstance(belts, dict) else None
            contender.media_heat = min(100, contender.media_heat + random.randint(6, 12))
            contender.popularity = min(100, contender.popularity + random.randint(1, 3))
            if champ_name and champ_name != contender.name:
                champion = next((fighter for fighter in roster if fighter.name == champ_name), None)
                if champion:
                    self.establish_rivalry(contender, champion, "Title-shot campaign", heat=random.randint(35, 56))
                    self.record_title_chase_story(company, contender, champion, "Title-shot campaign")
                else:
                    contender.rival = champ_name
                self.news.insert(0, f"Week {self.week}: {contender.name} is on a tear at {company} and is calling for a shot at {contender.gender} {contender.weight} champion {champ_name}.")
            else:
                self.record_title_chase_story(company, contender, None, "Contender surge")
                self.news.insert(0, f"Week {self.week}: {contender.name} has surged into title contention in the {company} {contender.weight} division.")
            return

    def simulate_gym_world_activity(self):
        if not getattr(self, "gyms", None):
            self.gyms = self.seed_gyms()
        self.sync_gym_membership()
        gym = random.choice(self.gyms)
        roll = random.random()
        if roll < 0.24:
            old = gym.facilities
            gym.facilities = min(99, gym.facilities + random.randint(1, 2))
            self.news.insert(0, f"Week {self.week}: {gym.name} upgraded its facilities from {old} to {gym.facilities}.")
            self.record_gym_story(gym, "Facility upgrade", f"Facilities improved from {old} to {gym.facilities}.")
        elif roll < 0.46:
            gym.scouting = min(99, gym.scouting + random.randint(1, 2))
            self.news.insert(0, f"Week {self.week}: {gym.name} expanded its regional scouting network.")
            self.record_gym_story(gym, "Scouting expansion", "The gym widened its regional talent network.")
        elif roll < 0.66:
            change = random.choice([-2, -1, 1, 2])
            gym.morale = max(25, min(95, gym.morale + change))
            self.news.insert(0, f"Week {self.week}: The room atmosphere at {gym.name} {'improved' if change > 0 else 'became strained'}.")
            self.record_gym_story(gym, "Room atmosphere", f"Morale {'improved' if change > 0 else 'dipped'} to {gym.morale}.")
        else:
            region = self.regions.get(gym.region)
            if region:
                change = random.choice([-3, -2, 2, 3, 4])
                region["mma_love"] = max(10, min(99, region.get("mma_love", 50) + change))
                direction = "rose" if change > 0 else "cooled"
                self.news.insert(0, f"Week {self.week}: Grassroots interest around {gym.city} {direction}; {gym.region} MMA love is now {region['mma_love']}%.")
        candidates = [
            f for f in self.roster + self.free_agents
            if f.camp == gym.name and not f.injured and f.fatigue < 65
        ]
        for promo in self.promotions:
            candidates.extend([f for f in promo.roster if f.camp == gym.name and not f.injured and f.fatigue < 65])
        if candidates and random.random() < 0.45:
            fighter = random.choice(candidates)
            self.apply_gym_camp_micro_improvement(fighter, gym, random.randint(2, 5))

    def process_gym_network_month(self):
        """Review room health, growth and AI camp movement once per month."""
        if not getattr(self, "gyms", None):
            self.gyms = self.seed_gyms()
        self.sync_gym_membership()
        player_ids = {id(fighter) for fighter in self.roster}
        rows = [(fighter, self.player_region) for fighter in self.free_agents]
        for promo in self.promotions:
            rows.extend((fighter, promo.region) for fighter in promo.roster)
        for sport_world in getattr(self, "combat_sport_worlds", {}).values():
            rows.extend((fighter, getattr(fighter, "region", "")) for fighter in sport_world.get("roster", []))
        by_gym = {gym.name: [] for gym in self.gyms}
        for fighter, owner_region in rows:
            if not fighter.retired:
                by_gym.setdefault(fighter.camp, []).append((fighter, owner_region))

        for gym in self.gyms:
            members = by_gym.get(gym.name, [])
            active = [fighter for fighter, _region in members]
            avg_form = sum(f.momentum for f in active) / max(1, len(active))
            elite = sum(f.overall >= 82 for f in active)
            champions = sum(f.champion or f.interim_champion for f in active)
            load = gym.member_count / max(1, gym.capacity)
            target_morale = 64 + min(10, champions * 2 + elite / max(4, len(active)) * 12) + max(-8, min(8, avg_form * 1.5))
            if gym.capacity < 500 and load > 1:
                target_morale -= min(24, (load - 1) * 28)
            gym.morale = max(25, min(95, round(gym.morale * 0.78 + target_morale * 0.22 + random.uniform(-1, 1))))
            target_momentum = max(-10, min(10, round(avg_form + champions * 1.5)))
            gym.momentum += 1 if target_momentum > gym.momentum else -1 if target_momentum < gym.momentum else 0
            if champions and random.random() < 0.12:
                gym.reputation = min(99, gym.reputation + 1)
            elif not active and gym.reputation > 35 and random.random() < 0.10:
                gym.reputation -= 1
            gym.development_reputation = max(30, min(99, round(gym.development_reputation * 0.85 + (gym.quality * 0.45 + gym.scouting * 0.25 + min(100, elite * 5) * 0.30) * 0.15)))
            if gym.capacity < 500 and load >= 0.92 and gym.facilities >= 65 and self.month - gym.last_review_month >= 6:
                growth = random.randint(5, 12)
                gym.capacity += growth
                gym.capacity_growth += growth
                gym.last_review_month = self.month
                self.record_gym_story(gym, f"Expanded capacity by {growth}", "Demand and facilities supported a larger coaching room.")
            elif not gym.last_review_month:
                gym.last_review_month = self.month
            if self.month % 3 == 0:
                self.record_gym_story(gym, "Quarterly room review", "Coaches reviewed room health, development output, and capacity.")

        moves = 0
        for gym in sorted(self.gyms, key=lambda item: item.member_count / max(1, item.capacity), reverse=True):
            if gym.capacity >= 500 or gym.member_count <= gym.capacity * 1.08:
                continue
            candidates = [(fighter, region) for fighter, region in by_gym.get(gym.name, []) if id(fighter) not in player_ids and self.month - getattr(fighter, "camp_joined_month", 0) >= 6]
            random.shuffle(candidates)
            candidates.sort(key=lambda row: self.gym_fit_score(row[0], gym, row[1]))
            for fighter, owner_region in candidates[:14]:
                old_score = self.gym_fit_score(fighter, gym, owner_region)
                target = self.gym_by_name(self.suggest_camp_for_fighter(fighter, owner_region))
                if target and target.name != gym.name and self.gym_fit_score(fighter, target, owner_region) >= old_score + 5:
                    if self.move_fighter_to_gym(fighter, target, "Sought a better training fit and more coaching attention"):
                        gym.member_count = max(0, gym.member_count - 1)
                        target.member_count += 1
                        moves += 1
                if moves >= 200:
                    break
            if moves >= 200:
                break
        self.sync_gym_membership()

    def tick_business_deals(self):
        self.ensure_finance_defaults()
        expired = []
        deals = self.finance.get("sponsor_deals", [])
        if not isinstance(deals, list):
            if deals not in (None, ""):
                self.finance.setdefault("sponsor_deals_legacy_raw", deals)
            deals = []
            self.finance["sponsor_deals"] = deals
        retained = []
        for deal in deals:
            if not isinstance(deal, dict):
                retained.append(deal)
                self.finance["sponsor_deal_review_required"] = True
                self.finance.setdefault("sponsor_deal_review_reason", "Malformed sponsor agreement retained during monthly expiry.")
                continue
            raw_months = deal.get("months", 0)
            try:
                months = int(raw_months)
            except (TypeError, ValueError):
                retained.append(deal)
                deal.setdefault("deal_review_required", True)
                deal.setdefault("deal_review_reason", "Sponsor term is malformed; expiry was held.")
                self.finance["sponsor_deal_review_required"] = True
                self.finance.setdefault("sponsor_deal_review_reason", "One or more sponsor terms are malformed.")
                continue
            deal["months"] = months - 1
            if deal["months"] <= 0:
                expired.append(deal)
            else:
                retained.append(deal)
        self.finance["sponsor_deals"] = retained
        for deal in expired:
            self.finance["ledger"].insert(0, f"Month {self.month}: Sponsor deal expired: {deal.get('name', 'Sponsor')}.")
        if self.finance.get("media_contracts"):
            # The developed media market owns contract expiry and keeps this
            # legacy alias synchronized. Do not decrement the same deal twice.
            self.sync_legacy_media_rights()
            return
        rights = self.finance.get("media_rights", {})
        if not isinstance(rights, dict):
            if rights not in (None, ""):
                self.finance.setdefault("media_rights_legacy_raw", rights)
            self.finance["media_rights_review_required"] = True
            self.finance.setdefault("media_rights_review_reason", "Saved media-rights package is malformed; expiry was held.")
            return
        raw_months = rights.get("months", 0)
        try:
            months = int(raw_months)
        except (TypeError, ValueError):
            rights.setdefault("contract_review_required", True)
            rights.setdefault("contract_review_reason", "Media-rights term is malformed; expiry was held.")
            return
        if months > 0:
            rights["months"] = months - 1
            if rights["months"] <= 0:
                self.finance["ledger"].insert(0, f"Month {self.month}: Media rights package expired: {rights.get('name', 'Media rights')}.")
                self.finance["media_rights"] = {"name": "No rights package", "months": 0, "fee": 0, "reach": 0}

    def normalize_inbox_messages(self):
        """Add durable ordering metadata to current and legacy inbox messages."""
        messages = list(getattr(self, "inbox", []) or [])
        current_month = max(1, int(getattr(self, "month", 1) or 1))
        current_week = max(1, min(4, int(getattr(self, "week", 1) or 1)))
        undated = [item for item in messages if not item.get("created_month")]
        legacy_total = len(messages)
        # Old saves did not timestamp mail. Inbox entries were appended in
        # chronological order, so spread large legacy queues conservatively at
        # roughly twenty messages per simulated month instead of declaring all
        # 600+ notices brand new forever.
        legacy_span = min(max(0, current_month - 1), max(0, (legacy_total - 1) // 20))
        for index, item in enumerate(messages):
            if not isinstance(item, dict):
                continue
            if not item.get("created_month"):
                distance = legacy_total - 1 - index
                offset = min(legacy_span, distance // 20) if legacy_total > 1 else 0
                item["created_month"] = max(1, current_month - offset)
                item["created_week"] = 1 if offset else current_week
            else:
                item["created_month"] = max(1, int(item.get("created_month", current_month) or current_month))
                item["created_week"] = max(1, min(4, int(item.get("created_week", 1) or 1)))
            item.setdefault("seen", False)
            item.setdefault("resolved", False)
        return messages

    def inbox_reader_rows(self):
        """Return display copies of inbox rows without repairing the save.

        Inbox repainting is a presentation read.  Legacy messages may not have
        created dates or read flags, so derive those defaults on a copy using
        the same conservative ordering used by ``normalize_inbox_messages``.
        The original message object is never changed here; explicit mail
        actions and the sanctioned migration boundary retain ownership of
        writes.
        """
        raw_messages = getattr(self, "inbox", [])
        if not isinstance(raw_messages, list):
            return [{
                "_source_index": None,
                "_read_status": "Unavailable",
                "subject": "Inbox unavailable",
                "body": "The saved inbox collection is not a list; load/migration review is required.",
                "type": "System", "resolved": False, "seen": False,
            }]
        def safe_int(value, fallback):
            if isinstance(value, bool) or value in (None, ""):
                return fallback
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return fallback
        current_month = max(1, safe_int(getattr(self, "month", 1), 1))
        current_week = max(1, min(4, safe_int(getattr(self, "week", 1), 1)))
        total = len(raw_messages)
        legacy_span = min(max(0, current_month - 1), max(0, (total - 1) // 20))
        rows = []
        for index, source in enumerate(raw_messages):
            if not isinstance(source, dict):
                rows.append({
                    "_source_index": index, "_read_status": "Unavailable",
                    "subject": "Malformed retained inbox row",
                    "body": "This message remains preserved for load/migration review.",
                    "type": "System", "resolved": False, "seen": False,
                })
                continue
            row = deepcopy(source)
            raw_month = row.get("created_month")
            if not raw_month:
                distance = total - 1 - index
                offset = min(legacy_span, distance // 20) if total > 1 else 0
                row["created_month"] = max(1, current_month - offset)
                row["created_week"] = 1 if offset else current_week
            else:
                row["created_month"] = max(1, safe_int(raw_month, current_month))
                row["created_week"] = max(1, min(4, safe_int(row.get("created_week", 1), 1)))
            row.setdefault("seen", False)
            row.setdefault("resolved", False)
            row["_source_index"] = index
            row["_read_status"] = "Recorded"
            rows.append(row)
        return rows

    def inbox_item_needs_action(self, item):
        """Return whether a still-live game decision depends on this message."""
        if not item or item.get("resolved", False):
            return False
        subject = str(item.get("subject", "") or "")
        subject_lower = subject.lower()
        fighter = None
        if any(token in subject_lower for token in ("contract expiring", "title shot owed", "retirement fight needed")) or item.get("action") == "serious_injury":
            fighter_id = str(item.get("fighter_id", "") or "")
            fighter_name = str(item.get("fighter", "") or subject.rsplit(" - ", 1)[-1]).strip()
            candidates = list(getattr(self, "roster", []) or []) + list(getattr(self, "free_agents", []) or []) + list(getattr(self, "retired_fighters", []) or [])
            if fighter_id:
                fighter = next((candidate for candidate in candidates if str(getattr(candidate, "fighter_id", "") or "") == fighter_id), None)
            if fighter is None and fighter_name:
                matches = []
                seen = set()
                for candidate in candidates:
                    if str(getattr(candidate, "name", "") or "") != fighter_name:
                        continue
                    identity = str(getattr(candidate, "fighter_id", "") or "") or f"object:{id(candidate)}"
                    if identity in seen:
                        continue
                    seen.add(identity)
                    matches.append(candidate)
                # Name-only legacy inbox rows are safe only when the name
                # resolves to one retained career; duplicate names fail closed.
                fighter = matches[0] if len(matches) == 1 else None
        action = str(item.get("action", "") or "")
        if action == "serious_injury":
            return bool(fighter and getattr(fighter, "serious_injury_pending", False))
        if action == "booking" and subject.startswith("Vacant Championship - "):
            key = subject.removeprefix("Vacant Championship - ")
            depth = sum(not candidate.retired and self.belt_key(candidate.gender, candidate.weight) == key for candidate in getattr(self, "roster", []))
            return key not in getattr(self, "closed_divisions", set()) and depth >= 2 and not self.normalize_belts(getattr(self, "belts", {})).get(key)
        if action:
            return True
        if "contract expiring" in subject_lower:
            try:
                remaining = int(getattr(fighter, "contract_months", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                remaining = 0
            return bool(fighter in getattr(self, "roster", []) and 0 < remaining <= 3)
        if "title shot owed" in subject_lower:
            return bool(fighter and getattr(fighter, "owed_title_shot", False))
        if "retirement fight needed" in subject_lower:
            return bool(fighter and getattr(fighter, "retirement_pending", False) and not getattr(fighter, "retired", False))
        if "academy prospect ready" in subject_lower or "academy graduation review" in subject_lower:
            name = subject.split(" - ", 1)[-1].strip()
            academy = getattr(self, "academy", {}) or {}
            return any(row.get("name") == name for row in academy.get("prospects", []) + academy.get("talent_pool", []))
        offer_id = item.get("super_event_id")
        if offer_id:
            return any(offer.get("id") == offer_id and offer.get("status", "Offered") == "Offered" for offer in getattr(self, "super_event_offers", []) or [])
        return subject_lower.startswith("urgent:")

    def maintain_inbox(self, manual=False):
        """Expire stale routine mail while preserving decisions and recent notices."""
        self.normalize_inbox_messages()
        current_month = max(1, int(getattr(self, "month", 1) or 1))
        resolved_limit = 1 if manual else 3
        read_limit = 3 if manual else 6
        unread_limit = 9 if manual else 12
        kept = []
        removed = 0
        for item in self.inbox:
            if not isinstance(item, dict):
                removed += 1
                continue
            if self.inbox_item_needs_action(item):
                kept.append(item)
                continue
            age = max(0, current_month - int(item.get("created_month", current_month) or current_month))
            subject = str(item.get("subject", "") or "").lower()
            stale_state_notice = (
                "contract expiring" in subject
                or "title shot owed" in subject
                or "observation expired" in subject
            )
            should_remove = (
                stale_state_notice
                or (item.get("resolved", False) and age >= resolved_limit)
                or (item.get("seen", False) and age >= read_limit)
                or (not item.get("seen", False) and age >= unread_limit)
            )
            if should_remove:
                removed += 1
            else:
                kept.append(item)

        # Keep the recent working set bounded even in scouting-heavy careers.
        # Actionable items never count against this limit.
        routine_positions = [index for index, item in enumerate(kept) if not self.inbox_item_needs_action(item)]
        excess = max(0, len(routine_positions) - 400)
        if excess:
            discard = set(routine_positions[:excess])
            kept = [item for index, item in enumerate(kept) if index not in discard]
            removed += excess
        self.inbox = kept
        return {"removed": removed, "remaining": len(kept)}

    def world_month_steps(self, player_ran_show):
        change_state = {}

        def capture_month_start():
            change_state["before"] = self.capture_player_change_snapshot()

        steps = [
            ("Capturing monthly changes", capture_month_start),
            ("Gym network review", self.process_gym_network_month),
            ("Player roster development", lambda: self.age_and_develop_fighters(self.roster, player_roster=True)),
            # Unsigned fighters still train, heal, lose fatigue, and age. Leaving
            # them outside this monthly pass made a minor injury permanent and
            # eventually froze both the retirement queue and transfer market.
            ("Free-agent recovery and development", lambda: self.age_and_develop_fighters(self.free_agents)),
            ("Annual regional wonderkid intake", self.spawn_annual_regional_wonderkid),
        ]
        worlds = getattr(self, "combat_sport_worlds", {}) or self.seed_combat_sport_worlds()
        self.combat_sport_worlds = worlds
        steps.append(("Career goals", self.process_career_goals))
        steps.append(("Career stories", self.process_career_arcs))
        for sport, world in list(worlds.items()):
            steps.append((
                f"{sport} circuit",
                lambda sport=sport, world=world: self.process_combat_sport_world(sport, world),
            ))
        steps.extend([
            ("Non-exclusive activity", self.simulate_nonexclusive_outside_fights),
            ("Free-agent negotiations", self.advance_free_agent_market),
            ("AI roster reviews", self.review_ai_roster_cuts),
            ("AI upgrade reviews", self.review_ai_upgrade_replacements),
            ("Monthly transfer market", self.market_churn),
            ("AI staff contracts", self.update_ai_staff_contracts),
            ("AI operating costs", self.apply_ai_operating_costs),
            ("Promotion survival", self.process_promotion_failures),
            ("Executive reviews", self.review_ai_executives),
            ("World replenishment", self.ensure_world_fighter_target),
            ("World balance metrics", self.update_world_metric_interactions),
            ("Media market and contracts", self.process_media_month),
            ("Contract warnings", self.check_contract_warnings),
            ("Staff contract warnings", self.check_staff_contract_warnings),
            ("Contract promises", self.review_contract_promises),
            ("Player renewals", self.auto_renew_player_contracts),
            ("Player contracts", self.update_contracts),
            ("Staff contracts", self.update_staff_contracts),
            ("Staff progression review", self.process_staff_progression_quarter_close if hasattr(self, "process_staff_progression_quarter_close") else lambda: None),
            ("AI contracts", self.update_ai_contracts),
            ("Retirement reviews", self.process_retirements),
            ("Promotion rankings", self.refresh_promotion_rankings),
            ("Company milestones and invitations", self.process_company_milestones_and_super_events),
            ("Inbox housekeeping", self.maintain_inbox),
        ])

        def finish_month():
            if not player_ran_show and not getattr(self, "spectator_mode", False):
                self.company_pop = max(1, self.company_pop - 1)
                self.news.insert(0, f"{self.player_company_name} stayed quiet this month; fans drifted toward other shows.")
            reason = "Monthly operations, contracts, training and market activity"
            if not player_ran_show and not getattr(self, "spectator_mode", False):
                reason += "; no event was promoted, causing audience drift"
            self.record_snapshot_changes(change_state.get("before"), reason, include_finance=False)
            self.news = self.news[:120]

        steps.append(("Finalising the month", finish_month))
        steps.append(("Industry standings snapshot", self.snapshot_industry_standings))
        return steps

    def process_promotion_month_review(self, promo):
        """Run one promotion's monthly development and card opportunity."""
        self.age_and_develop_fighters(promo.roster)
        if getattr(promo, "is_regional_feeder", False):
            self.simulate_regional_feeder_month(promo)
        elif random.random() < self.ai_show_chance(promo) * 0.65:
            self.simulate_ai_promotion_month(promo, develop=False)

    def process_world_month(self, player_ran_show):
        for _label, task in self.world_month_steps(player_ran_show):
            task()

    def update_world_metric_interactions(self):
        """Let the big world metrics talk to each other once per month.

        This gives long saves a pulse: company finance affects risk appetite,
        thin divisions create scouting pressure, strong regions become more
        attractive, and combat-sport activity feeds the wider fight economy.
        """
        active = [fighter for fighter in self.all_fighter_objects() if not fighter.retired]
        free = [fighter for fighter in self.free_agents if not fighter.retired]
        contracted = [fighter for fighter in self.roster if not fighter.retired]
        contracted.extend(
            fighter for promo in self.promotions
            if not getattr(promo, "is_regional_feeder", False)
            for fighter in promo.roster if not fighter.retired
        )
        contracted_80 = sum(fighter.overall >= 80 for fighter in contracted)
        contracted_90 = sum(fighter.overall >= 90 for fighter in contracted)
        contracted_95 = sum(fighter.overall >= 95 for fighter in contracted)
        share_80 = contracted_80 / max(1, len(contracted))
        share_90 = contracted_90 / max(1, len(contracted))
        distressed = [promo for promo in self.promotions if not getattr(promo, "is_regional_feeder", False) and (promo.cash < 0 or promo.stability < 28)]
        healthy = [promo for promo in self.promotions if not getattr(promo, "is_regional_feeder", False) and promo.cash > promo.size * 16_000 and promo.stability >= 55]
        sport_activity = sum(len(world.get("event_history", [])) for world in getattr(self, "combat_sport_worlds", {}).values())
        self.world_balance_metrics = {
            "month": self.month,
            "active_fighters": len(active),
            "free_agents": len(free),
            "contracted_fighters": len(contracted),
            "contracted_80_plus": contracted_80,
            "contracted_90_plus": contracted_90,
            "contracted_95_plus": contracted_95,
            "contracted_80_share": round(share_80, 4),
            "contracted_90_share": round(share_90, 4),
            "distressed_promotions": len(distressed),
            "healthy_promotions": len(healthy),
            "combat_sport_activity": sport_activity,
        }
        current_year = self.current_year()
        if ((self.month - 1) % 12 == 0
                and int(self.rules.get("talent_health_report_year", 0) or 0) < current_year):
            self.rules["talent_health_report_year"] = current_year
            detail = (
                f"Contracted MMA talent: {len(contracted)} fighters; {contracted_80} rated 80+ "
                f"({share_80:.1%}), {contracted_90} rated 90+ ({share_90:.1%}), and "
                f"{contracted_95} rated 95+. Free-agent reserve: {len(free)}."
            )
            self.record_world_story(
                "World Talent Report", f"{current_year} world talent report published.",
                detail, importance=2,
            )
            if not getattr(self, "spectator_mode", False) and (share_80 < 0.13 or share_90 < 0.015):
                self.inbox.append({
                    "subject": f"World Talent Pipeline Warning - {current_year}",
                    "body": detail + " The global elite pipeline is below its sustainable range; regional scouting and academy development may carry extra value.",
                    "type": "Scouting", "resolved": False,
                })
        if len(free) < 70 and random.random() < 0.35:
            region = random.choice(REGION_GENERATION_POOL)
            prospect = self.create_generated_fighter(6, 34, 42, 80, region=region)
            self.avoid_name_collision(prospect, self.active_fighter_names())
            self.free_agents.append(prospect)
            self.news.insert(0, f"World scouting response: {prospect.name} emerged from {region} as the market tightened.")
        for promo in healthy[:4]:
            strategy = self.promotion_strategy(promo)
            strategy["market_momentum"] = min(38, strategy.get("market_momentum", 0) + random.uniform(0.4, 1.2))
            if strategy.get("current_mode") == "Financial Recovery":
                strategy["current_mode"] = "Balanced"
        for promo in distressed:
            strategy = self.promotion_strategy(promo)
            strategy["current_mode"] = "Financial Recovery"
            strategy["market_momentum"] = max(-38, strategy.get("market_momentum", 0) - random.uniform(0.6, 1.8))
        if sport_activity and self.month % 6 == 0:
            for region, data in self.regions.items():
                combat_lift = sum(1 for world in getattr(self, "combat_sport_worlds", {}).values() for fighter in world.get("roster", []) if fighter.region == region) // 20
                if combat_lift:
                    data["mma_love"] = max(1, min(100, data.get("mma_love", 50) + min(2, combat_lift)))

    def combat_sport_roster(self, sport, employer=None):
        worlds = getattr(self, "combat_sport_worlds", {})
        worlds = worlds if isinstance(worlds, dict) else {}
        world = worlds.get(sport, {})
        world = world if isinstance(world, dict) else {}
        raw_roster = world.get("roster", [])
        raw_roster = raw_roster if isinstance(raw_roster, (list, tuple)) else []
        roster = [fighter for fighter in raw_roster
                  if hasattr(fighter, "name") and not getattr(fighter, "retired", False)]
        if employer:
            roster = [fighter for fighter in roster if fighter.sport_employer == employer]
        return roster

    def combat_sport_for_fighter(self, fighter):
        for sport, world in getattr(self, "combat_sport_worlds", {}).items():
            if fighter in world.get("roster", []):
                return sport
        native = getattr(fighter, "primary_discipline", "")
        if native == "Lethwei":
            return "Muay Thai"
        return native if native in ("Boxing", "Kickboxing", "Muay Thai", "Wrestling", "Brazilian Jiu-Jitsu") else ""

    def combat_sport_rating(self, fighter, sport):
        if getattr(fighter, "primary_discipline", "") == "Lethwei":
            # Keep Lethwei's toughness/power identity without giving its shared
            # Muay Thai rankings a larger total weighting than native athletes.
            return fighter.striking * 1.08 + fighter.power * 0.40 + fighter.toughness * 0.34 + fighter.cardio * 0.22 + fighter.fight_iq * 0.16
        if sport == "Boxing":
            return fighter.striking * 1.25 + fighter.power * 0.42 + fighter.chin * 0.28 + fighter.cardio * 0.24 + fighter.fight_iq * 0.22
        if sport in ("Kickboxing", "Muay Thai"):
            return fighter.striking * 1.12 + fighter.power * 0.36 + fighter.toughness * 0.28 + fighter.cardio * 0.24 + fighter.fight_iq * 0.20
        if sport == "Wrestling":
            return fighter.wrestling * 1.35 + fighter.ground_control * 0.42 + fighter.cardio * 0.30 + fighter.toughness * 0.20 + fighter.fight_iq * 0.22
        if sport == "Brazilian Jiu-Jitsu":
            return fighter.grappling * 1.30 + fighter.submissions * 0.46 + fighter.ground_control * 0.30 + fighter.cardio * 0.20 + fighter.fight_iq * 0.24
        return fighter.overall * 2.0 + fighter.popularity * 0.25

    def combat_sport_rating_scale(self, sport, fighter=None):
        """Convert each raw ranking formula to the same readable 1-99 scale."""
        if fighter is not None and getattr(fighter, "primary_discipline", "") == "Lethwei":
            return 2.20
        return {
            "Boxing": 2.41,
            "Kickboxing": 2.20,
            "Muay Thai": 2.20,
            "Wrestling": 2.49,
            "Brazilian Jiu-Jitsu": 2.50,
        }.get(sport, 2.0)

    def combat_sport_display_rating(self, fighter, sport):
        return round(self.combat_sport_rating(fighter, sport) / self.combat_sport_rating_scale(sport, fighter), 1)

    def combat_sport_development_profile(self, sport):
        """Detailed-skill source of truth for training and age decline by sport."""
        profiles = {
            "Boxing": {
                "growth": ("punch_technique", "hand_speed", "footwork", "head_movement", "guard_defence", "punch_power", "feints", "conditioning", "composure", "adaptability"),
                "decline": ("hand_speed", "footwork", "head_movement", "reflexes", "conditioning", "stun_recovery", "punch_power"),
                "preferred_focus": "Striking", "growth_mult": 1.03, "decline_base": 0.020, "decline_slope": 0.032,
            },
            "Kickboxing": {
                "growth": ("punch_technique", "hand_speed", "footwork", "high_kick_technique", "high_kick_speed", "low_kick_technique", "low_kick_speed", "kick_defence", "conditioning", "mobility", "composure"),
                "decline": ("hand_speed", "footwork", "high_kick_speed", "low_kick_speed", "reflexes", "conditioning", "mobility", "stun_recovery"),
                "preferred_focus": "Striking", "growth_mult": 1.00, "decline_base": 0.022, "decline_slope": 0.034,
            },
            "Muay Thai": {
                "growth": ("low_kick_technique", "high_kick_technique", "knees", "elbows", "thai_plum", "clinch_control", "kick_defence", "mobility", "conditioning", "resilience", "composure"),
                "decline": ("high_kick_speed", "low_kick_speed", "mobility", "reflexes", "conditioning", "footwork", "stun_recovery", "resilience"),
                "preferred_focus": "Striking", "growth_mult": 1.04, "decline_base": 0.026, "decline_slope": 0.034,
            },
            "Wrestling": {
                "growth": ("takedowns", "takedown_setup", "takedown_speed", "chain_wrestling", "sprawl", "takedown_defence_detail", "throws", "ride_control", "top_control", "scrambles", "strength", "conditioning", "discipline"),
                "decline": ("takedown_speed", "chain_wrestling", "scrambles", "mobility", "strength", "conditioning", "get_ups", "resilience"),
                "preferred_focus": "Wrestling", "growth_mult": 1.00, "decline_base": 0.030, "decline_slope": 0.030,
            },
            "Brazilian Jiu-Jitsu": {
                "growth": ("guard_work", "transitions", "positional_ability", "submission_attack", "submission_defence_detail", "back_control", "mount_control", "leg_locks", "scrambles", "bottom_control", "top_control", "flexibility", "composure", "adaptability"),
                "decline": ("scrambles", "mobility", "conditioning", "strength", "flexibility", "get_ups", "resilience"),
                "preferred_focus": "Grappling", "growth_mult": 0.97, "decline_base": 0.032, "decline_slope": 0.025,
            },
        }
        return profiles.get(sport, profiles["Boxing"])

    def combat_sport_effective_prime_end(self, fighter, sport):
        tail = 1 if getattr(fighter, "career_archetype", "") == "Durable Career" else 0
        if sport == "Brazilian Jiu-Jitsu":
            tail += 1
        return fighter.prime_end + tail

    def combat_sport_development_stage(self, fighter, sport):
        if fighter.age < fighter.prime_start:
            return "Pre-prime"
        end = self.combat_sport_effective_prime_end(fighter, sport)
        if fighter.age <= end:
            return "Prime"
        years = fighter.age - end
        return "Early decline" if years <= 2 else "Decline" if years <= 6 else "Deep decline"

    def combat_sport_focus_keys(self, focus):
        return {
            "Striking": tuple(STANDING_SKILLS),
            "Wrestling": tuple(WRESTLING_SKILLS),
            "Grappling": tuple(GROUND_SKILLS),
            "Conditioning": ("conditioning", "resilience", "stun_recovery", "mobility"),
            "Game Plan": ("composure", "adaptability", "discipline", "confidence", "consistency"),
            "Weight Management": ("weight_cutting", "conditioning", "discipline"),
        }.get(focus, ())

    def combat_sport_growth_allowed(self, fighter, sport):
        if getattr(fighter, "retired", False) or fighter.injured:
            return False
        current = self.combat_sport_display_rating(fighter, sport)
        return current < min(99, fighter.potential)

    def combat_sport_weighted_skill_sample(self, pool, count):
        chosen = []
        candidates = list(pool)
        while candidates and len(chosen) < count:
            key = random.choice(candidates)
            chosen.append(key)
            candidates = [candidate for candidate in candidates if candidate != key]
        return chosen

    def apply_combat_sport_broad_delta(self, fighter, sport, amount, keys):
        """Keep the readable native rating moving with its detailed source skills."""
        primary = "striking" if sport in ("Boxing", "Kickboxing", "Muay Thai") else "wrestling" if sport == "Wrestling" else "grappling"
        setattr(fighter, primary, max(1, min(99, getattr(fighter, primary) + amount)))
        key_set = set(keys)
        secondary = []
        if key_set & {"punch_power", "high_kick_power", "low_kick_power", "strength"}:
            secondary.append("power")
        if key_set & {"conditioning", "resilience", "stun_recovery"}:
            secondary.append("cardio")
        if key_set & {"composure", "adaptability", "discipline", "confidence", "consistency"}:
            secondary.append("fight_iq")
        if key_set & {"chin_strength", "stun_recovery", "resilience"}:
            secondary.append("chin")
        if sport == "Wrestling" and key_set & {"ride_control", "top_control", "scrambles"}:
            secondary.append("ground_control")
        if sport == "Brazilian Jiu-Jitsu":
            if key_set & {"submission_attack", "leg_locks", "back_control"}:
                secondary.append("submissions")
            if key_set & {"top_control", "positional_ability", "mount_control"}:
                secondary.append("ground_control")
            if key_set & {"submission_defence_detail", "guard_work"}:
                secondary.append("submission_defence")
        if secondary:
            field = random.choice(list(dict.fromkeys(secondary)))
            setattr(fighter, field, max(1, min(99, getattr(fighter, field) + amount)))

    def adjust_combat_sport_training_key(self, fighter, sport, key, amount, reason):
        """Apply one camp improvement without invoking the MMA-wide detail resync."""
        if amount > 0 and not self.combat_sport_growth_allowed(fighter, sport):
            return False
        self.ensure_detailed_skills(fighter)
        before_rating = self.combat_sport_display_rating(fighter, sport)
        before_detail = fighter.detailed_skills.get(key, 50)
        broad_fields = ("striking", "wrestling", "grappling", "cardio", "chin", "power", "ground_control", "submissions", "submission_defence", "fight_iq")
        broad_before = {field: getattr(fighter, field) for field in broad_fields}
        next_detail = max(1, min(99, before_detail + amount))
        if next_detail == before_detail:
            return False
        fighter.detailed_skills[key] = next_detail
        self.apply_combat_sport_broad_delta(fighter, sport, amount, [key])
        after_rating = self.combat_sport_display_rating(fighter, sport)
        if amount > 0 and after_rating > min(99, fighter.potential) + 0.01:
            fighter.detailed_skills[key] = before_detail
            for field, value in broad_before.items():
                setattr(fighter, field, value)
            return False
        if fighter.detailed_skills[key] != before_detail:
            self.record_combat_sport_development(fighter, sport, before_rating, after_rating, [key], reason)
            return True
        return False

    def adjust_combat_sport_skill_bundle(self, fighter, sport, amount, reason="Training", decline=False, key_count=None):
        """Mutate native detailed skills first, then synchronize broad ratings once."""
        if amount > 0 and not self.combat_sport_growth_allowed(fighter, sport):
            return []
        self.ensure_detailed_skills(fighter)
        profile = self.combat_sport_development_profile(sport)
        base_pool = list(profile["decline" if decline else "growth"])
        if not decline:
            focus = getattr(fighter, "camp_focus", "Balanced")
            focus_pool = list(self.combat_sport_focus_keys(focus))
            compatible = [key for key in focus_pool if key in base_pool]
            if compatible:
                base_pool = compatible * 2 + base_pool
            # An incompatible focus does not convert child-sport development
            # into hidden MMA cross-training. Native skills remain the source
            # of truth until the athlete actually crosses into MMA.
        stage = self.combat_sport_development_stage(fighter, sport)
        if key_count is None:
            key_count = 5 if stage == "Pre-prime" and not decline else 3 if not decline else 5
        keys = self.combat_sport_weighted_skill_sample(base_pool, key_count)
        if not keys:
            return []
        before_values = {key: fighter.detailed_skills.get(key, 50) for key in keys}
        broad_fields = ("striking", "wrestling", "grappling", "cardio", "chin", "power", "ground_control", "submissions", "submission_defence", "fight_iq")
        broad_before = {field: getattr(fighter, field) for field in broad_fields}
        before_rating = self.combat_sport_display_rating(fighter, sport)
        for key in keys:
            fighter.detailed_skills[key] = max(1, min(99, fighter.detailed_skills.get(key, 50) + amount))
        changed = [key for key in keys if fighter.detailed_skills.get(key, 50) != before_values[key]]
        if not changed:
            return []
        self.apply_combat_sport_broad_delta(fighter, sport, amount, changed)
        after_rating = self.combat_sport_display_rating(fighter, sport)
        if not decline and after_rating > min(99, fighter.potential) + 0.01:
            for key, value in before_values.items():
                fighter.detailed_skills[key] = value
            for field, value in broad_before.items():
                setattr(fighter, field, value)
            return []
        if changed:
            self.record_combat_sport_development(fighter, sport, before_rating, self.combat_sport_display_rating(fighter, sport), changed, reason)
        return changed

    def record_combat_sport_development(self, fighter, sport, before, after, keys, reason):
        fighter.sport_development_log = list(getattr(fighter, "sport_development_log", None) or [])
        fighter.sport_development_log.insert(0, {
            "month": self.month, "year": self.current_year(), "sport": sport,
            "before": round(before, 1), "after": round(after, 1),
            "change": round(after - before, 1), "skills": list(keys), "reason": reason,
        })
        fighter.sport_development_log = fighter.sport_development_log[:60]

    def record_combat_sport_rating_snapshot(self, fighter, sport):
        history = dict(getattr(fighter, "sport_rating_history", None) or {})
        sport_history = dict(history.get(sport, {}) or {})
        sport_history[str(self.month)] = self.combat_sport_display_rating(fighter, sport)
        if len(sport_history) > 180:
            for key in sorted(sport_history, key=lambda value: int(value))[:-180]:
                sport_history.pop(key, None)
        history[sport] = sport_history
        fighter.sport_rating_history = history

    def combat_sport_rating_trend(self, fighter, sport, months=12):
        history = (getattr(fighter, "sport_rating_history", None) or {}).get(sport, {})
        if not history:
            return 0.0
        current = self.combat_sport_display_rating(fighter, sport)
        target = self.month - months
        eligible = [(int(key), value) for key, value in history.items() if int(key) <= target]
        if not eligible:
            eligible = [(int(key), value) for key, value in history.items()]
        _month, previous = min(eligible, key=lambda item: abs(item[0] - target))
        return round(current - previous, 1)

    def combat_sport_monthly_growth_chance(self, fighter, sport):
        if not self.combat_sport_growth_allowed(fighter, sport):
            return 0.0
        stage = self.combat_sport_development_stage(fighter, sport)
        current = self.combat_sport_display_rating(fighter, sport)
        gap = max(0, min(99, fighter.potential) - current)
        gym = self.gym_by_name(fighter.camp)
        quality = self.gym_quality(fighter.camp)
        facilities = gym.facilities if gym else quality
        dedication = self.ds(fighter, "dedication", fighter.professionalism)
        human = (dedication + fighter.professionalism + fighter.motivation + fighter.morale) / 4
        specialty = self.gym_specialty_bonus(fighter, gym)
        crowd = max(0, (gym.member_count - gym.capacity) / max(1, gym.capacity)) if gym and gym.capacity < 500 else 0
        inactivity = self.combat_sport_inactivity_months(fighter)
        if inactivity >= 20:
            activity = -0.075
        elif inactivity >= 12:
            activity = -0.035
        elif 1 <= inactivity <= 6:
            activity = 0.025
        else:
            activity = 0.0
        if stage == "Pre-prime":
            base = 0.10
            gap_bonus = min(0.12, gap * 0.006)
        elif stage == "Prime":
            base = 0.025
            gap_bonus = min(0.055, gap * 0.0035)
        else:
            base = min(0.012, self.veteran_resurgence_chance(fighter) * 0.30)
            gap_bonus = 0.0
        chance = (
            base + gap_bonus
            + (quality + facilities - 100) / 900
            + (human - 55) / 650
            + specialty / 360
            + activity
            + max(0, fighter.momentum) * 0.006
            - fighter.fatigue * 0.0015
            - crowd * 0.11
        ) * self.combat_sport_development_profile(sport)["growth_mult"]
        ceiling = 0.40 if stage == "Pre-prime" else 0.16 if stage == "Prime" else 0.015
        return max(0.0, min(ceiling, chance))

    def combat_sport_monthly_decline_chance(self, fighter, sport):
        years_over = fighter.age - self.combat_sport_effective_prime_end(fighter, sport)
        if years_over <= 0:
            return 0.0
        profile = self.combat_sport_development_profile(sport)
        resilience = self.ds(fighter, "resilience", fighter.toughness)
        conditioning = self.ds(fighter, "conditioning", fighter.cardio)
        professional_buffer = (fighter.professionalism + resilience + conditioning - 165) / 1800
        health = fighter.injured * 0.012 + max(0, fighter.fatigue - 45) / 850 + effective_injury_tendency(fighter) / 3000
        form = max(0, -fighter.momentum) * 0.012 + max(0, 45 - fighter.morale) / 950
        chance = profile["decline_base"] + years_over * profile["decline_slope"] + health + form - professional_buffer
        if years_over <= 2:
            chance *= 0.62
        if getattr(fighter, "career_archetype", "") == "Durable Career":
            chance *= 0.80
        return max(0.0, min(0.34, chance))

    def apply_combat_sport_annual_age_curve(self, fighter, sport):
        stage = self.combat_sport_development_stage(fighter, sport)
        if stage == "Pre-prime" and self.combat_sport_growth_allowed(fighter, sport):
            gap = max(0, min(99, fighter.potential) - self.combat_sport_display_rating(fighter, sport))
            chance = min(0.62, 0.22 + gap * 0.016 + max(0, fighter.professionalism - 55) / 500)
            if random.random() < chance:
                self.adjust_combat_sport_skill_bundle(fighter, sport, 1, "Annual athletic and technical maturation", key_count=5)
        elif stage in ("Early decline", "Decline", "Deep decline"):
            years_over = fighter.age - self.combat_sport_effective_prime_end(fighter, sport)
            profile = self.combat_sport_development_profile(sport)
            chance = min(0.88, 0.10 + years_over * 0.10 + profile["decline_slope"] * 2)
            if getattr(fighter, "career_archetype", "") == "Durable Career":
                chance *= 0.78
            if random.random() < chance:
                amount = -2 if years_over >= 5 and random.random() < min(0.75, 0.25 + years_over * 0.07) else -1
                self.adjust_combat_sport_skill_bundle(fighter, sport, amount, "Annual age-curve review", decline=True, key_count=6)
        self.record_combat_sport_rating_snapshot(fighter, sport)

    def combat_sport_ranked(self, sport, employer=None):
        return sorted(
            self.combat_sport_roster(sport, employer),
            key=lambda fighter: (
                self.combat_sport_rating(fighter, sport),
                fighter.record_w - fighter.record_l,
                fighter.popularity,
                -fighter.age,
            ),
            reverse=True,
        )

    def combat_sport_division_key(self, fighter, sport=None):
        """Stable save key for a non-MMA championship division."""
        sport = sport or ("Muay Thai" if getattr(fighter, "primary_discipline", "") == "Lethwei" else getattr(fighter, "primary_discipline", ""))
        division = self.combat_sport_competition_class(sport, fighter) if sport else (getattr(fighter, "sport_weight_class", "") or fighter.weight)
        return f"{fighter.gender}|{division}"

    def combat_sport_division_label(self, key):
        gender, _, weight = str(key).partition("|")
        return f"{gender} {weight}" if weight else gender

    def combat_sport_state(self, sport, world, player_owned=False):
        if player_owned:
            return getattr(self, "player_combat_divisions", {}).get(sport, world)
        return world

    def ensure_player_combat_division_identity(self, sport, world=None, *, repair=True):
        """Repair player child-promotion membership and bookings to stable IDs.

        Older saves stored display names.  Keep those mirrors for presentation,
        but make ``roster_ids`` and bout corner IDs the authoritative links so
        same-name athletes remain independent.  ``repair=False`` returns the
        same compatibility projection on a defensive copy for presentation
        readers, leaving the retained division unchanged.
        """
        if world is None:
            worlds = getattr(self, "combat_sport_worlds", {})
            world = worlds.get(sport, {}) if isinstance(worlds, dict) else {}
        if not isinstance(world, dict):
            world = {}
        divisions = getattr(self, "player_combat_divisions", {})
        division = divisions.get(sport) if isinstance(divisions, dict) else None
        if not isinstance(division, dict) or not division:
            return None
        division = division if repair else deepcopy(division)
        raw_roster = world.get("roster", [])
        roster = list(raw_roster) if isinstance(raw_roster, (list, tuple)) else []
        eligible = [
            fighter for fighter in roster
            if getattr(fighter, "sport_employer", "") == self.player_company_name
            and not getattr(fighter, "retired", False)
            and getattr(fighter, "fighter_id", "")
            and getattr(fighter, "name", "")
        ]
        by_id = {fighter.fighter_id: fighter for fighter in eligible}
        by_name = {}
        for fighter in eligible:
            by_name.setdefault(fighter.name, []).append(fighter)
        raw_ids = division.get("roster_ids", [])
        raw_ids = raw_ids if isinstance(raw_ids, (list, tuple)) else []
        ids = [fighter_id for fighter_id in raw_ids if fighter_id in by_id]
        raw_names = division.get("roster", [])
        raw_names = raw_names if isinstance(raw_names, (list, tuple)) else []
        for name in raw_names:
            matches = by_name.get(name, [])
            if len(matches) == 1 and matches[0].fighter_id not in ids:
                ids.append(matches[0].fighter_id)
        # Employer ownership is the final repair source for legacy saves whose
        # name list was incomplete or ambiguous.
        for fighter in eligible:
            if fighter.fighter_id not in ids:
                ids.append(fighter.fighter_id)
        division["roster_ids"] = ids
        division["roster"] = [by_id[fighter_id].name for fighter_id in ids]

        repaired_bouts = []
        raw_bouts = division.get("booked_bouts", [])
        raw_bouts = raw_bouts if isinstance(raw_bouts, (list, tuple)) else []
        for raw in raw_bouts:
            if not isinstance(raw, dict):
                continue
            bout = dict(raw)
            a = by_id.get(str(bout.get("a_id", "")))
            b = by_id.get(str(bout.get("b_id", "")))
            if a is None:
                matches = by_name.get(str(bout.get("a", "")), [])
                a = matches[0] if len(matches) == 1 else None
            if b is None:
                matches = by_name.get(str(bout.get("b", "")), [])
                b = matches[0] if len(matches) == 1 else None
            if not a or not b or a.fighter_id == b.fighter_id:
                continue
            bout.update({"a_id": a.fighter_id, "b_id": b.fighter_id, "a": a.name, "b": b.name})
            repaired_bouts.append(bout)
        division["booked_bouts"] = repaired_bouts
        return division

    def add_player_combat_member(self, sport, fighter, world=None):
        division = self.ensure_player_combat_division_identity(sport, world)
        if not division:
            return
        if fighter.fighter_id not in division["roster_ids"]:
            division["roster_ids"].append(fighter.fighter_id)
        division["roster"] = [
            candidate.name for candidate in (world or self.combat_sport_worlds[sport]).get("roster", [])
            if candidate.fighter_id in set(division["roster_ids"])
        ]

    def player_combat_bout_contains(self, bout, fighter):
        corner_ids = (bout.get("a_id", ""), bout.get("b_id", ""))
        if any(corner_ids):
            return fighter.fighter_id in corner_ids
        # Legacy name-only cards cannot distinguish namesakes. Removing the
        # stale bout is safer than allowing the wrong athlete to compete.
        return fighter.name in (bout.get("a"), bout.get("b"))

    def combat_sport_roster_target(self, sport, world):
        """Return the persistent circuit depth target, including migrated saves."""
        current = len(self.combat_sport_roster(sport, world.get("promotion", "")))
        baseline = max(36, int(world.get("starting_roster_size", current or 36)))
        target = max(int(world.get("roster_target", 0) or 0), baseline * COMBAT_SPORT_ROSTER_TARGET_MULTIPLIER)
        world["starting_roster_size"] = baseline
        world["roster_target"] = target
        return target

    def ensure_combat_sport_circuit_state(self, sport, world, employer=None, player_owned=False, repair=True):
        """Migrate the old one-champion circuit into divisional state.

        ``repair=False`` is the reader boundary used by overview/history pages.
        It projects the same legacy compatibility rules onto defensive copies,
        so opening a page cannot seed weight classes, crowns or ranking fields
        into the saved world.  Simulation and explicit management callers keep
        the repairing default.
        """
        source_state = self.combat_sport_state(sport, world, player_owned)
        state = source_state if repair else deepcopy(source_state if isinstance(source_state, dict) else {})
        if not player_owned:
            employer = world.get("promotion", employer)
        state.setdefault("titles", {})
        state.setdefault("title_ids", {})
        state.setdefault("title_history", {})
        state.setdefault("rankings_by_division", {})
        state.setdefault("records", {})
        state.setdefault("record_book", {})
        state.setdefault("season_stats", {})
        state.setdefault("awards", [])
        state.setdefault("hall_of_fame", [])
        state.setdefault("finance_history", [])
        state.setdefault("reputation", 50 if player_owned else 62)
        state.setdefault("stability", 60 if player_owned else 72)
        if not player_owned:
            starting_cash = {
                "Boxing": 8_000_000,
                "Kickboxing": 4_500_000,
                "Muay Thai": 3_800_000,
                "Wrestling": 3_000_000,
                "Brazilian Jiu-Jitsu": 2_800_000,
            }.get(sport, 3_000_000)
            state.setdefault("cash", starting_cash)
            state.setdefault("starting_roster_size", len(self.combat_sport_roster(sport, employer)))
            if repair:
                self.combat_sport_roster_target(sport, world)
            else:
                baseline = max(36, int(state.get("starting_roster_size", 36) or 36))
                target = max(int(state.get("roster_target", 0) or 0), baseline * COMBAT_SPORT_ROSTER_TARGET_MULTIPLIER)
                state["starting_roster_size"] = baseline
                state["roster_target"] = target
        roster = self.combat_sport_roster(sport, employer)
        if not repair:
            # Weight assignment and champion flags below are compatibility
            # projection work; copies keep the live Fighter objects untouched.
            roster = [deepcopy(fighter) for fighter in roster]
        for fighter in roster:
            native_sport = getattr(fighter, "primary_discipline", sport)
            if native_sport not in COMBAT_SPORT_WEIGHT_CLASSES:
                native_sport = sport
            expected = (getattr(self, "combat_sport_seed_divisions", {}) or {}).get(native_sport, {}).get(fighter.name, "")
            if not expected:
                expected = COMBAT_SPORT_REAL_DIVISIONS.get(native_sport, {}).get(fighter.name, "")
            ladder_labels = {label for label, _limit in self.combat_sport_weight_ladder(native_sport, fighter.gender)}
            current = getattr(fighter, "sport_weight_class", "")
            if current not in ladder_labels or (expected and current != expected):
                self.assign_combat_sport_weight(native_sport, fighter, expected, reset_walk_weight=True)
            else:
                fighter.weight = self.combat_sport_mma_equivalent(native_sport, current, fighter.gender)
        valid_ids = {fighter.fighter_id for fighter in roster}
        groups = {}
        for fighter in roster:
            groups.setdefault(self.combat_sport_division_key(fighter, sport), []).append(fighter)
        ranked_groups = {
            key: sorted(
                fighters,
                key=lambda fighter: (self.combat_sport_rating(fighter, sport), fighter.record_w - fighter.record_l, fighter.popularity),
                reverse=True,
            )
            for key, fighters in groups.items()
        }
        state["rankings_by_division"] = {key: [fighter.name for fighter in fighters[:10]] for key, fighters in ranked_groups.items()}
        # Old saves keyed titles by a randomly assigned MMA division.  Move
        # every champion and lineage onto the athlete's corrected sport class.
        roster_by_id = {fighter.fighter_id: fighter for fighter in roster}
        roster_by_name = {}
        for fighter in roster:
            roster_by_name.setdefault(fighter.name, []).append(fighter)
        migrated_title_ids = {}
        old_title_ids = state.get("title_ids", {}) or {}
        for old_key, champion_id in list(old_title_ids.items()):
            champion_fighter = roster_by_id.get(champion_id)
            key = self.combat_sport_division_key(champion_fighter, sport) if champion_fighter else old_key
            if key in groups and champion_fighter:
                migrated_title_ids.setdefault(key, champion_fighter.fighter_id)
        for old_key, champion in list(state.get("titles", {}).items()):
            matches = roster_by_name.get(champion, [])
            champion_fighter = matches[0] if len(matches) == 1 else None
            key = self.combat_sport_division_key(champion_fighter, sport) if champion_fighter else old_key
            if key in groups and champion_fighter and key not in migrated_title_ids:
                migrated_title_ids[key] = champion_fighter.fighter_id
        state["title_ids"] = migrated_title_ids
        state["titles"] = {key: roster_by_id[champion_id].name for key, champion_id in migrated_title_ids.items() if champion_id in roster_by_id}
        migrated_history = {}
        for old_key, entries in list(state.get("title_history", {}).items()):
            sample_id = next((entry.get("winner_id") or entry.get("previous_champion_id") or entry.get("loser_id") for entry in entries if isinstance(entry, dict)), "")
            sample_name = next((entry.get("winner") or entry.get("previous_champion") or entry.get("loser") for entry in entries if isinstance(entry, dict)), "")
            matches = roster_by_name.get(sample_name, [])
            sample = roster_by_id.get(sample_id) or (matches[0] if len(matches) == 1 else None)
            key = self.combat_sport_division_key(sample, sport) if sample else old_key
            if key in groups:
                migrated_history.setdefault(key, []).extend(entries)
        state["title_history"] = migrated_history
        # Retirements, crossovers and signings vacate belts rather than silently
        # transferring them to the next athlete in a table.
        for key, champion_id in list(state["title_ids"].items()):
            if champion_id not in valid_ids:
                state["title_ids"].pop(key, None)
                state["titles"][key] = ""
        if not state.get("titles_initialized"):
            legacy_champion = state.get("champion", "")
            legacy_matches = roster_by_name.get(legacy_champion, [])
            legacy_fighter = legacy_matches[0] if len(legacy_matches) == 1 else None
            if legacy_fighter:
                key = self.combat_sport_division_key(legacy_fighter, sport)
                state["titles"][key] = legacy_fighter.name
                state["title_ids"][key] = legacy_fighter.fighter_id
            # A fresh AI universe begins with established divisional champions;
            # player child divisions crown theirs through booked title bouts.
            if not player_owned:
                for key, fighters in ranked_groups.items():
                    if len(fighters) >= 2:
                        if key not in state["title_ids"]:
                            state["title_ids"][key] = fighters[0].fighter_id
                            state["titles"][key] = fighters[0].name
            state["titles_initialized"] = True
        champion_ids = {fighter_id for fighter_id in state["title_ids"].values() if fighter_id}
        champions = [roster_by_id[fighter_id].name for fighter_id in state["title_ids"].values() if fighter_id in roster_by_id]
        state["champion"] = champions[0] if champions else ""
        for fighter in roster:
            fighter.champion = fighter.fighter_id in champion_ids
        return state

    def combat_sport_record_book(self, sport, world, employer=None, player_owned=False, repair=True):
        # Keep compatibility with lightweight test/extension mixins that still
        # expose the original four-argument ensure method on the normal
        # repairing path; only the new reader path needs the keyword.
        state = (
            self.ensure_combat_sport_circuit_state(sport, world, employer, player_owned)
            if repair else
            self.ensure_combat_sport_circuit_state(sport, world, employer, player_owned, repair=False)
        )
        roster = self.combat_sport_roster(sport, employer)
        if not roster:
            state["record_book"] = {}
            return state["record_book"]
        eligible_pct = [fighter for fighter in roster if fighter.record_w + fighter.record_l + fighter.record_d >= 5]
        title_counts = {}
        roster_by_id = {fighter.fighter_id: fighter for fighter in roster}
        roster_by_name = {}
        for fighter in roster:
            roster_by_name.setdefault(fighter.name, []).append(fighter)
        for history in state.get("title_history", {}).values():
            for entry in history:
                winner_id = entry.get("winner_id", "")
                if not winner_id:
                    matches = roster_by_name.get(entry.get("winner", ""), [])
                    winner_id = matches[0].fighter_id if len(matches) == 1 else ""
                if winner_id in roster_by_id:
                    title_counts[winner_id] = title_counts.get(winner_id, 0) + 1
        finish_methods = ("KO", "KO/TKO", "TKO", "Submission", "Technical Fall", "Pin")
        finish_counts = {}
        for fighter in roster:
            finish_counts[fighter.fighter_id] = sum(1 for line in fighter.fight_history if sport in line and any(f"by {method}" in line for method in finish_methods))
        most_wins = max(roster, key=lambda fighter: fighter.record_w)
        best_pct = max(eligible_pct, key=lambda fighter: fighter.record_w / max(1, fighter.record_w + fighter.record_l + fighter.record_d)) if eligible_pct else most_wins
        most_titles_id = max(title_counts, key=title_counts.get) if title_counts else ""
        most_titles = roster_by_id[most_titles_id].name if most_titles_id in roster_by_id else "No title history yet"
        most_finishes_id = max(finish_counts, key=finish_counts.get) if finish_counts else most_wins.fighter_id
        most_finishes = roster_by_id[most_finishes_id].name
        state["record_book"] = {
            "Most wins": f"{most_wins.name} ({most_wins.record_w})",
            "Best win rate (5+ bouts)": f"{best_pct.name} ({best_pct.record_w / max(1, best_pct.record_w + best_pct.record_l + best_pct.record_d):.1%})",
            "Most championship wins": f"{most_titles} ({title_counts.get(most_titles_id, 0)})",
            "Most recorded finishes": f"{most_finishes} ({finish_counts.get(most_finishes_id, 0)})",
            "Oldest active athlete": f"{max(roster, key=lambda fighter: fighter.age).name} ({max(fighter.age for fighter in roster)})",
        }
        return state["record_book"]

    def refresh_combat_sport_rankings(self, sport, world, employer=None, division=None):
        ranked = self.combat_sport_ranked(sport, employer)
        names = [fighter.name for fighter in ranked[:15]]
        if division is not None:
            division["rankings"] = names[:10]
            self.ensure_combat_sport_circuit_state(sport, world, employer, player_owned=True)
        else:
            if not employer or employer == world.get("promotion", employer):
                world["rankings"] = names
            self.ensure_combat_sport_circuit_state(sport, world, employer, player_owned=False)
        return ranked

    def combat_sport_inactivity_months(self, fighter):
        return max(0, self.month - getattr(fighter, "last_fight_month", 0))

    def combat_sport_card_strategy(self, sport, world, employer, player_owned=False):
        if player_owned:
            return getattr(self, "player_combat_divisions", {}).get(sport, {}).get("strategy", "Balanced")
        world.setdefault("strategy", random.choice(["Champion Showcase", "Prospect Rotation", "Deep Roster", "Merit Ladder"]))
        roster = self.combat_sport_roster(sport, employer)
        inactive = sum(1 for fighter in roster if self.combat_sport_inactivity_months(fighter) >= 5)
        if inactive >= max(8, len(roster) // 4):
            world["strategy"] = "Deep Roster"
        elif any(world.get("titles", {}).values()) and random.random() < 0.18:
            world["strategy"] = "Champion Showcase"
        return world["strategy"]

    def combat_sport_method(self, sport, winner, loser, rating_gap):
        finish_pressure = max(0, rating_gap) / 46 + max(0, winner.finishing_instinct - loser.toughness) / 120
        if sport == "Boxing":
            return "KO" if random.random() < 0.18 + finish_pressure else "Decision"
        if sport in ("Kickboxing", "Muay Thai"):
            return "KO/TKO" if random.random() < 0.22 + finish_pressure else "Decision"
        if getattr(winner, "primary_discipline", "") == "Lethwei":
            return "KO" if random.random() < 0.32 + finish_pressure else "Draw" if random.random() < 0.18 else "Decision"
        if sport == "Wrestling":
            return random.choices(["Points", "Technical Fall", "Pin"], weights=[58, 24, 18], k=1)[0]
        if sport == "Brazilian Jiu-Jitsu":
            return "Submission" if random.random() < 0.38 + max(0, winner.submissions - loser.submission_defence) / 140 else "Points"
        return "Decision"

    def combat_sport_skill_set(self, sport, fighter):
        """Sport-specific skill lens used by non-MMA combat cards.

        This deliberately shares fighter attributes with MMA, but each sport
        weights them differently so a world-class wrestler, boxer, or grappler
        does not feel like a generic overall roll.
        """
        ds = self.ds
        if sport == "Boxing":
            attack = ds(fighter, "punch_technique", fighter.striking) * 0.34 + ds(fighter, "hand_speed", fighter.striking) * 0.22 + ds(fighter, "footwork", fighter.striking) * 0.14 + fighter.power * 0.20 + fighter.fight_iq * 0.10
            defense = ds(fighter, "head_movement", fighter.striking) * 0.26 + ds(fighter, "guard_defence", fighter.striking) * 0.24 + ds(fighter, "footwork", fighter.striking) * 0.18 + fighter.chin * 0.18 + fighter.fight_iq * 0.14
            finishing = fighter.power * 0.42 + ds(fighter, "punch_power", fighter.power) * 0.32 + fighter.finishing_instinct * 0.20 + ds(fighter, "killer_instinct", fighter.finishing_instinct) * 0.06
            return attack, defense, finishing
        if sport in ("Kickboxing", "Muay Thai"):
            clinch_bonus = 0.16 if sport == "Muay Thai" or getattr(fighter, "primary_discipline", "") == "Lethwei" else 0.05
            attack = ds(fighter, "punch_technique", fighter.striking) * 0.18 + ds(fighter, "high_kick_technique", fighter.striking) * 0.12 + ds(fighter, "low_kick_technique", fighter.striking) * 0.15 + ds(fighter, "high_kick_speed", fighter.striking) * 0.10 + ds(fighter, "knees", fighter.striking) * clinch_bonus + fighter.power * 0.20 + fighter.fight_iq * 0.10
            defense = ds(fighter, "guard_defence", fighter.striking) * 0.18 + ds(fighter, "kick_defence", fighter.striking) * 0.22 + ds(fighter, "footwork", fighter.striking) * 0.16 + fighter.chin * 0.18 + fighter.toughness * 0.14 + fighter.fight_iq * 0.12
            finishing = fighter.power * 0.34 + ds(fighter, "high_kick_power", fighter.power) * 0.14 + ds(fighter, "low_kick_power", fighter.power) * 0.10 + ds(fighter, "knees", fighter.striking) * 0.14 + fighter.finishing_instinct * 0.20 + fighter.toughness * 0.08
            return attack, defense, finishing
        if sport == "Wrestling":
            attack = ds(fighter, "takedowns", fighter.wrestling) * 0.30 + ds(fighter, "takedown_setup", fighter.wrestling) * 0.18 + ds(fighter, "chain_wrestling", fighter.wrestling) * 0.22 + ds(fighter, "ride_control", fighter.ground_control) * 0.14 + fighter.cardio * 0.10 + fighter.fight_iq * 0.06
            defense = ds(fighter, "sprawl", fighter.wrestling) * 0.24 + ds(fighter, "takedown_defence_detail", fighter.takedown_defence) * 0.22 + ds(fighter, "get_ups", fighter.wrestling) * 0.16 + ds(fighter, "mobility", fighter.wrestling) * 0.12 + fighter.cardio * 0.14 + fighter.toughness * 0.12
            finishing = ds(fighter, "slams", fighter.wrestling) * 0.16 + ds(fighter, "ride_control", fighter.ground_control) * 0.24 + ds(fighter, "top_control", fighter.ground_control) * 0.22 + ds(fighter, "strength", fighter.wrestling) * 0.18 + fighter.fight_iq * 0.20
            return attack, defense, finishing
        if sport == "Brazilian Jiu-Jitsu":
            attack = ds(fighter, "transitions", fighter.grappling) * 0.20 + ds(fighter, "guard_work", fighter.grappling) * 0.18 + ds(fighter, "positional_ability", fighter.grappling) * 0.18 + fighter.submissions * 0.24 + fighter.fight_iq * 0.12 + fighter.cardio * 0.08
            defense = ds(fighter, "submission_defence_detail", fighter.submission_defence) * 0.26 + ds(fighter, "guard_work", fighter.grappling) * 0.16 + ds(fighter, "scrambles", fighter.grappling) * 0.18 + fighter.ground_control * 0.16 + fighter.cardio * 0.12 + fighter.fight_iq * 0.12
            finishing = fighter.submissions * 0.42 + ds(fighter, "back_control", fighter.grappling) * 0.18 + ds(fighter, "mount_control", fighter.grappling) * 0.14 + ds(fighter, "flexibility", fighter.grappling) * 0.10 + fighter.fight_iq * 0.16
            return attack, defense, finishing
        rating = self.combat_sport_rating(fighter, sport) / 2
        return rating, rating, rating

    def combat_sport_bout_rules(self, sport, title=False, a=None, b=None):
        lethwei = getattr(a, "primary_discipline", "") == "Lethwei" or getattr(b, "primary_discipline", "") == "Lethwei"
        if sport == "Boxing":
            # Pro boxing grows from developmental six-rounders to eight- and
            # ten-round contests; recognized championship fights use 12.
            level = max((self.combat_sport_display_rating(fighter, sport) for fighter in (a, b) if fighter), default=50)
            rounds = 12 if title else 10 if level >= 86 else 8 if level >= 74 else 6
            return {"rounds": rounds, "finish": "KO/TKO", "decision": "Decision", "draws": True, "fatigue": 2.35, "finish_divisor": 355, "finish_cap": 0.17, "draw_chance": 0.04, "judges": 3}
        if sport == "Kickboxing":
            return {"rounds": 5 if title else 3, "finish": "KO/TKO", "decision": "Decision", "draws": True, "fatigue": 4.0, "finish_divisor": 230, "finish_cap": 0.33, "draw_chance": 0.22}
        if sport == "Muay Thai":
            return {"rounds": 5 if title or lethwei else 3, "finish": "KO" if lethwei else "KO/TKO", "decision": "Decision", "draws": True, "fatigue": 4.2, "finish_divisor": 292 if not lethwei else 260, "finish_cap": 0.31 if not lethwei else 0.36, "draw_chance": 0.08 if not lethwei else 1.0, "lethwei": lethwei, "judges": 3}
        if sport == "Wrestling":
            return {"rounds": 3, "finish": "Pin", "decision": "Points", "draws": False, "fatigue": 3.4, "tech_gap": 10}
        if sport == "Brazilian Jiu-Jitsu":
            return {"rounds": 1, "finish": "Submission", "decision": "Points", "draws": False, "fatigue": 3.2}
        return {"rounds": 3, "finish": "Finish", "decision": "Decision", "draws": True, "fatigue": 3.5}

